insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ: لَقَدْ خَشِيتُ أَنْ يَطُولَ بِالنَّاسِ زَمَانٌ، حَتَّى يَقُولَ قَائِلٌ: مَا أَجِدُ الرَّجْمَ فِي كِتَابِ اللَّهِ، فَيَضِلُّوا بِتَرْكِ فَرِيضَةٍ مِنْ فَرَائِضِ اللَّهِ. أَلَا وَإِنَّ الرَّجْمَ حَقٌّ إِذَا أُحْصِنَ الرَّجُلُ وَقَامَتِ الْبَيِّنَةُ، أَوْ كَانَ حَمْلٌ أَوِ اعْتِرَافٌ. وَقَدْ قَرَأْتُهَا: [الشَّيْخُ وَالشَّيْخَةُ إِذَا زَنَيَا فَارْجُمُوهُمَا الْبَتَّةَ] رَجَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَجَمْنَا بَعْدَهُ. (ق,د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) പറഞ്ഞു: കാലം അധികം പിന്നിടുമ്പോൾ ജനങ്ങൾ പറയുന്നത് ഞാൻ ഭയപ്പെടുന്നു: ഖുർആനിൽ എറിഞ്ഞുകൊല്ലണമെന്നു ഞാൻ കാണുന്നില്ല. അങ്ങനെ നിർബന്ധ കാര്യങ്ങളിൽ നിന്ന് ഒരു നിർബന്ധ കാര്യത്തെ ഉപേക്ഷിക്കുക മൂലം അവൻ വഴിപിഴക്കും. എന്നാൽ അറിയുക, വിവാഹിതനായ ഒരാൾ വ്യഭിചരിക്കുകയും അവനെതിരെ തെളിവ് ഉണ്ടാവുകയും ചെയ്താൽ അവനെ എറിഞ്ഞുകൊല്ലുകയെന്ന(ശിക്ഷ)ത് നീതിയാണ്. അല്ലെങ്കിൽ, ഗർഭമുണ്ടാവുകയോ അവൾ സമ്മതിക്കുകയോ ചെയ്താൽ. ഞാൻ വിശുദ്ധ ഖുർആനിൽ നിന്ന് വായിച്ചെടുത്തു: ''ഒരു വിവാഹിതനും വിവാഹിതയും അവിഹിത ബന്ധത്തിലേർപ്പെട്ടാൽ നിർബന്ധമായും അവർ രണ്ടുപേരെയും എറിഞ്ഞുകൊല്ലുക'' എന്ന്. നബി(സ)യും ശേഷം ഞങ്ങളും എറിഞ്ഞുകൊന്നിട്ടുണ്ട്. (ബു,മു,ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], 'الشَّيْخُ وَالشَّيْخَةُ إِذَا زَنَيَا فَارْجُمُوهُمَا الْبَتَّةَ', null, 457, 457, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ مَاعِزُ بْنُ مَالِكٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي زَنَيْتُ، فَأَعْرَضَ عَنْهُ، ثُمَّ قَالَ: إِنِّي قَدْ زَنَيْتُ. فَأَعْرَضَ عَنْهُ، ثُمَّ قَالَ: إِنِّي زَنَيْتُ. فَأَعْرَضَ عَنْهُ، ثُمَّ قَالَ: قَدْ زَنَيْتُ. فَأَعْرَضَ عَنْهُ، حَتَّى أَقَرَّ أَرْبَعَ مَرَّاتٍ، فَأَمَرَ بِهِ أَنْ يُرْجَمَ. فَلَمَّا أَصَابَتْهُ الْحِجَارَةُ أَدْبَرَ يَشْتَدُّ، فَلَقِيَهُ رَجُلٌ بِيَدِهِ لَحْيُ جَمَلٍ، فَضَرَبَهُ فَصَرَعَهُ، فَذُكِرَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِرَارُهُ حِينَ مَسَّتْهُ الْحِجَارَةُ، فَقَالَ: "فَهَلَّا تَرَكْتُمُوهُ". (جه)', 'അബൂഹുറൈറ(റ): മാഇസുബ്നു മാലിക്(റ) നബി(സ)യുടെ അടുത്തുവന്ന് പറഞ്ഞു: ഞാൻ വ്യഭിചരിച്ചു. നബി(സ) അത് ശ്രദ്ധിക്കാതെ തിരിഞ്ഞു കളഞ്ഞു. പിന്നെയും അദ്ദേഹം പറഞ്ഞു: ഞാൻ വ്യഭിചരിച്ചിട്ടുണ്ട്. നബി(സ) ഗൗനിച്ചില്ല. പിന്നെയും അദ്ദേഹം പറഞ്ഞു: ഞാൻ വ്യഭിചരിച്ചു. അപ്പോഴും നബി(സ) തിരിഞ്ഞുകളഞ്ഞു. വീണ്ടും അദ്ദേഹം പറഞ്ഞു: ഞാൻ വ്യഭിചരിച്ചു. അപ്പോഴും നബി(സ) ശ്രദ്ധിച്ചില്ല. അങ്ങിനെ നാല് പ്രാവശ്യം അദ്ദേഹം തറപ്പിച്ചു പറഞ്ഞു. തുടർന്ന് നബി(സ) അദ്ദേഹത്തെ എറിയാൻ ആജ്ഞാപിച്ചു. കല്ലേറ് കഠിനമായതിനാൽ അദ്ദേഹം പിന്തിരിഞ്ഞോടാൻ തുടങ്ങി. അങ്ങനെ ഒരാൾ ഒരട്ടകത്തിന്റെ താടിയെല്ലുകൊണ്ട് നേരിടുകയും അടിച്ചുവീഴ്ത്തുകയും ചെയ്തു. കല്ലേറേറ്റപ്പോൾ അദ്ദേഹം ഓടിയെന്ന കാര്യമവർ നബി(സ)യോട് പറഞ്ഞപ്പോൾ നബി(സ) അവരോടു ചോദിച്ചു: "നിങ്ങൾക്കദ്ദേഹത്തെ ഉപേക്ഷിച്ചു കൂടായിരുന്നോ?". (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 457, 457, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: {وَاللَّاتِي يَأْتِينَ الْفَاحِشَةَ مِنْ نِسَائِكُمْ فَاسْتَشْهِدُوا عَلَيْهِنَّ أَرْبَعَةً مِنْكُمْ فَإِنْ شَهِدُوا فَأَمْسِكُوهُنَّ فِي الْبُيُوتِ حَتَّى يَتَوَفَّاهُنَّ الْمَوْتُ أَوْ يَجْعَلَ اللَّهُ لَهُنَّ سَبِيلًا} [النساء:١٥]. وَذَكَرَ الرَّجُلَ بَعْدَ الْمَرْأَةِ ثُمَّ جَمَعَهُمَا، فَقَالَ: {وَاللَّذَانِ يَأْتِيَانِهَا مِنْكُمْ فَآذُوهُمَا فَإِنْ تَابَا وَأَصْلَحَا فَأَعْرِضُوا عَنْهُمَا} [النساء:١٦]. فَنَسَخَ ذَلِكَ بِآيَةِ الْجَلْدِ فَقَالَ: {الزَّانِيَةُ وَالزَّانِي فَاجْلِدُوا كُلَّ وَاحِدٍ مِنْهُمَا مِائَةَ جَلْدَةٍ} [النور:٢]. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): അദ്ദേഹം ഓതി: ''നിങ്ങളുടെ സ്ത്രീകളിൽ നിന്നും നീചവൃത്തി (വ്യഭിചാരം) ചെയ്യുന്നവരുടെ മേൽ നിങ്ങളിൽ (മുസ്ലിം പുരുഷൻമാരിൽനിന്നു) നാലുപേരെ സാക്ഷി നിറുത്തുവീൻ. അവർ (അവരുടെ മേൽ) അപ്രകാരം സാക്ഷിനിന്നാൽ അവരെ നിങ്ങൾ വീടുകളിൽ തടഞ്ഞുവെക്കുക, അവരെ മരണം പിടികൂടുന്നതുവരെ അല്ലെങ്കിൽ അല്ലാഹു അവർക്ക് ഒരുമാർഗ്ഗം നിശ്ചയിക്കുന്നതുവരെ.'' (അന്നിസാഅ്:15) സ്ത്രീയെ പരാമർശിച്ചതിന് ശേഷം പുരുഷനെ പറയുകയും പിന്നീട് രണ്ടിനെയും ഒരുമിച്ചു പറയുകയും ചെയ്തു. അദ്ദേഹം ഓതി: ''നിങ്ങളിൽനിന്നു അതു ചെയ്ത രണ്ടുപേർ അവർ ഇരുവരെയും (ശാസിക്കൽ കൊണ്ടും മറ്റും) ഉപദ്രവിക്കൂ. അവർ പശ്ചാത്തപിച്ചു മടങ്ങുകയും പ്രവർത്തനങ്ങൾ നന്നാക്കുകയും ചെയ്താൽ അവരെ നിങ്ങൾ ഒഴിവാക്കുക.'' (അന്നിസാഅ്: 16) അടിയുടെ സൂക്തം മുഖേന അല്ലാഹു അത് ദുർബലമാക്കി: ''വ്യഭിചാരിണിയെയും വ്യഭിചാരിയെയും നിങ്ങൾ നൂറടി അടിക്കുക.'' (അന്നൂർ:2). (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'النور:٢', null, 457, 458, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ مُجَاهِدٍ قَالَ: السَّبِيلُ الْحَدُّ، قَالَ سُفْيَانُ: {فَآذُوهُمَا} الْبِكْرَانِ {فَأَمْسِكُوهُنَّ فِي الْبُيُوتِ} الثَّيِّبَاتُ. (د)', 'മുജാഹിദ്(റ): അദ്ദേഹം പറഞ്ഞു: (വിശുദ്ധ ഖുർആനിൽ) ''സബീൽ'' എന്നതു കൊണ്ട് അർത്ഥമാക്കുന്നത് ഹദ്ദ് ആണ്. സുഫ്‌യാൻ(റ) പറഞ്ഞു: അവർ രണ്ടു പേരെയും നിങ്ങൾ ഉപദ്രവിക്കണമെന്ന് പറഞ്ഞതിന്റെ അർത്ഥം കന്യകകളാണ്. ''അവരെ വീട്ടിൽ പിടിച്ചുവെക്കുക'' എന്നതുകൊണ്ടുദ്ദേശിക്കുന്നത് വിവാഹിതരെയാണ്. (ദ)', 'مُجَاهِدٍ قَالَ', 'മുജാഹിദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 458, 458, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "خُذُوا عَنِّي، خُذُوا عَنِّي، قَدْ جَعَلَ اللَّهُ لَهُنَّ سَبِيلًا: الثَّيِّبُ بِالثَّيِّبِ جَلْدُ مِائَةٍ وَرَمْيٌ بِالْحِجَارَةِ". وفي رواية: "وَالرَّجْمُ. وَالْبِكْرُ بِالْبِكْرِ جَلْدُ مِائَةٍ وَنَفْيُ سَنَةٍ". (م,د,ت,جه)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്നിൽ നിന്ന് നിങ്ങൾ മനസ്സിലാക്കുക, എന്നിൽനിന്നു നിങ്ങൾ മനസ്സിലാക്കുക, (വ്യഭിചാരശിക്ഷയുടെ വിധി) അല്ലാഹു അവർക്ക് ഒരു മാർഗ്ഗമാക്കി: ഒരാൾ (വിവാഹിതൻ) മറ്റൊരു വിവാഹിതയുമായുള്ള അവിഹിത വേഴ്ചക്ക് നൂറടിയും കല്ലേറുമാണ് ശിക്ഷ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=5), 1, 'وَفِي رِوَايَةٍ: "وَالرَّجْمُ. وَالْبِكْرُ بِالْبِكْرِ جَلْدُ مِائَةٍ وَنَفْيُ سَنَةٍ". (م,د,ت,جه)', 'മറ്റൊരു നിവേദനം: "എന്നാൽ ഒരു അവിവാഹിതൻ ഒരവിവാഹിതയുമായി അവിഹിത ബന്ധത്തിലേർപ്പെട്ടാൽ നൂറടിയും ഒരു വർഷത്തേക്കു നാടു കടത്തലുമാണ്." (മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عِمْرَانَ بْنِ الْحُصَيْنِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاعْتَرَفَتْ بِالزِّنَا. فَأَمَرَ بِهَا فَشُكَّتْ عَلَيْهَا ثِيَابُهَا، ثُمَّ رَجَمَهَا، ثُمَّ صَلَّى عَلَيْهَا. وفي رواية: فَقَالَ نَاسٌ لِسَعْدِ بْنِ عُبَادَةَ رَضِيَ اللهُ عَنْهُ: يَا أَبَا ثَابِتٍ، قَدْ نَزَلَتِ الْحُدُودُ، لَوْ أَنَّكَ وَجَدْتَ مَعَ امْرَأَتِكَ رَجُلًا، كَيْفَ كُنْتَ صَانِعًا؟ قَالَ: كُنْتُ ضَارِبَهُمَا بِالسَّيْفِ حَتَّى يَسْكُتَا، أَفَأَنَا أَذْهَبُ فَأَجْمَعُ أَرْبَعَةَ شُهَدَاءٍ؟ فَإِلَى ذَلِكَ قَدْ قَضَى الْحَاجَةَ. فَانْطَلَقُوا فَاجْتَمَعُوا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: يَا رَسُولَ اللَّهِ، أَلَمْ تَرَ إِلَى أَبِي ثَابِتٍ قَالَ كَذَا وَكَذَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَفَى بِالسَّيْفِ شَاهِدًا". ثُمَّ قَالَ: "لَا، لَا، أَخَافُ أَنْ يَتَتَابَعَ فِيهَا السَّكْرَانُ وَالْغَيْرَانُ". (د,جه)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): ഒരു സ്ത്രീ നബി(സ)യുടെ അടുക്കൽ വന്ന് വ്യഭിചരിച്ചതായി സമ്മതിച്ചു. അപ്പോൾ നബി(സ) അവളെ എറിഞ്ഞു കൊല്ലാൻ ആജ്ഞാപിച്ചു. അവളുടെ വസ്ത്രം അവൾക്കുമേൽ ചുറ്റി. പിന്നീട് അവളെ എറിഞ്ഞു കൊന്നു. അവൾക്കു വേണ്ടി നമസ്കരിക്കുകയും ചെയ്തു. മറ്റൊരു റിപ്പോർട്ടിൽ ഇങ്ങനെയാണ്: ചിലർ സഅ്ദ്ബ്നു ഉബാദ(റ)വിനോട് ചോദിച്ചു: അബൂസാബിതേ, ശിക്ഷകൾ അല്ലാഹു നിർബന്ധമാക്കി. താങ്കളുടെ ഭാര്യയോടൊപ്പം ഒരു പുരുഷനെ കണ്ടാൽ താങ്കൾ എന്തു ചെയ്യും? അദ്ദേഹം പറഞ്ഞു: അവർ രണ്ടു പേരെയും ഞാൻ വാളുകൊണ്ടു കൊന്നുകളയും. ഞാൻ പോയി നാല് സാക്ഷികളുമായി വരുമ്പോഴേക്കും അവരുടെ ആവശ്യമെല്ലാമവർ നിർവ്വഹിച്ചു കഴിയില്ലേ. അങ്ങനെ അവർ പിരിഞ്ഞു പോയി. പിന്നീടവർ നബി(സ)യുടെ സവിധത്തിൽ ഒത്തുകൂടിയപ്പോൾ അവർ നബി(സ)യോട് പറഞ്ഞു: നബിയേ, അബൂസാബിത് ഇവ്വിധമൊക്കെ പറഞ്ഞു. താങ്കളുടെ അഭിപ്രായമെന്താണ്? അപ്പോൾ നബി(സ) പ്രതിവചിച്ചു: "വാളുകൊണ്ട് വെട്ടൽ തന്നെയാണ്." ശേഷം നബി(സ) പറഞ്ഞു: "അല്ല അങ്ങനെയല്ല, കോപവും വൈരാഗ്യവും അതിന്റെ പിന്നാലെയുണ്ടാകുമെന്നു ഞാൻ ഭയപ്പെടുന്നു." (ദ,ജ)', 'عِمْرَانَ بْنِ الْحُصَيْنِ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 458, 459, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=6), 1, 'وَفِي رِوَايَةٍ: فَقَالَ نَاسٌ لِسَعْدِ بْنِ عُبَادَةَ رَضِيَ اللهُ عَنْهُ: يَا أَبَا ثَابِتٍ، قَدْ نَزَلَتِ الْحُدُودُ، لَوْ أَنَّكَ وَجَدْتَ مَعَ امْرَأَتِكَ رَجُلًا، كَيْفَ كُنْتَ صَانِعًا؟ قَالَ: كُنْتُ ضَارِبَهُمَا بِالسَّيْفِ حَتَّى يَسْكُتَا، أَفَأَنَا أَذْهَبُ فَأَجْمَعُ أَرْبَعَةَ شُهَدَاءٍ؟ فَإِلَى ذَلِكَ قَدْ قَضَى الْحَاجَةَ. فَانْطَلَقُوا فَاجْتَمَعُوا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: يَا رَسُولَ اللَّهِ، أَلَمْ تَرَ إِلَى أَبِي ثَابِتٍ قَالَ كَذَا وَكَذَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَفَى بِالسَّيْفِ شَاهِدًا". ثُمَّ قَالَ: "لَا، لَا، أَخَافُ أَنْ يَتَتَابَعَ فِيهَا السَّكْرَانُ وَالْغَيْرَانُ". (د,جه)', 'മറ്റൊരു നിവേദനിൽ ഇങ്ങനെയാണ്: ചിലർ സഅ്ദ്ബ്നു ഉബാദ(റ)വിനോട് ചോദിച്ചു: അബൂസാബിതേ, ശിക്ഷകൾ അല്ലാഹു നിർബന്ധമാക്കി. താങ്കളുടെ ഭാര്യയോടൊപ്പം ഒരു പുരുഷനെ കണ്ടാൽ താങ്കൾ എന്തു ചെയ്യും? അദ്ദേഹം പറഞ്ഞു: അവർ രണ്ടു പേരെയും ഞാൻ വാളുകൊണ്ടു കൊന്നുകളയും. ഞാൻ പോയി നാല് സാക്ഷികളുമായി വരുമ്പോഴേക്കും അവരുടെ ആവശ്യമെല്ലാമവർ നിർവ്വഹിച്ചു കഴിയില്ലേ. അങ്ങനെ അവർ പിരിഞ്ഞു പോയി. പിന്നീടവർ നബി(സ)യുടെ സവിധത്തിൽ ഒത്തുകൂടിയപ്പോൾ അവർ നബി(സ)യോട് പറഞ്ഞു: നബിയേ, അബൂസാബിത് ഇവ്വിധമൊക്കെ പറഞ്ഞു. താങ്കളുടെ അഭിപ്രായമെന്താണ്? അപ്പോൾ നബി(സ) പ്രതിവചിച്ചു: "വാളുകൊണ്ട് വെട്ടൽ തന്നെയാണ്." ശേഷം നബി(സ) പറഞ്ഞു: "അല്ല അങ്ങനെയല്ല, കോപവും വൈരാഗ്യവും അതിന്റെ പിന്നാലെയുണ്ടാകുമെന്നു ഞാൻ ഭയപ്പെടുന്നു." (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ نُعَيْمِ بْنِ هَزَّالٍ قَالَ: كَانَ مَاعِزُ بْنُ مَالِكٍ يَتِيمًا فِي حِجْرِ أَبِي فَأَصَابَ جَارِيَةً مِنَ الْحَيِّ، فَقَالَ لَهُ أَبِي: ائْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبِرْهُ بِمَا صَنَعْتَ، لَعَلَّهُ يَسْتَغْفِرُ لَكَ. وَإِنَّمَا يُرِيدُ بِذَلِكَ رَجَاءَ أَنْ يَكُونَ لَهُ مَخْرَجًا، فَأَتَاهُ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي زَنَيْتُ فَأَقِمْ عَلَيَّ كِتَابَ اللَّهِ. فَأَعْرَضَ عَنْهُ، فَعَادَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي زَنَيْتُ فَأَقِمْ عَلَيَّ كِتَابَ اللَّهِ. فَأَعْرَضَ عَنْهُ، فَعَادَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي زَنَيْتُ فَأَقِمْ عَلَيَّ كِتَابَ اللَّهِ. حَتَّى قَالَهَا أَرْبَعَ مِرَارٍ، قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّكَ قَدْ قُلْتَهَا أَرْبَعَ مَرَّاتٍ، فَبِمَنْ". قَالَ: بِفُلَانَةٍ، فَقَالَ: "هَلْ ضَاجَعْتَهَا". قَالَ: نَعَمْ، قَالَ: "هَلْ بَاشَرْتَهَا". قَالَ: نَعَمْ، قَالَ: "هَلْ جَامَعْتَهَا". قَالَ: نَعَمْ، قَالَ: فَأَمَرَ بِهِ أَنْ يُرْجَمَ، فَأُخْرِجَ بِهِ إِلَى الْحَرَّةِ، فَلَمَّا رُجِمَ فَوَجَدَ مَسَّ الْحِجَارَةِ جَزِعَ فَخَرَجَ يَشْتَدُّ، فَلَقِيَهُ عَبْدُ اللَّهِ بْنُ أُنَيْسٍ وَقَدْ عَجَزَ أَصْحَابُهُ فَنَزَعَ لَهُ بِوَظِيفِ بَعِيرٍ فَرَمَاهُ بِهِ فَقَتَلَهُ، ثُمَّ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ: "هَلَّا تَرَكْتُمُوهُ، لَعَلَّهُ أَنْ يَتُوبَ فَيَتُوبَ اللَّهُ عَلَيْهِ". (د)', 'നുഐമുബ്നു ഹസ്സാൽ(റ): മാഇസുബ്നു മാലിക്(റ) എന്റെ പിതാവിന്റെ പരിപാലനത്തിൽ വളർന്ന ഒരു അനാഥനായിരുന്നു. അങ്ങനെ അദ്ദേഹം ഒരു അടിമസ്ത്രീയുമായി അവിഹിത വേഴ്ചയിലേർപ്പെട്ടു അപ്പോൾ എന്റെ പിതാവ് അദ്ദേഹത്തോടു പറഞ്ഞു: നീ നബി(സ)യുടെ അടുത്തുപോയി ചെയ്ത തെറ്റു പറയുക. നബ(സ) നിനക്കു മാപ്പപേക്ഷിക്കുമായിരിക്കും. അതുമുഖേന അദ്ദേഹം ഉദ്ദേശിച്ചത് മാഇസിന് രക്ഷനേടാനാവുമെന്നാണ്. അങ്ങനെ അദ്ദേഹം നബി(സ)യുടെ അടുത്തു ചെന്നു പറഞ്ഞു: നബിയേ, ഞാൻ വ്യഭിചരിച്ചു. അല്ലാഹുവിന്റെ വിധി എന്റെ മേൽ നടപ്പാക്കുക. അപ്പോൾ നബി(സ) തിരിഞ്ഞു കളഞ്ഞു. വീണ്ടുമദ്ദേഹം ചെന്നു പറഞ്ഞു: ഞാൻ വ്യഭിചരിച്ചു, എന്റെ മേൽ അല്ലാഹുവിന്റെ വിധി നടപ്പാക്കണം. അപ്പോഴും നബി(സ) അദ്ദേഹത്തെ ശ്രദ്ധിച്ചില്ല. വീണ്ടുമദ്ദേഹം വന്ന് പറഞ്ഞു: ഞാൻ വ്യഭിചരിച്ചു. എന്റെ മേൽ അല്ലാഹുവിന്റെ വിധി നടപ്പാക്കണം. അങ്ങനെ നാലു പ്രാവശ്യം അദ്ദേഹം നബി(സ)യോടിതാവർത്തിച്ചു. "നീ ഇതു നാലു പ്രാവശ്യമായി പറയുന്നു, നീ ആരുമായാണു വ്യഭിചരിച്ചത്?" നബി(സ) ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: ഇന്നവളുമായാണ്. നബി(സ) ചോദിച്ചു: "നീ അവളുടെ കൂടെ കിടന്നുവോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. തിരുമേനി(സ) ചദിച്ചു: "നീ അവളെ സ്പർശിച്ചിട്ടുണ്ടോ?" അദ്ദേഹം: അതെ. തിരുമേനി(സ) ചോദിച്ചു: "അവളുമായി ശാരീരിക ബന്ധത്തിലേർപ്പെട്ടിട്ടുണ്ടോ?" അതെ, അദ്ദേഹം പ്രതിവചിച്ചു. നിവേദകൻ: അദ്ദേഹത്തെ എറിഞ്ഞു കൊല്ലാൻ നബി(സ) കൽപിച്ചു. അങ്ങനെ അദ്ദേഹത്തെ ''ഹർറ''(കല്ലുകൾ കൂടിയ ഒരു സ്ഥലം)യിലേക്കു കൊണ്ടുപോയി, എറിയാൻ തുടങ്ങി. കല്ല് അദ്ദേഹത്തിന്റെ ശരീരത്തിലേറ്റപ്പോൾ അസഹ്യത കാരണം ഓടാൻ ആരംഭിച്ചു. അപ്പോൾ അബ്ദുല്ലാഹിബ്നു ഉനൈസ്(റ) അദ്ദേഹത്തെ നേരിടുകയും - അദ്ദേഹത്തിന്റെ കൂട്ടാളികൾ ക്ഷീണിതരായിരുന്നു - ഒരൊട്ടകത്തിന്റെ കൈയെല്ല് എടുത്ത് എറിയുകയും അങ്ങനെ അദ്ദേഹത്തെ വധിക്കുകയും ചെയ്തു. എന്നിട്ടദ്ദേഹം നബി(സ)യുടെയടുത്ത് വരികയും വിവരം പറയുകയും ചെയ്തു. അപ്പോൾ നബി(സ) അവരോടു പ്രതിവചിച്ചു: "നിങ്ങൾക്കദ്ദേഹത്തെ വെറുതെവിട്ടുകൂടായിരുന്നില്ലേ? അദ്ദേഹം തൗബ ചെയ്യുകയും അല്ലാഹു അദ്ദേഹത്തിന് മാപ്പുകൊടുക്കുകയും ചെയ്യുമായിരുന്നില്ലേ?" (ദ)', 'نُعَيْمِ بْنِ هَزَّالٍ قَالَ', 'നുഐമുബ്നു ഹസ്സാൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 459, 460, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ مُحَمَّدِ بْنِ إِسْحَقَ قَالَ: ذَكَرْتُ لِعَاصِمِ بْنِ عُمَرَ ابْنِ قَتَادَةَ قِصَّةَ مَاعِزِ ابْنِ مَالِكٍ، فَقَالَ لِي: حَدَّثَنِي حَسَنُ بْنُ مُحَمَّدِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: حَدَّثَنِي ذَلِكَ مِنْ قَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَهَلَّا تَرَكْتُمُوهُ" مَنْ شِئْتُمْ مِنْ رِجَالِ أَسْلَمَ مِمَّنْ لَا أَتَّهِمُ، قَالَ: وَلَمْ أَعْرِفْ هَذَا الْحَدِيثَ، قَالَ: فَجِئْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا فَقُلْتُ: إِنَّ رِجَالًا مِنْ أَسْلَمَ يُحَدِّثُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُمْ - حِينَ ذَكَرُوا لَهُ جَزَعَ مَاعِزٍ مِنَ الْحِجَارَةِ حِينَ أَصَابَتْهُ -: "أَلَّا تَرَكْتُمُوهُ" وَمَا أَعْرِفُ الْحَدِيثَ؟ قَالَ: يَا ابْنَ أَخِي، أَنَا أَعْلَمُ النَّاسِ بِهَذَا الْحَدِيثِ، كُنْتُ فِيمَنْ رَجَمَ الرَّجُلَ، إِنَّا لَمَّا خَرَجْنَا بِهِ فَرَجَمْنَاهُ فَوَجَدَ مَسَّ الْحِجَارَةِ صَرَخَ بِنَا: يَا قَوْمُ رُدُّونِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَإِنَّ قَوْمِي قَتَلُونِي وَغَرُّونِي مِنْ نَفْسِي، وَأَخْبَرُونِي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَيْرُ قَاتِلِي. فَلَمْ نَنْزِعْ عَنْهُ حَتَّى قَتَلْنَاهُ، فَلَمَّا رَجَعْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَخْبَرْنَاهُ قَالَ: "فَهَلَّا تَرَكْتُمُوهُ وَجِئْتُمُونِي بِهِ". لِيَسْتَثْبِتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهُ، فَأَمَّا لِتَرْكِ حَدٍّ فَلَا، قَالَ: فَعَرَفْتُ وَجْهَ الْحَدِيثِ. (ق,د,ت,ن)', 'മുഹമ്മദുബ്നു ഇസ്ഹാഖ്: ആസിമുബ്നു ഉമറുബ്നു ഖതാദയോട് മാഇസുബ്നു മാലിക്(റ)വിന്റെ സംഭവം ഞാൻ പറഞ്ഞു. അപ്പോൾ അദ്ദേഹം എന്നോട് പറഞ്ഞു: ഹസനുബ്നു മുഹമ്മദിബ്നി അലിയ്യിബ്നി അബീത്വാലിബ്(റ) എന്നോട് പറഞ്ഞു: "നിങ്ങൾക്കദ്ദേഹത്തെ വെറുതെവിട്ടുകൂടായിരുന്നോ" എന്നത് നബി(സ)യുടെ വാക്കാണെന്ന്, നിങ്ങളുദ്ദേശിക്കുന്ന, അസ്‌ലം ഗോത്രത്തിലെ ഞാൻ സംശയിക്കാത്ത ചിലയാളുകൾ എന്നോട് പറഞ്ഞിട്ടുണ്ട്. നിവേദകൻ: എന്നാൽ ഈ ഹദീസ് എനിക്കറിയില്ലായിരുന്നു. നിവേദകൻ: അതിനാൽ ഞാൻ ജാബിറുബ്നു അബ്ദില്ല(റ)വിന്റെയടുക്കൽ ചെന്ന് പറഞ്ഞു: മാഇസ്(റ)വിന് ഏറേറ്റപ്പോൾ അദ്ദേഹത്തിനുണ്ടായ അസഹ്യത സ്വഹാബികൾ റസൂൽ(സ)യോട് വിവരിച്ചപ്പോൾ "നിങ്ങൾക്കദ്ദേഹത്തെ വെറുതെവിട്ടുകൂടായിരുന്നില്ലേ" എന്ന് തിരുമേനി(സ) അവരോട് പറഞ്ഞുവെന്ന് അസ്‌ലം ഗോത്രത്തിലെ ചിലയാളുകൾ ഉദ്ധരിക്കുന്നു. ഈ ഹദീസ് എനിക്കറിയില്ലല്ലോ? അപ്പോൾ ജാബിർ(റ) പറഞ്ഞു: എന്റെ സഹോദരപുത്രാ, ഈ ഹദീസിനെക്കുറിച്ച് ജനങ്ങളിൽ കൂടുതൽ അറിയുക എനിക്കാണ്. ഞാനും അദ്ദേഹത്തെ എറിഞ്ഞവരിലംഗമാണ്. ഞങ്ങൾ അദ്ദേഹത്തെ കൊണ്ടുപോയി എറിഞ്ഞു. കല്ല് ശരീരത്തിലേറ്റപ്പോൾ അദ്ദേഹം അട്ടഹസിച്ചു: കൂട്ടരേ, എന്നെ നബി(സ)യുടെ അടുത്തു കൊണ്ടുപോവുക. എന്റെ സമൂഹമെന്നെ വധിക്കുന്നു. അവർ എന്നെ വഞ്ചിച്ചു. റസൂൽ(സ) എന്നെ വധിക്കുകയില്ലെന്ന് അവർ എന്നോട് പറഞ്ഞിരുന്നു. അങ്ങനെ അദ്ദേഹത്തെ മരിക്കുന്നതു വരെ ഞങ്ങൾ എറിഞ്ഞു കൊണ്ടിരുന്നു. അങ്ങിനെ ശേഷം ഞങ്ങൾ നബി(സ)യുടെ അടുത്തു ചെല്ലുകയും വിവരം പറയുകയും ചെയ്തപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്കദ്ദേഹത്തെ (ഏറുനിർത്തി) ഇങ്ങോട്ട് കൊണ്ടു വന്നുകൂടായിരുന്നോ?" ഇതിന്റെ ഉറപ്പിനെ കുറിച്ചന്വേഷിക്കാൻ വേണ്ടിയായിരുന്നു നബി(സ) അങ്ങനെ ചോദിച്ചത്, ഹദ്ദ് ഉപേക്ഷിക്കാൻ വേണ്ടിയായിരുന്നില്ല. നിവേദകൻ: അങ്ങനെ ഈ ഹദീസിന്റെ രൂപം ഞാൻ അറിഞ്ഞു. (ബു,മു,ദ,തു,ന)', 'مُحَمَّدِ بْنِ إِسْحَقَ قَالَ', 'മുഹമ്മദുബ്നു ഇസ്ഹാഖ്', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 460, 460, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ مَاعِزَ بْنَ مَالِكٍ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّهُ زَنَى، فَأَعْرَضَ عَنْهُ، فَأَعَادَ عَلَيْهِ مِرَارًا، فَأَعْرَضَ عَنْهُ، فَسَأَلَ قَوْمَهُ: "أَمَجْنُونٌ هُوَ". قَالُوا: لَيْسَ بِهِ بَأْسٌ، قَالَ: "أَفَعَلْتَ بِهَا" قَالَ: نَعَمْ، فَأَمَرَ بِهِ أَنْ يُرْجَمَ، فَانْطُلِقَ بِهِ فَرُجِمَ، وَلَمْ يُصَلِّ عَلَيْهِ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): മാഇസുബ്നു മാലിക് നബി(സ)യുടെയടുക്കൽ വന്ന്, അദ്ദേഹം വ്യഭിചരിച്ചിരിക്കുന്നു എന്ന് പറഞ്ഞു. അപ്പോൾ നബി(സ) തിരിഞ്ഞുകളഞ്ഞു. അങ്ങനെ ഇത് ഏതാനും പ്രാവശ്യം ആവർത്തിച്ചു. അപ്പോഴും നബി(സ) തിരിഞ്ഞുകളഞ്ഞു. എന്നിട്ട് ജനങ്ങളോടു ചോദിച്ചു: "ഇദ്ദേഹം ഭ്രാന്തനാണോ?" അവർ പറഞ്ഞു: അദ്ദേഹത്തിന് ഒരു ഭ്രാന്തുമില്ല. നബി(സ) അദ്ദേഹത്തോടു ചോദിച്ചു: "നീ അവളുമായി വ്യഭിചരിച്ചുവോ?" അതെ, അദ്ദേഹം മറുപടി പറഞ്ഞു. അപ്പോൾ നബി(സ) അദ്ദേഹത്തെ എറിഞ്ഞു കൊല്ലാൻ ആജ്ഞാപിച്ചു. അങ്ങനെ അദ്ദേഹത്തെ കൊണ്ടുപോയി എറിഞ്ഞു. അദ്ദേഹത്തിന്റെ മേൽ നിസ്കരിച്ചില്ല. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 460, 461, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ مَاعِزَ بْنَ مَالِكٍ حِينَ جِيءَ بِهِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَجُلًا قَصِيرًا أَعْضَلَ لَيْسَ عَلَيْهِ رِدَاءٌ، فَشَهِدَ عَلَى نَفْسِهِ أَرْبَعَ مَرَّاتٍ أَنَّهُ قَدْ زَنَى، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَلَعَلَّكَ قَبَّلْتَهَا". قَالَ: لَا وَاللَّهِ، إِنَّهُ قَدْ زَنَى الْآخِرُ. قَالَ: فَرَجَمَهُ، ثُمَّ خَطَبَ فَقَالَ: "أَلَا كُلَّمَا نَفَرْنَا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ خَلَفَ أَحَدُهُمْ لَهُ نَبِيبٌ كَنَبِيبِ التَّيْسِ، يَمْنَحُ إِحْدَاهُنَّ الْكُثْبَةَ، أَمَا إِنَّ اللَّهَ إِنْ يُمَكِّنِّي مِنْ أَحَدٍ مِنْهُمْ إِلَّا نَكَلْتُهُ عَنْهُنَّ". وفي رواية: فَرَدَّهُ مَرَّتَيْنِ. وفي رواية: إِنَّهُ رَدَّهُ أَرْبَعَ مَرَّاتٍ. (م,د)', 'ജാബിറുബ്നു സമുറ(റ): മാഇസുബ്നു മാലികിനെ നബി(സ)യുടെ അടുക്കൽ കൊണ്ടുവന്നപ്പോൾ ഞാൻ അദ്ദേഹത്തെ കണ്ടു. അദ്ദേഹം നീളം കുറഞ്ഞ പേശികൾ മുറുകിയ ഒരാളായിരുന്നു. അദ്ദേഹത്തിന്റെ മേൽമുണ്ട് ഉണ്ടായിരുന്നില്ല. അദ്ദേഹം വ്യഭിചരിച്ചിട്ടുണ്ടെന്നു നാലു പ്രാവശ്യം സ്വയം സാക്ഷ്യം വഹിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ അവളെ ചുംബിച്ചതാകും." അദ്ദേഹം പറഞ്ഞു: അല്ല, അതു തികച്ചും നീചമായ വ്യഭിചാരം തന്നെയായിരുന്നു. അങ്ങനെ അദ്ദേഹത്തിന് ശിക്ഷ നടപ്പാക്കുകയും ചെയ്തു. ശേഷം നബി(സ) ഒരു പ്രസംഗം നടത്തി. അതിൽ നബി(സ) പറഞ്ഞു: "അറിയുക, നാം അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധത്തിനിറങ്ങുമ്പോഴെല്ലാം അവരിൽനിന്നൊരാൾ പിന്മാറും. അവന് വികാരമുണ്ടാകുകയും അവൻ കൂറ്റനാടിന്റേതു പോലെ വികാരശബ്ദമുണ്ടാക്കുകയും ചെയ്യും. അവരിലൊരാൾ മറ്റൊരാൾക്ക് അൽപം പാൽ നൽകുകയും ചെയ്യും. എന്നാൽ അറിയുക, അവരെ എനിക്ക് ശിക്ഷകൾ പറഞ്ഞു പിന്തിരിപ്പിക്കാനല്ലാതെ സാധ്യമല്ല." ചില റിപ്പോർട്ടിൽ അദ്ദേഹത്തെ രണ്ടു പ്രാവശ്യം മടക്കിയെന്നും ചില റിപ്പോർട്ടിൽ നാലു പ്രാവശ്യം മടക്കിയെന്നുമുണ്ട്. (മു,ദ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 461, 461, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=10), 1, 'وَفِي رِوَايَةٍ: فَرَدَّهُ مَرَّتَيْنِ.', null);
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=10), 2, 'وَفِي رِوَايَةٍ: إِنَّهُ رَدَّهُ أَرْبَعَ مَرَّاتٍ. (م,د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِمَاعِزِ بْنِ مَالِكٍ: "أَحَقٌّ مَا بَلَغَنِي عَنْكَ". قَالَ: وَمَا بَلَغَكَ عَنِّي؟ قَالَ: "بَلَغَنِي عَنْكَ أَنَّكَ وَقَعْتَ عَلَى جَارِيَةِ بَنِي فُلَانٍ". قَالَ: نَعَمْ فَشَهِدَ أَرْبَعَ شَهَادَاتٍ، فَأَمَرَ بِهِ فَرُجِمَ. (م,د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): മാഇസുബ്നു മാലികിനോട് നബി(സ) ചോദിച്ചു: "നിന്നെ സംബന്ധിച്ച് എനിക്കു ലഭിച്ചത് സത്യമാണോ?" മാഇസ് ചോദിച്ചു: എന്നെസംബന്ധിച്ച് എന്താണു വിവരം ലഭിച്ചത്? നബി(സ) പറഞ്ഞു: "ഇന്ന കുടുംബത്തിലെ അടിമസ്ത്രീയുമായി നീ വ്യഭിചരിച്ചിരിക്കുന്നു എന്ന്." അതെ, ശരിയാണ്, മാഇസ് പറഞ്ഞു. അങ്ങനെ നാല് പ്രാവശ്യം സമ്മതിക്കുകയും ചെയ്തു. അപ്പോൾ അദ്ദേഹത്തെ എറിഞ്ഞുകൊല്ലാൻ നബി(സ) ആജ്ഞാപിക്കുകയും എറിയപ്പെടുകയും ചെയ്തു. (മു,ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 461, 461, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ مَاعِزُ بْنُ مَالِكٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاعْتَرَفَ بِالزِّنَا مَرَّتَيْنِ فَطَرَدَهُ، ثُمَّ جَاءَ فَاعْتَرَفَ بِالزِّنَا مَرَّتَيْنِ، فَقَالَ: "شَهِدْتَ عَلَى نَفْسِكَ أَرْبَعَ مَرَّاتٍ، اذْهَبُوا بِهِ فَارْجُمُوهُ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): മാഇസുബ്നു മാലിക് നബി(സ)യുടെ അടുക്കൽ വന്ന് വ്യഭിചരിച്ചതായി രണ്ടു പ്രാവശ്യം സമ്മതിച്ചു. അപ്പോൾ നബി(സ) അദ്ദേഹത്തെ അകറ്റി. വീണ്ടും വന്ന് രണ്ട് പ്രാവശ്യം സമ്മതിച്ചു. നബി(സ) പറഞ്ഞു: "നാലു പ്രാവശ്യം നീ സ്വശരീരത്തിനെതിരെ സാക്ഷ്യം വഹിച്ചിരിക്കുന്നു. ആയതിനാൽ ഇദ്ദേഹത്തെ നിങ്ങൾ കൊണ്ടുപോയി എറിയുക." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 461, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِمَاعِزِ بْنِ مَالِكٍ: "لَعَلَّكَ قَبَّلْتَ أَوْ غَمَزْتَ أَوْ نَظَرْتَ". قَالَ: لَا، قَالَ: "أَفَنِكْتَهَا". قَالَ: نَعَمْ، قَالَ: فَعِنْدَ ذَلِكَ أَمَرَ بِرَجْمِهِ. (د,خ)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മാഇസുബ്നു മാലികിനോട് പറഞ്ഞു: "നീ ചുംബിക്കുകയോ സ്പർശിക്കുകയോ നോക്കുകയോ ആയിരിക്കും ചെയ്തിട്ടുണ്ടാവുക." അദ്ദേഹം പറഞ്ഞു: അല്ല. നബി(സ) ചോദിച്ചു: "നീ അവളെ വ്യഭിചരിച്ചുവോ?" അതെ, അദ്ദേഹം പറഞ്ഞു. അങ്ങനെ അദ്ദേഹത്തെ എറിഞ്ഞുകൊല്ലാൻ നബി(സ) കൽപിച്ചു. (ബു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','خ']::text[], array['ബു','ദ']::text[], null, null, 462, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ الْأَسْلَمِيُّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَشَهِدَ عَلَى نَفْسِهِ أَنَّهُ أَصَابَ امْرَأَةً حَرَامًا أَرْبَعَ مَرَّاتٍ، كُلُّ ذَلِكَ يُعْرِضُ عَنْهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَقْبَلَ فِي الْخَامِسَةِ فَقَالَ: "أَنِكْتَهَا". قَالَ: نَعَمْ، قَالَ: "حَتَّى غَابَ ذَلِكَ مِنْكَ فِي ذَلِكَ مِنْهَا". قَالَ: نَعَمْ، قَالَ: "كَمَا يَغِيبُ الْمِرْوَدُ فِي الْمُكْحُلَةِ وَالرِّشَاءُ فِي الْبِئْرِ". قَالَ: نَعَمْ، قَالَ: "فَهَلْ تَدْرِي مَا الزِّنَا". قَالَ: نَعَمْ، أَتَيْتُ مِنْهَا حَرَامًا مَا يَأْتِي الرَّجُلُ مِنِ امْرَأَتِهِ حَلَالًا. قَالَ: "فَمَا تُرِيدُ بِهَذَا الْقَوْلِ". قَالَ: أُرِيدُ أَنْ تُطَهِّرَنِي، فَأَمَرَ بِهِ فَرُجِمَ، فَسَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلَيْنِ مِنْ أَصْحَابِهِ يَقُولُ أَحَدُهُمَا لِصَاحِبِهِ: انْظُرْ إِلَى هَذَا الَّذِي سَتَرَ اللَّهُ عَلَيْهِ فَلَمْ تَدَعْهُ نَفْسُهُ حَتَّى رُجِمَ رَجْمَ الْكَلْبِ. فَسَكَتَ عَنْهُمَا، ثُمَّ سَارَ سَاعَةً حَتَّى مَرَّ بِجِيفَةِ حِمَارٍ شَائِلٍ بِرِجْلِهِ، فَقَالَ: "أَيْنَ فُلَانٌ وَفُلَانٌ". فَقَالَا: نَحْنُ ذَانِ يَا رَسُولَ اللَّهِ، قَالَ: "انْزِلَا فَكُلَا مِنْ جِيفَةِ هَذَا الْحِمَارِ". فَقَالَا: يَا نَبِيَّ اللَّهِ، مَنْ يَأْكُلُ مِنْ هَذَا؟ قَالَ: "فَمَا نِلْتُمَا مِنْ عِرْضِ أَخِيكُمَا آنِفًا أَشَدُّ مِنْ أَكْلٍ مِنْهُ، وَالَّذِي نَفْسِي بِيَدِهِ إِنَّهُ الْآنَ لَفِي أَنْهَارِ الْجَنَّةِ يَنْقَمِسُ فِيهَا". وفي رواية: رُبِطَ إِلَى شَجَرَةٍ، وَقَالَ بَعْضُهُمْ: وُقِفَ. (د)', 'അബൂഹുറൈറ(റ): അസ്‌ലമിയ്യ് (മാഇസുബ്നു മാലിക്) നബി(സ)യുടെ അടുക്കൽ വന്ന് അദ്ദേഹം ഒരന്യസത്രീയുമായി അവിഹിത വേഴ്ചയിലേർപ്പെട്ടുവെന്നു നാല് പ്രാവശ്യം സാക്ഷ്യം വഹിച്ചു. അപ്പോഴെല്ലാം അത് നബി(സ) അവഗണിച്ചു. അഞ്ചാം പ്രാവശ്യവുമദ്ദേഹം ആവർത്തിക്കാൻ ആരംഭിച്ചപ്പോൾ നബി(സ) ചോദിച്ചു: "നീ അവളുമായി വ്യഭിചരിച്ചോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. നബി(സ) ചോദിച്ചു: "നിന്റെ അത് അവളുടെ അതിൽ മറയുവോളം?" അതെ, അദ്ദേഹം മറുപടി പറഞ്ഞു. നബി(സ) ചോദിച്ചു: "സുറുമക്കോൽ സുറുമക്കുപ്പിയിലും തൊട്ടിയുടെ കയർ കിണറ്റിലും പ്രവേശിക്കും പ്രകാരം കടന്നുവോ?" അതെ, അദ്ദേഹം പ്രതിവചിച്ചു. നബി(സ) ചോദിച്ചു: "വ്യഭിചാരമെന്താണെന്നു നിനക്കറിയുമോ?" അതെ എനിക്കറിയാം. ഒരാൾ തന്റെ ഭാര്യയുമായി അനുവദനീയമായതു ചെയ്യുന്നതിനു പകരം ഞാൻ അവളുമായി നിഷിദ്ധമായതു ചെയ്തു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "നീ ഈ പറയുന്നതുകൊണ്ടു എന്താണർത്ഥമാക്കുന്നത്?" അദ്ദേഹം പറഞ്ഞു: അവിടുന്നെന്നെ ശുദ്ധീകരിക്കണം. അങ്ങനെ നബി(സ) എറിഞ്ഞുകൊല്ലാൻ നിർദേശിക്കുകയും ശിക്ഷ നടപ്പാക്കുകയും ചെയ്തു. അപ്പോൾ രണ്ടുപേരിൽ ഒരാൾ മറ്റൊരാളോടു പറയുന്നതായി നബി(സ) ശ്രദ്ധിച്ചു: ഇദ്ദേഹത്തെ നോക്കൂ, ഇദ്ദേഹം ചെയ്ത തെറ്റ് അല്ലാഹു മറച്ചുവെങ്കിലും അദ്ദേഹം സ്വശരീരത്തെ വെറുതെ വിട്ടില്ല. അങ്ങിനെ നായയെ എറിയുന്നതുപോലെ അദ്ദേഹം എറിഞ്ഞുകൊല്ലപ്പെട്ടു. അപ്പോൾ നബി(സ) മൗനം ഭഞ്ജിച്ചു. പിന്നീട് ഒരു കഴുതയുടെ ശവത്തിനരികിലൂടെ നബി(സ) നടന്നുപോകവെ അവിടുന്ന് ചോദിച്ചു: "എവിടെ ആ രണ്ടു പേർ?" അവർ പറഞ്ഞു: ഇതാ ഞങ്ങളിവിടെ. നബി(സ) പറഞ്ഞു: "ഇതാ രണ്ടു പേരും ഈ കഴുതയുടെ ശവം തിന്നൂ." അവർ ചോദിച്ചു: ആരാണു നബിയേ ഈ ശവം തിന്നുക? നബി(സ) പറഞ്ഞു: "അൽപം മുമ്പ് നിങ്ങളുടെ സഹോദരന്റെ അഭിമാനം ഹനിച്ചത് ഇത് തിന്നുന്നതിനേക്കാളും കഠിനമാണ്. അല്ലാഹുവാണ, അദ്ദേഹമിപ്പോൾ സ്വർഗ്ഗത്തിലെ നദികളിൽ ഊളിയിട്ടുകളിക്കുകയാണ്." ചില റിപ്പോർട്ടുകളിൽ: അദ്ദേഹത്തെ മരത്തിൽ ബന്ധിക്കപ്പെട്ടു. ചിലർ പറഞ്ഞു: അദ്ദേഹം അവിടെ നിർത്തപ്പെട്ടു. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 462, 463, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=14), 1, 'وَفِي رِوَايَةٍ: رُبِطَ إِلَى شَجَرَةٍ، وَقَالَ بَعْضُهُمْ: وُقِفَ. (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَجُلًا مِنْ أَسْلَمَ جَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاعْتَرَفَ بِالزِّنَا، فَأَعْرَضَ عَنْهُ، ثُمَّ اعْتَرَفَ فَأَعْرَضَ عَنْهُ، حَتَّى شَهِدَ عَلَى نَفْسِهِ أَرْبَعَ شَهَادَاتٍ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَبِكَ جُنُونٌ". قَالَ: لَا، قَالَ: "أُحْصِنْتَ". قَالَ: نَعَمْ، قَالَ: فَأَمَرَ بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُجِمَ فِي الْمُصَلَّى، فَلَمَّا أَذْلَقَتْهُ الْحِجَارَةُ فَرَّ، فَأُدْرِكَ فَرُجِمَ حَتَّى مَاتَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْرًا، وَلَمْ يُصَلِّ عَلَيْهِ. (ق,د,ت,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): അസ്‌ലം ഗോത്രത്തിലെ ഒരാൾ നബി(സ)യുടെയടുക്കൽ വന്ന് വ്യഭിചരിച്ചതായി ഏറ്റുപറഞ്ഞു. നബി(സ) അതു ഗൗനിക്കാതെ തിരിഞ്ഞുകളഞ്ഞു. വീണ്ടും ഏറ്റുപറഞ്ഞപ്പോഴും നബി(സ) തിരിഞ്ഞുകളഞ്ഞു. അങ്ങിനെ നാലുപ്രാവശ്യം സ്വന്തത്തിനെതിരെ അദ്ദേഹം സാക്ഷ്യം വഹിച്ചു. അപ്പോൾ നബി(സ) അദ്ദേഹത്തോടു ചോദിച്ചു: "നിനക്ക് വല്ല ഭ്രാന്തുമുണ്ടോ?" ഇല്ല, അദ്ദേഹം പ്രതിവചിച്ചു. നബി(സ) പ്രതിവചിച്ചു: "നീ വിവാഹംകഴിക്കുകയും ബന്ധപ്പെടുകയും ചെയ്തിട്ടുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. അങ്ങനെ നബി(സ) ശിക്ഷ നടപ്പാക്കാൻ കൽപിച്ചു. അങ്ങനെ അദ്ദേഹത്തെ മൈതാനത്തു കൊണ്ടുപോയി ശിക്ഷ നടപ്പാക്കി. എറിയുന്ന അവസരത്തിൽ കല്ല് അദ്ദേഹത്തിന്റെ മേൽ പതിഞ്ഞപ്പോൾ അദ്ദേഹം ഓടി. അദ്ദേഹത്തെ പിടികൂടി എറിഞ്ഞു. അനന്തരം അദ്ദേഹം മരിച്ചു. അപ്പോൾ നബി(സ) അദ്ദേഹത്തെ സംബന്ധിച്ച് നല്ലതുപറഞ്ഞു. അവിടുന്ന് അദ്ദേഹത്തിന്റെ മേൽ നമസ്കരിച്ചില്ല. (ബു,മു,ദ,തു,ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 463, 463, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا أَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَجْمِ مَاعِزِ بْنِ مَالِكٍ خَرَجْنَا بِهِ إِلَى الْبَقِيعِ، فَوَاللَّهِ مَا أَوْثَقْنَاهُ وَلَا حَفَرْنَا لَهُ، وَلَكِنَّهُ قَامَ لَنَا، فَرَمَيْنَاهُ بِالْعِظَامِ وَالْمَدَرِ وَالْخَزَفِ، فَاشْتَدَّ وَاشْتَدَدْنَا خَلْفَهُ حَتَّى أَتَى عَرْضَ الْحَرَّةِ فَانْتَصَبَ لَنَا، فَرَمَيْنَاهُ بِجَلَامِيدِ الْحَرَّةِ حَتَّى سَكَتَ، قَالَ: فَمَا اسْتَغْفَرَ لَهُ وَلَا سَبَّهُ. (م,د).
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=16), 1, 'وَفِي رِوَايَةٍ: عَنْ أَبِي نَضْرَةَ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، نَحْوَهُ وَلَيْسَ بِتَمَامِهِ، قَالَ: ذَهَبُوا يَسُبُّونَهُ فَنَهَاهُمْ، قَالَ: ذَهَبُوا يَسْتَغْفِرُونَ لَهُ فَنَهَاهُمْ، قَالَ: "هُوَ رَجُلٌ أَصَابَ ذَنْبًا، حَسِيبُهُ اللَّهُ". (د)', 'മറ്റൊരു നിവേദനം: അബൂനള്റ: ഒരാൾ നബി(സ)യുടെ സമീപം വന്നു(എന്നു തുടങ്ങി) മുൻ ഹദീസ് പോലെ. ഈ ഹദീസ് മുൻ ഹദീസിനെപ്പോലെ സമ്പൂർണ്ണമല്ല. അദ്ദേഹം പറഞ്ഞു: അവർ അദ്ദേഹത്തെ അസഭ്യം പറഞ്ഞപ്പോൾ നബി(സ) അവരെ വിലക്കി. അവർ അദ്ദേഹത്തിന്റെ പാപവിമുക്തിക്കു വേണ്ടി പ്രാർത്ഥിച്ചപ്പോഴും നബി(സ) അവരെ തടഞ്ഞു. നബി(സ) അവരോടു പറഞ്ഞു: "അദ്ദേഹമൊരു തെറ്റു ചെയ്ത വ്യക്തിയാണ്. അദ്ദേഹത്തെ വിചാരണ ചെയ്യുന്നവൻ അല്ലാഹുവാകുന്നു." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أُنْزِلَ عَلَيْهِ الوحي كُرِبَ لِذَلِكَ وَتَرَبَّدَ لَهُ وَجْهُهُ، قَالَ: فَأُنْزِلَ عَلَيْهِ ذَاتَ يَوْمٍ فَلُقِيَ كَذَلِكَ، فَلَمَّا سُرِّيَ عَنْهُ قَالَ: "خُذُوا عَنِّي، فَقَدْ جَعَلَ اللَّهُ لَهُنَّ سَبِيلًا: الثَّيِّبُ بِالثَّيِّبِ، وَالْبِكْرُ بِالْبِكْرِ، الثَّيِّبُ جَلْدُ مِائَةٍ ثُمَّ رَجْمٌ بِالْحِجَارَةِ، وَالْبِكْرُ جَلْدُ مِائَةٍ ثُمَّ نَفْيُ سَنَةٍ". (م,ت)', 'ഉബാദത്തുബ്നു സ്വാമിത്(റ): നബി(സ)ക്കു ഖുർആൻ അവതരിക്കുമ്പോൾ മനോവിഷമമനുഭവപ്പെടുകയും മുഖം വിവർണ്ണമാകുകയും ചെയ്യുമായിരുന്നു. അങ്ങനെ ഒരു ദിവസം ഖുർആൻ അവതരിച്ചപ്പോൾ അപ്രകാരം തന്നെ സംഭവിച്ചു. അതിൽനിന്നു മുക്തമായപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ എന്നിൽ നിന്നു മനസ്സിലാക്കുക. നിശ്ചയം അല്ലാഹു അവർക്കു മാർഗ്ഗമാക്കിയിരിക്കുന്നു: വിവാഹിതയെ വിവാഹിതന് പകരവും കന്യകയെ കന്യകന് പകരവും (ഹദ്ദ് നടപ്പാക്കപ്പെട്ടു) വിവാഹിതനെ നൂറ് അടിയും പിന്നീട് കല്ലേറുമാണ്. അവിവാഹിതനെ നൂറടിയും ഒരു വർഷം നാടുകടത്തലുമാണ്." (മു,തു)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദത്തുബ്നു സ്വാമിത്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 464, 464, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَجَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَرَجَمَ أَبُو بَكْرٍ، وَرَجَمْتُ، وَلَوْلَا أَنِّي أَكْرَهُ أَنْ أَزِيدَ فِي كِتَابِ اللَّهِ لَكَتَبْتُهُ فِي الْمُصْحَفِ، فَإِنِّي قَدْ خَشِيتُ أَنْ تَجِيءَ أَقْوَامٌ فَلَا يَجِدُونَهُ فِي كِتَابِ اللَّهِ، فَيَكْفُرُونَ بِهِ. حَسَنٌ صَحِيحٌ . (ق,ت)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): നബി(സ)യും അബൂബക്കർ സിദ്ദീഖ്(റ)വും ഞാനും എറിഞ്ഞു(ശിക്ഷ നടപ്പാക്കിയിരുന്നു). ഖുർആനിൽ വർദ്ധിപ്പിക്കുന്നതിനെ ഞാൻ വെറുത്തില്ലായിരുന്നുവെങ്കിൽ ഞാൻ മുസ്ഹഫിൽ(ഖുർആൻ) അതെഴുതുമായിരുന്നു. പിന്നീട് വരുന്ന ജനങ്ങൾ ഖുർആനിൽ അത് (റജ്മ്) കാണാതിരിക്കുന്നതിനാൽ അവരതിനെ നിഷേധിക്കുന്നതു ഞാൻ ഭയപ്പെടുന്നു. (ബു,മു,തു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 464, 464, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي هُرَيْرَةَ وَزَيْدِ بْنِ خَالِدٍ – رَضِيَ اللَّهُ عَنْهُمَا – أَنَّهُمْ كَانُوا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَتَاهُ رَجُلَانِ يَخْتَصِمَانِ، فَقَامَ إِلَيْهِ أَحَدُهُمَا وَقَالَ: أَنْشُدُكَ اللَّهَ – يَا رَسُولَ اللَّهِ – لَمَا قَضَيْتَ بَيْنَنَا بِكِتَابِ اللَّهِ. فَقَالَ خَصْمُهُ، وَكَانَ أَفْقَهَ مِنْهُ: أَجَلْ يَا رَسُولَ اللَّهِ، اقْضِ بَيْنَنَا بِكِتَابِ اللَّهِ، وَأْذَنْ لِي فَأَتَكَلَّمَ: إِنَّ ابْنِي كَانَ عَسِيفًا عَلَى هَذَا، فَزَنَى بِامْرَأَتِهِ، فَأَخْبَرُونِي أَنَّ عَلَى ابْنِي الرَّجْمَ، فَفَدَيْتُ مِنْهُ بِمِائَةِ شَاةٍ وَخَادِمٍ. ثُمَّ لَقِيتُ نَاسًا مِنْ أَهْلِ الْعِلْمِ فَزَعَمُوا أَنَّ عَلَى ابْنِي جَلْدَ مِائَةٍ وَتَغْرِيبَ عَامٍ، وَإِنَّمَا الرَّجْمُ عَلَى امْرَأَةِ هَذَا. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِهِ لَأَقْضِيَنَّ بَيْنَكُمَا بِكِتَابِ اللَّهِ: الْمِائَةُ شَاةٍ وَالْخَادِمُ رَدٌّ عَلَيْكَ، وَعَلَى ابْنِكَ جَلْدُ مِائَةٍ وَتَغْرِيبُ عَامٍ، وَاغْدُ يَا أُنَيْسُ عَلَى امْرَأَةِ هَذَا: فَإِنِ اعْتَرَفَتْ فَارْجُمْهَا". فَغَدَا عَلَيْهَا فَاعْتَرَفَتْ فَرَجَمَهَا. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ), സൈദുബ്നു ഖാലിദ്(റ): അവർ നബി(സ)യുടെ സന്നിധിയിൽ നിൽക്കവെ തർക്കിച്ചുകൊണ്ട് രണ്ടുപേർ അവരുടെ അടുക്കൽ വന്നു. അവരിലൊരാൾ പറഞ്ഞു: അല്ലാഹുവിനെത്തന്നെ സത്യം, തിരുദൂതരേ, അങ്ങയോടു ഞാൻ ചോദിക്കുന്നു, അങ്ങ് ഞങ്ങൾക്കിടയിൽ ഖുർആൻ കൊണ്ട് വിധിക്കണം. അപ്പോൾ അദ്ദേഹത്തിന്റെ പ്രതിയോഗി പറഞ്ഞു - അദ്ദേഹമായിരുന്നു ഏറ്റവും വിവരം കൂടിയയാൾ: അതെ നബിയേ, ഞങ്ങൾക്കിടയിൽ ഖുർആൻ കൊണ്ട് അവിടുന്ന് വിധിക്കണം. എനിക്കു സമ്മതം തന്നാൽ ഞാൻ സംസാരിക്കാം. എന്റെ മകൻ ഇദ്ദേഹത്തിന്റെ അടുക്കൽ സേവകനായിരുന്നു. അങ്ങനെ അവൻ ഇവന്റെ ഭാര്യയുമായി അവിഹിത വേഴ്ചയിലേർപ്പെട്ടു. അവർ എന്റെ മകനെ എറിഞ്ഞു കൊല്ലണമെന്നു പറഞ്ഞു. അപ്പോൾ അതിനു പകരമായി ഒരു സേവകനെയും നൂറ് ആടിനെയും ഞാൻ നൽകി. പിന്നീട് ഞാൻ ചില പണ്ഡിതന്മാരെ കണ്ടപ്പോൾ അവർ പറഞ്ഞു: നിന്റെ മകന് നൂറടിയും ഒരു വർഷം നാടു കടത്തലുമാണ്. എറിഞ്ഞു കൊല്ലൽ ഇയാളുടെ ഭാര്യക്കുമാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ സത്യം, ഖുർആൻ കൊണ്ട് നിങ്ങളിൽ ഞാൻ വിധിക്കാൻ പോവുകയാണ്. നൂറാടിനെയും സേവകനേയും തിരിച്ചു വാങ്ങുകയും നിന്റെ മകന് നൂറടിയും ഒരു വർഷം നാടുകടത്തലുമാണ്. അതുകൊണ്ട് ഉനൈസേ, രാവിലെ സ്ത്രീയുടെയടുത്ത് പോവുക. അവൾ കുറ്റസമ്മതം നടത്തിയാൽ അവളെ കൊണ്ടുപോയി എറിയുക." അങ്ങനെ പ്രഭാതത്തിൽ അവളെ കൊണ്ടുപോയി അവളെ എറിഞ്ഞുകൊന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ وَزَيْدِ بْنِ خَالِدٍ –', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 464, 465, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ : أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَنْكَهَ مَاعِزًا. (د)', 'ബുറൈദ(റ): മാഇസ്(റ)വിനെ നബി(സ) തന്റെ വായ വാസനിപ്പിച്ചു. (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 465, 465, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا أَصْحَابَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَتَحَدَّثُ: أَنَّ الْغَامِدِيَّةَ وَمَاعِزَ بْنَ مَالِكٍ لَوْ رَجَعَا بَعْدَ اعْتِرَافِهِمَا، أَوْ قَالَ: لَوْ لَمْ يَرْجِعَا بَعْدَ اعْتِرَافِهِمَا، لَمْ يَطْلُبْهُمَا، وَإِنَّمَا رَجَمَهُمَا عِنْدَ الرَّابِعَةِ. (د)', 'ബുറൈദ(റ): ഞങ്ങൾ, നബി(സ)യുടെ അനുചരർ സംസാരിച്ചിരിക്കുകയായിരുന്നു. ഗാമിദ് ഗോത്രക്കാരിയും മാഇസുബ്നു മാലികും കുറ്റം സമ്മതിച്ചതിന് ശേഷം പിന്മാറിയിരുന്നെങ്കിൽ, അല്ലെങ്കിൽ സമ്മതിച്ചതിന് ശേഷം പിന്തിരിഞ്ഞിരുന്നില്ലെങ്കിൽ അവരെ രണ്ടുപേരെയും അന്വേഷിക്കുകയില്ലായിരുന്നു. നാലാം പ്രാവശ്യമാണ് അവരെ എറിഞ്ഞത്. (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 465, 465, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنِ اللَّجْلَاجِ رَضِيَ اللَّهُ عَنْهُ : أَنَّهُ كَانَ قَاعِدًا يَعْتَمِلُ فِي السُّوقِ، فَمَرَّتِ امْرَأَةٌ تَحْمِلُ صَبِيًّا، فَثَارَ النَّاسُ مَعَهَا وَثُرْتُ فِيمَنْ ثَارَ، فَانْتَهَيْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقُولُ: "مَنْ أَبُو هَذَا مَعَكِ". فَسَكَتَتْ، فَقَالَ شَابٌّ حَذْوَهَا: أَنَا أَبُوهُ يَا رَسُولَ اللَّهِ، فَأَقْبَلَ عَلَيْهَا فَقَالَ: "مَنْ أَبُو هَذَا مَعَكِ". قَالَ الْفَتَى: أَنَا أَبُوهُ يَا رَسُولَ اللَّهِ، فَنَظَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى بَعْضِ مَنْ حَوْلَهُ يَسْأَلُهُمْ عَنْهُ، فَقَالُوا: مَا عَلِمْنَا إِلَّا خَيْرًا، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَحْصَنْتَ". قَالَ: نَعَمْ، فَأَمَرَ بِهِ فَرُجِمَ، قَالَ: فَخَرَجْنَا بِهِ، فَحَفَرْنَا لَهُ حَتَّى أَمْكَنَّا، ثُمَّ رَمَيْنَاهُ بِالْحِجَارَةِ حَتَّى هَدَأَ، فَجَاءَ رَجُلٌ يَسْأَلُ عَنِ الْمَرْجُومِ، فَانْطَلَقْنَا بِهِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْنَا: هَذَا جَاءَ يَسْأَلُ عَنِ الْخَبِيثِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَهُوَ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ". فَإِذَا هُوَ أَبُوهُ، فَأَعَنَّاهُ عَلَى غُسْلِهِ وَتَكْفِينِهِ وَدَفْنِهِ، وَمَا أَدْرِي قَالَ: وَالصَّلَاةِ عَلَيْهِ، أَمْ لَا. (د)', 'ലജ്‌ലാജ്(റ): അദ്ദേഹം അങ്ങാടിയിൽ ജോലി ചെയ്തുകൊണ്ടിരിക്കുകയായിരുന്നു. അന്നേരം ഒരു കുട്ടിയുമായി ഒരു സ്ത്രീ നടന്നുപോയി. അപ്പോൾ ജനങ്ങൾ അവളുടെ പിന്നാലെ ധാർമ്മികരോഷം പൂണ്ട് പിന്തുടർന്നു. ഞാനും കൂട്ടത്തിൽ ചേർന്നു. അങ്ങനെ ഞാൻ നബി(സ)യുടെ സന്നിധിയിലെത്തി. അവിടുന്ന് ചോദിക്കുന്നുണ്ടായിരുന്നു: "ഇവളുടെ കൂടെയുള്ളതിന്റെ പിതാവാരാണ്?" അവൾ മൗനം പാലിച്ചു. ഉടനെ അവളുടെ അടുത്തുനിന്ന ഒരു യുവാവ് പറഞ്ഞു: റസൂലേ, ഞാനാണവന്റെ പിതാവ്. അപ്പോൾ തിരുമേനി(സ) അവളുടെ നേർക്ക് തിരിഞ്ഞു ചോദിച്ചു: "നിന്റെ കൂടെയുള്ള കുഞ്ഞിന്റെ പിതാവാരാണ്?" യുവാവ് പറഞ്ഞു: റസൂലേ, ഞാനാണവന്റെ പിതാവ്. അപ്പോൾ ചുറ്റുമുള്ളവരിലേക്ക് റസൂൽ(സ) ചോദ്യഭാവേന നോക്കി. അവർ പറഞ്ഞു: നന്മയല്ലാതെ ഞങ്ങളൊന്നുമറിഞ്ഞിട്ടില്ല. അന്നേരം റസൂൽ(സ) അയാളോട് ചോദിച്ചു: "നീ വിവാഹം കഴിച്ചിട്ടുണ്ടോ?" അയാൾ പറഞ്ഞു: അതെ. ഉടനെ നബി(സ) ശിക്ഷ നടപ്പാക്കാൻ കൽപിക്കുകയും അയാളെ എറിഞ്ഞുകൊല്ലുകയും ചെയ്തു. നിവേദകൻ: അങ്ങനെ ഞങ്ങളുമായി പുറപ്പെട്ടു. കുഴിയുണ്ടാക്കുകയും അയാളെ കുഴിയിലിറക്കി എറിയാൻ സൗകര്യമാക്കുകയും ചെയ്തു. ശേഷം ജീവനടങ്ങുന്നതു വരെ കല്ലുകൊണ്ടെറിഞ്ഞു. അന്നേരം കൊല്ലപ്പെട്ടവനെ അന്വേഷിച്ച് ഒരാൾ അവിടെ വന്നു. ഞങ്ങളദ്ദേഹത്തെ റസൂൽ(സ)യുടെ സന്നിധിയിൽ കൊണ്ടുചെന്നു പറഞ്ഞു: ഇയാൾ ആ നികൃഷ്ടനെ അന്വേഷിച്ചുവന്നതാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "കസ്തൂരി ഗന്ധത്തേക്കാൾ അദ്ദേഹം അല്ലാഹുവിന്റെയടുക്കൽ പരിശുദ്ധനാണ്." അദ്ദേഹം കൊല്ലപ്പെട്ടവന്റെ പിതാവായിരുന്നു. പിന്നീട് അയാളെ കുളിപ്പിക്കാനും കഫൻ ചെയ്യാനും മറമാടാനും ഞങ്ങളദ്ദേഹത്തെ സഹായിച്ചു. ''അയാളുടെ മേൽ നിസ്കരിക്കുവാനും'' പറഞ്ഞുവോ ഇല്ലയോ എന്നെനിക്കറിയില്ല. (ദ)', 'اللَّجْلَاجِ', 'ലജ്‌ലാജ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 465, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَجُلًا أَتَاهُ فَأَقَرَّ عِنْدَهُ أَنَّهُ زَنَى بِامْرَأَةٍ سَمَّاهَا لَهُ، فَبَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمَرْأَةِ فَسَأَلَهَا عَنْ ذَلِكَ، فَأَنْكَرَتْ أَنْ تَكُونَ زَنَتْ، فَجَلَدَهُ الْحَدَّ وَتَرَكَهَا. (د)', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ) നബി(സ)യിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: ഒരാൾ അവിടത്തെ സമീപിച്ച് ഒരു സ്ത്രീയുടെ പേര് പറഞ്ഞുകൊടുത്തിട്ട് അവളെ ഞാൻ വ്യഭിചരിച്ചുവെന്ന് സ്വയം സമ്മതിച്ചു. ഉടനെ നബി(സ) സ്ത്രീയുടെയടുത്തേക്ക് ആളെവിട്ട് അതിനെക്കുറിച്ച് ചോദിച്ചു. താൻ വ്യഭിചരിച്ചുവെന്നതിനെ അവൾ നിഷേധിച്ചു. അനന്തരം നബി(സ) അവളെ വെറുതെവിടുകയും അയാളെ നിശ്ചിത ശിക്ഷയായി അടിക്കുകയും ചെയ്തു. (ദ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 466, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا زَنَى بِامْرَأَةٍ، فَأَمَرَ بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجُلِدَ الْحَدَّ، ثُمَّ أُخْبِرَ أَنَّهُ مُحْصَنٌ، فَأَمَرَ بِهِ فَرُجِمَ. (د)', 'ജാബിർ(റ): ഒരാൾ ഒരു സ്ത്രീയുമായി വ്യഭിചരിച്ചു. നബി(സ) ശിക്ഷ നടപ്പാക്കാൻ നിർദേശം നൽകി. അങ്ങനെ അയാളെ ഹദ്ദടിച്ചു. അയാൾ വിവാഹിതനാണെന്ന് പിന്നീട് നബി(സ)യോട് അറിയിക്കപ്പെട്ടു. അപ്പോൾ നബി(സ) അയാളോട് എറിയാൻ കൽപിക്കുകയും അയാൾ എറിഞ്ഞുകൊല്ലപ്പെടുകയും ചെയ്തു. (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 466, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِيَهُودِيٍّ وَيَهُودِيَّةٍ قَدْ زَنَيَا، فَانْطَلَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى جَاءَ يَهُودَ، فَقَالَ: "مَا تَجِدُونَ فِي التَّوْرَاةِ عَلَى مَنْ زَنَى". قَالُوا: نُسَوِّدُ وُجُوهَهُمَا وَنُحَمِّلُهُمَا، وَنُخَالِفُ بَيْنَ وُجُوهِهِمَا، وَيُطَافُ بِهِمَا. قَالَ: "فَأْتُوا بِالتَّوْرَاةِ إِنْ كُنْتُمْ صَادِقِينَ". فَجَاءُوا بِهَا فَقَرَءُوهَا، حَتَّى إِذَا مَرُّوا بِآيَةِ الرَّجْمِ وَضَعَ الْفَتَى الَّذِي يَقْرَأُ يَدَهُ عَلَى آيَةِ الرَّجْمِ، وَقَرَأَ مَا بَيْنَ يَدَيْهَا وَمَا وَرَاءَهَا، فَقَالَ لَهُ عَبْدُ اللَّهِ بْنُ سَلَامٍ وَهُوَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مُرْهُ فَلْيَرْفَعْ يَدَهُ. فَرَفَعَهَا فَإِذَا تَحْتَهَا آيَةُ الرَّجْمِ، فَأَمَرَ بِهِمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُجِمَا، قَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: كُنْتُ فِيمَنْ رَجَمَهُمَا، فَلَقَدْ رَأَيْتُهُ يَقِيهَا مِنَ الْحِجَارَةِ بِنَفْسِهِ. (م)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): വ്യഭിചാരത്തിലേർപ്പെട്ട ഒരു യഹൂദസ്ത്രീയെയും പുരുഷനെയും നബി(സ)യുടെ അടുത്തു കൊണ്ടുവന്നു. അപ്പോൾ നബി(സ) യഹൂദികളുടെ അടുക്കൽപോയി ചോദിച്ചു: "വ്യഭിചാരിക്ക് എന്തു ശിക്ഷയാണെന്നാണ് തൗറാത്തിലുള്ളത്?" അവർ പറഞ്ഞു: അവർ രണ്ടുപേരുടെയും മുഖം കറുപ്പിക്കുകയും കഴുതപ്പുറത്തേറ്റുകയും ചെയ്യുകയാണ്. പിന്നീട് പുറം തിരിച്ചിരുത്തി ചുറ്റിക്കലാണ്. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ തൗറാത്ത് കൊണ്ടുവരിക, നിങ്ങൾ സത്യം പറയുന്നവരെങ്കിൽ." അപ്പോൾ അവർ തൗറാത്ത് കൊണ്ടുവരികയും വായിക്കുകയും ചെയ്തു. ''റജ്മി''(എറിഞ്ഞു കൊല്ലണമെന്ന വിധി)ന്റെ സൂക്തമെത്തിയപ്പോൾ വായിക്കുന്നവൻ പ്രസ്തുത വരിയിൽ വിരൽവെച്ച് അതിന്റെ അടുത്തുള്ളതും മുമ്പുള്ളതും വായിച്ചു. അപ്പോൾ അബ്ദുല്ലാഹിബ്നു സലാം നബി(സ)യോട് പറഞ്ഞു: അയാളോട് കൽപിക്കൂ, അയാൾ കൈ ഉയർത്തട്ടെ. (അദ്ദേഹം നബിയുടെ കൂടെയായിരുന്നു) അപ്പോൾ അയാൾ കൈ ഉയർത്തി. അപ്പോൾ അതിന്റെ താഴെയതാ ''റജ്മി'' സൂക്തം. നബി(സ) അവരെ എറിഞ്ഞുകൊല്ലാൻ കൽപിച്ചു. അബ്ദല്ലാഹിബ്നു ഉമർ(റ) പറഞ്ഞു: അവരെ എറിഞ്ഞവരിൽപ്പെട്ടവനാണു ഞാൻ. അയാളുടെ ശരീരത്തിൽ ഏറു കൊള്ളുന്നത് ഞൻ കണ്ടിട്ടുണ്ട്. (മു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 466, 467, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجَمَ يَهُودِيَّيْنِ، أَنَا فِيمَنْ رَجَمَهُمَا، فَلَقَدْ رَأَيْتُهُ وَإِنَّهُ يَسْتُرُهَا مِنَ الْحِجَارَةِ. (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) രണ്ടു യഹൂദികളെ എറിഞ്ഞു(ശിക്ഷ നടപ്പാക്കി). ഞാനും അവരെ എറിഞ്ഞവരിൽപ്പെട്ടവനാണ്. കല്ലുകളിൽ നിന്ന് അയാളവളെ സ്വന്തം ദേഹം കൊണ്ട് മറക്കുന്നതായി എനിക്കയാളെ കാണാമായിരുന്നു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 467, 467, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ : أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجَمَ يَهُودِيًّا وَيَهُودِيَّةً. (ت,جه)', 'ജാബിറുബ്നു സമുറ: നബി(സ) ഒരു യഹൂദിയെയും യഹുദസ്ത്രീയെയും എറിഞ്ഞു(ശിക്ഷ നടപ്പാക്കി). (തു,ജ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 467, 467, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: إِنَّ الْيَهُودَ جَاءُوا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرُوا لَهُ أَنَّ رَجُلًا مِنْهُمْ وَامْرَأَةً زَنَيَا، فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا تَجِدُونَ فِي التَّوْرَاةِ فِي شَأْنِ الزِّنَا". فَقَالُوا: نَفْضَحُهُمْ وَيُجْلَدُونَ فَقَالَ عَبْدُ اللَّهِ بْنُ سَلَامٍ: كَذَبْتُمْ، إِنَّ فِيهَا الرَّجْمَ. فَأَتَوْا بِالتَّوْرَاةِ فَنَشَرُوهَا، فَجَعَلَ أَحَدُهُمْ يَدَهُ عَلَى آيَةِ الرَّجْمِ، ثُمَّ جَعَلَ يَقْرَأُ مَا قَبْلَهَا وَمَا بَعْدَهَا، فَقَالَ لَهُ عَبْدُ اللَّهِ بْنُ سَلَامٍ: ارْفَعْ يَدَيْكَ، فَرَفَعَهَا فَإِذَا فِيهَا آيَةُ الرَّجْمِ، فَقَالُوا: صَدَقَ يَا مُحَمَّدُ، فِيهَا آيَةُ الرَّجْمِ. فَأَمَرَ بِهِمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُجِمَا، قَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: فَرَأَيْتُ الرَّجُلَ يَحْنِي عَلَى الْمَرْأَةِ يَقِيهَا الْحِجَارَةَ. (ق,د,ت)', 'ഇബ്നുഉമർ(റ): യഹൂദികളിൽ ചിലർ നബി(സ)യുടെ അടുത്തുവന്ന് നബി(സ)യോടു പറഞ്ഞു, അവരിലെ ഒരു സ്ത്രീയും പുരുഷനും വ്യഭിചരിച്ചിരിക്കുന്നു. നബി(സ) അവരോടു ചോദിച്ചു: "വ്യഭിചാരത്തെ സംബന്ധിച്ചു നിങ്ങളുടെ തൗറാത്തിൽ എന്താണു പറയുന്നത്?" അവർ പറഞ്ഞു: അവരെ ഞങ്ങൾ വഷളാക്കുകയും അടിക്കുകയും ചെയ്യും. അപ്പോൾ അബ്ദുല്ലാഹിമുബ്നു സലാം പറഞ്ഞു: നിങ്ങൾ കളവാണു പറഞ്ഞത്. എറിഞ്ഞുകൊല്ലണമെന്നാണ് അതിലുള്ളത്. അങ്ങനെയവർ തൗറാത്ത് കൊണ്ടുവരികയും വായിക്കുകയും ചെയ്യവെ അവരിലൊരാൾ ''റജ്മി''നെ പരാമർശിക്കുന്ന സൂക്തത്തിനു മുകളിൽ വിരൽവെച്ചു. അതിനു മുമ്പും പിമ്പുമുള്ളതു വായിക്കാൻ തുടങ്ങി. അപ്പോൾ അബ്ദുല്ലാഹിമുബ്നു സലാം പറഞ്ഞു: നിന്റെ കൈ ഉയർത്തുക. അയാൾ കൈ ഉയർത്തിയപ്പോൾ അവിടെ ആയത്തുറജ്മ് ഉണ്ടായിരുന്നു. അവർ പറഞ്ഞു. മുഹമ്മദേ, അദ്ദേഹം പറഞ്ഞതു വാസ്തവമാണ്. ഇതിൽ ആയത്തു റജ്മ് ഉണ്ട്. അങ്ങനെയവരെ എറിഞ്ഞുകൊല്ലാൻ നബി(സ) ഉത്തരവിട്ടു. അവരെ എറിഞ്ഞുകൊന്നു. അബ്ദുല്ലാഹിമുബ്നു ഉമർ(റ) പറഞ്ഞു: കല്ലുകളേൽക്കുമ്പോൾ അദ്ദേഹമവളുടെ മേൽ മറിയും. അവൾക്ക് ഏറ് ഏൽക്കാതിരിക്കാൻ. (ബു,മു,ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 467, 468, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: مَرُّوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَهُودِيٍّ قَدْ حُمِّمَ وَجْهُهُ وَهُوَ يُطَافُ بِهِ، فَنَاشَدَهُمْ: "مَا حَدُّ الزَّانِي فِي كِتَابِهِمْ"؟ قَالَ: فَأَحَالُوهُ عَلَى رَجُلٍ مِنْهُمْ، فَنَشَدَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا حَدُّ الزَّانِي فِي كِتَابِكُمْ؟ فَقَالَ: الرَّجْمُ، وَلَكِنْ ظَهَرَ الزِّنَا فِي أَشْرَافِنَا، فَكَرِهْنَا أَنْ يُتْرَكَ الشَّرِيفُ وَيُقَامُ عَلَى مَنْ دُونَهُ، فَوَضَعْنَا هَذَا عَنَّا. فَأَمَرَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُجِمَ، ثُمَّ قَالَ: "اللَّهُمَّ إِنِّي أَوَّلُ مَنْ أَحْيَا مَا أَمَاتُوا مِنْ كِتَابِكَ". (م,د)', 'ബറാഉബ്നു ആസിബ്(റ): മുഖം കറുപ്പിക്കപ്പെട്ട ഒരു യഹൂദിയായ മനുഷ്യനെയും കൊണ്ട് നബി(സ)ക്കരികിലൂടെ ചിലർ പോയി. നബി(സ) ചോദിച്ചു: "അവരുടെ ഗ്രന്ഥത്തിൽ വ്യഭിചാരിയുടെ ശിക്ഷയെന്താണ്?" അപ്പോൾ ഇവർ അവരിലെ ഒരാളെ ഏൽപിച്ചു (മറുപടി പറയാൻ). നബി(സ) അയാളോട് ചോദിച്ചു: "വ്യഭിചാരിക്ക് എന്തു ശിക്ഷയാണു നിങ്ങളുടെ ഗ്രന്ഥത്തിൽ?" അദ്ദേഹം പറഞ്ഞു: റജ്മ് (എറിഞ്ഞുകൊല്ലൽ) പക്ഷേ, ഈ വ്യഭിചാരം പിടിക്കപ്പെട്ടതു ഞങ്ങളിലെ ഉന്നതരെയാണ്. അവരിൽ ഈ ശിക്ഷ നടപ്പാക്കാൻ ഞങ്ങൾ മടിക്കുന്നു. താഴ്ന്നവരിൽ ഞങ്ങളതു നടപ്പാക്കുന്നു. അങ്ങനെ ഞങ്ങൾ അത് ഒഴിവാക്കി എന്നു പറഞ്ഞപ്പോൾ നബി(സ) അദ്ദേഹത്തെ എറിഞ്ഞുകൊല്ലാൻ നിർദ്ദേശിക്കുകയും എറിഞ്ഞുകൊല്ലുകയും ചെയ്തു. തുടർന്നു നബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, നിന്റെ ഗ്രന്ഥത്തിൽനിന്നവർ മരിപ്പിച്ചതിനെ ഞാനാണാദ്യമായി ജീവിപ്പിച്ചത്." (മു,ദ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 468, 468, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: مُرَّ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَهُودِيٍّ مُحَمَّمٍ مَجْلُودٍ، فَدَعَاهُمْ فَقَالَ: "هَكَذَا تَجِدُونَ حَدَّ الزَّانِي". فَقَالُوا: نَعَمْ، فَدَعَا رَجُلًا مِنْ عُلَمَائِهِمْ قَالَ لَهُ: "نَشَدْتُكَ بِاللَّهِ الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى، أَهَكَذَا تَجِدُونَ حَدَّ الزَّانِي فِي كِتَابِكُمْ". فَقَالَ: اللَّهُمَّ لَا، وَلَوْلَا أَنَّكَ نَشَدْتَنِي بِهَذَا لَمْ أُخْبِرْكَ، نَجِدُ حَدَّ الزَّانِي فِي كِتَابِنَا الرَّجْمَ، وَلَكِنَّهُ كَثُرَ فِي أَشْرَافِنَا، فَكُنَّا إِذَا أَخَذْنَا الرَّجُلَ الشَّرِيفَ تَرَكْنَاهُ، وَإِذَا أَخَذْنَا الرَّجُلَ الضَّعِيفَ أَقَمْنَا عَلَيْهِ الْحَدَّ، فَقُلْنَا: تَعَالَوْا فَنَجْتَمِعُ عَلَى شَيْءٍ نُقِيمُهُ عَلَى الشَّرِيفِ وَالْوَضِيعِ، فَاجْتَمَعْنَا عَلَى التَّحْمِيمِ وَالْجَلْدِ، وَتَرَكْنَا الرَّجْمَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ إِنِّي أَوَّلُ مَنْ أَحْيَا أَمْرَكَ إِذْ أَمَاتُوهُ". فَأَمَرَ بِهِ فَرُجِمَ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: {يَا أَيُّهَا الرَّسُولُ لَا يَحْزُنْكَ الَّذِينَ يُسَارِعُونَ فِي الْكُفْرِ} إِلَى قَوْلِهِ: {يَقُولُونَ إِنْ أُوتِيتُمْ هَذَا فَخُذُوهُ وَإِنْ لَمْ تُؤْتَوْهُ فَاحْذَرُوا} إِلَى قَوْلِهِ: {وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الْكَافِرُونَ} فِي الْيَهُودِ، إِلَى قَوْلِهِ: {وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الظَّالِمُونَ} فِي الْيَهُودِ، إِلَى قَوْلِهِ: {وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الْفَاسِقُونَ} [المائدة:٤١-٤٧] قَالَ: هِيَ فِي الْكُفَّارِ كُلُّهَا، يَعْنِي هَذِهِ الْآيَةَ. (م,د,ت)', 'ബറാഉബ്നു ആസിബ്(റ): അടിക്കപ്പെടുകയും മുഖം കരിപുരട്ടുകയും ചെയ്ത ഒരു യഹൂദിയെ നബി(സ)യുടെ അരികിലൂടെ കൊണ്ടുപോയി. അപ്പോൾ നബി(സ) അവരെ വിളിച്ചു ചോദിച്ചു: "ഇപ്രകാരമാണോ വ്യഭിചാരിയുടെ ശിക്ഷ?" അതെ, അവർ പ്രത്യുത്തരം നൽകി. അപ്പോൾ അവരിലെ ഒരു പണ്ഡിതനെ വിളിച്ച് നബി(സ) ചോദിച്ചു: "അല്ലാഹുവാണ, അല്ലാഹു മൂസാ നബി(അ)ക്കു തൗറാത്ത് അവതരിപ്പിച്ചു. ഇപ്രകാരമാണോ വ്യഭിചാരിയുടെ ശിക്ഷ നിങ്ങളുടെ കിതാബിൽ വിവരിക്കുന്നത്?" അദ്ദേഹം പറഞ്ഞു: അല്ല. നിങ്ങളെന്നോടു ചോദിച്ചില്ലായിരുന്നുവെങ്കിൽ ഞാനിതു പറയുമായിരുന്നില്ല. എറിഞ്ഞു കൊല്ലണമെന്നതാണു വ്യഭിചാരശിക്ഷയായി തൗറാത്തിലുള്ളത്. പക്ഷേ, ഞങ്ങളുടെ ഉന്നതരിൽ ഇതു വർദ്ധിച്ചിരിക്കുന്നു. ഉന്നതരെ ഇതിൽ പിടിക്കുമ്പോൾ ഞങ്ങളവനെ ഉപേക്ഷിക്കുന്നു. താഴ്ന്നവരെ പിടിക്കുമ്പോൾ ഞങ്ങളാ ശിക്ഷ നടപ്പാക്കുന്നു. അപ്പോൾ ഞങ്ങൾ പറഞ്ഞു: വരൂ, സാധാരണക്കാരനെയും ഉന്നതനെയും ശിക്ഷയിൽ നമുക്ക് ഏകീകരിക്കണം. അങ്ങനെ ഞങ്ങൾ മുഖം കരിപുരട്ടാനും അടിക്കാനും തീരുമാനിക്കുകയും ഏറ് എടുത്തുകളയുകയും ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, അവർ നിന്റെ കൽപനകളെ വധിച്ചുകളഞ്ഞപ്പോൾ അതിനെ ഞാനാണ് ആദ്യമായി ജീവിപ്പിച്ചത്." അങ്ങനെ നബി(സ) അവനെ എറിഞ്ഞുകൊല്ലാൻ കൽപിക്കുകയും അവൻ എറിയപ്പെടുകയും ചെയ്തു. അപ്പോൾ അല്ലാഹു അവതരിപ്പിച്ചു: ''റസൂലേ, സത്യനിഷേധത്തിലേക്ക് കുതിച്ചുചെല്ലുന്നവരുടെ പ്രവൃത്തി താങ്കൾക്ക് ദുഃഖമുണ്ടാക്കാതിരിക്കട്ടെ'' ഇതുവരെ: ''അവർ പറയും: ഇതേ വിധി തന്നെയാണ് നബിയിൽ നിന്ന് നിങ്ങൾക്ക് നൽകപ്പെടുന്നതെങ്കിൽ അത് സ്വീകരിക്കുക. അതല്ല നൽകപ്പെടുന്നതെങ്കിൽ നിങ്ങൾ സൂക്ഷിച്ചുകൊള്ളുക'' - യഹൂദികളുടെ വിഷയത്തിലാണിത് അവതരിച്ചത്. ഈ സൂക്തം വരെയും ഓതി: ''അല്ലാഹു ഇറക്കിയതനുസരിച്ച് വിധിക്കാത്തവരാരോ അവരാണ് സത്യനിഷേധികൾ'' - യഹൂദികളെ കുറിച്ചാണിത്. ഇതുവരെയും ഓതി: ''അല്ലാഹു അവതരിപ്പിച്ചതനുസരിച്ച് വിധിക്കാത്തവരാരോ അവർ തന്നെയാകുന്നു അക്രമികൾ'' - യഹൂദികളെക്കുറിച്ച്. ഇതും കൂടി ഓതി: ''അല്ലാഹു ഇറക്കിയതനുസരിച്ച് വിധിക്കാത്തവരാരോ അവർ തന്നെയാണ് തെമ്മാടികൾ.'' (മാഇദ: 41-47) ബറാഅ്(റ) പറയുന്നു: ഈ സൂക്തങ്ങൾ മുഴുവനും സത്യനിഷേധികളെക്കുറിച്ചാണ്. (മു,ദ,തു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], 'المائدة:٤١-٤٧', null, 468, 469, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَتَى نَفَرٌ مِنْ يَهُودٍ فَدَعَوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْقُفِّ فَأَتَاهُمْ فِي بَيْتِ الْمِدْرَاسِ، فَقَالُوا: يَا أَبَا الْقَاسِمِ، إِنَّ رَجُلًا مِنَّا زَنَى بِامْرَأَةٍ، فَاحْكُمْ بَيْنَهُمْ. فَوَضَعُوا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وِسَادَةً فَجَلَسَ عَلَيْهَا، ثُمَّ قَالَ: "ائْتُونِي بِالتَّوْرَاةِ". فَأُتِيَ بِهَا، فَنَزَعَ الْوِسَادَةَ مِنْ تَحْتِهِ فَوَضَعَ التَّوْرَاةَ عَلَيْهَا، ثُمَّ قَالَ: "آمَنْتُ بِكِ وَبِمَنْ أَنْزَلَكِ". ثُمَّ قَالَ: "ائْتُونِي بِأَعْلَمِكُمْ". فَأُتِيَ بِفَتًى شَابٍّ.... ثُمَّ ذَكَرَ قِصَّةَ الرَّجْمِ نَحْوَ حَدِيثِ مَالِكٍ عَنْ نَافِعٍ. (د)', 'ഇബ്നുഉമർ(റ): യഹൂദികളിൽ ചിലർ നബി(സ)യുടെ അടുത്തുവന്നു. നബി(സ)യെ മദീനയിലെ ''കുഫ്'' എന്ന സ്ഥലത്തേക്കു ക്ഷണിച്ചു. അങ്ങനെ (ജൂതർ) അധ്യാപനം നടത്തുന്ന ഒരു വീട്ടിൽ അവർ ഒരുമിച്ചുകൂടി. അവർ പറഞ്ഞു: അബൂഖാസിം! ഞങ്ങളിൽ ഒരാൾ ഒരു സ്ത്രീയുമായി വ്യഭിചരിച്ചു. ആയതിനാൽ, അവർക്കിടയിൽ നിങ്ങൾ വിധി നടത്തണം. അവർ നബി(സ)ക്ക് ഒരു തലയണ കൊടുത്തു. നബി(സ) അതിന്മേൽ ഇരുന്നു. "നിങ്ങൾ തൗറാത്തു കൊണ്ടുവരിക", നബി(സ) പറഞ്ഞു. അവർ കൊണ്ടുവന്നു. നബി(സ) തലയണയെടുത്ത് അതിന്മേൽ തൗറാത്ത് വെച്ചു. നബി(സ) പറഞ്ഞു: "ഞാൻ നിന്നിലും (തൗറാത്ത്) നിന്റെ അവതാരകനിലും വിശ്വസിച്ചിരിക്കുന്നു". തുടർന്ന് നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഏറ്റവും വലിയ പണ്ഡിതനെ കൊണ്ടുവരിക." അവർ ഒരു ചെറുപ്പക്കാരനെ കൊണ്ടുവന്നു. ശേഷം ഇബ്നുഉമർ(റ) നാഫിഇൽ നിന്നുദ്ധരിക്കുന്ന മാലികിന്റെ റജ്മിനെക്കുറിച്ച് പറയുന്ന ഹദീസ് ഉദ്ധരിച്ചു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 469, 469, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: زَنَى رَجُلٌ مِنَ الْيَهُودِ وَامْرَأَةٌ، فَقَالَ بَعْضُهُمْ لِبَعْضٍ: اذْهَبُوا بِنَا إِلَى هَذَا النَّبِيِّ، فَإِنَّهُ نَبِيٌّ بُعِثَ بِالتَّخْفِيفِ، فَإِنْ أَفْتَانَا بِفُتْيَا دُونَ الرَّجْمِ قَبِلْنَاهَا وَاحْتَجَجْنَا بِهَا عِنْدَ اللَّهِ، قُلْنَا: فُتْيَا نَبِيٍّ مِنْ أَنْبِيَائِكَ. قَالَ: فَأَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ جَالِسٌ فِي الْمَسْجِدِ فِي أَصْحَابِهِ، فَقَالُوا: يَا أَبَا الْقَاسِمِ، مَا تَرَى فِي رَجُلٍ وَامْرَأَةٍ زَنَيَا؟ فَلَمْ يُكَلِّمْهُمْ كَلِمَةً حَتَّى أَتَى بَيْتَ مِدْرَاسِهِمْ، فَقَامَ عَلَى الْبَابِ فَقَالَ: "أَنْشُدُكُمْ بِاللَّهِ الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى، مَا تَجِدُونَ فِي التَّوْرَاةِ عَلَى مَنْ زَنَى إِذَا أَحْصَنَ". قَالُوا: يُحَمَّمُ وَيُجَبَّهُ وَيُجْلَدُ، وَالتَّجْبِيهُ: أَنْ يُحْمَلَ الزَّانِيَانِ عَلَى حِمَارٍ وَتُقَابَلُ أَقْفِيَتُهُمَا وَيُطَافُ بِهِمَا، قَالَ: وَسَكَتَ شَابٌّ مِنْهُمْ، فَلَمَّا رَآهُ النَّبِيُّ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ سَكَتَ أَلَظَّ بِهِ النِّشْدَةَ، فَقَالَ: اللَّهُمَّ إِذْ نَشَدْتَنَا فَإِنَّا نَجِدُ فِي التَّوْرَاةِ الرَّجْمَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَمَا أَوَّلُ مَا ارْتَخَصْتُمْ أَمْرَ اللَّهِ". قَالَ: زَنَى ذُو قَرَابَةٍ مِنْ مَلِكٍ مِنْ مُلُوكِنَا فَأَخَّرَ عَنْهُ الرَّجْمَ، ثُمَّ زَنَى رَجُلٌ فِي أُسْرَةٍ مِنَ النَّاسِ فَأَرَادَ رَجْمَهُ فَحَالَ قَوْمُهُ دُونَهُ، وَقَالُوا: لَا يُرْجَمُ صَاحِبُنَا حَتَّى تَجِيءَ بِصَاحِبِكَ فَتَرْجُمَهُ، فَاصْطَلَحُوا عَلَى هَذِهِ الْعُقُوبَةِ بَيْنَهُمْ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَإِنِّي أَحْكُمُ بِمَا فِي التَّوْرَاةِ". فَأَمَرَ بِهِمَا فَرُجِمَا. قَالَ الزُّهْرِيُّ: فَبَلَغَنَا أَنَّ هَذِهِ الْآيَةَ نَزَلَتْ فِيهِمْ: {إِنَّا أَنْزَلْنَا التَّوْرَاةَ فِيهَا هُدًى وَنُورٌ يَحْكُمُ بِهَا النَّبِيُّونَ الَّذِينَ أَسْلَمُوا} [المائدة:٤٤] كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهُمْ. (د)', 'അബൂഹുറൈറ(റ): ഒരു യഹൂദ സ്ത്രീയും പുരുഷനും വ്യഭിചരിച്ചു. അപ്പോൾ അവരിൽ ചിലർ ചിലരോടു പറഞ്ഞു: നമുക്ക് ഈ (മദീനയിലെ) പ്രവാചകന്റെ അടുത്തുപോയി ചോദിക്കാം. ആയാസരാഹിത്യവുമായി അയക്കപ്പെട്ട പ്രവാചകനാണ് അദ്ദേഹം. അദ്ദേഹം എറിഞ്ഞുകൊല്ലുകയെന്ന നിയമമല്ലാത്ത ലഘുവായ വല്ലതും നിർദ്ദേശിക്കുകയാണെങ്കിൽ നമുക്കതു സ്വീകരിക്കുകയും അല്ലാഹുവിന്റെയടുക്കൽ നമുക്ക് നിന്റെ പ്രവാചകന്റെ മതവിധിയനുസരിച്ചാണു ഞങ്ങൾ പ്രവർത്തിച്ചതെന്നു തെളിവു പറയുകയും ചെയ്യാം. അങ്ങനെയവർ നബി(സ)യുടെ അടുത്തുചെല്ലുന്നു. നബി(സ)യും അനുചരരോടൊത്ത് പള്ളിയിൽ ഇരിക്കുകയായിരുന്നു. അവർ ചോദിച്ചു: അബൂഖാസിം, വ്യഭിചരിച്ച സ്ത്രീപുരുഷരെ എന്തുചെയ്യണം? അവരുടെ പാഠശാലയിൽ എത്തുന്നതുവരെ നബി(സ) അവരോട് ഒന്നും ഉരിയാടിയില്ല. അവിടെയെത്തി നബി(സ) വാതിൽക്കൽ നിന്ന് പറഞ്ഞു: "മൂസാനബിക്കു തൗറാത്ത് ഇറക്കിയ അല്ലാഹുവാണ, ഞാൻ നിങ്ങളോടു ചോദിക്കുന്നു, വിവാഹിതൻ വ്യഭിചരിച്ചാൽ അവനുള്ള ശിക്ഷയെ സംബന്ധിച്ചു തൗറാത്തിൽ നിങ്ങൾ എന്താണു കാണുന്നത്?" അവർ പറഞ്ഞു: അവരുടെ മുഖം കറുപ്പിക്കുകയും തിരിച്ചിരുത്തുകയും അടിക്കുകയും ചെയ്യും. മുഖം തിരിച്ചിരുത്തൽ ഇപ്രകാരമാണ്: അവർ രണ്ടുപേരേയും (രണ്ടുപേരുടേയും പിരടി പരസ്പരം എതിർദിശയിൽ ചേർത്തി) കഴുതയുടെ പുറത്തിരുത്തി ചുറ്റിക്കുകയും അവരെ അടിക്കുകയുമാണ്. അബൂഹുറൈറ(റ) പറയുന്നു: അവരിൽ ഒരു യുവാവ് നിശ്ശബ്ദനായിരുന്നു. അയാൾ നിശ്ശബ്ദനായിരിക്കുന്നതു കണ്ടപ്പോൾ നബി(സ) അദ്ദേഹത്തെ സത്യം ചെയ്യാൻ നിർബന്ധിപ്പിച്ചു. അപ്പോൾ അയാൾ പറഞ്ഞു: അല്ലാഹുവേ നീ സാക്ഷി (നീ സത്യം ചെയ്തിരിക്കുന്ന) തൗറാത്തിലുള്ളത് എറിഞ്ഞുകൊല്ലണമെന്നതാണ്. അപ്പോൾ നബി(സ) ചോദിച്ചു: "അല്ലാഹുവിന്റെ വിധിയിൽ നിന്ന് ആദ്യമായി നിങ്ങൾ എളുപ്പമാക്കിയത് എന്താണ്?" അയാൾ പറഞ്ഞു: ഞങ്ങളുടെ രാജാവിന്റെ ഒരു അടുത്തബന്ധു വ്യഭിചരിച്ചപ്പോൾ രാജാവ് അവനെ എറിഞ്ഞുകൊല്ലാൻ അനുവദിച്ചില്ല. പിന്നീട് ഒരു സാധാരണക്കാരൻ വ്യഭിചാരത്തിലേർപ്പെട്ടപ്പോൾ അദ്ദേഹത്തെ എറിഞ്ഞുകൊല്ലാൻ തുനിഞ്ഞപ്പോൾ അവന്റെ കുടുംബക്കാർ അതിന് അനുവദിച്ചില്ല. അവർ പറഞ്ഞു: നിങ്ങളുടെ വൃക്തിയെ എറിഞ്ഞുകൊന്നതിനുശേഷമല്ലാതെ ഇദ്ദേഹത്തെ വധിക്കാൻ അനുവദിക്കില്ല. അങ്ങനെ ഇവ്വിധം അവർക്കിടയിൽ ഒരു ശിക്ഷ പുതുതായുണ്ടാക്കി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഞാൻ തൗറാത്തിലുള്ളതുകൊണ്ടു വിധിക്കുന്നു." അങ്ങനെ എറിഞ്ഞുകൊല്ലാൻ കൽപിക്കുകയും കൊല്ലുകയും ചെയ്തു.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: زَنَى رَجُلٌ وَامْرَأَةٌ مِنَ الْيَهُودِ، وَقَدْ أُحْصِنَا، حِينَ قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ، وَقَدْ كَانَ الرَّجْمُ مَكْتُوبًا عَلَيْهِمْ فِي التَّوْرَاةِ فَتَرَكُوهُ وَأَخَذُوا بِالتَّجْبِيهِ، يُضْرَبُ مِائَةً بِحَبْلٍ مَطْلِيٍّ بِقَارٍ، وَيُحْمَلُ عَلَى حِمَارٍ وَجْهُهُ مِمَّا يَلِي دُبُرَ الْحِمَارِ، فَاجْتَمَعَ أَحْبَارٌ مِنْ أَحْبَارِهِمْ فَبَعَثُوا قَوْمًا آخَرِينَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: سَلُوهُ عَنْ حَدِّ الزَّانِي، وَسَاقَ الْحَدِيثَ، فَقَالَ فِيهِ: قَالَ: وَلَمْ يَكُونُوا مِنْ أَهْلِ دِينِهِ فَيَحْكُمَ بَيْنَهُمْ، فَخُيِّرَ فِي ذَلِكَ. قَالَ: {فَإِنْ جَاءُوكَ فَاحْكُمْ بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ}. [المائدة:٤٢] (د)', 'അബൂഹുറൈറ(റ): നബി(സ) മദീനയിൽ വന്നപ്പോൾ യഹൂദികളിലെ വിവാഹിതരായ ഒരു സ്ത്രീയും പുരുഷനും വ്യഭിചാരത്തിലേർപ്പെട്ടതായ കേസുവന്നു. തൗറാത്തിൽ അതിനുള്ള ശിക്ഷ എറിഞ്ഞുകൊല്ലണമെന്നായിരുന്നുവെങ്കിലും അവർ ഉപേക്ഷിക്കുകയും പകരം ടാറു പുരട്ടിയ കയറുപയോഗിച്ചു നൂറടിയും കഴുതപ്പുറത്തു മുഖം കഴുതയുടെ പിൻഭാഗത്തേക്കാക്കിയിരുത്തി നാട്ടിലൂടെ നടത്തലുമാക്കി ഭേദഗതി ചെയ്തു. അങ്ങനെ അവരിലെ ഏതാനും പുരോഹിതന്മാർ കൂടിച്ചേർന്ന് ചിലരെ നബി(സ)യുടെയടുത്തേക്ക് അയക്കാൻ തീരുമാനിക്കുകയും അയക്കുകയും ചെയ്തു. അവർ പറഞ്ഞു: വ്യഭിചാരിയുടെ ശിക്ഷയെന്താണെന്നു അദ്ദേഹത്തോട് നിങ്ങൾ ചോദിക്കുക. (ഹദീസ് പറഞ്ഞു) അബൂഹുറൈറ(റ) പറഞ്ഞു: ആ പുരോഹിതർ നബി(സ)യുടെ മതവിശ്വാസികളായിരുന്നില്ല. അവർ നബി(സ)ക്കു വിധിക്കാൻ അവസരം നൽകി. അല്ലാഹു പറഞ്ഞു: ''അവർ (യഹൂദി) നിങ്ങളുടെ അടുത്തുവന്നാൽ അവർക്കിടയിൽ വിധിക്കുകയോ തിരിഞ്ഞുകളയുകയോ ചെയ്യുക.'' (മാഇദ: 42) (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'المائدة:٤٢', null, 470, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَاءَتِ الْيَهُودُ بِرَجُلٍ وَامْرَأَةٍ مِنْهُمْ زَنَيَا، فَقَالَ: "ائْتُونِي بِأَعْلَمِ رَجُلَيْنِ مِنْكُمْ". فَأَتَوْهُ بِابْنَيْ صُورِيَا، فَنَشَدَهُمَا: "كَيْفَ تَجِدَانِ أَمْرَ هَذَيْنِ فِي التَّوْرَاةِ"؟ قَالَا: نَجِدُ فِي التَّوْرَاةِ إِذَا شَهِدَ أَرْبَعَةٌ أَنَّهُمْ رَأَوْا ذَكَرَهُ فِي فَرْجِهَا مِثْلَ الْمِيلِ فِي الْمُكْحُلَةِ رُجِمَا، قَالَ: "فَمَا يَمْنَعُكُمَا أَنْ تَرْجُمُوهُمَا". قَالَا: ذَهَبَ سُلْطَانُنَا فَكَرِهْنَا الْقَتْلَ. فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالشُّهُودِ، فَجَاءُوا بِأَرْبَعَةٍ فَشَهِدُوا أَنَّهُمْ رَأَوْا ذَكَرَهُ فِي فَرْجِهَا مِثْلَ الْمِيلِ فِي الْمُكْحُلَةِ، فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَجْمِهِمَا. (د,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): വ്യഭിചരിച്ച ഒരു പുരുഷനെയും സ്ത്രീയെയും കൊണ്ട് യഹൂദികൾ വന്നു. അപ്പോൾ നബി(സ) അവരോടു പറഞ്ഞു: "നിങ്ങളിലെ ഏറ്റവും അറിവുള്ള രണ്ടുപേരെ കൊണ്ടുവരിക." സൂരിയയുടെ രണ്ടു മക്കളെയവർ കൊണ്ടുവന്നു. നബി(സ) സത്യംചെയ്ത് അവരോടു ചോദിച്ചു: "ഇവർ രണ്ടുപേരെ സംബന്ധിച്ച് തൗറാത്ത് എന്തുപറയുന്നു?" അവർ പറഞ്ഞു: സുറുമക്കുപ്പിയിലെ സുറുമക്കോൽപോലെ അവന്റെ ലിംഗം അവളുടെ യോനിയിൽ പ്രവേശിച്ചതു കണ്ടതായി നാലുപേർ സാക്ഷിനിന്നാൽ അവനെ എറിഞ്ഞുകൊല്ലണമെന്ന് തൗറാത്തിലുണ്ട്. നബി(സ) ചോദിച്ചു: "എന്നാൽ, എന്തുകൊണ്ട് അവരെ നിങ്ങൾ എറിഞ്ഞുകൊല്ലുന്നില്ല?" അവർ പറഞ്ഞു: ഞങ്ങളുടെ രാജാവ് ശക്തനും ഞങ്ങളെ കീഴടക്കിയവനുമായതുകൊണ്ടു വധിക്കാൻ ഞങ്ങൾ ഭയപ്പെടുന്നു. സുറുമക്കുപ്പിയിലെ സുറുമക്കോലുപോലെ ഇയാളുടെ ലിംഗം അവളുടെ യോനിയിൽ പ്രവേശിച്ചതായി ദർശിച്ച നാലുപേരെ റസൂൽ(സ) വിളിച്ചുവരുത്തി. ശേഷം അവർ രണ്ടുപേരെയും എറിഞ്ഞുകൊല്ലാൻ നബി(സ) കൽപിച്ചു. (ദ,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 471, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: رَجَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا مِنَ الْيَهُودِ وَامْرَأَةً زَنَيَا. (م,د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): വ്യഭിചരിച്ച യഹൂദികളായ ഒരു പുരുഷനെയും സ്ത്രീയെയും നബി(സ) എറിഞ്ഞ് ശിക്ഷ നടപ്പാക്കി. (മു,ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 471, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ امْرَأَةً مِنْ جُهَيْنَةَ أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنَّهَا زَنَتْ وَهِيَ حُبْلَى، فَدَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلِيًّا لَهَا، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَحْسِنْ إِلَيْهَا، فَإِذَا وَضَعَتْ فَجِئْ بِهَا". فَلَمَّا أَنْ وَضَعَتْ جَاءَ بِهَا، فَأَمَرَ بِهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَشُكَّتْ عَلَيْهَا ثِيَابُهَا، ثُمَّ أَمَرَ بِهَا فَرُجِمَتْ، ثُمَّ أَمَرَهُمْ فَصَلَّوْا عَلَيْهَا، فَقَالَ عُمَرُ: يَا رَسُولَ اللَّهِ، تُصَلِّي عَلَيْهَا وَقَدْ زَنَتْ؟ قَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ لَقَدْ تَابَتْ تَوْبَةً لَوْ قُسِّمَتْ بَيْنَ سَبْعِينَ مِنْ أَهْلِ الْمَدِينَةِ لَوَسِعَتْهُمْ، وَهَلْ وَجَدْتَ أَفْضَلَ مِنْ أَنْ جَادَتْ بِنَفْسِهَا". (م,د,ت,ن,جه)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): ജുഹൈന ഗോത്രത്തിലെ ഒരു സ്ത്രീ നബി(സ)യുടെ അടുക്കൽ വന്ന് അവൾ വ്യഭിചരിച്ചുവെന്നും ഗർഭിണിയായെന്നും പറഞ്ഞു. അപ്പോൾ അവളുടെ രക്ഷാകർത്താവിനോടു നബി(സ) വരാൻ കൽപിച്ചു. അയാൾ വന്നപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അവളോടു നന്മയിൽ വർത്തിക്കുക. അവൾ പ്രസവിച്ചാൽ അവളെ കൂട്ടിവരിക." അവൾ പ്രസവിച്ചപ്പോൾ അദ്ദേഹമവളെയും കൂട്ടിവന്നു. അങ്ങനെ അവളെ എറിഞ്ഞുകൊല്ലാൻ കൽപിക്കുകയും അവളുടെ മേൽവസ്ത്രം കെട്ടുകയും ചെയ്തു. പിന്നീട് എറിയാൻ കൽപിക്കുകയും എറിഞ്ഞുകൊല്ലുകയും ചെയ്തു. തുടർന്ന് അവരോടു നിസ്കരിക്കാൻ പറഞ്ഞു. അവർ നിസ്കരിക്കുകയും ചെയ്തു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: നിസ്കരിക്കുകയോ നബിയേ, അവൾ വ്യഭിചരിച്ചിട്ടില്ലെയോ? നബി(സ) പറഞ്ഞു: "അല്ലാഹുവാണ, മദീനായിലെ എഴുപതുപേർക്കു വീതിച്ചാൽ പോലും അവർക്കെല്ലാവർക്കും വിശാലമാവുന്ന പശ്ചാത്താപമാണവൾ ചെയ്തത്. അവളുടെ ആത്മാവിനെക്കാളും മെച്ചപ്പെട്ട ഒരാളെ നിനക്കു കാണാൻ കഴിയുമോ?" (മു,ദ,തു,ന,ജ)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 471, 472, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ : أَنَّ امْرَأَةً – يَعْنِي مِنْ غَامِدٍ – أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنِّي قَدْ فَجَرْتُ، فَقَالَ: "ارْجِعِي". فَرَجَعَتْ، فَلَمَّا أَنْ كَانَ الْغَدُ أَتَتْهُ فَقَالَتْ: لَعَلَّكَ أَنْ تَرُدَّنِي كَمَا رَدَدْتَ مَاعِزَ بْنَ مَالِكٍ، فَوَاللَّهِ إِنِّي لَحُبْلَى. فَقَالَ لَهَا: "ارْجِعِي". فَرَجَعَتْ، فَلَمَّا كَانَ الْغَدُ أَتَتْهُ، فَقَالَ لَهَا: "ارْجِعِي حَتَّى تَلِدِي". فَرَجَعَتْ، فَلَمَّا وَلَدَتْ أَتَتْهُ بِالصَّبِيِّ فَقَالَتْ: هَذَا قَدْ وَلَدْتُهُ، فَقَالَ لَهَا: "ارْجِعِي فَأَرْضِعِيهِ حَتَّى تَفْطِمِيهِ". فَجَاءَتْ بِهِ وَقَدْ فَطَمَتْهُ وَفِي يَدِهِ شَيْءٌ يَأْكُلُهُ، فَأَمَرَ بِالصَّبِيِّ فَدُفِعَ إِلَى رَجُلٍ مِنَ الْمُسْلِمِينَ، وَأَمَرَ بِهَا فَحُفِرَ لَهَا، وَأَمَرَ بِهَا فَرُجِمَتْ، وَكَانَ خَالِدٌ فِيمَنْ يَرْجُمُهَا، فَرَجَمَهَا بِحَجَرٍ فَوَقَعَتْ قَطْرَةٌ مِنْ دَمِهَا عَلَى وَجْنَتِهِ، فَسَبَّهَا، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَهْلًا يَا خَالِدُ، فَوَالَّذِي نَفْسِي بِيَدِهِ، لَقَدْ تَابَتْ تَوْبَةً لَوْ تَابَهَا صَاحِبُ مَكْسٍ لَغُفِرَ لَهُ". وَأَمَرَ بِهَا فَصُلِّيَ عَلَيْهَا وَدُفِنَتْ. (د,م)', 'ബുറൈദ(റ): ഗാമിദ് ഗോത്രത്തിൽപ്പെട്ട ഒരു സ്ത്രീ നബി(സ)യുടെ അടുക്കൽ വന്നുപറഞ്ഞു: ഞാൻ തെറ്റു ചെയ്തു. നബി(സ) പറഞ്ഞു: "നീ മടങ്ങിപ്പോവുക." പിറ്റേ ദിവസമായപ്പോൾ അവൾ വീണ്ടും വന്നുപറഞ്ഞു: അങ്ങ് എന്നെ മടക്കി അയച്ചത് മാഇസുബ്നു മാലികിനെ പറഞ്ഞയച്ചതുപോലെയാവും. എന്നാൽ നിശ്ചയം ഞാൻ ഗർഭിണിയാണ്. അപ്പോൾ നബി(സ) അവളോടു പറഞ്ഞു നീ മടങ്ങിപ്പോവുക. അവൾ മടങ്ങിപ്പോയെങ്കിലും പിറ്റെദിവസവും വന്നു. അപ്പോൾ നബി(സ) അവളോടു പറഞ്ഞു: "നീ മടങ്ങിപ്പോവുക, പ്രസവിച്ചതിനുശേഷം വരിക." പ്രസവിച്ചശേഷം കുഞ്ഞിനെയുമായവൾ നബി(സ)യുടെ അടുക്കൽ വന്ന് പറഞ്ഞു: ഇതാ ഞാൻ പ്രസവിച്ചത്. നബി(സ) അവളോടു പറഞ്ഞു: "നീ മടങ്ങിപ്പോവുക, കുട്ടിയെ മുലയൂട്ടുക. മുലകുടി അവസാനിച്ചതിനുശേഷം വരിക." അങ്ങനെയവൾ മടങ്ങുകയും കുട്ടിയുടെ പാലുകുടി മുറിഞ്ഞതിനുശേഷം വരികയും ചെയ്തപ്പോൾ കുട്ടിയുടെ കൈയിൽ തിന്നാൻ പറ്റുന്ന ഒരു വസ്തുവുമുണ്ടായിരുന്നു. കുട്ടിയെ മുസ്‌ലിംകളിലൊരാളെ ഏൽപിക്കാൻ പറയുകയും അവൾക്കുവേണ്ടി കുഴിവെട്ടാൻ കൽപിക്കുകയും ചെയ്തു. അവളെ എറിഞ്ഞുകൊന്നു. ഖാലിദ്(റ) എറിഞ്ഞവരിലെ ഒരു വ്യക്തിയായിരുന്നു. അദ്ദേഹം കല്ല് കൊണ്ടെറിഞ്ഞപ്പോൾ അവളുടെ രക്തം അദ്ദേഹത്തിന്റെ കവിളിൽ പതിക്കാനിടയായി. ഖാലിദ്(റ) അവളെ ശകാരിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "പാടില്ല ഖാലിദേ, അല്ലാഹുവാണ, ഒരു ചുങ്കം പിരിക്കുന്നവന്റെ ദോഷം പോലും മാപ്പാക്കാൻ മാത്രം പര്യാപ്തമായ പശ്ചാത്താപമാണവൾ ചെയ്തിരിക്കുന്നത്." അങ്ങനെ അവൾക്കു വേണ്ടി നിസ്കരിക്കാൻ കൽപിക്കുകയും നിസ്കരിക്കുകയും മറമാടപ്പെടുകയും ചെയ്തു. (മു,ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','م']::text[], array['മു','ദ']::text[], null, null, 472, 473, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ : أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجَمَ امْرَأَةً فَحُفِرَ لَهَا إِلَى الثَّنْدُوَةِ. وَفِي رِوَايَةٍ: ثُمَّ رَمَاهَا بِحَصَاةٍ مِثْلَ الْحِمِّصَةِ، ثُمَّ قَالَ: "ارْمُوا وَاتَّقُوا الْوَجْهَ". فَلَمَّا طَفِئَتْ أَخْرَجَهَا فَصَلَّى عَلَيْهَا. (د,ن)', 'അബൂബക്റ(റ): നബി(സ) ഒരു സ്ത്രീയെ എറിഞ്ഞുകൊല്ലാൻ വിധിച്ചു. അവൾക്കു വേണ്ടി നെഞ്ചോളം ആഴത്തിൽ കുഴിവെട്ടി. ഒരു റിപ്പോർട്ടിൽ: കടല പോലെയുള്ള കല്ലുകൾ കൊണ്ട് അവളെ എറിഞ്ഞു. തുടർന്ന് നബി(സ) പറഞ്ഞു: "നിങ്ങൾ എറിയുക, മുഖം സൂക്ഷിക്കുക." മരിച്ചപ്പോൾ അവളെ പുറത്തെടുക്കുകയും നിസ്കരിക്കുകയും ചെയ്തു. (ദ,ന)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 473, 473, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=38), 1, 'وَفِي رِوَايَةٍ: ثُمَّ رَمَاهَا بِحَصَاةٍ مِثْلَ الْحِمِّصَةِ، ثُمَّ قَالَ: "ارْمُوا وَاتَّقُوا الْوَجْهَ". فَلَمَّا طَفِئَتْ أَخْرَجَهَا فَصَلَّى عَلَيْهَا. (د,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ امْرَأَةً مِنْ جُهَيْنَةَ اعْتَرَفَتْ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالزِّنَا فَقَالَتْ: إِنِّي حُبْلَى. فَدَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلِيَّهَا فَقَالَ: "أَحْسِنْ إِلَيْهَا، فَإِذَا وَضَعَتْ حَمْلَهَا فَأَخْبِرْنِي". فَفَعَلَ، فَأَمَرَ بِهَا فَشُدَّتْ عَلَيْهَا ثِيَابُهَا، ثُمَّ أَمَرَ بِرَجْمِهَا فَرُجِمَتْ، ثُمَّ صَلَّى عَلَيْهَا. فَقَالَ لَهُ عُمَرُ بْنُ الْخَطَّابِ: يَا رَسُولَ اللَّهِ، رَجَمْتَهَا ثُمَّ تُصَلِّي عَلَيْهَا؟ فَقَالَ: "لَقَدْ تَابَتْ تَوْبَةً لَوْ قُسِمَتْ بَيْنَ سَبْعِينَ مِنْ أَهْلِ الْمَدِينَةِ لَوَسِعَتْهُمْ، وَهَلْ وَجَدْتَ شَيْئًا أَفْضَلَ مِنْ أَنْ جَادَتْ بِنَفْسِهَا لِلَّهِ". (م,ت,ن,جه)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): ജുഹൈന ഗോത്രത്തിലെ ഒരു സ്ത്രീ വ്യഭിചരിച്ചതായി നബി(സ)യോടു സമ്മതിച്ചു. ഞാൻ ഗർഭിണിയാണെന്ന് അവൾ പറഞ്ഞപ്പോൾ നബി(സ) അവളുടെ രക്ഷാകർത്താവിനെ വിളിച്ചു. അദ്ദേഹത്തോടു പറഞ്ഞു: "നിങ്ങൾ ഇവളോടു നല്ലനിലയിൽ വർത്തിക്കുകയും പ്രസവിച്ചുകഴിഞ്ഞാൽ എനിക്കു വിവരം തരികയും ചെയ്യുക." അദ്ദേഹം അങ്ങനെ ചെയ്തു. അവളുടെ മേൽവസ്ത്രം ചുറ്റികെട്ടാൻ നബി(സ) കൽപിച്ചു. അപ്രകാരം ചെയ്തതിന് ശേഷം അവളെ എറിഞ്ഞുകൊല്ലാൻ നബി(സ) ആജ്ഞാപിച്ചു. അപ്രകാരം ചെയ്തു. ശേഷമവൾക്കുവേണ്ടി നിസ്കരിച്ചു. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: നബിയേ, അങ്ങവളെ എറിഞ്ഞുകൊല്ലാൻ വിധിക്കുകയും പിന്നീടു തങ്ങൾ തന്നെ അവൾക്കുവേണ്ടി നിസ്കരിക്കുകയും ചെയ്യുകയോ? നബി(സ) പ്രത്യുത്തരം നൽകി: "മദീനയിലെ എഴുപതുപേരിൽ വീതിക്കപ്പെട്ടാൽ പോലും അവർക്കു മതിയാവാൻ മാത്രം മഹത്തായ പശ്ചാത്താപമാണവൾ ചെയ്തത്. തന്റെ ജീവൻ അവൾ അല്ലാഹുവിനു വേണ്ടി ബലിയർപ്പിച്ചതിനേക്കാളും ശ്രേഷ്ഠമായത് നീ കണ്ടിട്ടുണ്ടോ?" (മു,തു,ന,ജ)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 473, 473, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَرَبَ وَغَرَّبَ، وَأَنَّ أَبَا بَكْرٍ ضَرَبَ وَغَرَّبَ، وَأَنَّ عُمَرَ ضَرَبَ وَغَرَّبَ. (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) അടിക്കുകയും നാടുകടത്തുകയും ചെയ്തു. അബൂബക്കർ സിദ്ദീഖ്(റ)വും അടിക്കുകയും നാടുകടത്തുകയും ചെയ്തു. ഉമർ(റ)വും അടിക്കുകയും നാടുകടത്തുകയും ചെയ്തു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 473, 473, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ حَبِيبِ بْنِ سَالِمٍ: أَنَّ رَجُلًا يُقَالَ لَهُ عَبْدُ الرَّحمَنِ بْنُ حُنَيْنٍ وَقَعَ عَلَى جَارِيَةِ امْرَأَتِهِ، فَرُفِعَ إِلَى النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا، وَهُوَ أَمِيرٌ عَلَى الْكُوفَةِ، فَقَالَ: لَأَقْضِيَنَّ فِيكَ بِقَضِيَّةِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: إِنْ كَانَتْ أَحَلَّتْهَا لَكَ جَلَدْتُكَ مِائَةً، وَإِنْ لَمْ تَكُنْ أَحَلَّتْهَا لَكَ رَجَمْتُكَ بِالْحِجَارَةِ. فَوَجَدُوهُ قَدْ أَحَلَّتْهَا لَهُ، فَجَلَدَهُ مِائَةً. (د)', 'ഹബീബുബ്നു സാലിം(റ): അബ്ദുറഹ്മാനുബ്നു ഹുനൈൻ എന്നൊരാൾ തന്റെ ഭാര്യയുടെ അടിമയുമായി അവിഹിതബന്ധത്തിലേർപ്പെട്ടു. അപ്പോൾ കൂഫയിലെ അമീറായിരുന്ന നുഅ്മാനുബ്നു ബശീറിനു മുമ്പിൽ പ്രശ്നം അവതരിപ്പിച്ചു. അദ്ദേഹം പറഞ്ഞു: ഇതിൽ ഞാൻ റസൂൽ(സ)യുടെ വിധി നടപ്പാക്കുന്നു: നിന്റെ ഭാര്യ അവളെ നിനക്ക് അനുവദിച്ചുതന്നിട്ടുണ്ടെങ്കിൽ നിന്നെ നൂറടി അടിക്കും. മറിച്ചാണെങ്കിൽ കല്ലു കൊണ്ടു നിന്നെ എറിഞ്ഞുകൊല്ലും. അങ്ങനെയവന്റെ ഭാര്യ അവളെ അദ്ദേഹത്തിന് ''ഹലാലാക്കി'' നൽകിയതായി കണ്ടെത്തുകയും തൽഫലമായി നൂറടി നൽകുകയും ചെയ്തു. (ദ)', 'حَبِيبِ بْنِ سَالِمٍ', 'ഹബീബുബ്നു സാലിം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 474, 474, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فِي الرَّجُلِ يَأْتِي جَارِيَةَ امْرَأَتِهِ، قَالَ: "إِنْ كَانَتْ أَحَلَّتْهَا لَهُ جُلِدَ مِائَةً، وَإِنْ لَمْ تَكُنْ أَحَلَّتْهَا لَهُ رَجَمْتُهُ". (د,ت,ن,جه)', 'നുഅ്മാനുബ്നു ബശീർ(റ): ഒരാൾ തന്റെ ഭാര്യയുടെ അടിമയുമായി വേഴ്ചയിലേർപ്പെട്ടാലുള്ള വിധിയെപ്പറ്റി നബി(സ) പറഞ്ഞു: "ഭാര്യ അവളെ തന്റെ ഭർത്താവിന് ''ഹലാലാക്കി'' നൽകിയിട്ടുണ്ടെങ്കിൽ നൂറടി അടിക്കണം. മറിച്ചാണെങ്കിൽ എറിഞ്ഞുകൊല്ലുകയും വേണം." (ദ,തു,ന,ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 474, 474, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ سَلَمَةَ بْنِ الْمُحَبَّقِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَضَى فِي رَجُلٍ وَقَعَ عَلَى جَارِيَةِ امْرَأَتِهِ: "إِنْ كَانَ اسْتَكْرَهَهَا فَهِيَ حُرَّةٌ، وَعَلَيْهِ لِسَيِّدَتِهَا مِثْلُهَا، فَإِنْ كَانَتْ طَاوَعَتْهُ فَهِيَ لَهُ وَعَلَيْهِ لِسَيِّدَتِهَا مِثْلُهَا". وَفِي رِوَايَةٍ: وَإِنْ كَانَتْ طَاوَعَتْهُ فَهِيَ وَمِثْلُهَا مِنْ مَالِهِ لِسَيِّدَتِهَا". (د,ن,جه)', 'സലമതുബ്നുൽ മുഹബ്ബഖ്(റ): തന്റെ ഭാര്യയുടെ അടിമയുമായി ബന്ധത്തിലേർപ്പെട്ട ഒരാൾക്കെതിരെ നബി(സ) വിധിച്ചു: "അയാളവളെ ബലാൽക്കാരമായി ചെയ്തതാണെങ്കിൽ അവൾ സ്വതന്ത്രയും അവൻ തന്റെ ഭാര്യക്ക് അവളെപ്പോലെയുള്ള ഒരടിമയെ വാങ്ങിക്കൊടുക്കുകയും വേണം. അവൾ അദ്ദേഹത്തിന് സ്വയം വഴിപ്പെട്ടതാണെങ്കിൽ അവൾ അയാളുടെ അടിമയും അവൻ തന്റെ ഭാര്യക്ക് ഒരടിമയെ നൽകുകയും വേണം." മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെ കാണാം: "അവൾ അയാൾക്ക് സ്വയം വഴിപ്പെട്ടതാണെങ്കിൽ ആ അടിമയും അത്രതന്നെ തന്റെ മുതലുകളും അവന്റെ ഭാര്യക്കായിരിക്കും." (ദ,ന,ജ)', 'سَلَمَةَ بْنِ الْمُحَبَّقِ', 'സലമതുബ്നുൽ മുഹബ്ബഖ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 474, 474, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=43), 1, 'وَفِي رِوَايَةٍ: وَإِنْ كَانَتْ طَاوَعَتْهُ فَهِيَ وَمِثْلُهَا مِنْ مَالِهِ لِسَيِّدَتِهَا". (د,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെ കാണാം: "അവൾ അയാൾക്ക് സ്വയം വഴിപ്പെട്ടതാണെങ്കിൽ ആ അടിമയും അത്രതന്നെ തന്റെ മുതലുകളും അവന്റെ ഭാര്യക്കായിരിക്കും." (ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ سَلَمَةَ بْنِ الْمُحَبَّقِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ رُفِعَ إِلَيْهِ رَجُلٌ وَطِئَ جَارِيَةَ امْرَأَتِهِ، فَلَمْ يَحُدَّهُ. (د,ن,جه)', 'സലമതുബ്നുൽ മുഹബ്ബഖ്(റ): ഒരാൾ തന്റെ ഭാര്യയുടെ അടിമയുമായി വേഴ്ചയിലേർപ്പെട്ട ഒരു കേസ് നബി(സ)യുടെ സന്നിധിയിൽ കൊണ്ടുവന്നു. എന്നാൽ നബി(സ) അയാളെ ഹദ്ദടിച്ചില്ല. (ദ,ന,ജ)', 'سَلَمَةَ بْنِ الْمُحَبَّقِ', 'സലമതുബ്നുൽ മുഹബ്ബഖ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 474, 474, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتُكْرِهَتِ امْرَأَةٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَدَرَأَ عَنْهَا رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ الْحَدَّ، وَأَقَامَهُ عَلَى الَّذِي أَصَابَهَا. وَلَمْ يُذْكَرْ أَنَّهُ جَعَلَ لَهَا مَهْرًا. (د,ت)', 'വാഇലുബ്നു ഹുജ്ർ(റ): റസൂൽ(സ)യുടെ കാലത്ത് ഒരു സ്ത്രീ ബലാൽസംഗം ചെയ്യപ്പെട്ടു. അപ്പോൾ നബി(സ) ശിക്ഷ (ഹദ്ദ്) അവളിൽനിന്ന് ഒഴിവാക്കുകയും ബലാൽസംഗം ചെയ്തവനു ശിക്ഷ നടപ്പാക്കുകയും ചെയ്തു. അയാൾ അവൾക്കു മഹ്റു നൽകണമെന്നു നബി(സ) കൽപിച്ചതായി പറഞ്ഞിട്ടില്ല. (ദ,തു)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 474, 475, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ : أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الْأَمَةِ إِذَا زَنَتْ وَلَمْ تُحْصِنْ؟ قَالَ: "إِنْ زَنَتْ فَاجْلِدُوهَا، ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا، ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا، ثُمَّ بِيعُوهَا وَلَوْ بِضَفِيرٍ". قَالَ ابْنُ شِهَابٍ: لَا أَدْرِي أَبَعْدَ الثَّالِثَةِ أَوِ الرَّابِعَةِ. (م)', 'അബൂഹുറൈറ(റ): അവിവാഹിതയായ ഒരു അടിമസ്ത്രീ വ്യഭിചരിച്ചാൽ എന്തു ശിക്ഷയാണുള്ളതെന്നു നബി(സ)യോടു ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "അവളെ അടിക്കുക. പിന്നെയും വ്യഭിചരിച്ചാൽ അടിക്കുക. വീണ്ടും വ്യഭിചരിച്ചാൽ അടിക്കുകയും പിന്നീടു വിൽക്കുകയും ചെയ്യുക, അതൊരു കയറിനു പകരമാണെങ്കിലും." ഇബ്നുശിഹാബ് പറഞ്ഞു: മൂന്നാം പ്രാവശ്യമാണോ നാലാം പ്രാവശ്യമാണോ അതെന്ന് എനിക്കറിയില്ല. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 475, 475, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ [رَضِيَ اللهُ عَنْهُ] قَالَ: خَطَبَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ فَقَالَ: يَا أَيُّهَا النَّاسُ أَقِيمُوا عَلَى أَرِقَّائِكُمُ الْحَدَّ، مَنْ أَحْصَنَ مِنْهُمْ وَمَنْ لَمْ يُحْصِنْ، فَإِنَّ أَمَةً لِرَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ زَنَتْ فَأَمَرَنِي أَنْ أَجْلِدَهَا، فَإِذَا هِيَ حَدِيثُ عَهْدٍ بِنِفَاسٍ، فَخَشِيتُ إِنْ أَنَا جَلَدْتُهَا أَنْ أَقْتُلَهَا، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَحْسَنْتَ". وزاد في رواية: "اتْرُكْهَا حَتَّى تَمَاثَلَ". (م)', 'അബൂഅബ്ദിറഹ്മാൻ(റ): അലി(റ) പ്രസംഗിക്കവെ പറഞ്ഞു: ജനങ്ങളേ, നിങ്ങളുടെ അടിമകളുടെ മേൽ നിങ്ങൾ ശിക്ഷ നടപ്പാക്കുക. വിവാഹിതരാവട്ടെ, അല്ലാതിരിക്കട്ടെ. നബി(സ)യുടെ ഒരടിമ വ്യഭിചരിച്ചപ്പോൾ അവളെ അടിക്കാൻ നബി(സ)യെന്നോടു കൽപിച്ചു. തദവസരത്തിൽ അവൾക്ക് പ്രസവരക്തസ്രാവത്തിന്റെ ഘട്ടമായിരുന്നു. അപ്പോൾ ഞാനവളെ അടിച്ചാൽ അവൾ മരിക്കുമെന്നു ഞാൻ ഭയപ്പെട്ടു. അതു ഞാൻ നബി(സ)യോടു പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "നീ പറഞ്ഞതു ശരിയാണ്." ഒരു റിപ്പോർട്ടിൽ: "അവൾ പ്രസവിക്കുന്നതുവരെ അവളെ ഉപേക്ഷിക്കുക." (മു)', 'أَبِي عَبْدِ الرَّحْمَنِ [', 'അബൂഅബ്ദിറഹ്മാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], 'رَضِيَ اللهُ عَنْهُ', null, 475, 475, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ بِرَجُلٍ قَصِيرٍ أَشْعَثَ ذِي عَضَلَاتٍ، عَلَيْهِ إِزَارٌ، وَقَدْ زَنَى، فَرَدَّهُ مَرَّتَيْنِ، ثُمَّ أَمَرَ بِهِ فَرُجِمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "كُلَّمَا نَفَرْنَا غَازِينَ فِي سَبِيلِ اللَّهِ تَخَلَّفَ أَحَدُكُمْ يَنِبُّ نَبِيبَ التَّيْسِ، يَمْنَحُ إِحْدَاهُنَّ الْكُثْبَةَ، إِنَّ اللَّهَ لَا يُمْكِنِّي مِنْ أَحَدٍ مِنْهُمْ إِلَّا جَعَلْتُهُ نَكَالًا. أَوْ: نَكَّلْتُهُ". قَالَ: فَحَدَّثْتُهُ سَعِيدَ بْنَ جُبَيْرٍ فَقَالَ: إِنَّهُ رَدَّهُ أَرْبَعَ مَرَّاتٍ. وفي رواية: فَرَدَّهُ مَرَّتَيْنِ أَوْ ثَلَاثًا. (م)', 'ജാബിറുബ്നു സമുറ(റ): മുടി ജടകുത്തിയ കുറുതായ മാംസപേശികൾ ഉറച്ച ഒരാളെ നബി(സ)യുടെ അടുക്കൽ കൊണ്ടുവന്നു. വ്യഭിചരിച്ച അവൻ കച്ചയുടുത്തിട്ടുണ്ട്. രണ്ടുപ്രാവശ്യമയാളെ നബി(സ) മടക്കി അയച്ചു. പിന്നീട് എറിഞ്ഞുകൊല്ലാൻ കൽപിച്ചു. എറിഞ്ഞുകൊന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യാൻ വേണ്ടി വീടുവിട്ടിറങ്ങുമ്പോഴെല്ലാം നിങ്ങളിൽനിന്നൊരാൾ ആട്ടിൻകുട്ടിയുടെ ശബ്ദമുണ്ടാക്കിക്കൊണ്ട് പിന്തുടരുന്നു. അവരിലൊരാൾ അവന് അൽപം പാലും നൽകുന്നു. അവരിൽനിന്നൊരാളെയും എന്റെ പിടിയിലകപ്പെടാൻ അല്ലാഹു വഴിയുണ്ടാക്കാതിരിക്കട്ടെ. അങ്ങനെയെങ്കിൽ അവനെ ഞാൻ മറ്റുള്ളവർക്ക് ഒരു ദൃഷ്ടാന്തമാക്കും. അല്ലെങ്കിൽ ഞാനവന് കഠിന ശിക്ഷ നൽകും." ജാബിറുബ്നു സമുറ(റ) പറഞ്ഞു: ഇത് ഞാൻ സഈദുബ്നു ജുബൈർ(റ)വിനോട് ഉദ്ധരിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അവിടുന്ന് ഇത് നാലു പ്രാവശ്യമാവർത്തിച്ചു. മറ്റൊരു നിവേദനത്തിൽ: രണ്ടോ മൂന്നോ പ്രാവശ്യം അവിടുന്ന് ഇതാവർത്തിച്ചു. (മു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 475, 476, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=48), 1, 'وَفِي رِوَايَةٍ: فَرَدَّهُ مَرَّتَيْنِ أَوْ ثَلَاثًا. (م)', 'മറ്റൊരു നിവേദനത്തിൽ: രണ്ടോ മൂന്നോ പ്രാവശ്യം അവിടുന്ന് ഇതാവർത്തിച്ചു. (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ مَاعِزَ بْنَ مَالِكٍ الْأَسْلَمِيَّ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي قَدْ ظَلَمْتُ نَفْسِي وَزَنَيْتُ، وَإِنِّي أُرِيدُ أَنْ تُطَهِّرَنِي. فَرَدَّهُ، فَلَمَّا كَانَ مِنَ الْغَدِ أَتَاهُ، فَقَالَ: يَا رَسُولَ اللَّهِ إِنِّي قَدْ زَنَيْتُ. فَرَدَّهُ الثَّانِيَةَ، فَأَرْسَلَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ إِلَى قَوْمِهِ فَقَالَ: "تَعْلَمُونَ بِعَقْلِهِ بَأْسًا؟ تُنْكِرُونَ مِنْهُ شَيْئًا". فَقَالُوا: مَا نَعْلَمُهُ إِلَّا وَفِيَّ الْعَقْلِ مِنْ صَالِحِينَا فِيمَا نُرَى. فَأَتَاهُ الثَّالِثَةَ، فَأَرْسَلَ إِلَيْهِمْ أَيْضًا فَسَأَلَ عَنْهُ، فَأَخْبَرُوهُ أَنَّهُ لَا بَأْسَ بِهِ وَلَا بِعَقْلِهِ، فَلَمَّا كَانَ الرَّابِعَةَ حَفَرَ لَهُ حُفْرَةً، ثُمَّ أَمَرَ بِهِ فَرُجِمَ. قَالَ: فَجَاءَتِ الْغَامِدِيَّةُ، فَقَالَتْ: يَا رَسُولَ اللَّهِ إِنِّي قَدْ زَنَيْتُ فَطَهِّرْنِي. وَإِنَّهُ رَدَّهَا، فَلَمَّا كَانَ الْغَدُ، قَالَتْ: يَا رَسُولَ اللَّهِ لِمَ تَرُدُّنِي؟ لَعَلَّكَ أَنْ تَرُدَّنِي كَمَا رَدَدْتَ مَاعِزًا، فَوَاللَّهِ إِنِّي لَحُبْلَى. قَالَ: "إِمَّا لَا فَاذْهَبِي حَتَّى تَلِدِي". قَالَ: فَلَمَّا وَلَدَتْ أَتَتْهُ بِالصَّبِيِّ فِي خِرْقَةٍ قَالَتْ: هَذَا قَدْ وَلَدْتُهُ، قَالَ: "اذْهَبِي فَأَرْضِعِيهِ حَتَّى تَفْطِمِيهِ". فَلَمَّا فَطَمَتْهُ أَتَتْهُ بِالصَّبِيِّ فِي يَدِهِ كِسْرَةُ خُبْزٍ، فَقَالَتْ: هَذَا يَا رَسُولَ اللَّهِ قَدْ فَطَمْتُهُ، وَقَدْ أَكَلَ الطَّعَامَ، فَدَفَعَ الصَّبِيَّ إِلَى رَجُلٍ مِنَ الْمُسْلِمِينَ، ثُمَّ أَمَرَ بِهَا فَحُفِرَ لَهَا إِلَى صَدْرِهَا، وَأَمَرَ النَّاسَ فَرَجَمُوهَا، فَيُقْبِلُ خَالِدُ بْنُ الْوَلِيدِ بِحَجَرٍ فَرَمَى رَأْسَهَا، فَتَنَضَّحَ الدَّمُ عَلَى وَجْهِ خَالِدٍ، فَسَبَّهَا، فَسَمِعَ نَبِيُّ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ سَبَّهُ إِيَّاهَا فَقَالَ: "مَهْلًا يَا خَالِدُ، فَوَالَّذِي نَفْسِي بِيَدِهِ لَقَدْ تَابَتْ تَوْبَةً لَوْ تَابَهَا صَاحِبُ مَكْسٍ لَغُفِرَ لَهُ". ثُمَّ أَمَرَ بِهَا فَصَلَّى عَلَيْهَا وَدُفِنَتْ. (م)', 'ബുറൈദ(റ): മാഇസുബ്നു മാലികിൽ അസ്ലമി റസൂൽ(സ)യുടെ അടുക്കൽ വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ എന്റെ ആത്മാവിനെ ദ്രോഹിച്ചു, ഞാൻ വ്യഭിചരിച്ചിരിക്കുന്നു. ആയതിനാൽ എന്നെ അങ്ങ് ശുദ്ധീകരിച്ചുതരണം. നബി(സ) അദ്ദേഹത്തെ മടക്കി അയച്ചു. രണ്ടാം ദിവസവുമദ്ദേഹം വന്നു. നബി(സ)യോടു പറഞ്ഞു: അല്ലഹുവിന്റെ റസൂലേ, ഞാൻ വ്യഭിചരിച്ചിരിക്കുന്നു. രണ്ടാമതും നബി(സ) അദ്ദേഹത്തെ മടക്കി അയച്ചു. അങ്ങനെ നബി(സ) ഒരാളെ അദ്ദേഹത്തിന്റെ നാട്ടുകാരിലേക്ക് പറഞ്ഞയച്ചു ചോദിച്ചു: "അദ്ദേഹത്തിന്റെ ബുദ്ധിക്കു വല്ല തകരാറുമുണ്ടോ? നന്മയല്ലാത്തത് ചെയ്യുന്നുവെന്ന് അഭിപ്രായമുണ്ടോ?" അവർ പറഞ്ഞു: ഞങ്ങളുടെ അഭിപ്രായത്തിൽ ഞങ്ങൾക്കിടയിലെ സദ്വൃത്തരിൽ ബുദ്ധിമാനാണദ്ദേഹം. അദ്ദേഹം മൂന്നാമതും നബി(സ)യുടെ അടുക്കൽ വന്നു. അങ്ങനെ വീണ്ടും നബി(സ) അവരിലേക്ക് ആളെവിട്ട് അദ്ദേഹത്തെക്കുറിച്ച് അന്വേഷിച്ചു. അദ്ദേഹത്തിന്റെ ബുദ്ധിക്ക് ഒരു തകരാറുമില്ലെന്നും അദ്ദേഹത്തിനൊരു കുഴപ്പവുമില്ലെന്നും അറിയിച്ചു. നാലാമതും വന്നപ്പോൾ അദ്ദേഹത്തിനു വേണ്ടി കുഴി വെട്ടുവാനും അദ്ദേഹത്തെ എറിഞ്ഞു കൊല്ലുവാനും കൽപിക്കുകയും എറിയപ്പെടുകയും ചെയ്തു. ബുറൈദ(റ) പറയുന്നു: ഗാമിദി ഗോത്രത്തിൽപ്പെട്ട ഒരു സ്ത്രീ വന്നു നബി(സ)യോടു പറഞ്ഞു: ഞാൻ വ്യഭിചരിച്ചിരിക്കുന്നു. നബിയേ, എന്നെ ശുദ്ധീകരിക്കണം. നബി(സ) അവളെ മടക്കി അയച്ചു. രണ്ടാം ദിവസം അവൾ വന്നു. നബി(സ)യോടു ചോദിച്ചു: താങ്കളെന്തിനാണെന്നെ മടക്കി അയക്കുന്നത്? താങ്കളെന്നെ മാഇസിനെ മടക്കി അയച്ചതുപോലെ അയക്കുകയാവും. എന്നാൽ അല്ലാഹുവാണ, നിശ്ചയം ഞാൻ ഗർഭിണിയാണ്. നബി(സ) പറഞ്ഞു: "എന്നാൽ നീ പ്രസവിച്ചതിന് ശേഷം വരിക." അങ്ങനെ പ്രസവിച്ചയുടനെ തുണിക്കഷ്ണത്തിൽ പൊതിഞ്ഞ ഒരു കുഞ്ഞിനെയുമായവൾ വന്നു. അവൾ പറഞ്ഞു: ഇതാ ഈ കുട്ടിയെ ഞാൻ പ്രസവിച്ചിരിക്കുന്നു. നബി(സ) അവളോടു പറഞ്ഞു: "നീ പോയി കുഞ്ഞിന് മുലകൊടുക്കുക, മുലകുടി മാറ്റുന്നതുവരെ." അങ്ങനെ കുട്ടി മുലകുടി മാറ്റിയ അവസരത്തിൽ അവൾ വന്നപ്പോൾ കുഞ്ഞിന്റെ കയ്യിൽ ഒരു പത്തിരിക്കഷ്ണമുണ്ടായിരുന്നു. അവൾ പറഞ്ഞു: ഇതാ നബിയേ, ഞാൻ മുലകുടി നിർത്തിച്ചിരിക്കുന്നു. ഇവൻ ഭക്ഷണം കഴിക്കാനും തുടങ്ങി. അങ്ങനെ കുഞ്ഞിനെ മുസ്ലിംകളിലൊരാളുടെയടുക്കൽ നൽകുകയും അവളുടെ നെഞ്ചിന്റെ ആഴത്തിൽ കുഴിവെട്ടാൻ നബി(സ) കൽപിക്കുകയും കുഴിയുണ്ടാക്കുകയും ചെയ്തു. ജനങ്ങളോട് എറിഞ്ഞുകൊല്ലാൻ ആജ്ഞാപിക്കുകയും അവർ എറിഞ്ഞു കൊല്ലുകയും ചെയ്തു. അതിൽ ഖാലിദുബ്നു വലീദ്(റ) ഒരു കല്ലെടുത്തു അവളുടെ തലക്കെറിഞ്ഞു. അപ്പോൾ അൽപം രക്തം ഖാലിദ്(റ)വിന്റെ മുഖത്തേക്ക് തെറിച്ചു. അപ്പോൾ ഖാലിദ്(റ) അവളെ ചീത്തവിളിച്ചു. നബി(സ) ഇതു കേൾക്കാനിടയായി. നബി(സ) പറഞ്ഞു: "വേണ്ട ഖാലിദേ, എന്റെ ശരീരം കയ്യിലടക്കിയവൻ തന്നെ സത്യം, ഒരു ചുങ്കം പിരിക്കുന്ന (ബലാൽക്കാരമായി) അസാൻമാർഗ്ഗിക്കു പോലും മാപ്പുലഭിക്കാവുന്ന പശ്ചാത്താപമാണവൾ ചെയ്തത്. ശേഷമവൾക്ക് വേണ്ടി നിസ്കരിക്കാൻ കൽപിക്കുകയും നബി(സ) നിസ്കരിക്കുകയും അവളെ മറമാടുകയും ചെയ്തു. (മു)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 476, 477, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا مِنْ بَكْرِ بْنِ لَيْثٍ أَتَى النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَأَقَرَّ أَنَّهُ زَنَى بِامْرَأَةٍ، أَرْبَعَ مَرَّاتٍ، فَجَلَدَهُ مِائَةً، وَكَانَ بِكْرًا، ثُمَّ سَأَلَهُ الْبَيِّنَةَ عَلَى الْمَرْأَةِ، فَقَالَتْ: كَذَبَ وَاللَّهِ يَا رَسُولَ اللَّهِ، فَجَلَدَهُ حَدَّ الْفِرْيَةِ ثَمَانِينَ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ബക്റുബ്നു ലൈസ് കുടുംബത്തിൽപ്പെട്ട ഒരാൾ നബി(സ)യുടെ അടുക്കൽ വന്ന് ഒരു സ്ത്രീയുമായി നാലു പ്രാവശ്യം താൻ വ്യഭിചരിച്ചതായി പറഞ്ഞു. അപ്പോൾ അദ്ദേഹത്തെ നൂറടി അടിച്ചു. അദ്ദേഹം അവിവാഹിതനായിരുന്നു. ശേഷം അവൾക്കെതിരെയുള്ള തെളിവ് ചോദിച്ചപ്പോൾ അവൾ പറഞ്ഞു: അല്ലാഹുവാണ, അവൻ കളവാണ് പറഞ്ഞത് നബിയേ. അങ്ങനെ അപവാദം പറഞ്ഞതിന് എൺപത് അടിയും നൽകി. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 477, 477, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي عَالَجْتُ امْرَأَةً مِنْ أَقْصَى الْمَدِينَةِ، فَأَصَبْتُ مِنْهَا مَا دُونَ أَنْ أَمَسَّهَا، فَأَنَا هَذَا، فَأَقِمْ عَلَيَّ مَا شِئْتَ. فَقَالَ عُمَرُ: قَدْ سَتَرَ اللَّهُ عَلَيْكَ لَوْ سَتَرْتَ عَلَى نَفْسِكَ، فَلَمْ يَرُدَّ عَلَيْهِ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ شَيْئًا، فَانْطَلَقَ الرَّجُلُ، فَأَتْبَعَهُ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ رَجُلًا فَدَعَاهُ، فَتَلَا عَلَيْهِ: {وَأَقِمِ الصَّلَاةَ طَرَفَيِ النَّهَارِ وَزُلَفًا مِنَ اللَّيْلِ} إِلَى آخِرِ الْآيَةِ، فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: يَا رَسُولَ اللَّهِ، أَلَهُ خَاصَّةً أَمْ لِلنَّاسِ كَافَّةً؟ فَقَالَ: "لِلنَّاسِ كَافَّةً". (ق,د,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഒരാൾ നബി(സ)യുടെ അടുക്കൽ വന്നു പറഞ്ഞു: മദീനായുടെ അറ്റത്തുള്ള ഒരു സ്ത്രീയുമായി ഞാൻ വ്യവഹരിച്ചു. വ്യഭിചാരമല്ലാത്ത കാര്യങ്ങൾ അവളിൽ ഞാൻ ചെയ്തു. ഞാനിതാ വന്നിരിക്കുന്നു. എന്റെ മേൽ വേണ്ട നടപടി കൈകൊള്ളുക. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: നീ ഇത് മറച്ചു വെച്ചിരുന്നുവെങ്കിൽ അല്ലാഹുവും അതു മറച്ചു വെക്കുമായിരുന്നില്ലെയോ? നബി(സ) മറുപടിയൊന്നും പറഞ്ഞില്ല. അങ്ങിനെ അദ്ദേഹം പോയപ്പോൾ ഒരാളെ വിട്ടു നബി(സ)അദ്ദേഹത്തെ വിളിപ്പിച്ചു. അദ്ദേഹത്തിന് നബി(സ) ഓതിക്കൊടുത്തു: ''പകലിന്റെ രണ്ടറ്റങ്ങളിലും രാത്രിയിൽനിന്നുള്ള ഭാഗങ്ങളിലും താങ്കൾ നിസ്കാരം നില നിർത്തുക'' എന്ന സൂക്തം അതിന്റെ അവസാനം വരെ. അപ്പോൾ അതിലൊരാൾ ചോദിച്ചു. അല്ലാഹുവിന്റെ റസൂലേ, അത് അദ്ദേഹത്തിന് മാത്രം പ്രത്യേകമോ അതോ എല്ലാവർക്കുമുള്ളതോ? നബി(സ) പറഞ്ഞു: "ജനങ്ങൾ എല്ലാവർക്കും." (ബു,മു,ദ,തു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 477, 478, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا زَنَتْ أَمَةُ أَحَدِكُمْ فَلْيَحُدَّهَا وَلَا يُعَيِّرْهَا، ثَلَاثَ مِرَارٍ، فَإِنْ عَادَتْ فِي الرَّابِعَةِ فَلْيَجْلِدْهَا وَلْيَبِعْهَا بِضَفِيرٍ. أَوْ: بِحَبْلٍ مِنْ شَعْرٍ". (م,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ അടിമസ്ത്രീ വ്യഭിചരിച്ചാൽ അവളെ നിങ്ങൾ അടിക്കുക, ഭീഷണിപ്പെടുത്തരുത്. മൂന്ന് പ്രാവശ്യം ഇങ്ങനെ ചെയ്യുക. നാലാം പ്രാവശ്യം ആവർത്തിച്ചാൽ അവളെ അടിക്കുകയും ഒരു കയറിനോ മുടിക്കയറിനോ പകരമായി വിൽക്കുകയും ചെയ്യുക." (മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 478, 478, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، بِهَذَا الْحَدِيثِ، قَالَ فِي كُلِّ مَرَّةٍ: "فَلْيَضْرِبْهَا، كِتَابُ اللَّهِ، وَلَا يُثَرِّبْ عَلَيْهَا". وَقَالَ فِي الرَّابِعَةِ: "فَإِنْ عَادَتْ فَلْيَضْرِبْهَا كِتَابُ اللَّهِ، ثُمَّ لِيَبِعْهَا وَلَوْ بِحَبْلٍ مِنْ شَعْرٍ". (ق,د)', 'അബൂഹുറൈറ(റ): മേൽ ഹദീസ് ഉദ്ധരിച്ചു, എല്ലാപ്രാവശ്യവും നബി(സ) പറഞ്ഞു: "അവളെ ഖുർആനിലുള്ളതുപോലെ അടിക്കുക, അവളെ ആക്ഷേപിക്കരുത്." നാലാം പ്രാവശ്യത്തിൽ പറഞ്ഞു: "വീണ്ടും അവളത് ആവർത്തിച്ചാൽ ഖുർആൻ പറഞ്ഞതനുസരിച്ച് അടിക്കുകയും ഒരു കയറിനു പകരമായെങ്കിലും വിൽക്കുകയും ചെയ്യുക." (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 478, 478, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَيْنَا أَنَا أَطُوفُ عَلَى إِبِلٍ لِي ضَلَّتْ إِذْ أَقْبَلَ رَكْبٌ - أَوْ فَوَارِسُ - مَعَهُمْ لِوَاءٌ، فَجَعَلَ الْأَعْرَابُ يَطِيفُونَ بِي لِمَنْزِلَتِي مِنَ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، إِذْ أَتَوْا قُبَّةً فَاسْتَخْرَجُوا مِنْهَا رَجُلًا فَضَرَبُوا عُنُقَهُ، فَسَأَلْتُ عَنْهُ، فَذَكَرُوا أَنَّهُ أَعْرَسَ بِامْرَأَةِ أَبِيهِ. (د)', 'ബറാഉബ്നു ആസിബ്(റ): എന്റെ നഷ്ടപ്പെട്ട ഒരൊട്ടകത്തെയും അന്വേഷിച്ച് നടക്കവെ ഒരു വാഹനസംഘത്തെ അല്ലെങ്കിൽ കുതിര സവാരിക്കാരെ കണ്ടുമുട്ടാനിടയായി. അവരുടെ കൂടെ ഒരു കൊടിയുണ്ടായിരുന്നു. എനിക്ക് നബി(സ)യുടെ അടുത്തുണ്ടായിരുന്ന സ്ഥാനം കാരണം, ആ അഅ്റാബികൾ എനിക്കുചുറ്റും വരാൻ തുടങ്ങി. അവർ ഒരു കൂടാരത്തിൽ നിന്നും ഒരാളെ പുറത്തെടുക്കുകയും പിരടിവെട്ടി കൊലപ്പെടുത്തുകയും ചെയ്തു. അതിനെപ്പറ്റി ആരാഞ്ഞപ്പോൾ അവർ പറഞ്ഞത് അദ്ദേഹം തന്റെ പിതാവിന്റെ ഭാര്യയെ വിവാഹം കഴിക്കുകയും ബന്ധപ്പെടുകയും ചെയ്തു എന്നാണ്. (ദ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 478, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: لَقِيتُ عَمِّي وَمَعَهُ رَايَةٌ، فَقُلْتُ لَهُ: أَيْنَ تُرِيدُ؟ قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ إِلَى رَجُلٍ نَكَحَ امْرَأَةَ أَبِيهِ، فَأَمَرَنِي أَنْ أَضْرِبَ عُنُقَهُ وَآخُذَ مَالَهُ. (د,ت,ن,جه)', 'ബറാഉബ്നു ആസിബ്(റ): ഞാൻ എന്റെ പിതൃവ്യനെ കണ്ടപ്പോൾ അദ്ദേഹത്തോടൊപ്പം ഒരു പതാകയുമുണ്ടായിരുന്നു. ഞാൻ അദ്ദേഹത്തോടു ചോദിച്ചു: എങ്ങോട്ടാണ് പോകുന്നത്? അദ്ദേഹം പറഞ്ഞു: തന്റെ പിതാവിന്റെ ഭാര്യയെ വിവാഹം ചെയ്ത ഒരാളുടെ അടുത്തേക്ക് നബി(സ) എന്നെ പറഞ്ഞയച്ചിരിക്കുന്നു. അദ്ദേഹത്തിന്റെ പിരടി അറുക്കുവാനും ധനം പിടിച്ചെടുക്കുവാനും നബി(സ) എന്നോട് ആജ്ഞാപിച്ചിരിക്കുന്നു. (ദ,തു,ന,ജ)', 'الْبَرَاءِ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 479, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَوْ كُنْتُ رَاجِمًا أَحَدًا بِغَيْرِ بَيِّنَةٍ لَرَجَمْتُ فُلَانَةَ، فَقَدْ ظَهَرَ مِنْهَا الرِّيبَةُ فِي مَنْطِقِهَا وَهَيْئَتِهَا وَمَنْ يَدْخُلُ عَلَيْهَا". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "തെളിവു കൂടാതെ ഞാൻ ഒരാളെ എറിഞ്ഞു കൊല്ലുന്നവനായിരുന്നുവെങ്കിൽ ഞാൻ ഇന്നാലിന്നവളെ എറിഞ്ഞുകൊല്ലുമായിരുന്നു. അവളുടെ സംസാരത്തിൽ നിന്നും രൂപത്തിൽനിന്നും അവളുടെയടുത്ത് പോകുന്നവർക്കും സംശയം പ്രകടമായിരിക്കുന്നു." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 479, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ قَالَ: ذَكَرَ ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا الْمُتَلَاعِنَيْنِ، فَقَالَ لَهُ ابْنُ شَدَّادٍ: هِيَ الَّتِي قَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَوْ كُنْتُ رَاجِمًا أَحَدًا بِغَيْرِ بَيِّنَةٍ لَرَجَمْتُهَا". فَقَالَ ابْنُ عَبَّاسٍ: تِلْكَ امْرَأَةٌ أَعْلَنَتْ. (ق,جه)', 'ഖാസിമുബ്നു മുഹമ്മദ്(റ): ഇബ്നുഅബ്ബാസ്(റ), പരസ്പരം ''ലിആൻ'' (പരസ്പരം ശാപവചനം ചൊല്ലിപ്പിരിയുന്ന ഭാര്യഭർത്താക്കന്മാർ) ചെയ്യുന്നവരെ പ്രതിപാദിച്ചു. അപ്പോൾ ഇബ്നുശദ്ദാദ് അദ്ദേഹത്തോടു പറഞ്ഞു: "തെളിവുകൂടാതെ ഞാനൊരാളെ എറിയുമായിരുന്നെങ്കിൽ ഞാൻ അവളെ എറിയുമായിരുന്നു" എന്ന് നബി(സ) പറഞ്ഞവളാണവൾ. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അവൾ പരസ്യമായി ചെയ്തവളാണ്. (ബു,മു,ജ)', 'الْقَاسِمِ بْنِ مُحَمَّدٍ قَالَ', 'ഖാസിമുബ്നു മുഹമ്മദ്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 479, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ أَتَى بَهِيمَةً فَاقْتُلُوهُ، وَاقْتُلُوهَا مَعَهُ". قَالَ: قُلْتُ لَهُ: مَا شَأْنُ الْبَهِيمَةِ؟ قَالَ: مَا أُرَاهُ قَالَ ذَلِكَ إِلَّا أَنَّهُ كَرِهَ أَنْ يُؤْكَلَ لَحْمُهَا وَقَدْ عُمِلَ بِهَا ذَلِكَ الْعَمَلُ. قَالَ أَبُو دَاوُدَ: لَيْسَ هَذَا بِالْقَوِيِّ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ (വേഴ്ച്ചക്കായി) മൃഗത്തെ സമീപിച്ചാൽ അവനെ വധിച്ചുകളയുക. മൃഗത്തെയും അവനോടെപ്പം കൊന്നുകളയുക." നിവേദകൻ പറയുന്നു: ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിനോടു ചോദിച്ചു: എന്തുകൊണ്ടാണ് മൃഗത്തെ വധിക്കുന്നത്? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഈ പ്രവർത്തനത്തിന് വേദിയാക്കിയ ജീവിയുടെ മാംസം ഭക്ഷിക്കുന്നത് വെറുത്തതു കാരണമാവും നബി(സ) അങ്ങനെ പറഞ്ഞതെന്ന് എനിക്ക് തോന്നുന്നു. അബൂദാവൂദ് പറഞ്ഞു: ഇത് ബലമുള്ള റിപ്പോർട്ടല്ല. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 479, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ وَقَعَ عَلَى ذَاتِ مَحْرَمٍ فَاقْتُلُوهُ، وَمَنْ وَقَعَ عَلَى بَهِيمَةٍ فَاقْتُلُوهُ وَاقْتُلُوا الْبَهِيمَةَ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ വിവാഹം ചെയ്യൽ നിഷിദ്ധമായവളുമായി അവിഹിത ബന്ധത്തിൽ ഏർപ്പെട്ടാൽ അവനെ വധിച്ചുകളുക. ഒരാൾ മൃഗവുമായി ബന്ധപ്പെട്ടാൽ അവനെയും മൃഗത്തെയും കൊന്നുകളയുക." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَيْسَ عَلَى الَّذِي يَأْتِي الْبَهِيمَةَ حَدٌّ. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): മൃഗവുമായി ഇഛരാശക്തി തീർക്കുന്നവന് ''ഹദ്ദ്'' (ശിക്ഷാവിധി) ഇല്ല. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ وَجَدْتُمُوهُ وَقَعَ عَلَى بَهِيمَةٍ فَاقْتُلُوهُ وَاقْتُلُوا الْبَهِيمَةَ". فَقِيلَ لِابْنِ عَبَّاسٍ: مَا شَأْنُ الْبَهِيمَةِ؟ قَالَ: مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فِي ذَلِكَ شَيْئًا، وَلَكِنْ أَرَى رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ كَرِهَ أَنْ يُؤْكَلَ مِنْ لَحْمِهَا أَوْ يُنْتَفَعَ بِهَا، وَقَدْ عُمِلَ بِهَا ذَلِكَ الْعَمَلُ. (د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ മൃഗവുമായി ഭോഗിക്കുന്നതുകണ്ടാൽ അവനെയും മൃഗത്തെയും വധിക്കുക." അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ)വിനോടു ചോദിക്കപ്പെട്ടു: മൃഗത്തെ വധിക്കുന്നത് എന്തിനാണ്? അദ്ദേഹം പറഞ്ഞു: അതേക്കുറിച്ച് റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടില്ല. പക്ഷേ, ആ മൃഗത്തെ അപ്രകാരം ചെയ്തതിന് ശേഷം അതിന്റെ മാംസം ഭക്ഷിക്കുന്നതും അതുകൊണ്ട് ഉപകാരമെടുക്കുന്നതും റസൂൽ(സ) വെറുക്കുന്നു എന്നാണ് ഞാൻ മനസ്സിലാക്കുന്നത്. (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ وَجَدْتُمُوهُ يَعْمَلُ عَمَلَ قَوْمِ لُوطٍ فَاقْتُلُوا الْفَاعِلَ وَالْمَفْعُولَ بِهِ". (د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ലൂത്ത്(അ)മിന്റെ ജനതയുടെ കർമ്മത്തിലേർപ്പെടുന്നതായി വല്ലവനെയും നിങ്ങൾക്ക് കാണാൻ കഴിഞ്ഞാൽ പ്രവർത്തിച്ചവനെയും പ്രവർത്തിക്കപ്പെട്ടവനെയും നിങ്ങൾ വധിക്കുക." (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ - فِي الَّذِي يَعْمَلُ عَمَلَ قَوْمِ لُوطٍ قَالَ: "ارْجُمُوا الْأَعْلَى وَالْأَسْفَلَ، ارْجُمُوهُمَا جَمِيعًا". (ت,جه)', 'അബൂഹുറൈറ(റ): ലൂത്ത് നബി(അ)മിന്റെ ജനതയുടെ പ്രവർത്തനത്തിലേർപ്പെടുന്നവനെക്കുറിച്ച് നബി(സ) പറഞ്ഞു: "മുകളിലുള്ളവനെയും താഴെയുള്ളവനെയും നിങ്ങൾ എറിഞ്ഞുകൊല്ലുക. രണ്ടുപേരെയും എറിഞ്ഞുകൊല്ലുക." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: فِي الْبِكْرِ يُؤْخَذُ عَلَى اللُّوطِيَّةِ، قَالَ: يُرْجَمُ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): അവിവാഹിതനെ ''ലിവാത്തി''ന്റെ (പിൻഭാഗത്തുകൂടെ വേഴ്ചനടത്തുക) വിഷയത്തിൽ പിടിക്കപ്പെട്ടാൽ എറിഞ്ഞുകൊല്ലണം. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 481, 481, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنَّ أَخْوَفَ مَا أَخَافُ عَلَى أُمَّتِي عَمَلُ قَوْمِ لُوطٍ". (ت,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിന്റെ മേൽ ഞാൻ ഏറ്റവും ഭയപ്പെടുന്നത് ലൂത്ത് നബി(അ)മിന്റെ ജനതയുടെ പ്രവർത്തനമാണ്." (തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 481, 481, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ قُرَيْشًا أَهَمَّهُمْ شَأْنُ الْمَرْأَةِ الْمَخْزُومِيَّةِ الَّتِي سَرَقَتْ، فَقَالُوا: مَنْ يُكَلِّمُ فِيهَا رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ؟ قَالُوا: وَمَنْ يَجْتَرِئُ عَلَيْهِ إِلَّا أُسَامَةُ بْنُ زَيْدٍ، حِبُّ رَسُولِ اللَّهِ صلى الله عليه وسلم؟ فَكَلَّمَهُ أُسَامَةُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "أَتَشْفَعُ فِي حَدٍّ مِنْ حُدُودِ اللَّهِ". ثُمَّ قَامَ فَاخْتَطَبَ فَقَالَ: "يَا أَيُّهَا النَّاسُ، إِنَّمَا هَلَكَ الَّذِينَ مِنْ قَبْلِكُمْ: أَنَّهُمْ كَانُوا إِذَا سَرَقَ فِيهِمُ الشَّرِيفُ تَرَكُوهُ، وَإِذَا سَرَقَ فِيهِمُ الضَّعِيفُ أَقَامُوا عَلَيْهِ الْحَدَّ. وَايْمُ اللَّهِ، لَوْ أَنَّ فَاطِمَةَ بِنْتَ مُحَمَّدٍ سَرَقَتْ لَقَطَعْتُ يَدَهَا". (ق,د,ت,ن,جه)', 'ആഇശ(റ): കളവ് നടത്തിയ മഖ്സൂം ഗോത്രത്തിലെ ഒരു സ്ത്രീയുടെ കാര്യം ഖുറൈശികളെ വല്ലാതെ ദുഃഖിപ്പിച്ചു. ഇതുസംബന്ധമായി ആരാണ് നബി(സ)യോട് സംസാരിക്കാൻ തയ്യാറാവുകയെന്ന് അവർ ചോദിച്ചു. അവരിൽ ചിലർ പറഞ്ഞു: റസൂൽ(സ)യുടെ പ്രിയങ്കരനായ ഉസാമതബ്നു സൈദ്(റ) അല്ലാതെ ആരാണതിന് ധൈര്യം കാണിക്കുക. അങ്ങനെ ഉസാമ(റ) റസൂൽ(സ)യുമായി സംസാരിച്ചു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "അല്ലാഹുവിന്റെ ശിക്ഷകളിൽ നിന്ന് ഒരു ശിക്ഷ (ഒഴിവാക്കാൻ) വേണ്ടി നീ ശിപാർശചെയ്യുകയാണോ?" തുടർന്നു നബി(സ) പ്രസംഗിക്കാൻ എഴുന്നേറ്റു നിന്നു. നബി(സ) പറഞ്ഞു: "മനുഷ്യരേ, നിങ്ങളുടെ മുൻഗാമികളായ സമൂഹം നശിക്കാൻ കാരണമായത് അവരിലെ ഉന്നതർ മോഷ്ടിച്ചാൽ അയാളെ അവർ വെറുതെ വിടുകയും പാവങ്ങൾ മോഷ്ടിച്ചാൽ അയാളുടെ മേൽ ഹദ്ദ് നടപ്പാക്കുകയും ചെയ്യുമായിരുന്നത് കൊണ്ടാണ്. അല്ലാഹുവാണ, മുഹമ്മദിന്റെ മകൾ ഫാത്തിമയാണ് മോഷ്ടിച്ചതെങ്കിലും അവളുടെ കൈ ഞാൻ മുറിക്കും." (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 481, 481, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ مَسْعُودِ بْنِ الْأَسْوَدِ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا سَرَقَتِ الْمَرْأَةُ تِلْكَ الْقَطِيفَةَ مِنْ بَيْتِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَعْظَمْنَا ذَلِكَ، وَكَانَتِ امْرَأَةً مِنْ قُرَيْشٍ، فَجِئْنَا إِلَى النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ نُكَلِّمُهُ، وَقُلْنَا: نَحْنُ نَفْدِيهَا بِأَرْبَعِينَ أُوقِيَّةً. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "تُطَهَّرُ خَيْرٌ لَهَا". فَلَمَّا سَمِعْنَا لِينَ قَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَتَيْنَا أُسَامَةَ فَقُلْنَا: كَلِّمْ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ. فَلَمَّا رَأَى رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ ذَلِكَ قَامَ خَطِيبًا، فَقَالَ: "مَا إِكْثَارُكُمْ عَلَيَّ فِي حَدٍّ مِنْ حُدُودِ اللَّهِ عَزَّ وَجَلَّ، وَقَعَ عَلَى أَمَةٍ مِنْ إِمَاءِ اللَّهِ؟ وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَوْ كَانَتْ فَاطِمَةُ ابْنَةُ رَسُولِ اللَّهِ نَزَلَتْ بِالَّذِي نَزَلَتْ بِهِ لَقَطَعَ مُحَمَّدٌ يَدَهَا". [ز: فِيهِ مُدَلِّسٌ عَنْعَنَهُ] (جه)', 'മസ്ഊദുബ്നുൽ അസ്വദ്(റ): റസൂൽ(സ)യുടെ വീട്ടിൽനിന്ന് ആ സ്ത്രീ സൂര്യകാന്തിപ്പട്ട് മോഷ്ടിച്ചപ്പോൾ ഞങ്ങൾക്കത് വലിയ പ്രശ്നമായി. അവൾ ഖുറൈശികളിൽപ്പെട്ട വളായിരുന്നു. അങ്ങനെ ഞങ്ങൾ സംസാരിക്കാൻ വേണ്ടി റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്നു. ഞങ്ങൾ പറഞ്ഞു: നാൽപത് ഊഖിയ (ഒരു പ്രത്യേക തൂക്കം) അവൾക്ക് പകരമായി ഞങ്ങൾ നൽകാം. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ശുദ്ധീകരണമാണ് അതിനേക്കാൾ നല്ലത്." നബി(സ)യുടെ വാക്കിലുള്ള മൃദുലത കണ്ടപ്പോൾ ഞങ്ങൾ ഉസാമ(റ)വിന്റെ അടുത്തുചെന്ന് പറഞ്ഞു: നീ നസൂൽ(സ)യോട് സംസാരിക്കുക. അതുകണ്ടപ്പോൾ റസൂൽ(സ) പ്രസംഗിക്കാൻ എഴുന്നേറ്റുനിന്നു. അവിടന്നു പറഞ്ഞു: "അല്ലാഹു നിർബന്ധമാക്കിയ ഒരു ഹദ്ദ് (ശിക്ഷ) അല്ലാഹുവിന്റെ ഒരടിമയിൽ സംഭവിച്ചിരിക്കുന്നു എന്ന വിഷയത്തിൽ എന്തിനാണ് നിങ്ങൾ എന്നോട് കൂടുതലായി സമ്മർദ്ദം ചെലുത്തുന്നത്! അല്ലാഹുവിനെ തന്നെയാണ് സത്യം, അല്ലാഹുവിന്റെ ദൂതന്റെ മകളായ ഫാത്വിമക്കാണിത് ഉണ്ടായതെങ്കിൽ മുഹമ്മദ് അവളുടെ കൈ മുറിച്ചുമാറ്റും." (ജ)', 'مَسْعُودِ بْنِ الْأَسْوَدِ', 'മസ്ഊദുബ്നുൽ അസ്വദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِيهِ مُدَلِّسٌ عَنْعَنَهُ', null, 481, 482, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَتِ امْرَأَةٌ مَخْزُومِيَّةٌ تَسْتَعِيرُ الْمَتَاعَ وَتَجْحَدُهُ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ بِقَطْعِ يَدِهَا، وَقَصَّ نَحْوَ حَدِيثِ قُتَيْبَةَ عَنِ اللَّيْثِ عَنِ ابْنِ شِهَابٍ زَادَ: فَقَطَعَ النَّبِيُّ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ يَدَهَا. (د)
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً سَرَقَتْ، فَعَاذَتْ بِزَيْنَبَ بِنْتِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ. (د)', 'ജാബിർ(റ): ഒരു സ്ത്രീ മോഷ്ടിച്ചു. അങ്ങിനെ റസൂൽ(സ)യുടെ മകൾ സൈനബ(റ)യോട് അവൾ അഭയം ആവശ്യപ്പെട്ടു. (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 482, 482, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: أَنَّ قُرَيْشًا أَهَمَّهُمْ شَأْنُ الْمَرْأَةِ الَّتِي سَرَقَتْ فِي عَهْدِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ الْفَتْحِ، فَقَالُوا: مَنْ يُكَلِّمُ فِيهَا رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ؟ فَقَالُوا: وَمَنْ يَجْتَرِئُ عَلَيْهِ إِلَّا أُسَامَةُ بْنُ زَيْدٍ حِبُّ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ. فَأُتِيَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَكَلَّمَهُ فِيهَا أُسَامَةُ بْنُ زَيْدٍ، فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَتَشْفَعُ فِي حَدٍّ مِنْ حُدُودِ اللَّهِ". فَقَالَ [لَهُ] أُسَامَةُ: اسْتَغْفِرْ لِي يَا رَسُولَ اللَّهِ. فَلَمَّا كَانَ الْعَشِيُّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَاخْتَطَبَ، فَأَثْنَى عَلَى اللَّهِ [تعالى] بِمَا هُوَ أَهْلُهُ ثُمَّ قَالَ: "أَمَّا بَعْدُ، فَإِنَّمَا أَهْلَكَ الَّذِينَ مِنْ قَبْلِكُمْ: أَنَّهُمْ كَانُوا إِذَا سَرَقَ فِيهِمُ الشَّرِيفُ تَرَكُوهُ، وَإِذَا سَرَقَ فِيهِمُ الضَّعِيفُ أَقَامُوا عَلَيْهِ الْحَدَّ، وَإِنِّي وَالَّذِي نَفْسِي بِيَدِهِ لَوْ أَنَّ فَاطِمَةَ بِنْتَ مُحَمَّدٍ سَرَقَتْ لَقَطَعْتُ يَدَهَا". ثُمَّ أَمَرَ بِتِلْكَ الْمَرْأَةِ الَّتِي سَرَقَتْ فَقُطِعَتْ يَدُهَا، قَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: فَحَسُنَتْ تَوْبَتُهَا بَعْدُ، وَتَزَوَّجَتْ، وَكَانَتْ تَأْتِينِي بَعْدَ ذَلِكَ فَأَرْفَعُ حَاجَتَهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ. (م)', 'നബി(സ)യുടെ ഭാര്യയായ ആഇശ(റ): നബി(സ)യുടെ കാലത്ത് മക്കാഫത്ഹ് യുദ്ധത്തിൽ കളവ് നടത്തിയ ഒരു സ്ത്രീയുടെ കാര്യം ഖുറൈശികൾക്ക് വലിയ പ്രശ്നമായി. ഇതു സംബന്ധമായി റസൂൽ(സ) യോട് ആര് സംസാരിക്കുമെന്നവർ ചോദിച്ചപ്പോൾ അവരിൽ ചിലർ പറഞ്ഞു: റസൂൽ(സ)യുടെ പ്രിയങ്കരനായ ഉസാമതുബ്നു സൈദ് അല്ലാതെ ആരാണതിന് ധൈര്യപ്പെടുക? അവളെ റസൂൽ(സ)യുടെ അടുക്കൽ കൊണ്ടുവന്നു. അവളുടെ പ്രശ്നത്തിൽ റസൂൽ(സ)യോട് ഉസാമതുബ്നു സൈദ്(റ) സംസാരിച്ചു. അപ്പോൾ നബി(സ)യുടെ മുഖം വിവർണ്ണമായി. നബി(സ) ചോദിച്ചു: "നീ അല്ലാഹുവിന്റെ ഹദ്ദുകളിൽ ഒരു ഹദ്ദ് നീക്കിക്കളയാൻ ശിപാർശ തേടുകയാണോ?" ഉസാമ(റ) പറഞ്ഞു: എനിക്ക് വേണ്ടി അങ്ങ് മാപ്പപേക്ഷിക്കണം. അങ്ങിനെ രാത്രിയായപ്പോൾ നബി(സ) പ്രസംഗിക്കാൻ എഴുന്നേറ്റുനിന്നു. അല്ലാഹുവിനെ സ്തുതിച്ചതിന് ശേഷം പറഞ്ഞു: "പ്രാരംഭമുറകൾക്ക് ശേഷം, നിങ്ങളുടെ മുൻഗാമികൾ നശിക്കാൻ കാരണമായത് അവരിലെ ഉന്നതൻ മോഷ്ടിച്ചാൽ അവനെ വെറുതെവിടുകയും അവരിലെ ബലഹീനൻ മോഷ്ടിച്ചാൽ അവന്റെ മേൽ ഹദ്ദ് നടപ്പാക്കുകയും ചെയ്തതായിരുന്നു. എന്നാൽ, അല്ലാഹുവാണ് സത്യം, മുഹമ്മദിന്റെ മകൾ ഫാത്വിമ തന്നെയാണ് കട്ടതെങ്കിലും നിശ്ചയം ഞാനവളുടെ കൈ മുറിക്കും." ശേഷം പ്രസ്തുത സ്ത്രീയുടെ കൈ മുറിക്കാൻ നിർദേശിക്കുകയും മുറിക്കുകയും ചെയ്തു. ആഇശ(റ) പറഞ്ഞു: പിന്നീടവൾ നന്നാവുകയും വിവാഹിതയാവുകയും ചെയ്തു. പിന്നീടവൾ എന്റടുത്തു വരാറുണ്ടായിരുന്നു. ഞാനവളുടെ ആവശ്യം റസൂൽ(സ)യോട് പറയും. (മു)', 'عَائِشَةَ', 'നബി(സ)യുടെ ഭാര്യയായ ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], 'تعالى', null, 482, 483, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَا يَقْبَلُ اللَّهُ مِنْ مُشْرِكٍ - أَشْرَكَ بَعْدَ مَا أَسْلَمَ - عَمَلًا حَتَّى يُفَارِقَ الْمُشْرِكِينَ إِلَى الْمُسْلِمِينَ". (ن,جه)', 'മുആവിയതുബ്നു ഹൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്ലിമായതിന് ശേഷം മുശ്രികായവനിൽനിന്ന് ഒരു പ്രവർത്തനവും അല്ലാഹു സ്വീകരിക്കുകയില്ല, മുശ്രിക്കുകളെ പിരിഞ്ഞ് മുസ്ലിംകളിലേക്ക് മടങ്ങുന്നത് വരെ." (ന,ജ)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 483, 483, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ: أَنَّ عُثْمَانَ بْنَ عَفَّانَ - رَضِيَ اللهُ عَنْهُ - أَشْرَفَ عَلَيْهِمْ، فَسَمِعَهُمْ وَهُمْ يَذْكُرُونَ الْقَتْلَ، فَقَالَ: إِنَّهُمْ لَيَتَوَاعَدُونِي بِالْقَتْلِ؟ فَلِمَ يَقْتُلُونِي؟ وَقَدْ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلَّا فِي إِحْدَى ثَلَاثٍ: رَجُلٌ زَنَى وَهُوَ مُحْصَنٌ فَرُجِمَ، أَوْ رَجُلٌ قَتَلَ نَفْسًا بِغَيْرِ نَفْسٍ، أَوْ رَجُلٌ ارْتَدَّ بَعْدَ إِسْلَامِهِ". فَوَاللَّهِ، مَا زَنَيْتُ فِي جَاهِلِيَّةٍ وَلَا فِي إِسْلَامٍ، وَلَا قَتَلْتُ نَفْسًا مُسْلِمَةً، وَلَا ارْتَدَدْتُ مُنْذُ أَسْلَمْتُ. (د,ت,ن,جه)', 'അബൂഉമാമതുബ്നു സഹ്ലുബ്നു ഹുനൈഫ്(റ): ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ) ജനങ്ങളിലേക്ക് എത്തിനോക്കി. അപ്പോൾ (ഉസ്മാൻ(റ)നെ) വധിക്കുന്ന വിഷയത്തെക്കുറിച്ച് ജനങ്ങൾ പറയുന്നത് അദ്ദേഹം കേട്ടു. അദ്ദേഹം പറഞ്ഞു: എന്നെ വധിക്കാനവർ വട്ടം കൂട്ടുകയാണ്. എന്തിനാണവർ എന്നെ വധിക്കുന്നത്? നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "മൂന്ന് കാര്യങ്ങളിലല്ലാതെ ഒരു മുസ്ലിമിന്റെ രക്തം അനുവദനീയമാവുകയില്ല: വിവാഹിതനായവൻ വ്യഭിചരിച്ചാൽ അവനെ എറിഞ്ഞുകൊല്ലണം. അകാരണമായി ഒരാൾ മുസ്ലിമിനെ വധിച്ചാൽ, മുസ്ലിമായതിനുശേഷം വീണ്ടും മതത്തെ ത്യജിച്ചാൽ (ഈ അവസരങ്ങളിലും കൊല്ലപ്പെടണം)." എന്നാൽ അല്ലാഹു തന്നെ സത്യം, ഇസ്ലാമിനുമുമ്പും ഇസ്ലാമായതിനുശേഷവും ഞാൻ വ്യഭിചരിച്ചിട്ടില്ല. ഒരു മുസ്ലിമിനെ ഞാൻ വധിച്ചിട്ടില്ല. മുസ്ലിമായതു മുതൽ മതം ഉപേക്ഷിച്ചിട്ടില്ല. (ദ,തു,ന,ജ)', 'أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ', 'അബൂഉമാമതുബ്നു സഹ്ലുബ്നു ഹുനൈഫ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 483, 483, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ - يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ - إِلَّا أَحَدُ ثَلَاثَةِ نَفَرٍ: النَّفْسُ بِالنَّفْسِ، وَالثَّيِّبُ الزَّانِي، وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ". (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും ഞാൻ അല്ലാഹുവിന്റെ ദൂതനാണെന്നും സാക്ഷ്യം വഹിക്കുന്ന മുസ്ലിമിന്റെ രകതം ഒരാൾക്കും അനുവദനീയമാവുകയില്ല, മൂന്ന് വ്യക്തികളെയല്ലാതെ: ഒരു ശരീരത്തിന് (വധിച്ചതിന്) പകരമായി മറ്റൊരു ശരീരത്തെ, വ്യഭിചരിയായ വിവാഹിതനെ, കൂട്ടത്തിൽ നിന്ന് വേറിട്ട് മതം നിരസിച്ചവനെ." (മു,ബു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['മു','ബു','ദ','തു','ന','ജ']::text[], null, null, 484, 484, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ عَطِيَّةَ الْقُرَظِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: عُرِضْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَوْمَ قُرَيْظَةَ: فَكَانَ مَنْ أَنْبَتَ قُتِلَ، وَمَنْ لَمْ يُنْبِتْ خُلِّيَ سَبِيلُهُ. فَكُنْتُ فِيمَنْ لَمْ يُنْبِتْ، فَخُلِّيَ سَبِيلِي. وفي رواية: فَهَا أَنَا ذَا بَيْنَ أَظْهُرِكُمْ. (د,ت,ن,جه)', 'അതിയ്യതുൽ ഖുറളി: ഖുറൈള യുദ്ധദിനത്തിൽ നബി(സ)യുടെ മുമ്പിൽ ഞങ്ങളെ ഹാജരാക്കി. അവിടുന്ന് പ്രായപൂർത്തിയായവരെ വധിച്ചു കളയുകയും പ്രായപൂർത്തിയാവാത്തവരെ വെറുതെ വിടുകയും ചെയ്തു. ഞാൻ പ്രായപൂർത്തിയാവാത്തവരിൽ പെട്ടവനായിരുന്നു. അങ്ങനെ എന്നെ വെറുതെ വിട്ടു. ഒരു റിപ്പോർട്ടിൽ: ഇതാ ഇന്ന് ഞാൻ നിങ്ങളുടെ ഇടയിൽ ഉണ്ട്. (ദ,തു,ന,ജ)', 'عَطِيَّةَ الْقُرَظِيِّ', 'അതിയ്യതുൽ ഖുറളി', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 484, 484, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=74), 1, 'وَفِي رِوَايَةٍ: فَهَا أَنَا ذَا بَيْنَ أَظْهُرِكُمْ. (د,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: عُرِضْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَوْمَ أُحُدٍ - وَأَنَا ابْنُ أَرْبَعَ عَشْرَةَ سَنَةً - فَلَمْ يُجِزْنِي، وَعُرِضْتُ عَلَيْهِ يَوْمَ الْخَنْدَقِ - وَأَنَا ابْنُ خَمْسَ عَشْرَةَ سَنَةً - فَأَجَازَنِي. (ق,جه)', 'ഇബ്നുഉമർ(റ): ഉഹ്ദദ് യുദ്ധദിവസം നബി(സ)യുടെ മുന്നിൽ എന്നെ കാണിക്കപ്പെട്ടു - അന്ന് ഞാൻ പതിനാലു വയസ്സുകാരനാണ് - അപ്പോൾ യുദ്ധത്തിൽ പങ്കെടുക്കാൻ എനിക്ക് സമ്മതം തന്നില്ല. ഖൻദഖ് യുദ്ധദിവസം നബി(സ)യുടെ മുന്നിൽ എന്നെ കാണിക്കപ്പെട്ടു. എന്ന് എനിക്ക് പതിനഞ്ച് വയസ്സായിരുന്നു. അപ്പോൾ നബി(സ) എനിക്ക് സമ്മതം തന്നു. (ബു,മു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 484, 484, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ : أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ: عَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ، وَعَنِ الصَّبِيِّ حَتَّى يَشِبَّ، وَعَنِ الْمَعْتُوهِ حَتَّى يَعْقِلَ". حَسَنٌ (د,ت)', 'അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് ആളുകളിൽനിന്നു പേന ഉയർത്തപ്പെട്ടിരിക്കുന്നു (അവർക്ക് ശിക്ഷയില്ല) ഉറങ്ങുന്നവൻ അവൻ ഉണരുന്നതുവരെ, കുട്ടി പ്രായപൂർത്തിയാവുന്നതുവരെ, ഭ്രാന്തന് ബുദ്ധിവരുന്നതുവരെ." ഹദീസ് ഹസനാണ്. (ദ,തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 484, 484, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ)പറഞ്ഞു: "ഒരു മുസ്ലിമായ മനുഷ്യന്റെ രഹസ്യം മറച്ചുവെച്ചാൽ അവന്റെ രഹസ്യം ഭൗതിലോകത്തും പരലോകത്തും അല്ലാഹു മറച്ചുവെക്കും." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 484, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "ادْفَعُوا الْحُدُودَ مَا وَجَدْتُمْ لَهُ مَدْفَعًا". [ز: في إسناده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് എടുത്തുകളയാൻ സാധിക്കാവുന്ന എല്ലാ ഹദ്ദുകളും നിങ്ങൾ ഉപേക്ഷിക്കുക." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 485, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ سَتَرَ عَوْرَةَ أَخِيهِ الْمُسْلِمِ سَتَرَ اللَّهُ عَوْرَتَهُ يَوْمَ الْقِيَامَةِ، وَمَنْ كَشَفَ عَوْرَةَ أَخِيهِ الْمُسْلِمِ كَشَفَ اللَّهُ عَوْرَتَهُ حَتَّى يَفْضَحَهُ بِهَا فِي بَيْتِهِ". [ز: فِي إِسْنَادِهِ رَاوٍ ضَعَّفَهُ بَعْضُهُمْ وَوَثَّقَهُ آخَرُونَ] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ മുസ്ലിമായ സഹോദരന്റെ നാണം മറച്ചുവെച്ചാൽ അവന്റെ നാണവും അന്ത്യനാളിൽ അല്ലാഹു മറച്ചുവെക്കും. ഒരാൾ തന്റെ മുസ്ലിമായ സഹോദന്റെ നാണം വെളിപ്പെടുത്തിയാൽ അല്ലാഹു അവന്റെ നാണവും വെളിപ്പെടുത്തുകയും അക്കാരണമായി അവന്റെ വീട്ടിൽ പോലും അവനെ അപമാനിതനാക്കുകയും ചെയ്യും." ഇതിന്റെ പരമ്പരയിൽ ചിലർ ബലഹീനനാണെന്ന് വിശേഷിപപ്പിച്ച ഒരാളുണ്ട്. എന്നാൽ, മറ്റു ചിലർ അദ്ദേഹത്തെ വിശ്വസ്തൻ എന്നും വിശേഷിപ്പിച്ചിട്ടുണ്ട്. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ رَاوٍ ضَعَّفَهُ بَعْضُهُمْ وَوَثَّقَهُ آخَرُونَ', null, 485, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "ادْرَءُوا الْحُدُودَ عَنِ الْمُسْلِمِينَ مَا اسْتَطَعْتُمْ، فَإِنْ كَانَ لَهُ مَخْرَجٌ فَخَلُّوا سَبِيلَهُ، فَإِنَّ الْإِمَامَ أَنْ يُخْطِئَ فِي الْعَفْوِ خَيْرٌ مِنْ أَنْ يُخْطِئَ فِي الْعُقُوبَةِ". (ت)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "കഴിയുന്നത്ര ഹദ്ദുകൾ മുസ്ലിംകളിൽനിന്ന് ഒഴിവാക്കുക. വല്ല പഴുതുമുണ്ടെങ്കിൽ അവനെ വെറുതെ വിടുക. കാരണം മാപ്പു ചെയ്യുന്നതിൽ ഇമാമിനു പിഴക്കുന്നതു ശിക്ഷനൽകുന്നതിൽ പിഴവ് സംഭവിക്കുന്നതിനേക്കാൾ നല്ലതാണ്." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 485, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ الْآخِرَةِ، وَمَنْ سَتَرَ عَلَى مُسْلِمٍ سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ، وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ". (م,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുഅ്മിനിന്റെ ദുൻയാവിലെ ഒരു ബുദ്ധിമുട്ട് ആരെങ്കിലും അകറ്റിക്കൊടുത്താൽ പരലോകത്ത് അവന്റെ ഒരു ബുദ്ധിമുട്ട് അല്ലാഹു അകറ്റിക്കൊടുക്കും. മുസ്ലിമിന്റെ കുറവ് ആരെങ്കിലും മറച്ചുവെച്ചാൽ ഇഹത്തിലും പരത്തിലും അവന്റെ കുറവ് അല്ലാഹു മറച്ചുവെക്കും. തന്റെ ദാസൻ അവന്റെ സഹോദരനെ സഹായിക്കുന്ന കാലമത്രയും അല്ലാഹു അവനെയും സഹായിക്കും." (മു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 485, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "الْمُسْلِمُ أَخُو الْمُسْلِمِ، لَا يَظْلِمُهُ وَلَا يُسْلِمُهُ، وَمَنْ كَانَ فِي حَاجَةِ أَخِيهِ كَانَ اللَّهُ فِي حَاجَتِهِ، وَمَنْ فَرَّجَ عَنْ مُسْلِمٍ كُرْبَةً فَرَّجَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ". (ق,د,ت,ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു മുസ്ലിം മറ്റൊരു മുസ്ലിമിന്റെ സഹോദരനാണ്. അതുകൊണ്ട് ഇവൻ ദ്രോഹിക്കുകയോ, ഒരു അക്രമിക്ക് ദ്രോഹിക്കാൻ വിട്ടുകൊടുക്കുകയോ ചെയ്യരുത്. വല്ലവനും തന്റെ സഹോദരന്റെ ഒരാവശ്യം സാധിച്ചുകൊടുക്കുവാനുള്ള പരിശ്രമത്തിൽ പ്രവേശിച്ചാൽ അവന്റെ ആവശ്യം നിറവേറ്റിക്കൊടുക്കാനുള്ള ശ്രമത്തിൽ അല്ലാഹുവും പ്രവേശിക്കും. വല്ലവനും ഒരു മുസ്ലിമിന്റെ പ്രയാസത്തിൽ നിന്ന് അവനെ മോചിപ്പിച്ചാൽ അന്ത്യനാളിലെ അവന്റെ പ്രയാസങ്ങളിലൊന്നിൽ നിന്ന് അവനെയും അല്ലാഹു മോചിപ്പിക്കും. ഒരു മുസ്ലിമിന്റെ പോരായ്മകൾ വല്ലവനും മറച്ചുവെക്കുന്ന പക്ഷം പുനരുത്ഥാന ദിവസം അവന്റെ പോരായ്മകൾ അല്ലാഹുവും മറച്ചുവെക്കും. (ബു,മു,ദ,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 485, 486, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "إِقَامَةُ حَدٍّ مِنْ حُدُودِ اللَّهِ خَيْرٌ مِنْ مَطَرِ أَرْبَعِينَ لَيْلَةً فِي بِلَادِ اللَّهِ عَزَّ وَجَلَّ". [ز: فِي إِسْنَادِهِ ضَعِيفٌ] (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ ഹദ്ദുകളിൽനിന്ന് വല്ല ഹദ്ദും നടപ്പാക്കൽ അല്ലാഹുവിന്റെ നാടുകളിൽ വർഷിക്കുന്ന നാൽപത് രാവുകളിലെ മഴയെക്കാളും അത്യുത്തമമാണ്." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ ضَعِيفٌ', null, 486, 486, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "حَدٌّ يُعْمَلُ بِهِ فِي الْأَرْضِ خَيْرٌ لِأَهْلِ الْأَرْضِ مِنْ أَنْ يُمْطَرُوا أَرْبَعِينَ صَبَاحًا". (ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഭൂമിയിൽ നടപ്പാക്കപ്പെടുന്ന ഹദ്ദ് (ശിക്ഷാനടപടി) നാൽപത് പ്രഭാതങ്ങളിൽ മഴ വർഷിക്കുന്നതിനേക്കാൾ ഉത്തമമാണ്." (ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 486, 486, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ جَحَدَ آيَةً مِنَ الْقُرْآنِ فَقَدْ حَلَّ ضَرْبُ عُنُقِهِ. وَمَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، فَلَا سَبِيلَ لِأَحَدٍ عَلَيْهِ، إِلَّا أَنْ يُصِيبَ حَدًّا فَيُقَامَ عَلَيْهِ". [ز: ضَعِيفٌ] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) അരുളി: "ഖുർആനിൽ നിന്ന് വല്ല സൂക്തവും ഒരാൾ നിഷേധിച്ചാൽ അവന്റെ കഴുത്ത് അറുക്കൽ അനുവദനീയമായി. വല്ലവനും ലാഇലാഹ ഇല്ലല്ലാഹു വഹ്ദഹു ലാ ശരീക ലഹു വഅന്ന മുഹമ്മദൻ അബ്ദഹു വറസൂലഹു (ആരാധനക്കർഹനായി അല്ലാഹു അല്ലാതെ മറ്റാരുമില്ലെന്നും, അവൻ ഏകനും പങ്കാളിയില്ലാത്തവനാണന്നും, മുഹമ്മദ്(സ) അവന്റെ ദാസനും ദൂതനുമാണ്) എന്ന് പറഞ്ഞാൽ അവനെ വധിച്ചുകളയാൻ ഒരു മാർഗ്ഗവുമില്ല, അവൻ വല്ല ശിക്ഷാനടപടിക്കും വിധേയനായാൽ അത് നടപ്പാക്കപ്പെടും എന്നതൊഴിച്ചാൽ." പരമ്പര ബലഹീനം (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: ضَعِيفٌ', null, 486, 486, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "أَقِيمُوا حُدُودَ اللَّهِ فِي الْقَرِيبِ وَالْبَعِيدِ، وَلَا تَأْخُذْكُمْ فِي اللَّهِ لَوْمَةُ لَائِمٍ". (جه)', 'ഉബാദത്തുബ്നു സ്വാമിത്: റസൂൽ(സ) പറഞ്ഞു: "അടുത്തവരിലും അകന്നവരിലും അല്ലാഹുവിന്റെ ഹദ്ദ് (ശിക്ഷ) നടപ്പാക്കുക. അല്ലാഹുവിന്റെ കാര്യത്തിൽ ഒരാളുടെ ആക്ഷേപവും നിങ്ങളെ പിടികൂടാതിരിക്കട്ടെ." (ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദത്തുബ്നു സ്വാമിത്', null, null, array['جه']::text[], array['ജ']::text[], null, null, 486, 486, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ: أَنَّهُ أَخْبَرَهُ بَعْضُ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ مِنَ الْأَنْصَارِ أَنَّهُ اشْتَكَى رَجُلٌ مِنْهُمْ حَتَّى أُضْنِيَ، فَعَادَ جِلْدَةً عَلَى عَظْمٍ، فَدَخَلَتْ عَلَيْهِ جَارِيَةٌ لِبَعْضِهِمْ، فَهَشَّ لَهَا فَوَقَعَ عَلَيْهَا، فَلَمَّا دَخَلَ عَلَيْهِ رِجَالُ قَوْمِهِ يَعُودُونَهُ أَخْبَرَهُمْ بِذَلِكَ، وَقَالَ اسْتَفْتُوا لِي رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَإِنِّي قَدْ وَقَعْتُ عَلَى جَارِيَةٍ دَخَلَتْ عَلَيَّ، فَذَكَرُوا ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، وَقَالُوا: مَا رَأَيْنَا بِأَحَدٍ مِنَ النَّاسِ مِنَ الضُّرِّ مِثْلَ الَّذِي هُوَ بِهِ، لَوْ حَمَلْنَاهُ إِلَيْكَ لَتَفَسَّخَتْ عِظَامُهُ، مَا هُوَ إِلَّا جِلْدٌ عَلَى عَظْمٍ. فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَنْ يَأْخُذُوا لَهُ مِائَةَ شِمْرَاخٍ، فَيَضْرِبُوهُ بِهَا ضَرْبَةً وَاحِدَةً. (د)', 'അബൂഉമാമതുബ്നു സഹ്ലുബ്നു ഹുനൈഫ്(റ): അൻസാറുകളായ ചില സ്വഹാബികൾ അദ്ദേഹത്തോടു പറഞ്ഞു: അവരിൽ നിന്നൊരാൾക്ക് ശക്തിയായ രോഗം പിടിപ്പെട്ടു. അദ്ദേഹത്തിന്റെ തൊലി എല്ലിനോട് ഒട്ടിച്ചേർന്നു. അവരിൽ ചിലരുടെ ഒരടിമസ്ത്രീ അദ്ദേഹത്തിന്റെ അടുത്ത് ചെന്നു. അപ്പോൾ അദ്ദേഹമവളോട് പുഞ്ചിരിക്കുകയും അവളുമായി അവിഹിതവേഴ്ചയിലേർപ്പെടുകയും ചെയ്തു. തന്റെ ജനങ്ങൾ വന്നപ്പോൾ അദ്ദേഹം ഈ സംഭവമെല്ലാം അവർക്ക് പറഞ്ഞുകൊടുത്തു. അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾ എനിക്ക് വേണ്ടി (ഇതിനെ സംബന്ധിച്ച്) റസൂൽ(സ)യോട് മതവിധിതേടുക. എന്റെ അടുത്തുവന്ന ഒരു സ്ത്രീയുമായി ഞാൻ അവിഹിത ബന്ധത്തിലേർപ്പെട്ടിരിക്കുന്നു. അങ്ങനെ അവർ റസൂൽ(സ)യോട് ഈ വിവരം പറഞ്ഞു. അവർ പറഞ്ഞു: അദ്ദേഹത്തേക്കാൾ വലിയ ബുദ്ധിമുട്ടുള്ള ഒരു രോഗിയുമില്ല, ഞങ്ങൾ അദ്ദേഹത്തെ തിരുസന്നിധിയിൽ കൊണ്ടുവരികയാണെങ്കിൽ അദ്ദേഹത്തിന്റെ അസ്ഥികൾ ചിന്നഭിന്നമായിപ്പോകും. അദ്ദേഹം അസ്ഥിയും തോലും മാത്രമാണ്. അപ്പോൾ നബി(സ) നൂറ് (ഇതളുകളുള്ള) ഈത്തപ്പനക്കുല കൊണ്ടുവരാനും അതുപയോഗിച്ച് അവരോട് അദ്ദേഹത്തെ ഒരടി അടിക്കാനും കൽപിച്ചു. (ദ)', 'أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ', 'അബൂഉമാമതുബ്നു സഹ്ലുബ്നു ഹുനൈഫ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 486, 487, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: فَجَرَتْ جَارِيَةٌ لِآلِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَقَالَ: "يَا عَلِيُّ، انْطَلِقْ فَأَقِمْ عَلَيْهَا الْحَدَّ". فَانْطَلَقْتُ فَإِذَا بِهَا دَمٌ يَسِيلُ لَمْ يَنْقَطِعْ، فَأَتَيْتُهُ، فَقَالَ: "يَا عَلِيُّ أَفَرَغْتَ". قُلْتُ: أَتَيْتُهَا وَدَمُهَا يَسِيلُ، فَقَالَ: "دَعْهَا حَتَّى يَنْقَطِعَ دَمُهَا، ثُمَّ أَقِمْ عَلَيْهَا الْحَدَّ، وَأَقِيمُوا الْحُدُودَ عَلَى مَا مَلَكَتْ أَيْمَانُكُمْ". وَفِي رِوَايَةٍ: قَالَ: "لَا تَضْرِبْهَا حَتَّى تَضَعَ". (م,ت,د)', 'അലി(റ): നബി(സ)യുടെ ബന്ധുവിന്റെ ഒരടിമസ്ത്രീ അവിഹിത വേഴ്ചയിലേർപ്പെട്ടു. അപ്പോൾ നബി(സ) അലി(റ)വിനോട് പറഞ്ഞു: "നീ പോയി അവൾക്ക് ശിക്ഷ നൽകുക." അങ്ങനെ ഞാൻ പോയപ്പോൾ അവളിൽനിന്ന് രക്തം ഒലിക്കുന്ന സമയമായിരുന്നു. താമസിയാതെ ഞൻ നബി(സ)യുടെ അടുത്ത് ചെന്നപ്പോൾ നബി(സ) എന്നോടു ചോദിച്ചു: "നീ ശിക്ഷ നടപ്പാക്കിയോ?" ഞാൻ പറഞ്ഞു: ഞാൻ ചെന്നപ്പോൾ അവളുടെ (പ്രസവ) രക്തം ഒലിച്ചുകൊണ്ടിരിക്കുന്ന അവസരമാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവളുടെ രക്തം മുറിയുന്നതുവരെ അവളെ ഉപേക്ഷിക്കുക, ശേഷം ശിക്ഷ നടപ്പാക്കുക. നിങ്ങളുടെ അടിമകളിലും നിങ്ങൾ ശിക്ഷ നടപ്പാക്കുക." മറ്റൊരു റിപ്പോർട്ടിൽ, "അവൾ പ്രസവിക്കുന്നത് വരെ അടിക്കരുത്" എന്നുണ്ട്. (മു,ദ,തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['م','ت','د']::text[], array['മു','ദ','തു']::text[], null, null, 487, 487, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=88), 1, 'وَفِي رِوَايَةٍ: قَالَ: "لَا تَضْرِبْهَا حَتَّى تَضَعَ". (م,ت,د)', 'മറ്റൊരു നിവേദനിൽ, "അവൾ പ്രസവിക്കുന്നത് വരെ അടിക്കരുത്" എന്നുണ്ട്. (മു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ مَاعِزٌ الْأَسْلَمِيُّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّهُ قَدْ زَنَى. فَأَعْرَضَ عَنْهُ، ثُمَّ جَاءَ مِنْ شِقِّهِ الْآخَرِ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّهُ قَدْ زَنَى. فَأَعْرَضَ عَنْهُ، ثُمَّ جَاءَ مِنْ شِقِّهِ الْآخَرِ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّهُ قَدْ زَنَى. فَأَمَرَ بِهِ فِي الرَّابِعَةِ فَأُخْرِجَ إِلَى الْحَرَّةِ، فَرُجِمَ بِالْحِجَارَةِ، فَلَمَّا وَجَدَ مَسَّ الْحِجَارَةِ فَرَّ يَشْتَدُّ، حَتَّى مَرَّ بِرَجُلٍ مَعَهُ لَحْيُ جَمَلٍ فَضَرَبَهُ بِهِ وَضَرَبَهُ النَّاسُ حَتَّى مَاتَ، فَذَكَرُوا ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: أَنَّهُ فَرَّ حِينَ وَجَدَ مَسَّ الْحِجَارَةِ وَمَسَّ الْمَوْتِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "هَلَّا تَرَكْتُمُوهُ". حَسَنٌ . (ت,جه)', 'അബൂഹുറൈറ(റ): മാഇസ്(റ) റസൂൽ(സ)യെ സമീപിച്ചു പറഞ്ഞു: ഞാൻ വ്യഭിചരിച്ചിരിക്കുന്നു. നബി(സ) തിരിഞ്ഞുകളഞ്ഞു. അപ്പോൾ മറുഭാഗത്ത് നബി(സ)യെ സമീപിച്ച് പറഞ്ഞു: റസൂലേ ഞാൻ വ്യഭിചരിച്ചിരിക്കുന്നു. നബി(സ) അപ്പോഴും തിരിഞ്ഞുകളഞ്ഞു. മറുഭാഗത്തുകൂടെ വന്നുകൊണ്ട് മാഇസ്(റ) പറഞ്ഞു: റസൂലേ, ഞാൻ വ്യഭിചരിച്ചിരിക്കുന്നു. നാലാമത്തെ പ്രാവശ്യം റസൂൽ(സ) മാഇസ്(റ)വിനെ എറഞ്ഞുകൊല്ലാൻ ഉത്തരവിട്ടു. ഹർറ എന്ന സ്ഥലത്തേക്ക് മാഇസ്(റ)വിനെ കൊണ്ടുപോയി. അദ്ദേഹത്തെ കല്ലുകൊണ്ട് എറിഞ്ഞു. കല്ലുകൾ ശരീരത്തിൽ കൊണ്ടപ്പോൾ മാഇസ്(റ) വേദനകൊണ്ട് ഓടി. ഒട്ടകത്തിന്റെ താടിയെല്ല് പിടിച്ചുനിൽക്കുന്ന ഒരാളുടെ അടുത്തുകൂടെ മാഇസ്(റ) ഓടി. അപ്പോൾ അയാൾ അതുകൊണ്ട് മാഇസ്(റ)വിനെ അടിച്ചു. ജനങ്ങളും അടിച്ചു. അങ്ങനെ അദ്ദേഹം മരിച്ചു. കല്ലിന്റെയും മരണത്തിന്റെയും വേദന കാരണം മാഇസ്(റ) ഓടി എന്ന് അവർ റസൂൽ(സ)യെ അറിയിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് അദ്ദേഹത്തെ വെറുതെവിടാമായിരുന്നില്ലേ." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 487, 488, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أَبِي بُرْدَةَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ : أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يُجْلَدُ أَحَدٌ فَوْقَ عَشَرَةِ أَسْوَاطٍ، إِلَّا فِي حَدٍّ مِنْ حُدُودِ اللَّهِ". (م,د)', 'അബൂബുർദതുൽ അൻസാരി(റ): റസൂൽ(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "അല്ലാഹുവിന്റെ ശിക്ഷാനടപടികളിലല്ലാതെ ആരെയും ചാട്ടകൊണ്ട് പത്ത് അടിയിലധികം അടിക്കരുത്." (മു,ദ)', 'أَبِي بُرْدَةَ الْأَنْصَارِيِّ', 'അബൂബുർദതുൽ അൻസാരി(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 488, 488, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ حُضَيْنِ بْنِ الْمُنْذِرِ أَبِي سَاسَانَ قَالَ: شَهِدْتُ عُثْمَانَ [بْنَ عَفَّانَ] رَضِيَ اللهُ عَنْهُ وَأُتِيَ بِالْوَلِيدِ قَدْ صَلَّى الصُّبْحَ رَكْعَتَيْنِ، ثُمَّ قَالَ: أَزِيدُكُمْ؟ فَشَهِدَ عَلَيْهِ رَجُلَانِ - أَحَدُهُمَا عِمْرَانُ - أَنَّهُ شَرِبَ الْخَمْرَ، وَشَهِدَ آخَرُ أَنَّهُ رَآهُ يَتَقَيَّأُ، فَقَالَ عُثْمَانُ: إِنَّهُ لَمْ يَتَقَيَّأْ حَتَّى شَرِبَهَا، فَقَالَ: يَا عَلِيُّ قُمْ فَاجْلِدْهُ، فَقَالَ عَلِيٌّ: قُمْ يَا حَسَنُ فَاجْلِدْهُ، فَقَالَ الْحَسَنُ: وَلِّ حَارَّهَا مَنْ تَوَلَّى قَارَّهَا. فَكَأَنَّهُ وَجَدَ عَلَيْهِ، فَقَالَ: يَا عَبْدَ اللَّهِ بْنَ جَعْفَرٍ قُمْ فَاجْلِدْهُ، فَجَلَدَهُ، وَعَلِيٌّ رَضِيَ اللهُ عَنْهُ يَعُدُّ، حَتَّى بَلَغَ أَرْبَعِينَ، فَقَالَ: أَمْسِكْ، ثُمَّ قَالَ: جَلَدَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَرْبَعِينَ، وَجَلَدَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ أَرْبَعِينَ، وَعُمَرُ رَضِيَ اللهُ عَنْهُ ثَمَانِينَ، وَكُلٌّ سُنَّةٌ، وَهَذَا أَحَبُّ إِلَيَّ. (م,د)', 'ഹുളൈനുബ്നു മുൻദിർ(റ): വലീദിനെ കൊണ്ടുവന്നപ്പോൾ ഞാൻ ഉസ്മാൻ(റ)വിന്റെ സമീപത്തുണ്ടായിരുന്നു. അദ്ദേഹം രണ്ട് റക്അത്ത് സുബ്ഹി നമസ്കരിച്ചു. പിന്നെ ചോദിച്ചു: ഞാൻ കുറ്റസമ്മതം നടത്തണോ? അപ്പോൾ രണ്ടുപേർ അദ്ദേഹത്തിനെതിരെ സാക്ഷിനിന്നു. ഒന്ന് ഇംറാനായിരുന്നു. കള്ളുകുടിച്ചിട്ടുണ്ട് എന്നതിന് ഇംറാൻ സാക്ഷിനിന്നു. ഛർദ്ദിക്കുന്നത് കണ്ടു എന്നതിന് മറ്റെയാളും സാക്ഷിനിന്നു. അപ്പോൾ ഉസ്മാൻ(റ) പറഞ്ഞു: മദ്യപിച്ചില്ലായിരുന്നെങ്കിൽ അവൻ ഛർദ്ദിക്കുമായിരുന്നില്ല. ഉസ്മാൻ(റ) പറഞ്ഞു: അലി, നിങ്ങളെഴുനേറ്റ് അവനെ അടിക്കൂ. അലി(റ) പറഞ്ഞു: ഹസൻ, നീ എഴുന്നേറ്റ് ശിക്ഷനടപ്പാക്കൂ. അപ്പോൾ ഹസൻ(റ) പറഞ്ഞു: (അധികാരത്തിന്റെ) തണുപ്പ് അനുഭവിക്കുന്നവരെത്തന്നെ (ശിക്ഷ നടപ്പാക്കുന്നതിന്റെ) ചൂടറിയുന്നതിനും ഉത്തരവാദപ്പെടുത്തുക. ഹസൻ(റ) ദേഷ്യം പിടിച്ചതുപോലെയുണ്ട്. അപ്പോൾ അലി(റ) പറഞ്ഞു: അബ്ദുല്ലാഹിബ്നു ജഅ്ഫറെ, നീ എഴുന്നേറ്റ് ശിക്ഷ നടപ്പാക്കൂ. അങ്ങനെ അദ്ദേഹം അടിച്ചു. അലി(റ) അടി എണ്ണിക്കൊണ്ടിരുന്നു. അങ്ങനെ നാൽപ്പത് എത്തിയപ്പോൾ അലി(റ) അടി നിർത്താനാവശ്യപ്പെട്ടു. എന്നിട്ട് പറഞ്ഞു: നബി(സ)യുടെയും അബൂബക്കർ(റ)വിന്റെയും അടി നാൽപ്പത് എണ്ണമാണ്, ഉമർ(റ)വിന്റേത് എൺപതും. എല്ലാം ചര്യ തന്നെയാണ്. ഞാൻ നാൽപതാണ് ഇഷ്ടപ്പെടുന്നത്. (മു,ദ)', 'حُضَيْنِ بْنِ الْمُنْذِرِ أَبِي سَاسَانَ قَالَ', 'ഹുളൈനുബ്നു മുൻദിർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], 'بْنَ عَفَّانَ', null, 488, 489, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ لَمْ يَقِتْ فِي الْخَمْرِ حَدًّا. وَقَالَ ابْنُ عَبَّاسٍ: شَرِبَ رَجُلٌ فَسَكِرَ فَلُقِيَ يَمِيلُ فِي الْفَجِّ، فَانْطُلِقَ بِهِ إِلَى النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَلَمَّا حَاذَى بِدَارِ الْعَبَّاسِ انْفَلَتَ فَدَخَلَ عَلَى الْعَبَّاسِ فَالْتَزَمَهُ، فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَضَحِكَ وَقَالَ: "أَفَعَلَهَا". وَلَمْ يَأْمُرْ فِيهِ بِشَيْءٍ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മദ്യപാനത്തിന് ശിക്ഷ നിർണ്ണയിച്ചിട്ടില്ല. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: ഒരാൾ മദ്യപിച്ച് ബോധം നഷ്ടപ്പെട്ട് ആടിക്കൊണ്ട് വഴിയിലൂടെ വന്നു. അദ്ദേഹത്തെ നബി(സ)യുടെ അടുത്ത് കൊണ്ടുപോയി. അബ്ബാസ്(റ)വിന്റെ വീടിനരികിലെത്തിയപ്പോൾ അയാൾ രക്ഷപ്പെടാൻ ശ്രമിക്കുകയും അബ്ബാസ്(റ)വിന്റെ വീട്ടിൽ കടന്ന് അവിടെ നിലയുറപ്പിക്കുകയും ചെയ്തു. ഈ വിഷയം നബി(സ)യെ അറിയിച്ചു. അപ്പോൾ നബി(സ) ചിരിച്ചു, എന്നിട്ട് പറഞ്ഞു: "അവൻ അങ്ങനെ ചെയ്തോ." അവന്റെ കാര്യത്തിൽ ഒന്നും കൽപിച്ചില്ല. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 489, 489, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أُتِيَ بِرَجُلٍ قَدْ شَرِبَ، فَقَالَ: "اضْرِبُوهُ". قَالَ أَبُو هُرَيْرَةَ: فَمِنَّا الضَّارِبُ بِيَدِهِ، وَالضَّارِبُ بِنَعْلِهِ، وَالضَّارِبُ بِثَوْبِهِ، فَلَمَّا انْصَرَفَ قَالَ بَعْضُ الْقَوْمِ: أَخْزَاكَ اللَّهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَا تَقُولُوا هَكَذَا، لَا تُعِينُوا عَلَيْهِ الشَّيْطَانَ". (خ,د)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=93), 1, 'وَفِي رِوَايَةٍ: قَالَ فِيهِ بَعْدَ الضَّرْبِ: ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ لِأَصْحَابِهِ: "بَكِّتُوهُ". فَأَقْبَلُوا عَلَيْهِ يَقُولُونَ: مَا اتَّقَيْتَ اللَّهَ، مَا خَشِيتَ اللَّهَ، وَمَا اسْتَحْيَيْتَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، ثُمَّ أَرْسَلُوهُ، وَقَالَ فِي آخِرِهِ: "وَلَكِنْ قُولُوا: اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ارْحَمْهُ، وَبَعْضُهُمْ يَزِيدُ الْكَلِمَةَ وَنَحْوَهَا. (د)', 'മറ്റൊരു നിവേദനം: ഈ ഹദീസിൽ അടിച്ചതിന് ശേഷം ഇപ്രകാരം പറഞ്ഞു: നബി(സ) തന്റെ അനുചരരോട് പറഞ്ഞു: "അവനെ ശാസിക്കൂ." അപ്പോൾ അവർ അയാളുടെ അടുത്തുചെന്ന് പറഞ്ഞു: നീ അല്ലാഹുവിനോട് ഭയഭക്തി കാണിക്കുന്നില്ല, അല്ലാഹുവിനെ ഭയപ്പെടുന്നില്ല, റസൂൽ(സ)യിൽ നിന്ന് നീ ലജ്ജ കാണിച്ചില്ല. ശേഷം അവർ അയാളെ വിട്ടയച്ചു. അവസാനം തിരുദൂതർ(സ) പറഞ്ഞു: "നിങ്ങൾ ഇങ്ങനെ പറയുക: അല്ലാഹുവേ അവന് പൊറുത്തുകൊടുക്കണേ, അല്ലാഹുവേ അവനോട് ദയ കാണിക്കണേ!" ചിലർ ഇത് പോലോത്തത് പറയുന്നുണ്ടായിരുന്നു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ جَلَدَ فِي الْخَمْرِ بِالْجَرِيدِ وَالنِّعَالِ، وَجَلَدَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ أَرْبَعِينَ، فَلَمَّا وَلِيَ عُمَرُ دَعَا النَّاسَ فَقَالَ لَهُمْ: إِنَّ النَّاسَ قَدْ دَنَوْا مِنَ الرِّيفِ، وَفِي رِوَايَةٍ: مِنَ الْقُرَى وَالرِّيفِ، فَمَا تَرَوْنَ فِي حَدِّ الْخَمْرِ؟ فَقَالَ لَهُ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ: نَرَى أَنْ تَجْعَلَهُ كَأَخَفِّ الْحُدُودِ، فَجَلَدَ فِيهِ ثَمَانِينَ. وَفِي رِوَايَةٍ: ضَرَبَ بِجَرِيدَتَيْنِ نَحْوَ الْأَرْبَعِينَ. (ق,ت,جه)', 'അനസുബ്നു മാലിക്(റ): മദ്യപിച്ചവനെ നബി(സ) ചെരിപ്പ് കൊണ്ടും ഈത്തപ്പനമടൽ കൊണ്ടും അടിച്ചു. അബൂബക്കർ(റ) നാൽപത് അടിയാണ് അടിച്ചത്. ഉമർ(റ) അധികാരം ഏറ്റെടുത്തപ്പോൾ ജനങ്ങളെ വിളിച്ച് ചോദിച്ചു: ജനങ്ങൾ ഉൾനാടുകളോട് അടുത്തിരിക്കുന്നു. മറ്റൊരു നിവേദനം: ഉൾനാടുകളോടും ഗ്രാമങ്ങളോടും അടുത്തിരിക്കുന്നു. അതുകൊണ്ട് മദ്യപാനത്തിനുള്ള ശിക്ഷയിൽ നിങ്ങൾ എന്താണ് അഭിപ്രായപ്പെടുന്നത്? അപ്പോൾ അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) പറഞ്ഞു: ഏറ്റവും ലഘുവായ ശിക്ഷ നിശ്ചയിക്കണമെന്ന് ഞങ്ങൾ അഭിപ്രായപ്പെടുന്നു. അങ്ങനെ ഉമർ(റ) മദ്യപിച്ചവനെ എൺപത് അടി അടിച്ചു. മറ്റൊരു നിവേദനം: രണ്ട് ഓലത്തണ്ട് കൊണ്ട് നാൽപത് അടി അടിച്ചു. (ബു,മു,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 489, 490, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=94), 1, 'وَفِي رِوَايَةٍ: مِنَ الْقُرَى وَالرِّيفِ، فَمَا تَرَوْنَ فِي حَدِّ الْخَمْرِ؟ فَقَالَ لَهُ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ: نَرَى أَنْ تَجْعَلَهُ كَأَخَفِّ الْحُدُودِ، فَجَلَدَ فِيهِ ثَمَانِينَ.', 'മറ്റൊരു നിവേദനം: ഉൾനാടുകളോടും ഗ്രാമങ്ങളോടും അടുത്തിരിക്കുന്നു. അതുകൊണ്ട് മദ്യപാനത്തിനുള്ള ശിക്ഷയിൽ നിങ്ങൾ എന്താണ് അഭിപ്രായപ്പെടുന്നത്? അപ്പോൾ അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) പറഞ്ഞു: ഏറ്റവും ലഘുവായ ശിക്ഷ നിശ്ചയിക്കണമെന്ന് ഞങ്ങൾ അഭിപ്രായപ്പെടുന്നു. അങ്ങനെ ഉമർ(റ) മദ്യപിച്ചവനെ എൺപത് അടി അടിച്ചു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=94), 2, 'وَفِي رِوَايَةٍ: ضَرَبَ بِجَرِيدَتَيْنِ نَحْوَ الْأَرْبَعِينَ. (ق,ت,جه)', 'മറ്റൊരു നിവേദനം: രണ്ട് ഓലത്തണ്ട് കൊണ്ട് നാൽപത് അടി അടിച്ചു. (ബു,മു,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَا كُنْتُ أَدِي مَنْ أَقَمْتُ عَلَيْهِ الْحَدَّ إِلَّا شَارِبَ الْخَمْرِ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ لَمْ يَسُنَّ فِيهِ شَيْئًا، إِنَّمَا هُوَ شَيْءٌ جَعَلْنَاهُ نَحْنُ. (ق,د,جه)', 'അലി(റ): ഞാൻ ശിക്ഷാവിധി നടപ്പാക്കിയ ഒരുത്തന്നും ഞാൻ നഷ്ടപരിഹാരം നൽകുകയില്ല, മദ്യപാനിക്കൊഴികെ. കാരണം റസൂലുല്ലാഹി(സ) അതിൽ ഒരു നിർണ്ണിത തീരുമാനം എടുത്തിരുന്നില്ല. അത് പിന്നീട് നാം ചെയ്തതാണ്. (ബു,മു,ദ,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 490, 490, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ ضَرَبَ الْحَدَّ بِنَعْلَيْنِ أَرْبَعِينَ. قَالَ مِسْعَرٌ: أَظُنُّهُ فِي الْخَمْرِ. حَسَنٌ . (ت)', 'അബൂസഈദ്(റ): തിരുദൂതർ(റ) ശിക്ഷയായി ചെരുപ്പ് കൊണ്ട് നാൽപ്പത് അടി അടിച്ചു. മിസ്അർ(റ) പറയന്നു: ഞാൻ കരുതുന്നത് അത് മദ്യത്തിന്റെ കാര്യത്തിലാണെന്നാണ്. ഹദീസ് ഹസനാണ്. (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 490, 490, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِذَا شَرِبُوا الْخَمْرَ فَاجْلِدُوهُمْ، ثُمَّ إِنْ شَرِبُوا فَاجْلِدُوهُمْ، ثُمَّ إِنْ شَرِبُوا فَاجْلِدُوهُمْ، ثُمَّ إِنْ شَرِبُوا فَاقْتُلُوهُمْ". (د,ن,جه)', 'മുആവിയ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "മദ്യപിച്ചവരെ നിങ്ങൾ അടിക്കുക. വീണ്ടും മദ്യപിച്ചാൽ അപ്പോഴും അടിക്കുക. പിന്നെയും മദ്യപിച്ചാൽ അപ്പോഴും അടിക്കുക. ഇനിയും മദ്യപിച്ചാൽ അവനെ വധിക്കുക." (ദ,ന,ജ)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ', 'മുആവിയ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 490, 490, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ، بِهَذَا الْمَعْنَى، قَالَ: وَأَحْسِبُهُ قَالَ فِي الْخَامِسَةِ: "إِنْ شَرِبَهَا فَاقْتُلُوهُ". (د)', 'ഇബ്നുഉമർ(റ): മുൻപറഞ്ഞ അതേ ഹദീസ് തിരുദൂതർ(സ) പറഞ്ഞു. ഇബ്നുഉമർ(റ) പറയുന്നു: "ഇനിയും മദ്യപിച്ചാൽ അവനെ വധിക്കുക" എന്ന് നബി(സ) പറഞ്ഞത് അഞ്ചാമത്തേതിലാണെന്നാണ് ഞാൻ വിചാരിക്കുന്നത്. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 490, 490, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِذَا سَكِرَ - وَفِي رِوَايَةٍ: شَرِبَ الْخَمْرَ - فَاجْلِدُوهُ، ثُمَّ إِنْ سَكِرَ فَاجْلِدُوهُ، فَإِنْ عَادَ الرَّابِعَةَ فَاقْتُلُوهُ". وَفِي رِوَايَةٍ: "إِنْ شَرِبُوا الرَّابِعَةَ فَاقْتُلُوهُمْ". (د,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ മദ്യപിച്ച് ബോധം നഷ്ടപ്പെട്ടാൽ - മറ്റൊരു നിവേദനം: മദ്യപിച്ചാൽ - നിങ്ങളവനെ അടിക്കുക. വീണ്ടും മദ്യപിച്ചാൽ വീണ്ടും അടിക്കുക. പിന്നെയും മദ്യപിച്ചാൽ അപ്പോഴും അടിക്കുക. നാലാം പ്രാവശ്യവും ആവർത്തിച്ചാൽ അവനെ വധിക്കുക." മറ്റൊരു നിവേദനം: "നാലാം പ്രാവശ്യവും അവർ മദ്യപിച്ചാൽ അവരെ വധിക്കുക." (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 490, 491, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=99), 1, 'وَفِي رِوَايَةٍ: شَرِبَ الْخَمْرَ - فَاجْلِدُوهُ، ثُمَّ إِنْ سَكِرَ فَاجْلِدُوهُ، فَإِنْ عَادَ الرَّابِعَةَ فَاقْتُلُوهُ".', 'മറ്റൊരു നിവേദനം: മദ്യപിച്ചാൽ - നിങ്ങളവനെ അടിക്കുക. വീണ്ടും മദ്യപിച്ചാൽ വീണ്ടും അടിക്കുക. പിന്നെയും മദ്യപിച്ചാൽ അപ്പോഴും അടിക്കുക. നാലാം പ്രാവശ്യവും ആവർത്തിച്ചാൽ അവനെ വധിക്കുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=99), 2, 'وَفِي رِوَايَةٍ: "إِنْ شَرِبُوا الرَّابِعَةَ فَاقْتُلُوهُمْ". (د,ن,جه)', 'മറ്റൊരു നിവേദനം: "നാലാം പ്രാവശ്യവും അവർ മദ്യപിച്ചാൽ അവരെ വധിക്കുക." (ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ قَبِيصَةَ بْنِ ذُؤَيْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ شَرِبَ الْخَمْرَ فَاجْلِدُوهُ، فَإِنْ عَادَ – فَاجْلِدُوهُ، فَإِنْ عَادَ فِي الثَّالِثَةِ أَوِ الرَّابِعَةِ – فَاقْتُلُوهُ". فَأُتِيَ بِرَجُلٍ قَدْ شَرِبَ فَجَلَدَهُ، ثُمَّ أُتِيَ بِهِ فَجَلَدَهُ، ثُمَّ أُتِيَ بِهِ فَجَلَدَهُ، ثُمَّ أُتِيَ بِهِ فَجَلَدَهُ، وَرَفَعَ الْقَتْلَ، وَكَانَتْ رُخْصَةً. (د)', 'ഖബീസതുബ്നു ദുഐബ്(റ): നബി(സ) പറഞ്ഞു: "മദ്യപിച്ചവനെ നിങ്ങൾ അടിക്കുക. വീണ്ടും ചെയ്താൽ അപ്പോഴും അടിക്കുക. മൂന്നാമതും നാലാമതും അതു ചെയ്താൽ അവനെ വധിക്കുക." പിന്നീടൊരിക്കൽ മദ്യപിച്ച ഒരാളെ നബി(സ)യുടെ അടുത്തേക്ക് കൊണ്ടുവന്നു. അവനെ അടിച്ചു. വീണ്ടും കൊണ്ടുവന്നു. അപ്പോഴും അവനെ അടിച്ചു. വീണ്ടും കൊണ്ടുവന്നു. അപ്പോഴും അടിച്ചു. വീണ്ടും കൊണ്ടുവന്നു. അപ്പോഴും അവനെ അടിച്ചു. അവനെ വധിച്ചില്ല. അത് ഒരു ഇളവായിരുന്നു. (ദ)', 'قَبِيصَةَ بْنِ ذُؤَيْبٍ', 'ഖബീസതുബ്നു ദുഐബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 491, 491, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ حُضَيْنِ بْنِ الْمُنْذِرِ قَالَ: لَمَّا جِيءَ بِالْوَلِيدِ بْنِ عُقْبَةَ إِلَى عُثْمَانَ، قَدْ شَهِدُوا عَلَيْهِ، قَالَ لِعَلِيٍّ: دُونَكَ ابْنَ عَمِّكَ، فَأَقِمْ عَلَيْهِ الْحَدَّ. فَجَلَدَهُ عَلِيٌّ، وَقَالَ: جَلَدَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَرْبَعِينَ، وَجَلَدَ أَبُو بَكْرٍ أَرْبَعِينَ، وَجَلَدَ عُمَرُ ثَمَانِينَ، وَكُلٌّ سُنَّةٌ. (م,د,جه)', 'ഹുളൈനുബ്നുൽ മുൻദിർ: വലീദുബ്നു ഉഖ്ബ(റ)വിനെ ഉസ്മാൻ(റ)വിന്റെയടുത്ത് കൊണ്ടുവരികയും ജനങ്ങൾ അദ്ദേഹത്തിനെതിരെ സാക്ഷി നിൽക്കുകയും ചെയ്തപ്പോൾ ഉസ്മാൻ(റ) അലി(റ)വിനോട് പറഞ്ഞു: ഇതാ അങ്ങയുടെ പിതൃവ്യപുത്രൻ അവന്റെ ശിക്ഷ നടപ്പാക്കൂ. അങ്ങനെ അലി(റ) അദ്ദേഹത്തെ അടിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: റസൂൽ(സ) അടിച്ചത് നാൽപത് പ്രാവശ്യമാണ്. അബൂബകർ(റ) അടിച്ചതും നാൽപത് പ്രാവശ്യം. ഉമർ(റ) അടിച്ചത് എൺപത് പ്രാവശ്യമാണ്. എല്ലാം ചര്യ തന്നെയാണ്. (മു,ദ,ജ)', 'حُضَيْنِ بْنِ الْمُنْذِرِ قَالَ', 'ഹുളൈനുബ്നുൽ മുൻദിർ', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 491, 491, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَصَابَ مِنْكُمْ حَدًّا، فَعُجِّلَتْ لَهُ عُقُوبَتُهُ، فَهُوَ كَفَّارَتُهُ. وَإِلَّا، فَأَمْرُهُ إِلَى اللَّهِ". (م,جه)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ നിന്നാരെങ്കിലും ശിക്ഷിക്കപ്പെടേണ്ട വല്ല തെറ്റും ചെയ്യുകയും അതിനുള്ള ശിക്ഷ അവന് പെട്ടെന്ന് നടപ്പിലാകുകയും ചെയ്താൽ അത് അവന്റെ പ്രായശ്ചിത്തമാണ്. ശിക്ഷ നടപ്പിലാക്കപ്പെട്ടില്ലെങ്കിൽ അവന്റെ കാര്യം അല്ലാഹുവിന്റെ പക്കലാണ്." (മു,ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 491, 491, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ أَبِي جُحَيْفَةَ، عَنْ عَلِيٍّ– رَضِيَ اللهُ عَنْهُمَا – قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَصَابَ فِي الدُّنْيَا ذَنْبًا، فَعُوقِبَ بِهِ، فَاللَّهُ أَعْدَلُ مِنْ أَنْ يُثَنِّيَ عُقُوبَتَهُ عَلَى عَبْدِهِ. وَمَنْ أَذْنَبَ ذَنْبًا فِي الدُّنْيَا، فَسَتَرَهُ اللَّهُ عَلَيْهِ، فَاللَّهُ أَكْرَمُ مِنْ أَنْ يَعُودَ فِي شَيْءٍ قَدْ عَفَا عَنْهُ". (ت,جه)', 'അലി(റ)വിൽ നിന്ന് അബൂഹുദൈഫ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഇഹലോകത്തു വെച്ച് തെറ്റു ചെയ്യുകയും അതിന് അവൻ ശിക്ഷിക്കപ്പെടുകയും ചെയ്തു. തന്റെ അടിമയായ അവന്റെ തെറ്റിന്റെ പേരിൽ രണ്ടാമതും ശിക്ഷിക്കാതിരിക്കാൻ മാത്രം അല്ലാഹു നീതിമാനാണ്. ആരെങ്കിലും ഇഹലോകത്ത് വെച്ച് തെറ്റ് ചെയ്യുകയും അല്ലാഹു അത് മറച്ചുവെക്കുകയും ചെയ്താൽ തന്റെ അടിമക്ക് മാപ്പ് നൽകിയതിൽ നിന്ന് മടങ്ങാതിരിക്കാൻ മാത്രം അല്ലാഹു ഔദാര്യവാനാണ്." (തു,ജ)', 'أَبِي جُحَيْفَةَ، عَنْ عَلِيٍّ–', 'അലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 491, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: أَخَذَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا أَخَذَ عَلَى النِّسَاءِ: أَنْ لَا نُشْرِكَ بِاللَّهِ شَيْئًا، وَلَا نَسْرِقَ، وَلَا نَزْنِيَ، وَلَا نَقْتُلَ أَوْلَادَنَا، وَلَا يَعْضَهَ بَعْضُنَا بَعْضًا: "فَمَنْ وَفَى مِنْكُمْ فَأَجْرُهُ عَلَى اللَّهِ، وَمَنْ أَتَى مِنْكُمْ حَدًّا فَأُقِيمَ عَلَيْهِ فَهُوَ كَفَّارَتُهُ، وَمَنْ سَتَرَهُ اللَّهُ عَلَيْهِ فَأَمْرُهُ إِلَى اللَّهِ: إِنْ شَاءَ عَذَّبَهُ وَإِنْ شَاءَ غَفَرَ لَهُ". (م,ت,ن)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): സ്ത്രീകളിൽ നിന്ന് പ്രതിജ്ഞയെടുത്തതുപോലെ ഞങ്ങളിൽ നിന്നും നബി(സ) പ്രതിജ്ഞയെടുത്തു: അല്ലാഹുവിനോട് ആരെയും ഞങ്ങൾ പങ്കുചേർക്കുകയില്ല. ഞങ്ങൾ കളവ് നടത്തുകയോ വ്യഭിചരിക്കുകയോ സന്താനങ്ങളെ വധിക്കുകയോ ചെയ്യില്ല. ഞങ്ങൾ പരസ്പരം കടിച്ചുപറിക്കുകയുമില്ല. (ശേഷം നബി(സ) പറഞ്ഞു): "കരാർ ആര് പൂർത്തിയാക്കുന്നുവോ അവന്റെ പ്രതിഫലം അല്ലാഹുവിങ്കലാണ്. നിങ്ങളിൽ ആരെങ്കിലും തെറ്റുചെയ്തു ശിക്ഷിക്കപ്പെട്ടാൽ അത് അവന്റെ പ്രായശ്ചിത്തമാണ്. ആരുടെയെങ്കിലും മേൽ അല്ലാഹു മറയിട്ടുവെങ്കിൽ അവന്റെ കാര്യം അല്ലാഹുവിന്റെ അടുത്താണ്. അവനുദ്ദേശിച്ചാൽ പൊറുത്തുകൊടുക്കും. അവനുദ്ദേശിച്ചാൽ ശിക്ഷിക്കും." (മു,തു,ന)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 492, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا نَزَلَ عُذْرِي قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ فَذَكَرَ ذَلِكَ، وَتَلَا الْقُرْآنَ، فَلَمَّا نَزَلَ أَمَرَ بِرَجُلَيْنِ وَامْرَأَةٍ فَضُرِبُوا حَدَّهُمْ. (د,ت,جه)', 'ആഇശ(റ): എന്റെ നിരപരാധിത്തത്തിന്റെ സൂക്തം അവതരിച്ചപ്പോൾ റസൂൽ(സ) മിമ്പറിൽ കയറുകയും അത് പറയുകയും ഖുർആൻ ഓതുകയും ചെയ്തു. അത് അവതരിച്ചപ്പോൾ രണ്ട് പുരുഷന്മാരെയും ഒരു സ്ത്രീയെയും റസൂൽ(സ) കൽപിച്ചതനുസരിച്ച് (വ്യഭിചാരാരോപണത്തിനുള്ള) ഹദ്ദ് അടിച്ചു. (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 492, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قَالَ الرَّجُلُ لِلرَّجُلِ: يَا مُخَنَّثُ، فَاجْلِدُوهُ عِشْرِينَ. وَإِذَا قَالَ الرَّجُلُ لِلرَّجُلِ: يَا لُوطِيُّ، فَاجْلِدُوهُ عِشْرِينَ". (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ഒരു വ്യക്തി മറ്റൊരുത്തനെ ''സ്ത്രൈണതയുള്ളവനേ'' എന്നു വിളിച്ചാൽ വിളിച്ചവനെ നിങ്ങൾ ഇരുപത് പ്രാവശ്യം അടിക്കുക. ഒരു വ്യക്തി മറ്റൊരുത്തനെ ''സ്വവർഗരതിക്കാരാ'' എന്നു വിളിച്ചാൽ അവനെയും നിങ്ങൾ ഇരുപത് പ്രാവശ്യം അടിക്കുക." (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 492, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمَّا نَزَلَ عُذْرِي قَامَ النَّبِيُّ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ فَذَكَرَ ذَاكَ، وَتَلَا – تَعْنِي الْقُرْآنَ – فَلَمَّا نَزَلَ مِنَ الْمِنْبَرِ أَمَرَ بِالرَّجُلَيْنِ وَالْمَرْأَةِ، فَضُرِبُوا حَدَّهُمْ. وَفِي رِوَايَةٍ: فَأَمَرَ بِرَجُلَيْنِ وَامْرَأَةٍ مِمَّنْ تَكَلَّمَ بِالْفَاحِشَةِ: حَسَّانَ بْنِ ثَابِتٍ وَمِسْطَحِ بْنِ أُثَاثَةَ، وَالْمَرْأَةُ حَمْنَةُ بِنْتُ جَحْشٍ. (د,ت,جه)', 'ആഇശ(റ): എന്റെ നിരപരാധം തെളിയിച്ചുകൊണ്ടുള്ള സൂക്തമിറങ്ങിയപ്പോൾ നബി(സ) പ്രസംഗപീഠത്തിൽ കയറി അത് പറഞ്ഞു. ഖുർആൻ ഓതി. സൂക്തമിറങ്ങിയപ്പോൾ രണ്ട് പുരുഷന്മാരുടെ മേലിലും ഒരു സ്ത്രീയുടെ മേലിലും ശിക്ഷ നടപ്പാക്കി. മറ്റൊരു നിവേദനം: മോശമായ രീതിയിൽ സംസാരിച്ച രണ്ട് പുരുഷന്മാരെയും ഒരു സ്ത്രീയെയും അടിക്കാൻ അവിടുന്ന് കൽപിച്ചു. അവർ ഹസ്സാനുബ്നു സാബിതും മിസ്ഥഹുബ്നു ഉസാസയും ഹംന ബിൻത് ജഹ്ഷുമാണ്. (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 492, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=107), 1, 'وَفِي رِوَايَةٍ: فَأَمَرَ بِرَجُلَيْنِ وَامْرَأَةٍ مِمَّنْ تَكَلَّمَ بِالْفَاحِشَةِ: حَسَّانَ بْنِ ثَابِتٍ وَمِسْطَحِ بْنِ أُثَاثَةَ، وَالْمَرْأَةُ حَمْنَةُ بِنْتُ جَحْشٍ. (د,ت,جه)', 'മറ്റൊരു നിവേദനം: മോശമായ രീതിയിൽ സംസാരിച്ച രണ്ട് പുരുഷന്മാരെയും ഒരു സ്ത്രീയെയും അടിക്കാൻ അവിടുന്ന് കൽപിച്ചു. അവർ ഹസ്സാനുബ്നു സാബിതും മിസ്ഥഹുബ്നു ഉസാസയും ഹംന ബിൻത് ജഹ്ഷുമാണ്. (ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَعَنَ اللَّهُ السَّارِقَ، يَسْرِقُ الْبَيْضَةَ فَتُقْطَعُ يَدُهُ، وَيَسْرِقُ الْحَبْلَ فَتُقْطَعُ يَدُهُ". (ق)', 'അബൂഹുറൈറ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "മോഷ്ടാവിനെ അല്ലാഹു ശപിച്ചിരിക്കുന്നു. അവൻ മുട്ട മോഷ്ടിക്കുന്നു അപ്പോൾ അവന്റെ കൈ മുറിക്കപ്പെടുന്നു. കയർ മോഷ്ടിക്കുന്നു, അപ്പോൾ അവന്റെ കൈ മുറിക്കപ്പെടുന്നു." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 493, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ قَطَعَ سَارِقًا فِي مِجَنٍّ قِيمَتُهُ ثَلَاثَةُ دَرَاهِمَ. (ق,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): മൂന്ന് ദിർഹം വിലയുള്ള ഒരു പരിച കട്ടതിന് നബി(സ) കൈ മുറിച്ചു. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 493, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُقْطَعُ يَدُ السَّارِقِ إِلَّا فِي رُبْعِ دِينَارٍ فَصَاعِدًا". (ق,د,ت,ن,جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ മോഷ്ടിച്ചവന്റെ കയ്യേ മുറിക്കാവൂ." (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 493, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ قَالَ: "تُقْطَعُ يَدُ السَّارِقِ فِي ثَمَنِ الْمِجَنِّ". (جه)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): നബി(സ) പറഞ്ഞു: "പരിചയുടെ എട്ടിലൊന്ന് വിലയുള്ള വസ്തു മോഷ്ടിച്ചാൽ അവന്റെ കൈമുറിക്കപ്പെടും." (ജ)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 493, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَطَعَ رَسُولُ اللَّهِ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ فِي مِجَنٍّ قِيمَتُهُ خَمْسَةُ دَرَاهِمَ. وَفِي رِوَايَةٍ: ثَمَنُهُ – قِيمَتُهُ – ثَلَاثَةُ دَرَاهِمَ. وَفِي رِوَايَةٍ: قَطَعَ يَدَ سَارِقٍ سَرَقَ تُرْسًا مِنْ صُفَّةِ النِّسَاءِ، ثَمَنُهُ ثَلَاثَةُ دَرَاهِمَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): അഞ്ച് ദിർഹം വിലയുള്ള അങ്കി മോഷ്ടിച്ചതിന് റസൂൽ(സ) കൈ മുറിച്ചു. മറ്റൊരു നിവേദനം: അതിന്റെ വില മൂന്ന് ദിർഹമാണ്. മറ്റൊരു നിവേദനം: സ്ത്രീകളുടെ ചെരുവിൽ നിന്ന് മൂന്ന് ദിർഹം വിലയുള്ള അങ്കി മോഷ്ടിച്ച ഒരു മോഷ്ടാവിന്റെ കൈ റസൂൽ(സ) മുറിച്ചു. (ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 493, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=112), 1, 'وَفِي رِوَايَةٍ: ثَمَنُهُ – قِيمَتُهُ – ثَلَاثَةُ دَرَاهِمَ.', 'മറ്റൊരു നിവേദനം: അതിന്റെ വില മൂന്ന് ദിർഹമാണ്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=112), 2, 'وَفِي رِوَايَةٍ: قَطَعَ يَدَ سَارِقٍ سَرَقَ تُرْسًا مِنْ صُفَّةِ النِّسَاءِ، ثَمَنُهُ ثَلَاثَةُ دَرَاهِمَ. (ن)', 'മറ്റൊരു നിവേദനം: സ്ത്രീകളുടെ ചെരുവിൽ നിന്ന് മൂന്ന് ദിർഹം വിലയുള്ള അങ്കി മോഷ്ടിച്ച ഒരു മോഷ്ടാവിന്റെ കൈ റസൂൽ(സ) മുറിച്ചു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:قَطَعَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ فِي مِجَنٍّ قِيمَتُهُ خَمْسَةُ دَرَاهِمَ. وَفِي رِوَايَةٍ: سَرَقَ رَجُلٌ مِجَنًّا عَلَى عَهْدِ أَبِي بَكْرٍ فَقُوِّمَ خَمْسَةَ دَرَاهِمَ، فَقُطِعَ. (ن)', 'അനസ്(റ): അഞ്ച് ദിർഹം വിലയുള്ള ഒരു അങ്കി മോഷ്ടിച്ചതിന് അബൂബകർ(റ) കൈ മുറിച്ചു. മറ്റൊരു നിവേദനം: അബൂബകർ(റ)വിന്റെ കാലത്ത് ഒരാൾ ഒരു അങ്കി മോഷ്ടിച്ചു. അങ്ങനെ അതിന് അഞ്ച് ദിർഹം നിശ്ചയിക്കപ്പെടുകയും അയാളുടെ കൈ മുറിക്കപ്പെടുകയും ചെയ്തു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 493, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=113), 1, 'وَفِي رِوَايَةٍ: سَرَقَ رَجُلٌ مِجَنًّا عَلَى عَهْدِ أَبِي بَكْرٍ فَقُوِّمَ خَمْسَةَ دَرَاهِمَ، فَقُطِعَ. (ن)', 'മറ്റൊരു നിവേദനം: അബൂബകർ(റ)വിന്റെ കാലത്ത് ഒരാൾ ഒരു അങ്കി മോഷ്ടിച്ചു. അങ്ങനെ അതിന് അഞ്ച് ദിർഹം നിശ്ചയിക്കപ്പെടുകയും അയാളുടെ കൈ മുറിക്കപ്പെടുകയും ചെയ്തു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: قَطَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رُبُعِ دِينَارٍ. (ن)', 'ആഇശ(റ): ഒരു ദീനാറിന്റെ നാലിലൊന്ന് മോഷ്ടിച്ചതിന് റസൂൽ(സ) കൈ മുറിച്ചു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 494, 494, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُقْطَعُ الْيَدُ إِلَّا فِي ثَمَنِ الْمِجَنِّ ثُلُثِ دِينَارٍ – أَوْ: نِصْفِ دِينَارٍ – فَصَاعِداً". وَفِي رِوَايَةٍ: "تُقْطَعُ يَدُ سَارِقٍ فِي رُبُعِ دِينَارٍ فَصَاعِداً". وَفِي رِوَايَةٍ: عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تُقْطَعُ اليَدُ فِي رُبُعِ دِينَارٍ فَصَاعِداً. وَفِي رِوَايَةٍ قَالَتْ: يُقْطَعُ فِي رُبُعِ دِينَارٍ فَصَاعِداً. وَفِي رِوَايَةٍ قَالَتْ: مَا طَالَ عَلَيَّ وَلَا نَسِيتُ: الْقَطْعُ فِي رُبُعِ دِينَارٍ فَصَاعِداً. (ن)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "അങ്കിയുടെ വിലയായ മൂന്നിലൊന്ന് ദീനാറോ - അല്ലെങ്കിൽ അര ദീനാറോ - അതിലധികമോ മോഷ്ടിച്ചാലല്ലാതെ കൈ മുറിക്കപ്പെടുകയില്ല. മറ്റൊരു നിവേദനം: "ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ മോഷ്ടിച്ചവന്റെ കൈ മുറിക്കപ്പെടും." മറ്റൊരു നിവേദനം: ആഇശ(റ) പറഞ്ഞു: ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ മോഷ്ടിച്ചതിന് കൈ മുറിക്കപ്പെടും. മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ ഉള്ളതിലാണ് അത് മുറിക്കപ്പെടുക. മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ ഉള്ളതിലാണ് കൈ മുറിക്കൽ എന്നത് ഞാൻ മറക്കുകയോ (അത് ഞാൻ അറിഞ്ഞതിന് ശേഷം) കുറെ കാലം കഴിയുകയോ ചെയ്തിട്ടില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 494, 494, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=115), 1, 'وَفِي رِوَايَةٍ: "تُقْطَعُ يَدُ سَارِقٍ فِي رُبُعِ دِينَارٍ فَصَاعِداً".', 'മറ്റൊരു നിവേദനം: "ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ മോഷ്ടിച്ചവന്റെ കൈ മുറിക്കപ്പെടും."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=115), 2, 'وَفِي رِوَايَةٍ: عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تُقْطَعُ اليَدُ فِي رُبُعِ دِينَارٍ فَصَاعِداً.', 'മറ്റൊരു നിവേദനം: ആഇശ(റ) പറഞ്ഞു: ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ മോഷ്ടിച്ചതിന് കൈ മുറിക്കപ്പെടും.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=115), 3, 'وَفِي رِوَايَةٍ قَالَتْ: يُقْطَعُ فِي رُبُعِ دِينَارٍ فَصَاعِداً.', 'മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ ഉള്ളതിലാണ് അത് മുറിക്കപ്പെടുക.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=115), 4, 'وَفِي رِوَايَةٍ قَالَتْ: مَا طَالَ عَلَيَّ وَلَا نَسِيتُ: الْقَطْعُ فِي رُبُعِ دِينَارٍ فَصَاعِداً. (ن)', 'മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ ഉള്ളതിലാണ് കൈ മുറിക്കൽ എന്നത് ഞാൻ മറക്കുകയോ (അത് ഞാൻ അറിഞ്ഞതിന് ശേഷം) കുറെ കാലം കഴിയുകയോ ചെയ്തിട്ടില്ല. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يُقْطَعُ – لَا تُقْطَعُ يَدُ – السَّارِقِ إِلَّا فِي رُبُعِ دِينَارٍ فَصَاعِداً". وَفِي رِوَايَةٍ: قَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: الْقَطْعُ فِي رُبُعِ دِينَارٍ فَصَاعِداً. وَفِي رِوَايَةٍ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُقْطَعُ يَدُ السَّارِقِ فِي ثَمَنِ المِجَنِّ". وَثَمَنُ المِجَنِّ رُبُعُ دِينَارٍ. وَفِي رِوَايَةٍ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْطَعُ اليَدَ فِي رُبُعِ دِينَارٍ فَصَاعِداً. وَفِي رِوَايَةٍ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُقْطَعُ اليَدُ إِلَّا فِي رُبُعِ دِينَارٍ".وَفِي رِوَايَةٍ: "فَمَا فَوْقَهُ".وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تُقْطَعُ اليَدُ فِي المِجَنِّ". وَفِي رِوَايَةٍ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُقْطَعُ يَدُ السَّارِقِ فِيمَا دُونَ المِجَنِّ". قِيلَ لَهَا: مَا ثَمَنُ المِجَنِّ؟ قَالَتْ: رُبُعُ دِينَارٍ. وَفِي رِوَايَةٍ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُقْطَعُ اليَدُ إِلَّا فِي المِجَنِّ أَوْ ثَمَنِهِ". وَفِي رِوَايَةٍ قَالَتْ: لَمْ تُقْطَعْ يَدُ سَارِقٍ فِي أَدْنَى مِنْ حَجَفَةٍ أَوْ تُرْسٍ، وَكُلٌّ وَاحِدٍ مِنْهُمَا ذُو ثَمَنٍ. (ن)', 'ആഇശ(റ): റസൂൽ(സ) പറയുന്നത് മഹതി കേട്ടു: "ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ മോഷ്ടിച്ചതിനല്ലാതെ മോഷ്ടാവിന്റെ കൈ മുറിക്കപ്പെടുകയില്ല." മറ്റൊരു നിവേദനം: ആഇശ(റ) പറഞ്ഞു: ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ മോഷ്ടിച്ചതിനാണ് കൈ മുറിക്കൽ. മറ്റൊരു നിവേദനം: ആഇശ(റ) പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "അങ്കിയുടെ വില മോഷ്ടിച്ചതിന് മോഷ്ടാവിന്റെ കൈ മുറിക്കപ്പെടും." അങ്കിയുടെ വിലയെന്നാൽ ഒരു ദീനാറിന്റെ നാലിലൊന്നാണ്. മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ മോഷ്ടിച്ചതിന് റസൂൽ(സ) കൈ മുറിക്കാറുണ്ടായിരുന്നു. മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "ഒരു ദീനാറിന്റെ നാലിലൊന്ന് മോഷ്ടിച്ചാലല്ലാതെ കൈ മുറിക്കപ്പെടുകയില്ല." മറ്റൊരു നിവേദനത്തിൽ "അതിലധികമോ" എന്ന് അധികമുണ്ട്. മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "അങ്കി മോഷ്ടിച്ചതിന് കൈ മുറിക്കപ്പെടും." മറ്റൊരു നിവേദനം: ആഇശ(റ) പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "അങ്കിയുടെ വിലയേക്കാൾ താഴ്ന്നത് മോഷ്ടിച്ചവന്റെ കൈ മുറിക്കപ്പെടുകയില്ല." മഹതിയോട് ചോദിക്കപ്പെട്ടു: അങ്കിയുടെ വില എത്രയാണ്? മഹതി പറഞ്ഞു: ഒരു ദീനാറിന്റെ നാലിലൊന്ന്. മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "അങ്കിയോ അതിന്റെ വിലയോ മോഷ്ടിച്ചാലല്ലാതെ കൈ മുറിക്കപ്പെടുകയില്ല." മറ്റൊരു നിവേദനം: ആഇശ(റ) പറഞ്ഞു: തോലങ്കിയേക്കാളോ അങ്കിയേക്കാളോ താഴ്ന്ന വിലയുള്ളത് മോഷ്ടിച്ച ആരുടെയും കൈ മുറിക്കപ്പെട്ടിട്ടില്ല. അവ രണ്ടും (പരിഗണിക്കപ്പെടുന്ന) വിലയുള്ളവയാണ്. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 494, 495, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=116), 1, 'وَفِي رِوَايَةٍ: قَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: الْقَطْعُ فِي رُبُعِ دِينَارٍ فَصَاعِداً.', 'മറ്റൊരു നിവേദനം: ആഇശ(റ) പറഞ്ഞു: ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ മോഷ്ടിച്ചതിനാണ് കൈ മുറിക്കൽ.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=116), 2, 'وَفِي رِوَايَةٍ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُقْطَعُ يَدُ السَّارِقِ فِي ثَمَنِ المِجَنِّ". وَثَمَنُ المِجَنِّ رُبُعُ دِينَارٍ.', 'മറ്റൊരു നിവേദനം: ആഇശ(റ) പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "അങ്കിയുടെ വില മോഷ്ടിച്ചതിന് മോഷ്ടാവിന്റെ കൈ മുറിക്കപ്പെടും." അങ്കിയുടെ വിലയെന്നാൽ ഒരു ദീനാറിന്റെ നാലിലൊന്നാണ്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=116), 3, 'وَفِي رِوَايَةٍ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْطَعُ اليَدَ فِي رُبُعِ دِينَارٍ فَصَاعِداً.', 'മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: ഒരു ദീനാറിന്റെ നാലിലൊന്നോ അതിലധികമോ മോഷ്ടിച്ചതിന് റസൂൽ(സ) കൈ മുറിക്കാറുണ്ടായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=116), 4, 'وَفِي رِوَايَةٍ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُقْطَعُ اليَدُ إِلَّا فِي رُبُعِ دِينَارٍ".', 'മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "ഒരു ദീനാറിന്റെ നാലിലൊന്ന് മോഷ്ടിച്ചാലല്ലാതെ കൈ മുറിക്കപ്പെടുകയില്ല."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=116), 5, 'وَفِي رِوَايَةٍ: "فَمَا فَوْقَهُ".', 'മറ്റൊരു നിവേദനത്തിൽ "അതിലധികമോ" എന്ന് അധികമുണ്ട്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=116), 6, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تُقْطَعُ اليَدُ فِي المِجَنِّ".', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "അങ്കി മോഷ്ടിച്ചതിന് കൈ മുറിക്കപ്പെടും."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=116), 7, 'وَفِي رِوَايَةٍ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُقْطَعُ يَدُ السَّارِقِ فِيمَا دُونَ المِجَنِّ". قِيلَ لَهَا: مَا ثَمَنُ المِجَنِّ؟ قَالَتْ: رُبُعُ دِينَارٍ.', 'മറ്റൊരു നിവേദനം: ആഇശ(റ) പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "അങ്കിയുടെ വിലയേക്കാൾ താഴ്ന്നത് മോഷ്ടിച്ചവന്റെ കൈ മുറിക്കപ്പെടുകയില്ല." മഹതിയോട് ചോദിക്കപ്പെട്ടു: അങ്കിയുടെ വില എത്രയാണ്? മഹതി പറഞ്ഞു: ഒരു ദീനാറിന്റെ നാലിലൊന്ന്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=116), 8, 'وَفِي رِوَايَةٍ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُقْطَعُ اليَدُ إِلَّا فِي المِجَنِّ أَوْ ثَمَنِهِ".', 'മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "അങ്കിയോ അതിന്റെ വിലയോ മോഷ്ടിച്ചാലല്ലാതെ കൈ മുറിക്കപ്പെടുകയില്ല."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=116), 9, 'وَفِي رِوَايَةٍ قَالَتْ: لَمْ تُقْطَعْ يَدُ سَارِقٍ فِي أَدْنَى مِنْ حَجَفَةٍ أَوْ تُرْسٍ، وَكُلٌّ وَاحِدٍ مِنْهُمَا ذُو ثَمَنٍ. (ن)', 'മറ്റൊരു നിവേദനം: ആഇശ(റ) പറഞ്ഞു: തോലങ്കിയേക്കാളോ അങ്കിയേക്കാളോ താഴ്ന്ന വിലയുള്ളത് മോഷ്ടിച്ച ആരുടെയും കൈ മുറിക്കപ്പെട്ടിട്ടില്ല. അവ രണ്ടും (പരിഗണിക്കപ്പെടുന്ന) വിലയുള്ളവയാണ്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطَعَ فِي قِيمَةِ خَمْسَةِ دَرَاهِمَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): അഞ്ച് ദിർഹം വിലയുള്ളത് മോഷ്ടിച്ചവന്റെ കൈ നബി(സ) മുറിച്ചു. (ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 495, 495, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ أَيْمَنَ مَوْلَى الزُّبَيْرِ قَالَ: لَمْ يَقْطَعِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ السَّارِقَ إِلَّا فِي ثَمَنِ الْمِجَنِّ، وَثَمَنُ الْمِجَنِّ يَوْمَئِذٍ دِينَارٌ. وَفِي رِوَايَةٍ قَالَ: لَمْ تَكُنْ تُقْطَعُ الْيَدُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا فِي ثَمَنِ الْمِجَنِّ، وَقِيمَتُهُ يَوْمَئِذٍ دِينَارٌ. وَفِي رِوَايَةٍ قَالَ: يُقْطَعُ السَّارِقُ فِي ثَمَنِ الْمِجَنِّ، وَكَانَ ثَمَنُ الْمِجَنِّ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دِينَارًا أَوْ عَشَرَةَ دَرَاهِمَ. وَفِي رِوَايَةٍ مَرْفُوعَةٍ قَالَ: لَا تُقْطَعُ اليَدُ إِلَّا فِي ثَمَنِ المِجَنِّ، وَثَمَنُهُ يَوْمَئِذٍ دِينَارٌ. وَفِي رِوَايَةٍ قَالَ: لَا يُقْطَعُ السَّارِقُ فِي أَقَلَّ مِنْ ثَمَنِ المِجَنِّ. (ن)', 'സുബൈർ(റ)വിന്റെ അടിമയായ അയ്മൻ(റ): അങ്കിയുടെ വിലയുള്ളത് മോഷ്ടിച്ചതിനല്ലാതെ നബി(സ) മോഷ്ടാവിന്റെ കൈ മുറിച്ചിട്ടില്ല. അന്ന് അങ്കിയുടെ വില ഒരു ദീനാറായിരുന്നു. മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: അങ്കിയുടെ വിലയുള്ളത് മോഷ്ടിച്ചതിനല്ലാതെ, റസൂൽ(സ)യുടെ കാലത്ത് കൈ മുറിക്കപ്പെടാറില്ലായിരുന്നു. അന്ന് അതിന്റെ വില ഒരു ദീനാറായിരുന്നു. മറ്റൊരു നിവേദനം: അയ്മൻ(റ) പറഞ്ഞു: അങ്കിയുടെ വില മോഷ്ടിച്ചവന്റെ കൈ മുറിക്കപ്പെടും. റസൂൽ(സ)യുടെ കാലത്ത് ഒരു അങ്കിയുടെ വില ഒരു ദീനാർ അല്ലെങ്കിൽ പത്ത് ദിർഹം ആയിരുന്നു. മർഫൂആയ മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "അങ്കിയുടെ വില മോഷ്ടിച്ചാലല്ലാതെ കൈ മുറിക്കപ്പെടുകയില്ല." അന്ന് അങ്കിയുടെ വില ഒരു ദീനാർ ആയിരുന്നു. മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: അങ്കിയുടെ വിലയേക്കാൾ കുറഞ്ഞത് മോഷ്ടിച്ചവന്റെ കൈ മുറിക്കപ്പെടുകയില്ല. (ന)', 'أَيْمَنَ مَوْلَى الزُّبَيْرِ قَالَ', 'സുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 495, 495, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=118), 1, 'وَفِي رِوَايَةٍ قَالَ: لَمْ تَكُنْ تُقْطَعُ الْيَدُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا فِي ثَمَنِ الْمِجَنِّ، وَقِيمَتُهُ يَوْمَئِذٍ دِينَارٌ.', 'മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: അങ്കിയുടെ വിലയുള്ളത് മോഷ്ടിച്ചതിനല്ലാതെ, റസൂൽ(സ)യുടെ കാലത്ത് കൈ മുറിക്കപ്പെടാറില്ലായിരുന്നു. അന്ന് അതിന്റെ വില ഒരു ദീനാറായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=118), 2, 'وَفِي رِوَايَةٍ قَالَ: يُقْطَعُ السَّارِقُ فِي ثَمَنِ الْمِجَنِّ، وَكَانَ ثَمَنُ الْمِجَنِّ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دِينَارًا أَوْ عَشَرَةَ دَرَاهِمَ.', 'മറ്റൊരു നിവേദനം: അയ്മൻ(റ) പറഞ്ഞു: അങ്കിയുടെ വില മോഷ്ടിച്ചവന്റെ കൈ മുറിക്കപ്പെടും. റസൂൽ(സ)യുടെ കാലത്ത് ഒരു അങ്കിയുടെ വില ഒരു ദീനാർ അല്ലെങ്കിൽ പത്ത് ദിർഹം ആയിരുന്നു. മർഫൂആയ');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=118), 3, 'وَفِي رِوَايَةٍ مَرْفُوعَةٍ قَالَ: لَا تُقْطَعُ اليَدُ إِلَّا فِي ثَمَنِ المِجَنِّ، وَثَمَنُهُ يَوْمَئِذٍ دِينَارٌ.', 'മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "അങ്കിയുടെ വില മോഷ്ടിച്ചാലല്ലാതെ കൈ മുറിക്കപ്പെടുകയില്ല." അന്ന് അങ്കിയുടെ വില ഒരു ദീനാർ ആയിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=118), 4, 'وَفِي رِوَايَةٍ قَالَ: لَا يُقْطَعُ السَّارِقُ فِي أَقَلَّ مِنْ ثَمَنِ المِجَنِّ. (ن)', 'മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: അങ്കിയുടെ വിലയേക്കാൾ കുറഞ്ഞത് മോഷ്ടിച്ചവന്റെ കൈ മുറിക്കപ്പെടുകയില്ല. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: كَانَ ثَمَنُ الْمِجَنِّ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَوَّمُ عَشَرَةَ دَرَاهِمَ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യുടെ കാലത്ത് അങ്കിക്ക് പത്ത് ദിർഹമായിരുന്നു വില കണക്കാക്കിയിരുന്നത്. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 495, 495, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أَبِي أُمَيَّةَ الْمَخْزُومِيِّ رَضِيَ اللَّهُ عَنْهُ : أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِلِصٍّ قَدِ اعْتَرَفَ اعْتِرَافًا، وَلَمْ يُوجَدْ مَعَهُ مَتَاعٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا إِخَالُكَ سَرَقْتَ". قَالَ: بَلَى، فَأَعَادَ عَلَيْهِ مَرَّتَيْنِ أَوْ ثَلَاثًا، فَأَمَرَ بِهِ فَقُطِعَ وَجِيءَ بِهِ، فَقَالَ: "اسْتَغْفِرِ اللَّهَ وَتُبْ إِلَيْهِ". فَقَالَ: أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ، فَقَالَ: "اللَّهُمَّ تُبْ عَلَيْهِ" ثَلَاثًا. (د,ن,جه)', 'അബൂഉമയ്യ(റ): നബി(സ)യുടെ അടുത്തേക്ക് ഒരു മോഷ്ടാവിനെ കൊണ്ടുവന്നു. അയാൾ പരസ്യമായിത്തന്നെ മോഷണം നടത്തിയത് സമ്മതിച്ചു. അയാളുടെ പക്കൽ ചരക്കുകളൊന്നും ഉണ്ടായിരുന്നില്ല. തിരുദൂതർ(സ) പറഞ്ഞു: "നീ മോഷണം നടത്തിയെന്ന് ഞാൻ കരുതുന്നില്ല." അയാൾ പറഞ്ഞു: അല്ല (ഞാൻ മോഷ്ടിച്ചിട്ടുണ്ട്.) രണ്ടുമൂന്ന് തവണ ഇത് ആവർത്തിച്ചു. അപ്പോൾ നബി(സ) അയാളുടെ കൈമുറിക്കാൻ കൽപിച്ചു. കൈ മുറിക്കപ്പെടുകയും ചെയ്തു. ശേഷം നബി(സ)യുടെ അരികിലേക്ക് കൊണ്ടുവന്നു. റസൂൽ(സ) പറഞ്ഞു: "നീ അല്ലാഹുവിനോട് പൊറുക്കലിനെത്തേടുക, അവനിലേക്ക് മടങ്ങുക." അപ്പോൾ അയാൾ പറഞ്ഞു: ഞാൻ അല്ലാഹുവിനോട് പൊറുക്കലിനെ തേടുകയും അവനിലേക്ക് മടങ്ങുകയും ചെയ്യുന്നു. അപ്പോൾ തിരുദൂതർ(സ) മൂന്ന് തവണ ഇപ്രകാരം പറഞ്ഞു: "അല്ലാഹുവേ, അവന് മാപ്പ് കൊടുക്കണേ." (ദ,ന,ജ)', 'أَبِي أُمَيَّةَ الْمَخْزُومِيِّ', 'അബൂഉമയ്യ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 495, 496, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِمَاعِزِ بْنِ مَالِكٍ: "أَحَقٌّ مَا بَلَغَنِي عَنْكَ". قَالَ: وَمَا بَلَغَكَ عَنِّي؟ قَالَ: "بَلَغَنِي أَنَّكَ وَقَعْتَ عَلَى جَارِيَةِ آلِ فُلَانٍ". قَالَ: نَعَمْ. فَشَهِدَ أَرْبَعَ شَهَادَاتٍ، فَأَمَرَ بِهِ فَرُجِمَ. حَسَنٌ. (م,د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മാഇസ്(റ)വിനോട് ചോദിച്ചു: "നിന്നെക്കുറിച്ച് എനിക്ക് ലഭിച്ച വിവരം സത്യമാണോ?" മാഇസ്(റ) ചോദിച്ചു: അങ്ങേക്ക് എന്നെക്കുറിച്ചെന്താണ് ലഭിച്ചത്? നബി(സ) പറഞ്ഞു: "ഇന്നാലിന്ന കുടുംബത്തിൽപ്പെട്ട പെൺകുട്ടിയുമായി നീ ബന്ധപ്പെട്ടുവെന്ന് ഞാനറിഞ്ഞു." മാഇസ്(റ) പറഞ്ഞു: അതെ. നാലുപേർ അതിന് സാക്ഷിനിന്നു. അപ്പോൾ നബി(സ) എറിഞ്ഞുകൊല്ലാൻ ഉത്തരവിട്ടു. (മു,ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 496, 496, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ رَفَعَ إِلَيْهِ نَفَرٌ مِنَ الْكَلَاعِيِّينَ: أَنَّ حَاكَةً سَرَقُوا مَتَاعًا. فَحَبَسَهُمْ أَيَّامًا ثُمَّ خَلَّى سَبِيلَهُمْ، فَأَتَوْهُ فَقَالُوا: خَلَّيْتَ سَبِيلَ هَؤُلَاءِ بِلَا امْتِحَانٍ وَلَا ضَرْبٍ؟ فَقَالَ النُّعْمَانُ: مَا شِئْتُمْ، إِنْ شِئْتُمْ أَضْرِبْهُمْ، فَإِنْ أَخْرَجَ اللَّهُ مَتَاعَكُمْ فَذَاكَ، وَإِلَّا أَخَذْتُ مِنْ ظُهُورِكُمْ مِثْلَهُ. قَالُوا: هَذَا حُكْمُكَ؟ قَالَ: هَذَا حُكْمُ اللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'നുഅ്മാനുബ്നു ബഷീർ(റ): വസ്ത്രം നെയ്യുന്ന ചിലയാളുകൾ എന്തോ ചരക്ക് മോഷ്ടിച്ചുവെന്ന് കലാഇ ഗോത്രത്തിൽപ്പെട്ട ചിലയാളുകൾ അദ്ദേഹത്തോട് പരാതിപ്പെട്ടു. അങ്ങനെ അദ്ദേഹം അക്കൂട്ടരെ തടവിൽ വെക്കുകയും ശേഷം വെറുതെവിടുകയും ചെയ്തു. അപ്പോൾ കലാഇ ഗോത്രക്കാർ അദ്ദേഹത്തിനടുത്ത് വരികയും ഇപ്രകാരം ചോദിക്കുകയും ചെയ്തു: അടിക്കാതെയും ചോദ്യം ചെയ്യാതെയും നിങ്ങൾ അവരെ വെറുതെ വിട്ടോ? അപ്പോൾ നുഅ്മാൻ(റ) പറഞ്ഞു: നിങ്ങളെന്താണ് ആഗ്രഹിക്കുന്നത്? നിങ്ങളാഗ്രഹിക്കുന്നുവെങ്കിൽ ഞാനവരെ അടിക്കും. അങ്ങനെ നിങ്ങളുടെ ചരക്ക് തിരിച്ചുകിട്ടിയാൽ അത് നിങ്ങൾക്കാവും. കണ്ടുമുട്ടിയില്ലെങ്കിൽ നിങ്ങളെയും അതുപോലെ അടിക്കും. അവർ ചോദിച്ചു: ഇത് നിങ്ങളുടെ വിധിയാണോ? നുഅ്മാൻ(റ) പറഞ്ഞു: ഇതാണ് അല്ലാഹുവിന്റെയും അവന്റെ തിരുദൂതരുടെയും വിധി. (ദ,ന)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബഷീർ(റ)', null, null, array['ن']::text[], array['ദ','ന']::text[], null, null, 496, 496, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَبَسَ رَجُلًا فِي تُهْمَةٍ ثُمَّ خَلَّى سَبِيلَهُ. وَفِي رِوَايَةٍ: حَبَسَ نَاساً فِي تُهْمَةٍ. (د,ن,جه)', 'മുആവിയതുബ്നു ഹൈദ(റ): റസൂൽ(സ) സംശയത്തിന്റെ അടിസ്ഥാനത്തിൽ ഒരാളെ പിടികൂടി. പിന്നെ അയാളെ വെറുതെ വിടുകയും ചെയ്തു. മറ്റൊരു നിവേദനം: ഒരു കൂട്ടമാളുകളെ പിടികൂടി. (ന)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['د','ن','جه']::text[], array['ന']::text[], null, null, 496, 496, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=123), 1, 'وَفِي رِوَايَةٍ: حَبَسَ نَاساً فِي تُهْمَةٍ. (د,ن,جه)', 'മറ്റൊരു നിവേദനം: ഒരു കൂട്ടമാളുകളെ പിടികൂടി. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَزْهَرَ بْنِ عَبْدِ اللَّهِ الْحَرَازِيِّ: أَنَّ قَوْمًا مِنَ الْكَلَاعِيِّينَ سُرِقَ لَهُمْ مَتَاعٌ، فَاتَّهَمُوا أُنَاسًا مِنَ الْحَاكَةِ، فَأَتَوُا النُّعْمَانَ بْنَ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُ، صَاحِبَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَحَبَسَهُمْ أَيَّامًا ثُمَّ خَلَّى سَبِيلَهُمْ، فَأَتَوُا النُّعْمَانَ فَقَالُوا: خَلَّيْتَ سَبِيلَهُمْ بِغَيْرِ ضَرْبٍ وَلَا امْتِحَانٍ؟ فَقَالَ النُّعْمَانُ: مَا شِئْتُمْ، إِنْ شِئْتُمْ أَنْ أَضْرِبَهُمْ، فَإِنْ خَرَجَ مَتَاعُكُمْ فَذَاكَ، وَإِلَّا أَخَذْتُ مِنْ ظُهُورِكُمْ مِثْلَ مَا أَخَذْتُ مِنْ ظُهُورِهِمْ. فَقَالُوا: هَذَا حُكْمُكَ؟ فَقَالَ: هَذَا حُكْمُ اللَّهِ وَحُكْمُ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د,ن)', 'അസ്ഹറുബ്നു അബ്ദില്ലാഹിൽ ഹറാസി(റ): കലാഈ ഗോത്രക്കാരായ ചിലരുടെ ഒരു ചരക്ക് മോഷ്ടിക്കപ്പെട്ടു. അവർ വസ്ത്ര നൈത്തുകാരായ ചിലരെ സംശയിക്കുകയും പ്രശ്നവുമായി നബി(സ)യുടെ അനുയായിയായ നുഅ്മാനുബ്നു ബശീർ(റ)വിനെ സമീപിക്കുകയും ചെയ്തു. അങ്ങനെ നുഅ്മാൻ(റ) കുറച്ചു ദിവസം അവരെ തടവിലിടുകയും ശേഷം വെറുതെവിടുകയും ചെയ്തു. ഉടനെ കലാഈ ഗോത്രക്കാർ അദ്ദേഹത്തിന്റെയടുത്തു വന്ന് ചോദിച്ചു: അടിക്കാതെയും ചോദ്യം ചെയ്യാതെയും താങ്കൾ അവരെ വെറുതെ വിട്ടുവോ? നുഅ്മാൻ(റ) പറഞ്ഞു: നിങ്ങൾ എന്താണാഗ്രഹിക്കുന്നത്. നിങ്ങൾക്ക് വേണമെങ്കിൽ ഞാനവരെ അടിക്കാം. അങ്ങനെ നിങ്ങളുടെ ചരക്ക് കിട്ടിയാൽ അതുണ്ടാകും. ഇല്ലായെങ്കിൽ അവരെ ശിക്ഷിച്ചതുപോലെ നിങ്ങളെയും ഞാൻ ശിക്ഷിക്കും. അവർ ചോദിച്ചു: ഇത് താങ്കളുടെ വിധിയാണോ? നുഅ്മാൻ പറഞ്ഞു: ഇത് അല്ലാഹുവിന്റെയും അവന്റെ റസൂലിന്റെയും വിധിയാണ്. (ദ,ന)', 'أَزْهَرَ بْنِ عَبْدِ اللَّهِ الْحَرَازِيِّ', 'അസ്ഹറുബ്നു അബ്ദില്ലാഹിൽ ഹറാസി(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 496, 497, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ صَفْوَانَ بْنِ أُمَيَّةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا سَرَقَ بُرْدَةً لَهُ، فَرَفَعَهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَ بِقَطْعِهِ، فَقَالَ: يَا رَسُولَ اللَّهِ، قَدْ تَجَاوَزْتُ عَنْهُ. فَقَالَ: "أَبَا وَهْبٍ، أَفَلَا كَانَ قَبْلَ أَنْ تَأْتِيَنَا بِهِ". وَفِي رِوَايَةٍ: "فَلَوْلَا كَانَ هَذَا قَبْلَ أَنْ تَأْتِيَنِي بِهِ يَا أَبَا وَهْبٍ". وَفِي رِوَايَةٍ مُرْسَلَةٍ عَنْ عَطَاءِ بْنِ أَبِي رَبَاحٍ: أَنَّ رَجُلًا سَرَقَ ثَوْبًا، فَأُتِيَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَ بِقَطْعِهِ، فَقَالَ الرَّجُلُ: يَا رَسُولَ اللَّهِ، هُوَ لَهُ. قَالَ: "فَهَلَّا قَبْلَ الْآنَ". فَقَطَعَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'സ്വഫ്വാനുബ്നു ഉമയ്യ(റ): ഒരാൾ അവരുടെ പുതപ്പ് മോഷ്ടിച്ചു. സ്വഫ്വാൻ(റ) നബി(സ)യോട് പരാതിപ്പെട്ടു. അവന്റെ കൈമുറിക്കാൻ നബി(സ) കൽപിച്ചു. അപ്പോൾ സ്വഫ്വാൻ(റ) പറഞ്ഞു: തിരുദൂതരേ, ഞാനത് അവന് മാപ്പ് നൽകിയിരിക്കുന്നു. അപ്പോൾ തിരുദൂതർ(സ) പറഞ്ഞു: "അബൂവഹ്ബേ, നമ്മുടെയടുത്ത് കൊണ്ടുവരുന്നതിന് മുമ്പായി കൂടായിരുന്നോ ഇത്." മറ്റൊരു നിവേദനം: "അബൂവഹ്ബേ, ഇത് അവനെ നീ എന്റെയടുത്ത് കൊണ്ടുവരുന്നതിന് മുമ്പായിരുന്നെങ്കിൽ എത്ര നന്നായിരുന്നു." അത്വാഉബ്നു അബീറബാഹ്(റ)വിൽ നിന്നും മുർസലായ ഒരു നിവേദനം: ഒരാൾ ഒരു വസ്ത്രം മോഷ്ടിച്ചു. അവനെ റസൂൽ(സ)യുടെ സമീപത്ത് കൊണ്ടുവരികയും അവിടന്ന് അവന്റെ കൈ മുറിക്കാൻ കൽപിക്കുകയും ചെയ്തു. അപ്പോൾ ഒരാൾ പറഞ്ഞു: റസൂലേ, അത് ഞാൻ അവന് നൽകിയിരിക്കുന്നു. റസൂൽ(സ) ചോദിച്ചു: "എന്നാൽ ഇതിന് മുമ്പേ ഇത് പറയാമായിരുന്നല്ലോ." എന്നിട്ട് തിരുദൂതർ(സ) അയാളുടെ കൈമുറിച്ചു. (ന)', 'صَفْوَانَ بْنِ أُمَيَّةَ', 'സ്വഫ്വാനുബ്നു ഉമയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 497, 497, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=125), 1, 'وَفِي رِوَايَةٍ: "فَلَوْلَا كَانَ هَذَا قَبْلَ أَنْ تَأْتِيَنِي بِهِ يَا أَبَا وَهْبٍ".', 'മറ്റൊരു നിവേദനം: "അബൂവഹ്ബേ, ഇത് അവനെ നീ എന്റെയടുത്ത് കൊണ്ടുവരുന്നതിന് മുമ്പായിരുന്നെങ്കിൽ എത്ര നന്നായിരുന്നു." അത്വാഉബ്നു അബീറബാഹ്(റ)വിൽ നിന്നും മുർസലായ ഒരു നിവേദനം: ഒരാൾ ഒരു വസ്ത്രം മോഷ്ടിച്ചു. അവനെ റസൂൽ(സ)യുടെ സമീപത്ത് കൊണ്ടുവരികയും അവിടന്ന് അവന്റെ കൈ മുറിക്കാൻ കൽപിക്കുകയും ചെയ്തു. അപ്പോൾ ഒരാൾ പറഞ്ഞു: റസൂലേ, അത് ഞാൻ അവന് നൽകിയിരിക്കുന്നു. റസൂൽ(സ) ചോദിച്ചു: "എന്നാൽ ഇതിന് മുമ്പേ ഇത് പറയാമായിരുന്നല്ലോ." എന്നിട്ട് തിരുദൂതർ(സ) അയാളുടെ കൈമുറിച്ചു. (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=125), 2, 'وَفِي رِوَايَةٍ مُرْسَلَةٍ عَنْ عَطَاءِ بْنِ أَبِي رَبَاحٍ: أَنَّ رَجُلًا سَرَقَ ثَوْبًا، فَأُتِيَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَ بِقَطْعِهِ، فَقَالَ الرَّجُلُ: يَا رَسُولَ اللَّهِ، هُوَ لَهُ. قَالَ: "فَهَلَّا قَبْلَ الْآنَ". فَقَطَعَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تُقْطَعُ يَدُ السَّارِقِ فِي رُبُعِ دِينَارٍ فَصَاعِدًا". (ق,ن,د)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു ദീനാറിന്റെ നാലിൽ ഒന്നോ അതിലധികമോ മോഷ്ടിച്ച മോഷ്ടാവിന്റെ കൈ മുറിക്കപ്പെടും." (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ن','د']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 497, 497, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطَعَ يَدَ سَارِقٍ سَرَقَ تُرْسًا مِنْ صُفَّةِ النِّسَاءِ ثَمَنُهُ ثَلَاثَةُ دَرَاهِمَ. (م,د,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): സ്ത്രീകൾ നിസ്കരിക്കുന്ന സ്ഥലത്തു നിന്ന് മൂന്ന് ദിർഹം വിലയുള്ള പരിച മോഷ്ടിച്ചവന്റെ കൈ നബി(സ) മുറിച്ചു. (മു,ദ,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 497, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَطَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَ رَجُلٍ فِي مِجَنٍّ قِيمَتُهُ دِينَارٌ أَوْ عَشَرَةُ دَرَاهِمَ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു ദീനാറോ പത്ത് ദിർഹമോ വിലയുള്ള പരിച മോഷ്ടിച്ചവന്റെ കൈ നബി(സ) മുറിച്ചുമാറ്റി. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 498, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا قَطْعَ فِي ثَمَرٍ وَلَا كَثَرٍ". وَالْكَثَرُ الْجُمَّارُ. (د,ت,ن,جه)', 'റാഫിഉബ്നു ഖദീജ്(റ): റസൂൽ(സ) പറഞ്ഞു: "പഴവും പനങ്കള്ളും മോഷ്ടിച്ചവന്റെ കൈ മുറിക്കരുത്." (ദ,തു,ന,ജ)', 'رَافِعِ بْنِ خَدِيجٍ', 'റാഫിഉബ്നു ഖദീജ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 498, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ عَلَى خَائِنٍ وَلَا مُنْتَهِبٍ وَلَا مُخْتَلِسٍ قَطْعٌ". (ن)', 'ജാബിർ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: വഞ്ചന നടത്തിയവന്റെയും റാഞ്ചിയവന്റെയും തട്ടിപ്പറിച്ചവന്റെയും കൈ മുറിക്കരുത്." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 498, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ: أَنَّ عَبْدًا سَرَقَ وَدِيًّا مِنْ حَائِطِ رَجُلٍ فَغَرَسَهُ فِي حَائِطِ سَيِّدِهِ، فَخَرَجَ صَاحِبُ الْوَدِيِّ يَلْتَمِسُ وَدِيَّهُ فَوَجَدَهُ، فَاسْتَعْدَى عَلَى الْعَبْدِ مَرْوَانَ بْنَ الْحَكَمِ، وَهُوَ أَمِيرُ الْمَدِينَةِ يَوْمَئِذٍ، فَسَجَنَ مَرْوَانُ الْعَبْدَ، وَأَرَادَ قَطْعَ يَدِهِ، فَانْطَلَقَ سَيِّدُ الْعَبْدِ إِلَى رَافِعِ ابْنِ خَدِيجٍ فَسَأَلَهُ عَنْ ذَلِكَ، فَأَخْبَرَهُ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا قَطْعَ فِي ثَمَرٍ وَلَا كَثَرٍ". فَقَالَ الرَّجُلُ: إِنَّ مَرْوَانَ أَخَذَ غُلَامِي وَهُوَ يُرِيدُ قَطْعَ يَدِهِ، وَأَنَا أُحِبُّ أَنْ تَمْشِيَ مَعِي إِلَيْهِ فَتُخْبِرَهُ بِالَّذِي سَمِعْتَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَمَشَى مَعَهُ رَافِعُ بْنُ خَدِيجٍ حَتَّى أَتَى مَرْوَانَ بْنَ الْحَكَمِ، فَقَالَ لَهُ رَافِعٌ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا قَطْعَ فِي ثَمَرٍ وَلَا كَثَرٍ". فَأَمَرَ مَرْوَانُ بِالْعَبْدِ فَأُرْسِلَ. وَفِي رِوَايَةٍ: فَجَلَدَهُ مَرْوَانُ جَلَدَاتٍ وَخَلَّى سَبِيلَهُ. (د,ت,ن,جه)', 'മുഹമ്മദുബ്നു യഹ്യബ്നു ഹബ്ബാൻ(റ): ഒരടിമ ഒരാളുടെ തോട്ടത്തിൽ നിന്ന് ഒരു പനത്തൈ മോഷ്ടിച്ച് തന്റെ യജമാനന്റെ തോട്ടത്തിൽ നട്ടു. പനത്തയ്യിന്റെ ഉടമ അന്വേഷിച്ച് അത് കണ്ടെത്തി. മദീനയിലെ അന്നത്തെ ഭരണാധിപനായ മർവാനുബ്നുൽ ഹകീമിനോട് അയാൾ അടിമയെക്കുറിച്ച് പരാതി പറഞ്ഞു. അങ്ങനെ മർവാൻ അടിമയെ ജയിലിലടച്ചു. അടിമയുടെ കൈ മുറിക്കാനായിരുന്നു മർവാന്റെ തീരുമാനം. അപ്പോൾ അടിമയുടെ യജമാനൻ റാഫിഉബ്നു ഖദീജ്(റ)വിനെ സമീപിച്ചു. അതിനെക്കുറിച്ചന്വേഷിച്ചു. "പഴവും പനങ്കള്ളും മോഷ്ടിച്ചവന്റെ കൈ മുറിക്കരുത്" എന്ന് നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ടെന്ന് റാഫിഅ്(റ) അറിയിച്ചു. അപ്പോൾ യജമാനൻ പറഞ്ഞു: മർവാൻ എന്റെ അടിമയെ കസ്റ്റഡിയിലെടുത്ത് അവന്റെ കൈ മുറിക്കാൻ തീരുമാനിച്ചിരിക്കുന്നു. താങ്കളെന്റെ കൂടെവന്ന് മർവാനോട് തിരുദൂതർ(സ)യിൽ നിന്ന് നിങ്ങൾ കേട്ടത് പറയണമെന്ന് ഞാനാഗ്രഹിക്കുന്നുണ്ട്. അങ്ങനെ റാഫിഅ്(റ) അദ്ദേഹത്തോടൊപ്പം നടന്നുചെന്ന് മർവാനെ സമീപിച്ചു. എന്നിട്ട് പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "പഴമോ പനങ്കള്ളോ മോഷ്ടിച്ചവന്റെ കൈ മുറിക്കരുത്." അപ്പോൾ മർവാൻ അടിമയെ വെറുതെ വിടാനുത്തരവിട്ടു. മറ്റൊരു നിവേദനം: മർവാനവനെ അടിച്ചു. എന്നിട്ട് അവനെ പറഞ്ഞുവിട്ടു. (ദ,തു,ന,ജ)', 'مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ', 'മുഹമ്മദുബ്നു യഹ്യബ്നു ഹബ്ബാൻ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 498, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=131), 1, 'وَفِي رِوَايَةٍ: فَجَلَدَهُ مَرْوَانُ جَلَدَاتٍ وَخَلَّى سَبِيلَهُ. (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: മർവാനവനെ അടിച്ചു. എന്നിട്ട് അവനെ പറഞ്ഞുവിട്ടു. (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ سُئِلَ عَنِ الثَّمَرِ الْمُعَلَّقِ فَقَالَ: "مَنْ أَصَابَ بِفِيهِ مِنْ ذِي حَاجَةٍ، غَيْرَ مُتَّخِذٍ خُبْنَةً، فَلَا شَيْءَ عَلَيْهِ. وَمَنْ خَرَجَ بِشَيْءٍ مِنْهُ فَعَلَيْهِ غَرَامَةُ مِثْلَيْهِ وَالْعُقُوبَةُ، وَمَنْ سَرَقَ مِنْهُ شَيْئًا بَعْدَ أَنْ يُؤْوِيَهُ الْجَرِينُ، فَبَلَغَ ثَمَنَ الْمِجَنِّ، فَعَلَيْهِ الْقَطْعُ. وَمَنْ سَرَقَ دُونَ ذَلِكَ فَعَلَيْهِ غَرَامَةُ مِثْلَيْهِ وَالْعُقُوبَةُ". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): മരത്തിൽ തൂങ്ങിക്കിടക്കുന്ന പഴത്തെക്കുറിച്ച് റസൂൽ(സ) ചോദിക്കപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "വിശന്നവൻ തന്റെ വായകൊണ്ട് എടുത്തുതിന്നുകയും എന്നാൽ അതിൽ നിന്ന് ഒന്നും തുണിയിൽ കെട്ടി കൊണ്ടുപോകാതിരിക്കുകയും ചെയ്താൽ അവനെതിരെ ഒരു നടപടിയുമില്ല. അതിൽ നിന്ന് എന്തെങ്കിലും കൊണ്ടുപോയാൽ അവൻ അതിന്റെ വിലയുടെ രണ്ടിരട്ടി പിഴയായി നൽകുകയും അവൻ ശിക്ഷിക്കപ്പെടുകയും ചെയ്യണം. ഉണക്കാനിട്ട സ്ഥലത്ത് നിന്ന് മോഷ്ടിച്ചുകൊണ്ടുപോയാൽ, അതിന് ഒരു പരിചയുടെ വിലയുണ്ടെങ്കിൽ, അവന്റെ കൈമുറിക്കപ്പെടും. അതിലും കുറഞ്ഞത് മോഷ്ടിച്ചാൽ അതിന്റെ വിലയുടെ രണ്ടിരട്ടി പിഴയായി നൽകുകയും അവൻ ശിക്ഷിക്കപ്പെടുകയും വേണം." (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ فَضَالَةَ بْنِ عُبَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ بِسَارِقٍ، فَقُطِعَتْ يَدُهُ، ثُمَّ أَمَرَ بِهَا فَعُلِّقَتْ فِي عُنُقِهِ. حَسَنٌ. (د,ت,ن,جه)', 'ഫളാലതുബ്നു ഉബൈദ്(റ): റസൂൽ(സ)യുടെ സന്നിധിയിലേക്ക് ഒരു മോഷ്ടാവിനെ കൊണ്ടുവരികയും അവന്റെ കൈ മുറിക്കപ്പെടുകയും ചെയ്തു. ശേഷം റസൂൽ(സ) കൽപിച്ചതു പ്രകാരം ആ കൈ അവന്റെ കഴുത്തിൽ തൂക്കിയിട്ടു. (ദ,തു,ന,ജ)', 'فَضَالَةَ بْنِ عُبَيْدٍ', 'ഫളാലതുബ്നു ഉബൈദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنِ ابْنِ مُحَيْرِزٍ قَالَ: سَأَلْتُ فَضَالَةَ بْنَ عُبَيْدٍ عَنْ تَعْلِيقِ يَدِ السَّارِقِ فِي عُنُقِهِ؟ قَالَ: سُنَّةٌ، قَطَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَ رَجُلٍ وَعَلَّقَ يَدَهُ فِي عُنُقِهِ. وَفِي رِوَايَةٍ قَالَ: قُلْتُ لِفَضَالَةَ بْنِ عُبَيْدٍ: أَرَأَيْتَ تَعْلِيقَ الْيَدِ فِي عُنُقِ السَّارِقِ مِنَ السُّنَّةِ هُوَ؟ قَالَ: نَعَمْ، أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَارِقٍ فَقَطَعَ يَدَهُ وَعَلَّقَهُ فِي عُنُقِهِ. (ن)', 'ഇബ്നുമുഹൈരിസ്(റ): കൈ കഴുത്തിൽ തൂക്കിയിടുന്നതിനെക്കുറിച്ച് ഞാൻ ഫളാലതുബ്നു ഉബൈദ്(റ)വിനോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: അത് ചര്യയാണ്. റസൂൽ(സ) ഒരാളുടെ കൈ മുറിക്കുകയും ശേഷം അത് അവന്റെ കഴുത്തിൽ ചാർത്തുകയും ചെയ്തു. മറ്റൊരു നിവേദനം: ഞാൻ ഫളാലതുബ്നു ഉബൈദ്(റ)വിനോട് പറഞ്ഞു: മോഷ്ടിച്ചവന്റെ കൈ കഴുത്തിൽ തൂക്കുന്നത് ചര്യയിൽ പെട്ടതാണോ എന്നു പറഞ്ഞുതരൂ. അദ്ദേഹം പറഞ്ഞു: അതെ. ഒരു മോഷ്ടാവിനെ റസൂൽ(സ)യുടെ സന്നിധിയിൽ കൊണ്ടുവന്നു. അവിടുന്ന് അവന്റെ കൈ മുറിക്കുകയും അത് അവന്റെ കഴുത്തിൽ ചാർത്തുകയും ചെയ്തു. (ന)', 'ابْنِ مُحَيْرِزٍ قَالَ', 'ഇബ്നുമുഹൈരിസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=134), 1, 'وَفِي رِوَايَةٍ قَالَ: قُلْتُ لِفَضَالَةَ بْنِ عُبَيْدٍ: أَرَأَيْتَ تَعْلِيقَ الْيَدِ فِي عُنُقِ السَّارِقِ مِنَ السُّنَّةِ هُوَ؟ قَالَ: نَعَمْ، أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَارِقٍ فَقَطَعَ يَدَهُ وَعَلَّقَهُ فِي عُنُقِهِ. (ن)', 'മറ്റൊരു നിവേദനം: ഞാൻ ഫളാലതുബ്നു ഉബൈദ്(റ)വിനോട് പറഞ്ഞു: മോഷ്ടിച്ചവന്റെ കൈ കഴുത്തിൽ തൂക്കുന്നത് ചര്യയിൽ പെട്ടതാണോ എന്നു പറഞ്ഞുതരൂ. അദ്ദേഹം പറഞ്ഞു: അതെ. ഒരു മോഷ്ടാവിനെ റസൂൽ(സ)യുടെ സന്നിധിയിൽ കൊണ്ടുവന്നു. അവിടുന്ന് അവന്റെ കൈ മുറിക്കുകയും അത് അവന്റെ കഴുത്തിൽ ചാർത്തുകയും ചെയ്തു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُغَرَّمُ صَاحِبُ سَرِقَةٍ إِذَا أُقِيمَ عَلَيْهِ الْحَدُّ". قَالَ أَبُو عَبْدِ الرَّحْمَنِ: وَهَذَا مُرْسَلٌ وَلَيْسَ بِثَابِتٍ. (ن)', 'അബ്ദുർഹ്മാനുബ്നു ഔഫ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ശിക്ഷ നടപ്പിലാക്കപ്പെട്ട മോഷ്ടാവിൽ നിന്ന് പിഴ ഈടാക്കുകയില്ല." അബൂഅബ്ദിർറഹ്മാൻ(റ) പറഞ്ഞു: ഈ ഹദീസ് മുർസലാണ്. സാബിത് അല്ല. (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ', 'അബ്ദുർഹ്മാനുബ്നു ഔഫ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 499, 500, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ جُنَادَةَ بْنِ أَبِي أُمَيَّةَ قَالَ: كُنَّا مَعَ بُسْرِ بْنِ أَرْطَاةَ رَضِيَ اللهُ عَنْهُ فِي الْبَحْرِ، فَأُتِيَ بِسَارِقٍ يُقَالُ لَهُ مِصْدَرٌ، قَدْ سَرَقَ بُخْتِيَّةً، فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تُقْطَعُ الْأَيْدِي فِي السَّفَرِ". وَلَوْلَا ذَلِكَ لَقَطَعْتُهُ. (د,ت,ن)', 'ജൂനാദതുബ്നു അബീഉമയ്യ(റ): ഞങ്ങൾ കടലിൽ ബുസ്ർബിൻ അർത്വാത്(റ)വിന്റെ കൂടെയായിരുന്നപ്പോൾ മിസ്ദർ എന്ന് പേരുള്ള ഒരു മോഷ്ടാവിനെ കൊണ്ടുവന്നു. അയാൾ ഒരു വലിയ ഒട്ടകത്തെ മോഷ്ടിച്ചിരുന്നു. അപ്പോൾ ബുസ്ർ(റ) പറഞ്ഞു: തിരുദൂതർ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "യാത്രയിൽ കൈ മുറിക്കപ്പെടുകയില്ല." അതില്ലായിരുന്നെങ്കിൽ ഞാൻ കൈ മുറിക്കുമായിരുന്നു. (ദ,തു,ന)', 'جُنَادَةَ بْنِ أَبِي أُمَيَّةَ قَالَ', 'ജൂനാദതുബ്നു അബീഉമയ്യ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 500, 500, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ ثَعْلَبَةَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ عَمْرَو بْنَ سَمُرَةَ رَضِيَ اللهُ عَنْهُ جَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي سَرَقْتُ جَمَلًا لِبَنِي فُلَانٍ، فَطَهِّرْنِي. فَأَرْسَلَ إِلَيْهِمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: إِنَّا افْتَقَدْنَا جَمَلًا لَنَا. فَأَمَرَ بِهِ النَّبِيُّ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ فَقُطِعَتْ يَدُهُ. قَالَ ثَعْلَبَةُ: أَنَا أَنْظُرُ إِلَيْهِ حِينَ وَقَعَتْ يَدُهُ وَهُوَ يَقُولُ: الْحَمْدُ لِلَّهِ الَّذِي طَهَّرَنِي مِنْكِ، أَرَدْتِ أَنْ تُدْخِلِي جَسَدِي النَّارَ. (جه)', 'സഅ്ലബതുൽ അൻസാരി(റ): അംറുബ്നു സുംറ(റ) തിരുദൂതർ(സ)യെ സമീപിച്ചു പറഞ്ഞു: റസൂലേ, ഇന്ന ഗോത്രക്കാരുടെ ഒരു ഒട്ടകം ഞാൻ മോഷ്ടിച്ചിരിക്കുന്നു. അതുകൊണ്ട് എന്നെ ശുദ്ധീകരിച്ചാലും. തിരുദൂതർ(സ) ആ ഗോത്രത്തിലേക്ക് ആളെ അയച്ചു. അവർ പറഞ്ഞു: ഞങ്ങളുടെ ഒരൊട്ടകത്തെ കാണാതായിട്ടുണ്ട്. അപ്പോൾ നബി(സ) അംറ്(റ)വിന്റെ കൈ മുറിക്കാനുത്തരവിട്ടു. കൈ മുറിക്കപ്പെട്ടു. സഅ്ലബ(റ) പറയുന്നു: അംറ്(റ)വിന്റെ കൈ നിലത്തുവീണ സമയത്ത് ഞാൻ അദ്ദേഹത്തെ നോക്കി. അദ്ദേഹം പറയുന്നുണ്ടായിരുന്നു: നിന്നിൽ നിന്ന് എന്നെ ശുദ്ധീകരിച്ച അല്ലാഹുവിന് സ്തുതി, എന്റെ ശരീരത്തെ നരകത്തിലിടാൻ നീ ആഗ്രഹിച്ചു. (ജ)', 'ثَعْلَبَةَ الْأَنْصَارِيِّ', 'സഅ്ലബതുൽ അൻസാരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 500, 500, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً خَرَجَتْ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تُرِيدُ الصَّلَاةَ، فَتَلَقَّاهَا رَجُلٌ، فَتَجَلَّلَهَا، فَقَضَى حَاجَتَهُ مِنْهَا، فَصَاحَتْ، وَانْطَلَقَ، فَمَرَّ عَلَيْهَا رَجُلٌ، فَقَالَتْ: إِنَّ ذَاكَ فَعَلَ بِي كَذَا وَكَذَا، وَمَرَّتْ عِصَابَةٌ مِنَ الْمُهَاجِرِينَ، فَقَالَتْ: إِنَّ ذَلِكَ الرَّجُلَ فَعَلَ بِي كَذَا وَكَذَا، فَانْطَلَقُوا فَأَخَذُوا الرَّجُلَ الَّذِي ظَنَّتْ أَنَّهُ وَقَعَ عَلَيْهَا، فَأَتَوْهَا بِهِ، فَقَالَتْ: نَعَمْ هُوَ هَذَا. فَأَتَوْا بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا أَمَرَ بِهِ قَامَ صَاحِبُهَا الَّذِي وَقَعَ عَلَيْهَا، فَقَالَ: يَا رَسُولَ اللَّهِ، أَنَا صَاحِبُهَا. فَقَالَ لَهَا: "اذْهَبِي فَقَدْ غَفَرَ اللَّهُ لَكِ". وَقَالَ لِلرَّجُلِ قَوْلًا حَسَنًا - قَالَ أَبُو دَاوُدَ: يَعْنِي الرَّجُلَ الْمَأْخُوذَ - وَقَالَ لِلرَّجُلِ الَّذِي وَقَعَ عَلَيْهَا: "ارْجُمُوهُ". فَقَالَ: "لَقَدْ تَابَ تَوْبَةً لَوْ تَابَهَا أَهْلُ الْمَدِينَةِ لَقُبِلَ مِنْهُمْ". (د,ت)', 'വാഇലുബ്നു ഹജർ(റ): നബി(സ)യുട കാലത്ത് ഒരു സ്ത്രീ നിസ്കരിക്കാൻ വേണ്ടി പുറപ്പെട്ടു. അപ്പോൾ ഒരു പുരുഷൻ അവളെ കണ്ടുമുട്ടുകയും അവളെ ആഞ്ഞുപിടിച്ച് വ്യഭിചരിക്കുകയും ചെയ്തു. അപ്പോൾ ആ സ്ത്രീ നിലവിളിച്ചു. അയാൾ പോയി. അവളുടെ അടുത്തുകൂടെ ഒരാൾ നടന്നുപോയി. അവൾ പറഞ്ഞു: അയാൾ എന്നെ ഇന്നതൊക്കെ ചെയ്തു. ശേഷം ഒരു കൂട്ടം മുഹാജിറുകൾ അതിലൂടെ നടന്നു. അവൾ പറഞ്ഞു: അയാൾ എന്നെ ഇന്നതൊക്കെ ചെയ്തു. അപ്പോളവർ പോയി. തന്നെ വ്യഭിചരിച്ച ആളെന്ന് അവൾ കരുതിയവനെ അവർ അവളുടെയടുത്തേക്ക് പിടിച്ചുകൊണ്ടുവന്നു. അവൾ പറഞ്ഞു: ഇയാൾ തന്നെ. അവർ അയാളെ തിരുസന്നിധിയിൽ ഹാജരാക്കി. അയാളെ എറിഞ്ഞുകൊല്ലാൻ കൽപിച്ചപ്പോൾ അവളെ വ്യഭിചരിച്ച ആൾ എഴുന്നേറ്റുനിന്നു പറഞ്ഞു: റസൂലേ, ഞാനാണ് അവളുമായി ബന്ധപ്പെട്ടത്. അപ്പോൾ തിരുദൂതർ(സ) ആ സ്ത്രീയോട് പറഞ്ഞു: "നീ പോവുക, അല്ലാഹു നിനക്ക് പൊറുത്തുതന്നിരിക്കുന്നു." അയാളോട് - അബൂദാവൂദ്: അതായത് പിടിക്കപ്പെട്ടവനോട് - തിരുദൂതർ(സ) നല്ല വാക്കുകൾ പറഞ്ഞു. അവളെ വ്യഭിചരിച്ചവനെ നോക്കി പറഞ്ഞു: "ഇവനെ എറിഞ്ഞുകൊല്ലുക." എന്നിട്ട് നബി(സ) പറഞ്ഞു: "അയാൾ ഒരു തൗബ ചെയ്തിരിക്കുന്നു, മദീനക്കാർ മുഴുവൻ ആ തൗബ ചെയ്തിരുന്നുവെങ്കിൽ അവരിൽ നിന്നത് സ്വീകരിക്കുമായിരുന്നു." (ദ,തു)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹജർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 500, 501, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَزْنِي الزَّانِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ، وَلَا يَسْرِقُ السَّارِقُ حِينَ يَسْرِقُ وَهُوَ مُؤْمِنٌ، وَلَا يَشْرَبُ الْخَمْرَ حِينَ يَشْرَبُهَا وَهُوَ مُؤْمِنٌ، وَلَا يَنْتَهِبُ نُهْبَةً ذَاتَ شَرَفٍ يَرْفَعُ النَّاسُ إِلَيْهَا أَبْصَارَهُمْ وَهُوَ مُؤْمِنٌ". وَفِي رِوَايَةٍ: ثُمَّ التَّوْبَةُ مَعْرُوضَةٌ بَعْدُ". وَفِي رِوَايَةٍ: "فَإِذَا فَعَلَ ذَلِكَ خَلَعَ رِبْقَةَ الْإِسْلَامِ مِنْ عُنُقِهِ، فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ". (ن)', 'അബൂഹുറൈറ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "മുഅ്മിനായിരിക്കെ ഒരാളും വ്യഭിചരിക്കുകയില്ല. മുഅ്മിനായിരിക്കെ ഒരാളും മോഷണം നടത്തുകയില്ല. മുഅ്മിനായിരിക്കെ ഒരാളും മദ്യപിക്കുകയില്ല. മുഅ്മിനായിരിക്കെ ഒരാളും ജനങ്ങൾ വലുതായിക്കാണുന്ന വിലയുള്ള വസ്തു കവർച്ച ചെയ്യുകയില്ല."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=139), 1, 'وَفِي رِوَايَةٍ: ثُمَّ التَّوْبَةُ مَعْرُوضَةٌ بَعْدُ".', 'മറ്റൊരു നിവേദനം: "പശ്ചാത്താപം അതിന് ശേഷമാണ് (അവനിലേക്ക്) പ്രത്യക്ഷപ്പെടുത്തുന്നത്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=139), 2, 'وَفِي رِوَايَةٍ: "فَإِذَا فَعَلَ ذَلِكَ خَلَعَ رِبْقَةَ الْإِسْلَامِ مِنْ عُنُقِهِ، فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ". (ن)', 'മറ്റൊരു നിവേദനം: "അവനത് ചെയ്താൽ തന്റെ കഴുത്തിൽ നിന്നും ഇസ്ലാമിന്റെ കുടുക്കിനെ ഊരിയിരിക്കുന്നു. അവൻ പശ്ചാത്തപിക്കുന്നുവെങ്കിൽ അല്ലാഹു അവന്റെ പശ്ചാത്താപം സ്വീകരിക്കും." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ أَبِي هُرَيْرَةَ رَضِي اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَعَنَ اللَّهُ السَّارِقَ، يَسْرِقُ الْبَيْضَةَ فَتُقْطَعُ يَدُهُ، وَيَسْرِقُ الْحَبْلَ فَتُقْطَعُ يَدُهُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു മോഷ്ടാവിനെ ശപിച്ചിരിക്കുന്നു. അവൻ മുട്ട മോഷ്ടിക്കുന്നു. അപ്പോൾ അവന്റെ കൈ മുറിക്കപ്പെടുന്നു. അവൻ പർവ്വതം മോഷ്ടിക്കുന്നു, അപ്പോഴും അവന്റെ കൈ മുറിക്കപ്പെടുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 501, 501, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنِ الْحَارِثِ بْنِ حَاطِبٍ رَضِيَ اللهُ عَنْهُ : أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِلِصٍّ فَقَالَ: "اقْتُلُوهُ". فَقَالُوا: يَا رَسُولَ اللَّهِ، إِنَّمَا سَرَقَ. فَقَالَ: "اقْتُلُوهُ". فَقَالُوا: يَا رَسُولَ اللهِ، إِنَّمَا سَرَقَ. قَالَ: "اقْطَعُوا يَدَهُ". قَالَ: ثُمَّ سَرَقَ فَقُطِعَتْ رِجْلُهُ، ثُمَّ سَرَقَ عَلَى عَهْدِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ حَتَّى قُطِعَتْ قَوَائِمُهُ كُلُّهَا، ثُمَّ سَرَقَ أَيْضًا الْخَامِسَةَ، فَقَالَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ : كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْلَمَ بِهَذَا حِينَ قَالَ: "اقْتُلُوهُ". ثُمَّ دَفَعَهُ إِلَى فِتْيَةٍ مِنْ قُرَيْشٍ لِيَقْتُلُوهُ، مِنْهُمْ عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ، وَكَانَ يُحِبُّ الْإِمَارَةَ، فَقَالَ: أَمِّرُونِي عَلَيْكُمْ. فَأَمَّرُوهُ عَلَيْهِمْ، فَكَانَ إِذَا ضَرَبَ ضَرَبُوهُ حَتَّى قَتَلُوهُ. (ن)', 'ഹാരിസുബിൻ ഹാത്വിബ്(റ): റസൂൽ (സ)യുടെ സന്നിധിയിൽ ഒരു മോഷ്ടാവിനെ കൊണ്ടുവന്നു. അവിടന്ന് പറഞ്ഞു: "അവനെ വധിക്കുക." അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ തിരുദൂതരേ, അവൻ മോഷ്ടിച്ചിട്ടേയുള്ളൂ. തിരുമേനി(സ) പറഞ്ഞു: "അവനെ വധിച്ച് കളയുക." അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവൻ മോഷ്ടിച്ചിട്ടേയുള്ളൂ. തിരുമേനി(സ) പറഞ്ഞു: "അവന്റെ കൈ മുറിച്ച് കളയുക." നിവേദകൻ പറയുന്നു: വീണ്ടും അവൻ മോഷ്ടിച്ചു, അപ്പോൾ അവന്റെ കാലുകൾ മുറിക്കപ്പെട്ടു. പിന്നെ അബൂബക്കർ(റ)വിന്റെ കാലത്ത് വീണ്ടും മോഷ്ടിച്ചു. അങ്ങനെ അവന്റെ കൈകാലുകൾ മുഴുവനും മുറിക്കപ്പെട്ടു. പിന്നെ അഞ്ചാമതും അവൻ മോഷ്ടിച്ചു. അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: ഇവനെയും തുടർപ്രവർത്തനത്തെയും നന്നായറിഞ്ഞതിനാലാണ് നബി(സ) നേരത്തേ പറഞ്ഞത്: "അവനെ വധിച്ചുകളയുക." പിന്നെ അയാളെ വധിക്കാൻ വേണ്ടി ഖുറൈശി യുവാക്കളെ ഏൽപ്പിച്ചു. അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)വും അവരിലുണ്ടായിരുന്നു. അദ്ദേഹം നേതൃത്വത്തെ ഇഷ്ടപ്പെടുന്നവരായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾ എന്നെ നേതാവാക്കുക. അപ്പോൾ അവർ അദ്ദേഹത്തെ നേതാവാക്കി. അദ്ദേഹം അടിച്ചാൽ അവരെല്ലാവരും അടിക്കും, അങ്ങനെ ആ മോഷ്ടാവിനെ വധിച്ചു. (ന)', 'الْحَارِثِ بْنِ حَاطِبٍ', 'ഹാരിസുബിൻ ഹാത്വിബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 501, 502, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ بُسْرِ بْنِ أَبِي أَرْطَاةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تُقْطَعُ الْأَيْدِي فِي السَّفَرِ". (ن)', 'ബുസ്റുബ്നു അർത്വാത്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "യാത്രയിൽ കൈകൾ മുറിക്കപ്പെടരുത്." (ന)', 'بُسْرِ بْنِ أَبِي أَرْطَاةَ', 'ബുസ്റുബ്നു അർത്വാത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 502, 502, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا سَرَقَ الْعَبْدُ فَبِعْهُ، وَلَوْ بِنَشٍّ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നു: "അടിമ മോഷ്ടിച്ചാൽ നീ അവനെ ഉടനെ വിൽക്കുക, നശ്ശിന് (ഇരുപത് ദിർഹം) പകരമെങ്കിലും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 502, 502, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ صَفْوَانَ بْنِ أُمَيَّةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ عَمْرُو بْنُ مُرَّةَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ اللَّهَ قَدْ كَتَبَ عَلَيَّ الشِّقْوَةَ، فَمَا أُرَانِي أُرْزَقُ إِلَّا مِنْ دُفِّي بِكَفِّي، فَأْذَنْ لِي فِي الْغِنَاءِ فِي غَيْرِ فَاحِشَةٍ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا آذَنُ لَكَ، وَلَا كَرَامَةَ، وَلَا نُعْمَةَ عَيْنٍ. كَذَبْتَ، أَيْ عَدُوَّ اللَّهِ، لَقَدْ رَزَقَكَ اللَّهُ طَيِّبًا حَلَالًا، فَاخْتَرْتَ مَا حَرَّمَ اللَّهُ عَلَيْكَ مِنْ رِزْقِهِ مَكَانَ مَا أَحَلَّ اللَّهُ عَزَّ وَجَلَّ لَكَ مِنْ حَلَالِهِ، وَلَوْ كُنْتُ تَقَدَّمْتُ إِلَيْكَ لَفَعَلْتُ بِكَ وَفَعَلْتُ، قُمْ عَنِّي وَتُبْ إِلَى اللَّهِ. أَمَا إِنَّكَ إِنْ فَعَلْتَ - بَعْدَ التَّقْدِمَةِ إِلَيْكَ - ضَرَبْتُكَ ضَرْبًا وَجِيعًا، وَحَلَقْتُ رَأْسَكَ مُثْلَةً، وَنَفَيْتُكَ مِنْ أَهْلِكَ، وَأَحْلَلْتُ سَلَبَكَ نُهْبَةً لِفِتْيَانِ أَهْلِ الْمَدِينَةِ". فَقَامَ عَمْرٌو، وَبِهِ مِنَ الشَّرِّ وَالْخِزْيِ مَا لَا يَعْلَمُهُ إِلَّا اللَّهُ. فَلَمَّا وَلَّى قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَؤُلَاءِ الْعُصَاةُ، مَنْ مَاتَ مِنْهُمْ بِغَيْرِ تَوْبَةٍ حَشَرَهُ اللَّهُ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ كَمَا كَانَ فِي الدُّنْيَا: مُخَنَّثًا عُرْيَانًا، لَا يَسْتَتِرُ مِنَ النَّاسِ بِهُدْبَةٍ، كُلَّمَا قَامَ صُرِعَ". [في إسناده متروك] (جه)', 'സ്വഫ്വാനുബ്നു ഉമയ്യ(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ അടുത്തായിരുന്നപ്പോൾ അംറുബ്നു മുർറ വന്നു പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ വളരെ ബുദ്ധിമുട്ടിലാണ്, ദഫ് മുട്ടുകയല്ലാതെ എനിക്ക് മറ്റു വരുമാന മാർഗമില്ല എന്ന് ഞാൻ മനസ്സിലാക്കുന്നു. അതുകൊണ്ട് മോശമാകാതെ പാടാൻ എനിക്കനുവാദം തന്നാലും. റസൂൽ(സ) പറഞ്ഞു: "നിനക്ക് ഞാൻ സമ്മതമോ കറാമത്തോ അനുഗ്രഹത്തിന്റെ കാഴ്ചയോ സമ്മതമായി നൽകുകയില്ല. നീ കള്ളം പറഞ്ഞിരിക്കുന്നു. അല്ലാഹുവിന്റെ ശത്രുവേ, നിനക്കല്ലാഹു അനുവദനീയവും ഉത്തമവുമായതിനെ നൽകിയിട്ടുണ്ട്. പക്ഷേ, അനുവദനീയമായതിന്റെ സ്ഥാനത്ത് നിഷിദ്ധമാക്കിയതിനെ നീ തെരഞ്ഞെടുത്തു. ഞാനായിരുന്നു ആദ്യം നിന്നിലേക്ക് വന്നതെങ്കിൽ നിന്നെ ചെയ്യേണ്ടതെല്ലാം ചെയ്യുമായിരുന്നു. എണീറ്റ് അല്ലാഹുവിലേക്ക് തൗബ ചെയ്യുക, ഞാൻ നിന്റെയടുത്ത് വന്നതിന് ശേഷം നീ ഇത് ചെയ്യുകയാണെങ്കിൽ വളരെ വേദനാജനകമായ പ്രഹരം നിനക്ക് ഞാൻ നൽകും. നിന്റെ തല വെട്ടിക്കളയും, നിന്റെ കുടുംബത്തിൽ നിന്ന് ഓടിക്കുകയും നിന്റെ സാധനങ്ങൾ മദീനയിലെ യുവാക്കൾക്ക് യുദ്ധമുതലായി അനുവദനീയമാക്കപ്പെടുകയും ചെയ്യും." ശേഷം അല്ലാഹു മാത്രമറിയുന്ന നാശവും അപമാനവും നേടി അംറ് എഴുന്നേറ്റു. അദ്ദേഹം മടങ്ങിയപ്പോൾ നബി(സ) പറഞ്ഞു: "ഈ ദോഷികൾ, ഇവരിൽ ആരെങ്കിലും തൗബ ചെയ്യാതെ മരിച്ചാൽ അന്ത്യനാളിൽ പെൺകൂസനായി, വിവസ്ത്രനായി ഒരുമിച്ചുകൂട്ടപ്പെടും. ജനങ്ങളിൽ നിന്ന് കണ്ണിന്റെ ഒരു ഇമകൊണ്ടും മറക്കപ്പെടുകയില്ല. എഴുന്നേൽക്കുമ്പോഴെല്ലാം അവൻ വീണുപേകും." പരമ്പരയിൽ മത്റൂക് ഉണ്ട്. (ജ)', 'صَفْوَانَ بْنِ أُمَيَّةَ', 'സ്വഫ്വാനുബ്നു ഉമയ്യ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في إسناده متروك', null, 502, 503, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ، عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهُمْ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا، فَسَمِعَ مُخَنَّثًا وَهُوَ يَقُولُ لِعَبْدِ اللَّهِ بْنِ أَبِي أُمَيَّةَ: إِنْ يَفْتَحِ اللَّهُ الطَّائِفَ غَدًا دَلَلْتُكَ عَلَى امْرَأَةٍ: تُقْبِلُ بِأَرْبَعٍ وَتُدْبِرُ بِثَمَانٍ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَخْرِجُوهُمْ مِنْ بُيُوتِكُمْ". (جه)', 'ഉമ്മുസലമ(റ)യിൽ നിന്ന് സൈനബ് ബിൻത് ഉമ്മുസലമ(റ): നബി(സ) അവരുടെയടുക്കൽ ചെന്നപ്പോൾ ഒരു പെൺകൂസൻ അബ്ദുല്ലാഹിബ്നു അബീഉമയ്യയോട് പറയുന്നതായി നബി(സ) കേട്ടു: നാളെ അല്ലാഹു ത്വാഇഫിനെ കീഴടക്കിത്തന്നാൽ ഞാൻ ഒരു സ്ത്രീയെക്കുറിച്ച് പറഞ്ഞുതരാം. അവൾ വരുമ്പോൾ നാല് വരകളും പോകുമ്പോൾ എട്ട് വരകളുമുണ്ടാകും (അവളുടെ ശരീരം മാംസളമാകുന്നു). അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവരെ നിങ്ങളുടെ വീടുകളിൽ നിന്നും പുറത്താക്കുക." (ജ)', 'زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ، عَنْ أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 503, 503, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قَالَ الرَّجُلُ لِلرَّجُلِ: يَا يَهُودِيُّ، فَاضْرِبُوهُ عِشْرِينَ. وَإِذَا قَالَ: يَا مُخَنَّثُ، فَاضْرِبُوهُ عِشْرِينَ. وَمَنْ وَقَعَ عَلَى ذَاتِ مَحْرَمٍ فَاقْتُلُوهُ". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറയുന്നു: "ഒരാൾ മറ്റൊരാളെ, ഓ യഹൂദിയേ എന്ന് വിളിച്ചാൽ അവനെ ഇരുപത് അടി അടിക്കുക. പെൺകൂസൻ എന്ന് വിളിച്ചാൽ അവനെയും ഇരുപത് അടി അടിക്കുക. വിവാഹം നിഷിദ്ധമായവരുമായി ബന്ധപ്പെട്ടാൽ (വ്യഭിചരിച്ചാൽ) അവനെ വധിക്കുക." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 503, 503, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا زَنَتْ أَمَةُ أَحَدِكُمْ فَلْيَجْلِدْهَا - ثَلَاثًا - بِكِتَابِ اللَّهِ، فَإِنْ عَادَتْ فَلْيَبِعْهَا وَلَوْ بِحَبْلٍ مِنْ شَعَرٍ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "നിങ്ങളുടെ അടിമസ്ത്രീ മൂന്ന് പ്രാവശ്യം വ്യഭിചരിച്ചാൽ അല്ലാഹുവിന്റെ ഗ്രന്ഥമനുസരിച്ച് അവളെ മൂന്ന് പ്രാവശ്യവും അടിക്കുക. വീണ്ടും അവൾ ചെയ്താൽ അവളെ ഒരു മുടിനാരിനെങ്കിലും വിൽക്കുക." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 504, 504, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ قَالَ: خَطَبَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ فَقَالَ: يَا أَيُّهَا النَّاسُ، أَقِيمُوا الْحُدُودَ عَلَى أَرِقَّائِكُمْ، مَنْ أَحْصَنَ مِنْهُمْ وَمَنْ لَمْ يُحْصِنْ، وَإِنَّ أَمَةً لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَنَتْ فَأَمَرَنِي أَنْ أَجْلِدَهَا، فَأَتَيْتُهَا فَإِذَا هِيَ حَدِيثَةُ عَهْدٍ بِنِفَاسٍ، فَخَشِيتُ إِنْ أَنَا جَلَدْتُهَا أَنْ أَقْتُلَهَا، أَوْ قَالَ: تَمُوتَ، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ: "أَحْسَنْتَ". حَسَنٌ صَحِيحٌ. (م,د,ت)', 'അബൂഅബ്ദിർറഹ്മാനിസ്സുലമി(റ): അലി(റ) പ്രസംഗിക്കുന്നു: ഓ ജനങ്ങളേ, നിങ്ങളുടെ അടിമകളിൽ ശിക്ഷയെ നടപ്പാക്കുക, വിവാഹം കഴിഞ്ഞവരിലും അല്ലാത്തവരിലും. കാരണം നബി(സ)യുടെ ഒരു അടിമസ്ത്രീ വ്യഭിചരിച്ചപ്പോൾ റസൂൽ(സ) എന്നോട് അവളെ അടിക്കാൻ ആജ്ഞാപിച്ചു. ഞാൻ അവിടെ ചെന്നപ്പോൾ അവൾക്ക് നിഫാസായിരുന്നു. അപ്പോൾ ഞാൻ ഭയന്നു, എന്റെ അടിയാൽ അവൾ വധിക്കപ്പെടുമോ, അല്ലെങ്കിൽ മരിക്കുമോ എന്ന്. അങ്ങനെ ഞാൻ റസൂൽ(സ)യുടെ സന്നിധിയിൽ ചെന്ന് കാര്യം പറഞ്ഞു: അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നീ നന്മ ചെയ്തിരിക്കുന്നു." (മു,ദ,തു)', 'أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ قَالَ', 'അബൂഅബ്ദിർറഹ്മാനിസ്സുലമി(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 504, 504, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَبِي هُرَيْرَةَ وَزَيْدِ بْنِ خَالِدٍ - رَضِيَ اللهُ عَنْهُمَا - قَالَا: كُنَّا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَهُ رَجُلٌ عَنِ الْأَمَةِ تَزْنِي قَبْلَ أَنْ تُحْصَنَ؟ فَقَالَ: "اجْلِدْهَا، فَإِنْ زَنَتْ فَاجْلِدْهَا". ثُمَّ قَالَ، فِي الثَّالِثَةِ أَوْ فِي الرَّابِعَةِ: "فَبِعْهَا وَلَوْ بِحَبْلٍ مِنْ شَعَرٍ". (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ), സൈദുബ്നു ഖാലിദ്(റ): ഞങ്ങൾ നബി(സ)യുടെ കൂടെ തിരുസന്നിധിയിലിരിക്കുമ്പോൾ ഒരാൾ വിവാഹം കഴിക്കാത്ത അടിമസ്ത്രീ വ്യഭിചരിക്കുന്നതിനെക്കുറിച്ച് ചോദിച്ചു. തിരുമേനി(സ) പറഞ്ഞു: "അവളെ അടിക്കുക, അവൾ വ്യഭിചരിച്ചാൽ അവളെ അടിക്കുക." പിന്നെ മൂന്നാമതോ നാലാമതോ ആയി അവിടന്ന് പറഞ്ഞു: "ഒരു മുടിനാരിനെങ്കിലും അവളെ വിൽക്കുക." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ وَزَيْدِ بْنِ خَالِدٍ -', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 504, 504, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا زَنَتِ الْأَمَةُ فَاجْلِدُوهَا، فَإِنْ زَنَتْ فَاجْلِدُوهَا، فَإِنْ زَنَتْ فَاجْلِدُوهَا، ثُمَّ بِيعُوهَا وَلَوْ بِضَفِيرٍ وَالضَّفِيرُ". [في إسناده مختلف فيه] (جه)', 'ആഇശ(റ): റസൂൽ(സ) പറയുന്നു: "അടിമസ്ത്രീ വ്യഭിചരിച്ചാൽ അവളെ അടിക്കുക, അവൾ വ്യഭിചരിച്ചാൽ അവളെ അടിക്കുക, അവൾ വ്യഭിചരിച്ചാൽ അവളെ അടിക്കുക, അവൾ വ്യഭിചരിച്ചാൽ അവളെ അടിക്കുക, പിന്നെ അവളെ ഒരു നാരിനെങ്കിലും വിൽക്കുക." പരമ്പരയിൽ സംശയിക്കപ്പെടുന്നയാളുണ്ട്. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في إسناده مختلف فيه', null, 504, 504, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ صَفْوَانَ بْنِ أُمَيَّةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ طَافَ بِالْبَيْتِ وَصَلَّى، ثُمَّ لَفَّ رِدَاءً لَهُ مِنْ بُرْدٍ فَوَضَعَهُ تَحْتَ رَأْسِهِ فَنَامَ، فَأَتَاهُ لِصٌّ فَاسْتَلَّهُ مِنْ تَحْتِ رَأْسِهِ فَأَخَذَهُ، فَأَتَى بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ هَذَا سَرَقَ رِدَائِي. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَسَرَقْتَ رِدَاءَ هَذَا". قَالَ: نَعَمْ. قَالَ: "اذْهَبَا بِهِ فَاقْطَعَا يَدَهُ". قَالَ صَفْوَانُ: مَا كُنْتُ أُرِيدُ أَنْ تُقْطَعَ يَدُهُ فِي رِدَائِي. فَقَالَ لَهُ: "فَلَوْ مَا قَبْلَ هَذَا". (ن)', 'സ്വഫ്വാനുബ്നു ഉമയ്യ(റ): അദ്ദേഹം കഅ്ബ ത്വവാഫ് ചെയ്ത്, നിസ്കരിച്ച ശേഷം തണുപ്പ് സമയത്ത് ഉപയോഗിച്ച തന്റെ ഷാൾ ചുരുട്ടി തലക്ക് വെച്ച് ഉറങ്ങി. അങ്ങനെ ഒരു കള്ളൻ വന്ന് മെല്ലെ ഷാൾ ഊരിയെടുത്തു. ഉടനെ അയാളെ പിടികൂടുകയും നബി(സ)യുടെ അടുത്തേക്ക് കൊണ്ടുവരികയും ചെയ്തു. എന്നിട്ട് അദ്ദേഹം പറഞ്ഞു: ഇവൻ എന്റെ ഷാൾ മോഷ്ടിച്ചിരിക്കുന്നു. അപ്പോൾ അയാളോട് നബി(സ) ചോദിച്ചു: "ഇദ്ദേഹത്തിന്റെ ഷാൾ നീ മോഷ്ടിച്ചിട്ടുണ്ടോ?" അയാൾ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "അവനെ കൊണ്ടുപോയി അവന്റെ കൈ മുറിക്കുക." സ്വഫ്വാൻ(റ) പറഞ്ഞു: എന്റെ ഷാൾ കാരണം അവന്റെ കൈ മുറിക്കപ്പെടണമെന്ന് ഞാൻ ആഗ്രഹിച്ചിരുന്നില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇതിന്റെ മുമ്പ് ആക്കാമായിരുന്നില്ലേ ഇത്." (ന)', 'صَفْوَانَ بْنِ أُمَيَّةَ', 'സ്വഫ്വാനുബ്നു ഉമയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 505, 505, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ صَفْوَانَ بْنِ أُمَيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ نَائِمًا فِي الْمَسْجِدِ عَلَى خَمِيصَةٍ لِي ثَمَنُهَا ثَلَاثُونَ دِرْهَمًا، فَجَاءَ رَجُلٌ فَاخْتَلَسَهَا مِنِّي، فَأُخِذَ الرَّجُلُ فَأُتِيَ بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ بِهِ لِيُقْطَعَ، فَأَتَيْتُهُ فَقُلْتُ: أَتَقْطَعُهُ مِنْ أَجْلِ ثَلَاثِينَ دِرْهَمًا، أَنَا أَبِيعُهُ وَأُنْسِئُهُ ثَمَنَهَا. قَالَ: "فَهَلَّا كَانَ هَذَا قَبْلَ أَنْ تَأْتِيَنِي بِهِ". (ن)', 'സ്വഫ്വാനുബ്നു ഉമയ്യ(റ): മുപ്പത് ദിർഹം വിലയുള്ള എന്റെ ഒരു കറുത്ത വിരിപ്പ് വിരിച്ച് ഞാൻ പള്ളിയിൽ കിടന്നുറങ്ങുകയായിരുന്നു. അപ്പോൾ ഒരാൾ വന്ന് പതുക്കെ അത് പൊക്കിയെടുത്തു. ഉടൻതന്നെ അയാൾ പിടിക്കപ്പെടുകയും നബി(സ)യുടെയടുത്തേക്ക് കൊണ്ടുവരപ്പെടുകയും ചെയ്തു. അയാളുടെ കൈ മുറിക്കാൻ നബി(സ) കൽപിച്ചു. അപ്പോൾ ഞാൻ റസൂൽ(സ)യുടെയടുത്ത് ചെന്ന് പറഞ്ഞു: മുപ്പത് ദിർഹമുകളുടെ പേരിലാണോ അവിടുന്ന് അവന്റെ കൈ മുറിക്കുന്നത്. ഞാൻ അത് അവന് വിൽക്കുകയും അതിന്റെ വില പിന്തിപ്പിച്ചുകൊടുക്കുകയും ചെയ്യുന്നു. നബി(സ) ചോദിച്ചു: "അവനെ എന്റെ അടുക്കൽ കൊണ്ടുവരുംമുമ്പ് അത് ചെയ്യാമായിരുന്നില്ലേ?" (ദ,ന,ജ)', 'صَفْوَانَ بْنِ أُمَيَّةَ', 'സ്വഫ്വാനുബ്നു ഉമയ്യ(റ)', null, null, array['ن']::text[], array['ദ','ന','ജ']::text[], null, null, 505, 505, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تَعَافَوُا الْحُدُودَ قَبْلَ أَنْ تَأْتُونِي بِهِ، فَمَا أَتَانِي مِنْ حَدٍّ فَقَدْ وَجَبَ". وَفِي رِوَايَةٍ: "تَعَافَوُا الْحُدُودَ فِيمَا بَيْنَكُمْ، فَمَا بَلَغَنِي مِنْ حَدٍّ فَقَدْ وَجَبَ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "എന്റെയടുത്ത് എത്തുന്നതിന് മുമ്പ് തന്നെ നിങ്ങൾ ശിക്ഷകൾ മാപ്പ് ചെയ്യുക, എന്റെയടുത്ത് വന്നാൽ അത് നിർബന്ധമായി." മറ്റൊരു റിപ്പോർട്ടിൽ: "ശിക്ഷകൾ നിങ്ങൾക്ക് മുമ്പിൽ തന്നെ പൊറുക്കുക. എന്റെയടുത്ത് വല്ല തെറ്റും വന്നാൽ ശിക്ഷ നിർബന്ധമായി." (ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 505, 505, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=153), 1, 'وَفِي رِوَايَةٍ: "تَعَافَوُا الْحُدُودَ فِيمَا بَيْنَكُمْ، فَمَا بَلَغَنِي مِنْ حَدٍّ فَقَدْ وَجَبَ". (ن)', 'മറ്റൊരു നിവേദനിൽ: "ശിക്ഷകൾ നിങ്ങൾക്ക് മുമ്പിൽ തന്നെ പൊറുക്കുക. എന്റെയടുത്ത് വല്ല തെറ്റും വന്നാൽ ശിക്ഷ നിർബന്ധമായി." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً مَخْزُومِيَّةً كَانَتْ تَسْتَعِيرُ الْمَتَاعَ - وَفِي رِوَايَةٍ: عَلَى أَلْسِنَةِ جَارَاتِهَا - فَتَجْحَدُهُ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَطْعِ يَدِهَا. (ن)', 'ഇബ്നുഉമർ(റ): ഒരു മഖ്സൂമി വനിത ചരക്കുകൾ വായ്പ വാങ്ങുകയും - മറ്റൊരു റിപ്പോർട്ടിൽ: അയൽപക്കക്കാരികളുടെ നാവിലൂടെ - ശേഷം അവൾ അതിനെ നിഷേധിക്കുകയും ചെയ്യും. അപ്പോൾ നബി(സ) അവളുടെ കൈ മുറിക്കാൻ ആജ്ഞാപിച്ചു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 505, 505, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=154), 1, 'وَفِي رِوَايَةٍ: عَلَى أَلْسِنَةِ جَارَاتِهَا - فَتَجْحَدُهُ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَطْعِ يَدِهَا. (ن)', 'മറ്റൊരു നിവേദനിൽ: അയൽപക്കക്കാരികളുടെ നാവിലൂടെ - ശേഷം അവൾ അതിനെ നിഷേധിക്കുകയും ചെയ്യും. അപ്പോൾ നബി(സ) അവളുടെ കൈ മുറിക്കാൻ ആജ്ഞാപിച്ചു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً كَانَتْ تَسْتَعِيرُ الْحُلِيَّ لِلنَّاسِ ثُمَّ تُمْسِكُهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لِتَتُبْ هَذِهِ الْمَرْأَةُ إِلَى اللَّهِ وَرَسُولِهِ، وَتَرُدَّ مَا تَأْخُذُ عَلَى الْقَوْمِ". ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قُمْ يَا بِلَالُ فَخُذْ بِيَدِهَا فَاقْطَعْهَا". وَفِي رِوَايَةٍ: "لِتَتُبْ هَذِهِ الْمَرْأَةُ وَتُؤَدِّي مَا عِنْدَهَا" مِرَارًا، فَلَمْ تَفْعَلْ، فَأَمَرَ بِهَا فَقُطِعَتْ. (ن)', 'ഇബ്നുഉമർ(റ): ജനങ്ങളുടെ ആഭരണങ്ങൾ വായ്പ വാങ്ങുകയും ശേഷം അത് പിടിച്ചുവെക്കുകയും ചെയ്യുന്ന ഒരു സത്രീയുണ്ടായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഈ സ്ത്രീ അല്ലാഹുവിലേക്കും അവന്റെ റസൂലിലേക്കും തൗബ ചെയ്യട്ടെ, സമൂഹത്തിൽ നിന്ന് അവളെടുത്തത് തിരിച്ച് കൊടുക്കുകയും ചെയ്യട്ടെ." പിന്നെ റസൂൽ(സ) പറഞ്ഞു: "എഴുന്നേൽക്കുക ബിലാൽ, അവളുടെ കൈ മുറിക്കുക." മറ്റൊരു നിവേദനത്തിൽ: "ഇവൾ തൗബ ചെയ്യട്ടെ, അവളുടെ പക്കലുള്ളത് കൊടുക്കുകയും ചെയ്യട്ടെ." പലപ്രാവശ്യം ഇങ്ങനെ പറഞ്ഞെങ്കിലും അവൾ ചെയ്തില്ല, അപ്പോൾ മുറിക്കാൻ കൽപിക്കുകയും മുറിക്കപ്പെടുകയും ചെയ്തു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 505, 506, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=155), 1, 'وَفِي رِوَايَةٍ: "لِتَتُبْ هَذِهِ الْمَرْأَةُ وَتُؤَدِّي مَا عِنْدَهَا" مِرَارًا، فَلَمْ تَفْعَلْ، فَأَمَرَ بِهَا فَقُطِعَتْ. (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: "ഇവൾ തൗബ ചെയ്യട്ടെ, അവളുടെ പക്കലുള്ളത് കൊടുക്കുകയും ചെയ്യട്ടെ." പലപ്രാവശ്യം ഇങ്ങനെ പറഞ്ഞെങ്കിലും അവൾ ചെയ്തില്ല, അപ്പോൾ മുറിക്കാൻ കൽപിക്കുകയും മുറിക്കപ്പെടുകയും ചെയ്തു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ امْرَأَةً مِنْ بَنِي مَخْزُومٍ سَرَقَتْ، فَأُتِيَ بِهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَعَاذَتْ بِأُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْ كَانَتْ فَاطِمَةَ بِنْتَ مُحَمَّدٍ لَقَطَعْتُ يَدَهَا". فَقُطِعَتْ يَدُهَا. (ن)', 'ജാബിർ(റ): ബനൂമഖ്സൂമിൽപ്പെട്ട ഒരു സ്ത്രീ മോഷ്ടിച്ചു. അവളെ റസൂൽ(സ)യുടെ തിരുസന്നിധിയിൽ കൊണ്ടുവന്നു. അപ്പോൾ അവൾ ഉമ്മുസലമ(റ)യുടെയടുത്ത് അഭയം തേടി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "മുഹമ്മദിന്റെ മകൾ ഫാത്വിമ കട്ടാലും അവളുടെ കൈ ഞാൻ മുറിക്കും." ശേഷം അവളുടെ കൈ മുറിക്കപ്പെട്ടു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 506, 506, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ صَفْوَانَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ نَامَ فِي الْمَسْجِدِ وَتَوَسَّدَ رِدَاءَهُ، فَأُخِذَ مِنْ تَحْتِ رَأْسِهِ، فَجَاءَ بِسَارِقِهِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقْطَعَ. فَقَالَ صَفْوَانُ: يَا رَسُولَ اللَّهِ، لَمْ أُرِدْ هَذَا، رِدَائِي عَلَيْهِ صَدَقَةٌ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَهَلَّا قَبْلَ أَنْ تَأْتِيَنِي بِهِ". (د,ن,جه)', 'സ്വഫ്വാൻ(റ): അദ്ദേഹം പള്ളിയിൽ കിടന്നുറങ്ങുകയും തന്റെ ഷാൾ തലയിണയായി വെക്കുകയും ചെയ്തു. അങ്ങനെ തന്റെ തലയുടെ താഴെ നിന്നും ഷാൾ മോഷ്ടിക്കപ്പെട്ടു. ശേഷം അദ്ദേഹം മോഷ്ടാവിനെ നബി(സ)യുടെ അടുത്ത് കൊണ്ടുവന്നു. നബി(സ) അവന്റെ കൈ മുറിക്കാൻ കൽപിച്ചു. അപ്പോൾ സ്വഫ്വാൻ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ ഇത്രയൊന്നും ഉദ്ദേശിച്ചിട്ടില്ല. എന്റെ ഷാൾ ഞാനവന് ദാനം ചെയ്തിരിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "അവനെ എന്റെയടുത്ത് കൊണ്ടുവരും മുമ്പ് അത് ചെയ്തുകൂടായിരുന്നില്ലേ." (ദ,ന,ജ)', 'صَفْوَانَ', 'സ്വഫ്വാൻ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 506, 506, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا مِنْ مُزَيْنَةَ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الثِّمَارِ، فَقَالَ: "مَا أُخِذَ فِي أَكْمَامِهِ فَاحْتُمِلَ، فَثَمَنُهُ وَمِثْلُهُ مَعَهُ. وَمَا كَانَ مِنَ الْجَرِينِ فَفِيهِ الْقَطْعُ إِذَا بَلَغَ ثَمَنَ الْمِجَنِّ. وَإِنْ أَكَلَ وَلَمْ يَأْخُذْ فَلَيْسَ عَلَيْهِ". قَالَ: الشَّاةُ الْحَرِيسَةُ مِنْهُنَّ يَا رَسُولَ اللَّهِ؟ قَالَ: "ثَمَنُهَا وَمِثْلُهُ مَعَهُ وَالنَّكَالُ. وَمَا كَانَ فِي الْمُرَاحِ فَفِيهِ الْقَطْعُ، إِذَا كَانَ مَا يَأْخُذُ مِنْ ذَلِكَ ثَمَنَ الْمِجَنِّ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): മുസൈന ഗോത്രത്തിൽപ്പെട്ട ഒരു വ്യക്തി നബി(സ)യോട് പഴങ്ങളെക്കുറിച്ച ചോദിച്ചു. അവിടന്ന് പറഞ്ഞു: "ഫലം അതിന്റെ പാളയിൽ നിന്ന് എടുത്ത് കൊണ്ടുപോയവൻ അതിന്റെ വിലയും അതുപോലോത്തതൊന്നും അവന്റെ മേൽ നിർബന്ധമാണ്. ഉണക്കാൻ വെച്ചതിൽ നിന്നും ഒരു പരിചയുടെ വിലയോളമുള്ളത് എടുത്താൽ കൈ മുറിക്കപ്പെടണം. എടുത്തു, പക്ഷേ കഴിച്ചിട്ടില്ല എങ്കിൽ അവന്റെ കൈ മുറിക്കപ്പെടുകയുമില്ല." അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, മേയാൻ വിട്ട ആടുകൾ അതിൽ പെടുമോ? അവിടന്ന് പറഞ്ഞു: "അതിന്റെ വിലയും അതുപോലെയുള്ള മറ്റൊന്നും കൂടെ ശിക്ഷയും. കുട്ടിയുള്ള ആടിനെയാണെങ്കിൽ മുറിക്കപ്പെടും, അത് പരിചയുടെ വിലയുള്ളതാണെങ്കിൽ." (ദ,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 506, 507, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ أَبِي بُرْدَةَ بْنِ نِيَارٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يُجْلَدُ فَوْقَ عَشْرِ جَلَدَاتٍ إِلَّا فِي حَدٍّ مِنْ حُدُودِ اللَّهِ". حَسَنٌ. (ت)', 'അബൂബുർദബിൻ നിയാർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ ശിക്ഷകളിലല്ലാതെ പത്ത് അടിയേക്കാൾ അടിക്കുക." (തു)', 'أَبِي بُرْدَةَ بْنِ نِيَارٍ', 'അബൂബുർദബിൻ നിയാർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 507, 507, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُعَزِّرُوا فَوْقَ عَشَرَةِ أَسْوَاطٍ". فِي إِسْنَادِهِ مَتْرُوكٌ. (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പത്ത് ചാട്ടവാറടിയേക്കാൾ നിങ്ങൾ ശിക്ഷിക്കരുത്." പരമ്പരയിൽ മത്റൂക് ഉണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 507, 507, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ أُنَاسًا مِنْ عُرَيْنَةَ قَدِمُوا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاجْتَوَوُا الْمَدِينَةَ، فَقَالَ: "لَوْ خَرَجْتُمْ إِلَى ذَوْدٍ لَنَا، فَشَرِبْتُمْ مِنْ أَلْبَانِهَا وَأَبْوَالِهَا". فَفَعَلُوا، فَارْتَدُّوا عَنِ الْإِسْلَامِ، وَقَتَلُوا رَاعِيَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاسْتَاقُوا ذَوْدَهُ، فَبَعَثَ رَسُولُ اللَّهِ فِي طَلَبِهِمْ فَجِيءَ بِهِمْ، فَقَطَعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ، وَسَمَرَ أَعْيُنَهُمْ، وَتَرَكَهُمْ بِالْحَرَّةِ حَتَّى مَاتُوا. (ق,جه)', 'അനസുബ്നു മാലിക്(റ): ഉറൈന ഗോത്രത്തിൽപ്പെട്ട ചിലയാളുകൾ നബി(സ)യുടെ കാലത്ത് മദീനയിൽ വന്നു. അവർക്ക് മദീനയുടെ അന്തരീക്ഷം പിടിച്ചില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നമ്മുടെ ഒട്ടകങ്ങളുടെയടുത്ത് പോകുക. അവയുടെ പാലും മൂത്രവും കുടിക്കുക." അവർ അങ്ങനെ ചെയ്തു. പക്ഷേ, അവർ ഇസ്‌ലാമിനെ ഉപേക്ഷിക്കുകയും റസൂൽ(സ) കൊടുത്ത ഇടയനെ വധിച്ചുകളയുകയും ഒട്ടകങ്ങളെ കൊണ്ടുപോവുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) അവരെ അന്വേഷിച്ച് ആളെ പറഞ്ഞയക്കുകയും അവരെ കൊണ്ടുവരികയും ചെയ്തു. ഉടനെ അവരുടെ കൈകാലുകൾ മുറിക്കപ്പെടുകയും കണ്ണുകൾ ചൂടുള്ള ആണി കൊണ്ട് കുത്തിപ്പൊട്ടിക്കപ്പെടുകയും ചൂടുള്ള മണലിൽ അവരെ ഉപേക്ഷിക്കപ്പെടുകയും ചെയ്തു. അങ്ങനെ അവർ മരിച്ചു. (ബു,മു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 507, 507, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا : أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ: عَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ، وَعَنِ الْمُبْتَلَى حَتَّى يَبْرَأَ، وَعَنِ الصَّبِيِّ حَتَّى يَكْبُرَ". (د,جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് കാര്യങ്ങളെത്തൊട്ട് പേന ഉയർത്തപ്പെട്ടിരിക്കുന്നു: ഉറങ്ങിയവൻ എഴുന്നേൽക്കുന്നത് വരെയും, പരീക്ഷണവിധേയൻ സുഖം പ്രാപിക്കുന്നത് വരേയും, കുട്ടി വലുതാകുന്നത് വരേയും." (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 507, 508, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أُتِيَ عُمَرُ بِمَجْنُونَةٍ قَدْ زَنَتْ، فَاسْتَشَارَ فِيهَا أُنَاسًا، فَأَمَرَ بِهَا عُمَرُ أَنْ تُرْجَمَ، مُرَّ بِهَا عَلَى عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ ،قَالَ: مَا شَأْنُ هَذِهِ؟ قَالُوا: مَجْنُونَةُ بَنِي فُلَانٍ زَنَتْ، فَأَمَرَ بِهَا عُمَرُ أَنْ تُرْجَمَ. فَقَالَ: ارْجِعُوا بِهَا، ثُمَّ أَتَاهُ فَقَالَ: يَا أَمِيرَ الْمُؤْمِنِينَ، أَمَا عَلِمْتَ أَنَّ الْقَلَمَ قَدْ رُفِعَ عَنْ ثَلَاثَةٍ: عَنِ الْمَجْنُونِ حَتَّى يَبْرَأَ، وَعَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ، وَعَنِ الصَّبِيِّ حَتَّى يَعْقِلَ؟ قَالَ: بَلَى، قَالَ: فَمَا بَالُ هَذِهِ تُرْجَمُ؟ قَالَ: لَا شَيْءَ، قَالَ: فَأَرْسِلْهَا، قَالَ: فَأَرْسَلَهَا، قَالَ: فَجَعَلَ يُكَبِّرُ. وَفِي رِوَايَةٍ: عَنِ الْمَجْنُونِ حَتَّى يُفِيقَ. وَفِي رِوَايَةٍ: قَالَ: أَوَ مَا تَذْكُرُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ: عَنِ الْمَجْنُونِ الْمَغْلُوبِ عَلَى عَقْلِهِ حَتَّى يُفِيقَ، وَعَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ، وَعَنِ الصَّبِيِّ حَتَّى يَحْتَلِمَ"؟ قَالَ: صَدَقْتَ قَالَ: فَخَلَّى عَنْهَا. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): വ്യഭിചരിച്ച ഒരു ഭ്രാന്തസ്ത്രീയെ ഉമർ(റ)വിന്റെ അടുക്കൽ കൊണ്ടുവന്നു. അദ്ദേഹം കുറച്ചാളുകളെ വിളിച്ച് ചർച്ച ചെയ്ത് അവളെ എറിയാൻ കൽപിച്ചു. അങ്ങനെ അവളെ അലി(റ)വിന്റെ അടുത്തുകൂടെ കൊണ്ടുപോകാനിടയായി. അദ്ദേഹം ചോദിച്ചു: ഇവൾക്കെന്താണ്? അവർ പറഞ്ഞു: ഇന്നവന്റെ ഭ്രാന്തുള്ള മകളാണ് അവൾ. അവൾ വ്യഭിചരിച്ചു. ഉമർ(റ) അവളെ എറിഞ്ഞുകൊല്ലാൻ കൽപിച്ചിരിക്കുന്നു. അലി(റ) പറഞ്ഞു: ഇവളെ നിങ്ങൾ തിരിച്ചുകൊണ്ടുപോവുക. ശേഷം ഉമർ(റ)വിന്റെയടുക്കൽ വന്ന് അദ്ദേഹം പറഞ്ഞു: അമീറുൽ മുഅ്മിനീൻ, നിങ്ങൾക്കറിയില്ലേ, മൂന്ന് കാര്യങ്ങളിൽ പേന ഉയർത്തപ്പെട്ടിട്ടുണ്ടെന്നത്: ഭ്രാന്തൻ അവന്റെ ഭ്രാന്ത് മാറുന്നത് വരേയും, ഉറങ്ങുന്നവൻ എഴുന്നേൽക്കുന്നത് വരേയും, കുട്ടി ബുദ്ധിവെക്കുന്നത് വരേയും? ഉമർ(റ) പറഞ്ഞു: അതെ. അലി(റ) ചോദിച്ചു: പിന്നെ എന്താണ് ഇവളെ എറിയുന്നതിന്റെ ഉദ്ദേശ്യം? ഉമർ(റ): ഒന്നുമില്ല. അലി(റ) പറഞ്ഞു: എങ്കിൽ അവളെ വിട്ടയക്കുക. നിവേദകൻ പറയുന്നു: അപ്പോൾ ഉമർ(റ) അവളെ വിട്ടയച്ചു. ശേഷം ഉമർ(റ) തക്ബീർ ചൊല്ലി തുടങ്ങി. മറ്റൊരു റിപ്പോർട്ടിൽ: ഭ്രാന്തൻ ബോധം തെളിയുന്നത് വരേയും (അറബിയിൽ വ്യത്യാസം). മറ്റൊരു റിപ്പോർട്ടിൽ: അലി(റ) ചോദിച്ചു: "മൂന്ന് കാര്യങ്ങളിൽ നിന്ന് പേന ഉയർത്തപ്പെട്ടിരിക്കുന്നു: ബുദ്ധി മറിഞ്ഞ ഭ്രാന്തൻ ബോധം തെളിയുന്നത് വരെ, ഉറങ്ങുന്നവൻ ഉണരുന്നത് വരെ, കുട്ടി സ്വപ്ന സ്ഖലനം ഉണ്ടാകുന്നത് വരെ" എന്ന് റസൂൽ(സ) പറഞ്ഞത് നിങ്ങൾ ഓർക്കുന്നുണ്ടോ? ഉമർ(റ) പറഞ്ഞു: താങ്കൾ സത്യം പറഞ്ഞിരിക്കുന്നു. നിവേദകൻ പറയുന്നു: അങ്ങനെ അവളെ വെറുതെവിട്ടു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 508, 508, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=163), 1, 'وَفِي رِوَايَةٍ: عَنِ الْمَجْنُونِ حَتَّى يُفِيقَ.', 'മറ്റൊരു നിവേദനിൽ: ഭ്രാന്തൻ ബോധം തെളിയുന്നത് വരേയും (അറബിയിൽ വ്യത്യാസം).');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=163), 2, 'وَفِي رِوَايَةٍ: قَالَ: أَوَ مَا تَذْكُرُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ: عَنِ الْمَجْنُونِ الْمَغْلُوبِ عَلَى عَقْلِهِ حَتَّى يُفِيقَ، وَعَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ، وَعَنِ الصَّبِيِّ حَتَّى يَحْتَلِمَ"؟ قَالَ: صَدَقْتَ قَالَ: فَخَلَّى عَنْهَا. (د)', 'മറ്റൊരു നിവേദനിൽ: അലി(റ) ചോദിച്ചു: "മൂന്ന് കാര്യങ്ങളിൽ നിന്ന് പേന ഉയർത്തപ്പെട്ടിരിക്കുന്നു: ബുദ്ധി മറിഞ്ഞ ഭ്രാന്തൻ ബോധം തെളിയുന്നത് വരെ, ഉറങ്ങുന്നവൻ ഉണരുന്നത് വരെ, കുട്ടി സ്വപ്ന സ്ഖലനം ഉണ്ടാകുന്നത് വരെ" എന്ന് റസൂൽ(സ) പറഞ്ഞത് നിങ്ങൾ ഓർക്കുന്നുണ്ടോ? ഉമർ(റ) പറഞ്ഞു: താങ്കൾ സത്യം പറഞ്ഞിരിക്കുന്നു. നിവേദകൻ പറയുന്നു: അങ്ങനെ അവളെ വെറുതെവിട്ടു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ امْرَأَةً سَرَقَتْ، فَأُتِيَ بِهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: مَنْ يَجْتَرِئُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا أَنْ يَكُونَ أُسَامَةَ؟ فَكَلَّمُوا أُسَامَةَ فَكَلَّمَهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أُسَامَةُ، إِنَّمَا هَلَكَتْ بَنُو إِسْرَائِيلَ حِينَ كَانُوا: إِذَا أَصَابَ الشَّرِيفُ فِيهِمُ الْحَدَّ تَرَكُوهُ وَلَمْ يُقِيمُوا عَلَيْهِ، وَإِذَا أَصَابَ الْوَضِيعُ أَقَامُوا عَلَيْهِ. لَوْ كَانَتْ فَاطِمَةُ بِنْتَ مُحَمَّدٍ لَقَطَعْتُهَا". وَفِي رِوَايَةٍ: كَانَتْ مَخْزُومِيَّةٌ: تَسْتَعِيرُ مَتَاعًا وَتَجْحَدُهُ، فَرُفِعَتْ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَكُلِّمَ فِيهَا، فَقَالَ: "لَوْ كَانَتْ فَاطِمَةُ لَقَطَعْتُ يَدَهَا". (ن)', 'ആഇശ(റ): ഒരു സ്ത്രീ മോഷ്ടിച്ചു. നബി(സ)യുടെ തിരുസന്നിധിയിൽ കൊണ്ടുവന്നു. അവർ പറഞ്ഞു: ഉസാമ(റ)വല്ലാതെ ആരുണ്ട് നബി(സ)യോട് ധൈര്യപ്പെട്ട് ഈ വിഷയം പറയാനുള്ളത്! അങ്ങനെ അവർ ഉസാമ(റ)വിനോട് കാര്യം സംസാരിച്ചു. അദ്ദേഹം നബി(സ)യോട് സംസാരിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഉസാമ, ബനൂഇസ്റാഈൽ സമുദായം നശിച്ചത്, അവരിലെ മാന്യന്മാർ തെറ്റ് ചെയ്ത് ശിക്ഷ വിധിക്കപ്പെട്ടാൽ അവന്റെ മേൽ അത് നടപ്പിലാക്കാതിരിക്കുകയും താഴ്ന്നവൻ തെറ്റ് ചെയ്ത് ശിക്ഷ വിധിക്കപ്പെട്ടാൽ അത് നടപ്പാക്കുകയും ചെയ്തതിനാലായിരുന്നു. മുഹമ്മദിന്റെ മകൾ ഫാത്വിമ കട്ടാലും അവളുടെ കൈ ഞാൻ മുറിക്കും." മറ്റൊരു റിപ്പോർട്ടിൽ: സാധനങ്ങൾ വായ്പ കൊടുക്കുകയും ശേഷം അതിനെ നിഷേധിക്കുകയും ചെയ്യുമായിരുന്ന ഒരു മഖ്സൂമി വനിതയെ നബി(സ)യുടെ തിരുസന്നിധിയിൽ കൊണ്ടുവന്നു. അവളുടെ വിഷയത്തിൽ ആരോ നബി(സ)യോട് സംസാരിച്ചു. അപ്പോൾ നബി(സ)പറഞ്ഞു: "മുഹമ്മദിന്റെ മകൾ ഫാത്വിമയാണെങ്കിലും അവളുടെ കൈ ഞാൻ മുറിക്കും." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 508, 509, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=164), 1, 'وَفِي رِوَايَةٍ: كَانَتْ مَخْزُومِيَّةٌ: تَسْتَعِيرُ مَتَاعًا وَتَجْحَدُهُ، فَرُفِعَتْ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَكُلِّمَ فِيهَا، فَقَالَ: "لَوْ كَانَتْ فَاطِمَةُ لَقَطَعْتُ يَدَهَا". (ن)', 'മറ്റൊരു നിവേദനിൽ: സാധനങ്ങൾ വായ്പ കൊടുക്കുകയും ശേഷം അതിനെ നിഷേധിക്കുകയും ചെയ്യുമായിരുന്ന ഒരു മഖ്സൂമി വനിതയെ നബി(സ)യുടെ തിരുസന്നിധിയിൽ കൊണ്ടുവന്നു. അവളുടെ വിഷയത്തിൽ ആരോ നബി(സ)യോട് സംസാരിച്ചു. അപ്പോൾ നബി(സ)പറഞ്ഞു: "മുഹമ്മദിന്റെ മകൾ ഫാത്വിമയാണെങ്കിലും അവളുടെ കൈ ഞാൻ മുറിക്കും." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَارِقٍ فَقَطَعَهُ، قَالُوا: مَا كُنَّا نُرِيدُ أَنْ يَبْلُغَ مِنْهُ هَذَا. قَالَ: "لَوْ كَانَتْ فَاطِمَةَ لَقَطَعْتُهَا". (ن)', 'ആഇശ(റ): നബി(സ)യുടെ അടുത്തേക്ക് ഒരു മോഷ്ടാവിനെ കൊണ്ടുവന്നു. അപ്പോൾ അവന്റെ കൈ മുറിക്കപ്പെട്ടു. അവർ പറഞ്ഞു: ഈ വിഷയത്തിൽ കൈ മുറിക്കപ്പെടുമെന്ന് ഞങ്ങൾ ഉദ്ദേശിച്ചിരുന്നില്ല. തിരുമേനി(സ) പറഞ്ഞു: "അത് ഫാത്വിമയായിരുന്നെങ്കിൽ അവളുടെ കൈ ഞാൻ മുറിക്കുമായിരുന്നു." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 509, 509, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: اسْتَعَارَتِ امْرَأَةٌ عَلَى أَلْسِنَةِ أُنَاسٍ يُعْرَفُونَ – وَهِيَ لَا تُعْرَفُ – حُلِيًّا، فَبَاعَتْهُ وَأَخَذَتْ ثَمَنَهُ، فَأُتِيَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَعَى أَهْلُهَا إِلَى أُسَامَةَ بْنِ زَيْدٍ، فَكَلَّمَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا، فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُكَلِّمُهُ، ثُمَّ قَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَتَشْفَعُ إِلَيَّ – وَفِي رِوَايَةٍ: أَتُكَلِّمُنِي – فِي حَدٍّ مِنْ حُدُودِ اللَّهِ". فَقَالَ أُسَامَةُ: اسْتَغْفِرْ لِي يَا رَسُولَ اللَّهِ، ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَشِيَّتَئِذٍ فَأَثْنَى عَلَى اللَّهِ عَزَّ وَجَلَّ بِمَا هُوَ أَهْلُهُ، ثُمَّ قَالَ: "أَمَّا بَعْدُ، فَإِنَّمَا هَلَكَ النَّاسُ قَبْلَكُمْ: أَنَّهُمْ كَانُوا إِذَا سَرَقَ الشَّرِيفُ فِيهِمْ تَرَكُوهُ، وَإِذَا سَرَقَ الضَّعِيفُ فِيهِمْ أَقَامُوا عَلَيْهِ الْحَدَّ. وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَوْ أَنَّ فَاطِمَةَ بِنْتَ مُحَمَّدٍ سَرَقَتْ لَقَطَعْتُ يَدَهَا". ثُمَّ قَطَعَ تِلْكَ الْمَرْأَةَ. وَفِي رِوَايَةٍ: ثُمَّ أَمَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِيَدِ تِلْكَ الْمَرْأَةِ فَقُطِعَتْ، فَحَسُنَتْ تَوْبَتُهَا بَعْدَ ذَلِكَ. قَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: وَكَانَتْ تَأْتِينِي بَعْدَ ذَلِكَ، فَأَرْفَعُ حَاجَتَهَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'ആഇശ(റ): ഒരു സ്ത്രീ താൻ അറിയാത്തവരും ജനങ്ങൾക്കിടയിൽ പ്രസിദ്ധരുമായവരുടെ വാക്കുകളുടെ മേൽ ആഭരണങ്ങൾ വായ്പക്കെടുക്കുകയും അത് വിറ്റ് വില എടുക്കുകയും ചെയ്തു. അവളെ നബി(സ)യുടെ തിരുസന്നിധിയിൽ കൊണ്ടുവന്നു. അങ്ങനെ അവളുടെ കുടുംബക്കാർ ഉസാമതുബ്നു സൈദ്(റ)വിന്റെ അടുക്കൽ ചെന്നു. അദ്ദേഹം നബി(സ)യോട് ഈ വിഷയത്തിൽ സംസാരിച്ചു. അപ്പോൾ തിരുമേനി(സ)യുടെ മുഖം വിവർണ്ണമാവുകയും ഉസാമ(റ)യോട് ഇങ്ങനെ ചോദിക്കുകയും ചെയ്തു: "അല്ലാഹുവിന്റെ ശിക്ഷയിൽ താങ്കൾ എന്നോട് ശിപാർശ ചെയ്യുകയാണോ? - അതോ: സംസാരിക്കുകയാണോ?" അപ്പോൾ ഉസാമ(റ) പറഞ്ഞു: തിരുദൂതരേ, എനിക്ക് വേണ്ടി പൊറുക്കലിനെ തേടിയാലും. അന്നു രാത്രി റസൂൽ(സ) എഴുന്നേറ്റ് അല്ലാഹുവിനെ വേണ്ടവിധം സ്തുതിച്ചു. എന്നിട്ട് പറഞ്ഞു: "പ്രാരംഭ മുറകൾക്ക് ശേഷം, നിങ്ങളുടെ മുമ്പുള്ള ജനങ്ങൾ നശിച്ചതിന് കാരണം അവരിലെ മാന്യന്മാർ മോഷണം നടത്തിയാൽ അവരെ ശിക്ഷയിൽ നിന്നൊഴിവാക്കുകയും താഴ്ന്നവർ മോഷണം നടത്തിയാൽ ശിക്ഷ നടപ്പാക്കുകയും ചെയ്തതായിരുന്നു. മുഹമ്മദിന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണ് സത്യം! മുഹമ്മദിന്റെ മകൾ ഫാത്വിമ കട്ടാലും അവളുടെ കൈ ഞാൻ മുറിക്കും." ശേഷം ആ സ്ത്രീയുടെ കൈ മുറിക്കപ്പെട്ടു. മറ്റൊരു റിപ്പോർട്ടിൽ: പിന്നീട് റസൂൽ(സ) ആ സ്ത്രീയുടെ കൈ മുറിക്കാൻ കൽപിച്ചു. ശേഷം അവൾ നന്നായി തൗബ ചെയ്തു. ആഇശ(റ) പറയുന്നു: അതിനു ശേഷം അവൾ എന്റടുക്കൽ വരാറുണ്ടായിരുന്നു. അവളുടെ ആവശ്യങ്ങൾ റസൂൽ(സ)യോട് ഞാൻ പറയുമായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 509, 510, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=166), 1, 'وَفِي رِوَايَةٍ: أَتُكَلِّمُنِي – فِي حَدٍّ مِنْ حُدُودِ اللَّهِ". فَقَالَ أُسَامَةُ: اسْتَغْفِرْ لِي يَا رَسُولَ اللَّهِ، ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَشِيَّتَئِذٍ فَأَثْنَى عَلَى اللَّهِ عَزَّ وَجَلَّ بِمَا هُوَ أَهْلُهُ، ثُمَّ قَالَ: "أَمَّا بَعْدُ، فَإِنَّمَا هَلَكَ النَّاسُ قَبْلَكُمْ: أَنَّهُمْ كَانُوا إِذَا سَرَقَ الشَّرِيفُ فِيهِمْ تَرَكُوهُ، وَإِذَا سَرَقَ الضَّعِيفُ فِيهِمْ أَقَامُوا عَلَيْهِ الْحَدَّ. وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَوْ أَنَّ فَاطِمَةَ بِنْتَ مُحَمَّدٍ سَرَقَتْ لَقَطَعْتُ يَدَهَا". ثُمَّ قَطَعَ تِلْكَ الْمَرْأَةَ.', 'മറ്റൊരു നിവേദനിൽ: പിന്നീട് റസൂൽ(സ) ആ സ്ത്രീയുടെ കൈ മുറിക്കാൻ കൽപിച്ചു. ശേഷം അവൾ നന്നായി തൗബ ചെയ്തു. ആഇശ(റ) പറയുന്നു: അതിനു ശേഷം അവൾ എന്റടുക്കൽ വരാറുണ്ടായിരുന്നു. അവളുടെ ആവശ്യങ്ങൾ റസൂൽ(സ)യോട് ഞാൻ പറയുമായിരുന്നു. (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=166), 2, 'وَفِي رِوَايَةٍ: ثُمَّ أَمَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِيَدِ تِلْكَ الْمَرْأَةِ فَقُطِعَتْ، فَحَسُنَتْ تَوْبَتُهَا بَعْدَ ذَلِكَ. قَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: وَكَانَتْ تَأْتِينِي بَعْدَ ذَلِكَ، فَأَرْفَعُ حَاجَتَهَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَرَقَتِ امْرَأَةٌ مِنْ قُرَيْشٍ مِنْ بَنِي مَخْزُومٍ، فَأُتِيَ بِهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: مَنْ يُكَلِّمُهُ فِيهَا؟ قَالُوا: أُسَامَةُ بْنُ زَيْدٍ. فَأَتَاهُ فَكَلَّمَهُ فَزَبَرَهُ، وَقَالَ: "إِنَّ بَنِي إِسْرَائِيلَ كَانُوا إِذَا سَرَقَ فِيهِمُ الشَّرِيفُ تَرَكُوهُ، وَإِذَا سَرَقَ الْوَضِيعُ قَطَعُوهُ. وَالَّذِي نَفْسِي بِيَدِهِ، لَوْ أَنَّ فَاطِمَةَ بِنْتَ مُحَمَّدٍ سَرَقَتْ لَقَطَعْتُهَا". وَفِي رِوَايَةٍ: أَنَّ امْرَأَةً فِي عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ الْفَتْحِ. (ن)', 'ആഇശ(റ): ബനൂമഖ്സൂമിൽപ്പെട്ട ഖുറൈശിയായ ഒരു സ്ത്രീ മോഷ്ടിക്കുകയും അവളെ നബി(സ)യുടെ അടുത്ത് കൊണ്ടുവരികയും ചെയ്തു. അപ്പോൾ ജനങ്ങൾ ചോദിച്ചു: അവളുടെ വിഷയത്തിൽ ആരാണ് നബി(സ)യോട് സംസാരിക്കുക? ചിലർ പറഞ്ഞു: ഉസാമതുബ്നു സൈദ്(റ) സംസാരിക്കും. അങ്ങനെ ഉസാമ(റ) നബി(സ)യുടെ അടുത്തുവന്ന് സംസാരിക്കുകയും നബി(സ) അദ്ദേഹത്തെ അതിൽ നിന്ന് വിലക്കുകയും ചെയ്തു. ശേഷം അവിടുന്ന് പറഞ്ഞു: "ബനൂഇസ്റാഈലുകൾ തങ്ങളിലെ പ്രമാണികൾ മോഷണം നടത്തിയാൽ അവരെ വെറുതെവിടുകയും കീഴാളർ മോഷണം നടത്തിയാൽ അവരുടെ കൈ മുറിക്കുകയും ചെയ്യുമായിരുന്നു. എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, മുഹമ്മദിന്റെ മകൾ ഫാത്വിമയാണ് കട്ടതെങ്കിൽ അവളുടെ കൈ ഞാൻ മുറിക്കുക തന്നെ ചെയ്യും." മറ്റൊരു നിവേദനം: റസൂൽ(സ)യുടെ കാലത്ത് മക്കാവിജയ സംഭവത്തിന്റെ സാഹചര്യത്തിൽ ഒരു സ്ത്രീ മോഷണം നടത്തി. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 510, 510, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=167), 1, 'وَفِي رِوَايَةٍ: أَنَّ امْرَأَةً فِي عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ الْفَتْحِ. (ن)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ)യുടെ കാലത്ത് മക്കാവിജയ സംഭവത്തിന്റെ സാഹചര്യത്തിൽ ഒരു സ്ത്രീ മോഷണം നടത്തി. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فِي كَمْ تُقْطَعُ الْيَدُ؟ قَالَ: "لَا تُقْطَعُ الْيَدُ فِي ثَمَرٍ مُعَلَّقٍ، فَإِذَا ضَمَّهُ الْجَرِينُ قُطِعَتْ فِي ثَمَنِ الْمِجَنِّ. وَلَا تُقْطَعُ فِي حَرِيسَةِ الْجَبَلِ، فَإِذَا آوَى الْمُرَاحَ قُطِعَتْ فِي ثَمَنِ الْمِجَنِّ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഏതെല്ലാം വിഷയത്തിലാണ് കൈ മുറിക്കപ്പെടുകയെന്ന് റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു. അവിടന്ന് പറഞ്ഞു: "പറിക്കാത്ത ഫലം മോഷ്ടിച്ചാൽ കൈ മുറിക്കപ്പെടുകയില്ല. ഉണക്കാനിട്ട പഴമാണെങ്കിൽ പരിചയുടെ വിലയോളം ഉണ്ടെങ്കിൽ മുറിക്കപ്പെടും. മേയാൻ വിട്ട മാടുകളാണെങ്കിൽ മുറിക്കപ്പെടുകയില്ല. കൂട്ടിൽ നിന്ന് മോഷ്ടിക്കുകയാണെങ്കിൽ പരിചയുടെ വിലയോളം ഉണ്ടെങ്കിൽ മുറിക്കപ്പെടും." (ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 510, 510, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ سُئِلَ عَنِ الثَّمَرِ الْمُعَلَّقِ؟ فَقَالَ: "مَا أَصَابَ مِنْ ذِي حَاجَةٍ غَيْرَ مُتَّخِذٍ خُبْنَةً فَلَا شَيْءَ عَلَيْهِ، وَمَنْ خَرَجَ بِشَيْءٍ مِنْهُ فَعَلَيْهِ غَرَامَةُ مِثْلَيْهِ وَالْعُقُوبَةُ، وَمَنْ سَرَقَ شَيْئًا مِنْهُ بَعْدَ أَنْ يُؤْوِيَهُ الْجَرِينُ فَبَلَغَ ثَمَنَ الْمِجَنِّ فَعَلَيْهِ الْقَطْعُ، وَمَنْ سَرَقَ دُونَ ذَلِكَ فَعَلَيْهِ غَرَامَةُ مِثْلَيْهِ وَالْعُقُوبَةُ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): പറിക്കാത്ത ഫലത്തെക്കുറിച്ച് റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു. അവിടുന്ന് പറഞ്ഞു: "കൊണ്ടുപോകാൻ വേണ്ടിയല്ലാതെ ആവശ്യക്കാരൻ എടുക്കുന്ന വസ്തുവിൽ അവന് ഒരു ശിക്ഷയുമില്ല. ആരെങ്കിലും അതിൽ നിന്ന് വല്ലതും എടുത്തുകൊണ്ടുപോയാൽ അവന് അതിന്റെ ഇരട്ടി ബാധ്യതയും ശിക്ഷയും ഉണ്ടായിരിക്കും. ഉണക്കാനിടുന്ന സ്ഥലത്തേക്കെത്തിച്ചതിനു ശേഷം ആരെങ്കിലും അതിൽ നിന്ന് മോഷ്ടിക്കുകയും അതിന്റെ വില ഒരു അങ്കിയോളമുണ്ടാകുകയും ചെയ്താൽ അവന്റെ കൈ മുറിക്കണം. അതിനേക്കാൾ വില കുറഞ്ഞത് മോഷ്ടിക്കുന്നവന് ഇരട്ടി ബാധ്യതയും ശിക്ഷയും ഉണ്ടായിരിക്കും." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 510, 511, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَجُلًا مِنْ مُزَيْنَةَ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، كَيْفَ تَرَى فِي حَرِيسَةِ الْجَبَلِ؟ فَقَالَ: "هِيَ وَمِثْلُهَا وَالنَّكَالُ، وَلَيْسَ فِي شَيْءٍ مِنَ الْمَاشِيَةِ قَطْعٌ، إِلَّا فِيمَا آوَاهُ الْمُرَاحُ فَبَلَغَ ثَمَنَ الْمِجَنِّ فَفِيهِ قَطْعُ الْيَدِ، وَمَا لَمْ يَبْلُغْ ثَمَنَ الْمِجَنِّ فَفِيهِ غَرَامَةُ مِثْلَيْهِ وَجَلَدَاتُ نَكَالٍ". قَالَ: يَا رَسُولَ اللَّهِ، كَيْفَ تَرَى فِي الثَّمَرِ الْمُعَلَّقِ؟ قَالَ: "هُوَ وَمِثْلُهُ مَعَهُ وَالنَّكَالُ، وَلَيْسَ فِي شَيْءٍ مِنَ الثَّمَرِ الْمُعَلَّقِ قَطْعٌ إِلَّا فِيمَا آوَاهُ الْجَرِينُ، فَمَا أُخِذَ مِنَ الْجَرِينِ فَبَلَغَ ثَمَنَ الْمِجَنِّ فَفِيهِ الْقَطْعُ، وَمَا لَمْ يَبْلُغْ ثَمَنَ الْمِجَنِّ فَفِيهِ غَرَامَةُ مِثْلَيْهِ وَجَلَدَاتُ نَكَالٍ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): മുസൈന ഗോത്രത്തിൽപ്പെട്ട ഒരു വ്യക്തി റസൂൽ(സ)യുടെ തിരുസന്നിധിയിൽ വന്ന് ചോദിച്ചു: തിരുദൂതരേ, മേയാൻ വിട്ട മാടുകളുടെ വിഷയത്തിൽ അവിടുന്ന് എന്താണ് പറയുന്നത്? തിരുമേനി(സ) പറഞ്ഞു: "അതും അതിന് സമാനമായ മറ്റെന്തും പിന്നെ ശിക്ഷയും. ആട് മാടുകളുടെ വിഷയത്തിൽ മുറിക്കപ്പെടുകയില്ല, കൂട്ടിൽ കെട്ടിയതും ഒരു പരിചയുടെ വിലയോളമുള്ളതിലൊഴികെ. അതിൽ (മോഷ്ടിച്ചാൽ) കൈ മുറിക്കപ്പെടും. പരിചയുടെ വിലയോളം വിലമതിക്കാത്തതാണെങ്കിൽ അതിന്റെ ഇരട്ടി പിഴ നൽകണം, ശിക്ഷയായി അടിയും വേണം." അദ്ദേഹം ചോദിച്ചു: തിരുദൂതരേ, പറിക്കാത്ത ഫലങ്ങളുടെ വിഷയത്തിൽ അവിടുന്ന് എന്താണ് പറയുന്നത്? തിരുമേനി(സ) പറഞ്ഞു: "അതും അതിനു സമാനമായ ഒന്നും ശിക്ഷയും ആകുന്നു. പറിക്കാത്ത പഴങ്ങളുടെ വിഷയത്തിൽ കൈ മുറിക്കപ്പെടുകയില്ല, ഉണക്കിച്ചതിലൊഴികെ. ഉണക്കാൻ വെച്ചതിൽ നിന്നെടുത്താൽ ഒരു പരിചയുടെ വിലയോളം ഉണ്ടെങ്കിൽ കൈ മുറിക്കപ്പെടും. പരിചയുടെ വിലയില്ലെങ്കിൽ അതിന്റെ ഇരട്ടി പിഴയും ശിക്ഷയായി അടിയും ഉണ്ടാകും." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 511, 511, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ هَنَّادٍ الْجَنْبِيِّ قَالَ: أُتِيَ عُمَرُ رَضِيَ اللهُ عَنْهُ بِامْرَأَةٍ قَدْ فَجَرَتْ، فَأَمَرَ بِرَجْمِهَا، فَمَرَّ عَلِيٌّ رَضِيَ اللهُ عَنْهُ فَأَخَذَهَا فَخَلَّى سَبِيلَهَا، فَأُخْبِرَ عُمَرُ، قَالَ: ادْعُوا لِي عَلِيًّا، فَجَاءَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ فَقَالَ: يَا أَمِيرَ الْمُؤْمِنِينَ، لَقَدْ عَلِمْتَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ: عَنِ الصَّبِيِّ حَتَّى يَبْلُغَ، وَعَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ، وَعَنِ الْمَعْتُوهِ حَتَّى يَبْرَأَ". وَإِنَّ هَذِهِ مَعْتُوهَةُ بَنِي فُلَانٍ، لَعَلَّ الَّذِي أَتَاهَا وَهِيَ فِي بَلَائِهَا؟ قَالَ: فَقَالَ عُمَرُ: لَا أَدْرِي، فَقَالَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ: وَأَنَا لَا أَدْرِي (د)', 'ഹന്നാദുൽ ജൻബീ(റ): വ്യഭിചരിച്ച ഒരു സ്ത്രീയെ ഉമർ(റ)വിന്റെ അടുത്ത് കൊണ്ടുവന്നു. അവളെ എറിഞ്ഞുകൊല്ലാൻ ഉമർ(റ) കൽപിച്ചു. അപ്പോൾ അലി(റ) അതിലൂടെ കടന്നുപോകുകയും ആ സ്ത്രീയെ വെറുതെവിടുകയും ചെയ്തു. ആ വിവരം ഉമർ(റ)വിനോട് പറയപ്പെട്ടു. ഉമർ(റ) പറഞ്ഞു: അലി(റ)വിനെ എന്റെ അടുത്തേക്ക് വിളിക്കൂ. അലി(റ) വന്നിട്ട് പറഞ്ഞു: അമീറുൽ മുഅ്മിനീൻ, റസൂൽ(സ) ഇപ്രകാരം പറഞ്ഞിട്ടുണ്ടെന്ന് താങ്കൾക്ക് അറിയില്ലേ: "മൂന്നാളുകളെത്തൊട്ട് പേന ഉയർത്തപ്പെട്ടിരിക്കുന്നു (അവർക്ക് ശിക്ഷയില്ല): കുട്ടിക്ക് പ്രായപൂർത്തിയാകും വരെ, ഉറങ്ങുന്നവൻ ഉണരുന്നത് വരെ, ഭ്രാന്തന് ഭ്രാന്ത് സുഖപ്പെടും വരെ." ഈ സ്ത്രീ ഇന്ന ഗോത്രത്തിലുള്ള ഒരു ഭ്രാന്തിയാണ്. ഭ്രാന്തുള്ളപ്പോഴാകാം അവൾ ആ തെറ്റ് ചെയ്തത്. നിവേദകൻ: ഉമർ(റ) പറഞ്ഞു: എനിക്കറിയില്ല. അപ്പോൾ അലി(റ) പറഞ്ഞു: എനിക്കുമറിയില്ല. (ദ)', 'هَنَّادٍ الْجَنْبِيِّ قَالَ', 'ഹന്നാദുൽ ജൻബീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 511, 512, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا ذَرٍّ". قُلْتُ: لَبَّيْكَ يَا رَسُولَ اللَّهِ وَسَعْدَيْكَ، فَقَالَ: "كَيْفَ أَنْتَ إِذَا أَصَابَ النَّاسَ مَوْتٌ يَكُونُ الْبَيْتُ فِيهِ بِالْوَصِيفِ" يَعْنِي الْقَبْرَ؟ قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، أَوْ: مَا خَارَ اللَّهُ وَرَسُولُهُ، قَالَ: "عَلَيْكَ بِالصَّبْرِ". أَوْ قَالَ: "تَصْبِرُ". (د)', 'അബൂദർറ്(റ): റസൂൽ(സ) എന്നോട് പറഞ്ഞു (വിളിച്ചു): "അബൂദർറേ." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാനിതാ അവിടത്തേക്ക് ഉത്തരം ചെയ്യുന്നു. അവിടുത്തേക്ക് സർവ്വ അഭിവാദ്യങ്ങളും. റസൂൽ(സ) ചോദിച്ചു: "ഒരു വീട് - അഥവാ ഖബർ - ഒരു അടിമക്ക് സമമാവും വിധം ജനങ്ങൾക്കിടയിൽ വലിയ വിപത്ത് ആസന്നമായാൽ നീ എന്തുചെയ്യും?" ഞാൻ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ റസൂലുമാണ് ഏറ്റവും അറിവുള്ളവർ - അല്ലെങ്കിൽ: അല്ലാഹുവും അവന്റെ ദൂതരും ഉദ്ദേശിച്ചതു പോലെ. റസൂൽ(സ) പറഞ്ഞു: "നീ ക്ഷമ കൈക്കൊള്ളുക." അല്ലെങ്കിൽ: "നീ ക്ഷമിക്കുക." (ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 512, 512, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً مَخْزُومِيَّةً كَانَتْ تَسْتَعِيرُ الْمَتَاعَ فَتَجْحَدُهُ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِهَا فَقُطِعَتْ يَدُهَا. وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ خَطِيبًا فَقَالَ: "هَلْ مِنِ امْرَأَةٍ تَائِبَةٍ إِلَى اللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ" ثَلَاثَ مَرَّاتٍ، وَتِلْكَ شَاهِدَةٌ، فَلَمْ تَقُمْ وَلَمْ تَتَكَلَّمْ. (د)', 'ഇബ്നുഉമർ(റ): ഒരു മഖ്സൂമിയായ വനിത ചരക്കുകൾ വായ്പയെടുക്കുകയും പിന്നെ അതിനെ നിഷേധിക്കുകയും ചെയ്യുമായിരുന്നു. അപ്പോൾ റസൂൽ(സ) അവളുടെ കൈ മുറിക്കാൻ കൽപിക്കുകയും മുറിക്കപ്പെടുകയും ചെയ്തു. മറ്റൊരു നിവേദനത്തിൽ: നബി(സ) പ്രസംഗിക്കാൻ എഴുന്നേറ്റു. മൂന്ന് പ്രാവശ്യം ചോദിച്ചു: "അല്ലാഹുവിലേക്കും അവന്റെ തിരുദൂതരിലേക്കും പശ്ചാത്തപിച്ചു മടങ്ങുന്ന ഏതെങ്കിലും സ്ത്രീയുണ്ടോ?" ആ സ്ത്രീ അവിടെയുണ്ടായിരുന്നു. അവർ എഴുന്നേൽക്കുകയോ സംസാരിക്കുകയോ ചെയ്തില്ല. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 512, 512, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=173), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ خَطِيبًا فَقَالَ: "هَلْ مِنِ امْرَأَةٍ تَائِبَةٍ إِلَى اللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ" ثَلَاثَ مَرَّاتٍ، وَتِلْكَ شَاهِدَةٌ، فَلَمْ تَقُمْ وَلَمْ تَتَكَلَّمْ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ: നബി(സ) പ്രസംഗിക്കാൻ എഴുന്നേറ്റു. മൂന്ന് പ്രാവശ്യം ചോദിച്ചു: "അല്ലാഹുവിലേക്കും അവന്റെ തിരുദൂതരിലേക്കും പശ്ചാത്തപിച്ചു മടങ്ങുന്ന ഏതെങ്കിലും സ്ത്രീയുണ്ടോ?" ആ സ്ത്രീ അവിടെയുണ്ടായിരുന്നു. അവർ എഴുന്നേൽക്കുകയോ സംസാരിക്കുകയോ ചെയ്തില്ല. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَرَضَهُ يَوْمَ أُحُدٍ وَهُوَ ابْنُ أَرْبَعَ عَشْرَةَ سَنَةً فَلَمْ يُجِزْهُ، وَعَرَضَهُ يَوْمَ الْخَنْدَقِ وَهُوَ ابْنُ خَمْسَ عَشْرَةَ سَنَةً فَأَجَازَهُ. قَالَ نَافِعٌ: حَدَّثْتُ بِهَذَا الْحَدِيثِ عُمَرَ بْنَ عَبْدِ الْعَزِيزِ، فَقَالَ: إِنَّ هَذَا الْحَدُّ بَيْنَ الصَّغِيرِ وَالْكَبِيرِ. (ق,د,ت,جه)', 'ഇബ്നുഉമർ(റ): ഉഹ്ദ് ദിവസം അദ്ദേഹത്തെ നബി(സ) യുദ്ധത്തിന് അനുവദിച്ചില്ല. അന്ന് അദ്ദേഹത്തിന് പതിനാല് വയസ്സായിരുന്നു. ശേഷം ഖൻദഖ് ദിവസം അദ്ദേഹത്തിന് നബി(സ) അനുവാദം നൽകുകയും ചെയ്തു. പതിനഞ്ച് വയസ്സായിരുന്നു അന്ന്. നാഫിഅ്(റ) പറയുന്നു: ഉമറുബ്നു അബ്ദിൽ അസീസിനോട് ഞാൻ ഈ ഹദീസ് പറഞ്ഞു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഇത് ചെറിയ കുട്ടിയുടെയും വലിയവന്റെയും ഇടയിലുള്ള കണക്കാകുന്നു. (ബു,മു,ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 512, 512, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَقِيلُوا ذَوِي الْهَيْئَاتِ عَثَرَاتِهِمْ إِلَّا الْحُدُودَ". (د)', 'ആഇശ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "ശിക്ഷക്ക് വിധേയമാക്കപ്പെടുന്ന കാര്യങ്ങളൊഴിച്ച് ഒരാളുടെയും മാന്യതക്ക് കോട്ടം വരുന്ന കാര്യങ്ങൾ നിങ്ങളൊഴിവാക്കുക." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 513, 513, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تَعَافُوا الْحُدُودَ فِيمَا بَيْنَكُمْ، فَمَا بَلَغَنِي مِنْ حَدٍّ فَقَدْ وَجَبَ". (د,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്കിടയിലുള്ള ശിക്ഷകളെ നിങ്ങൾ പരസ്പരം പൊറുക്കുക. ശിക്ഷിക്കപ്പെടേണ്ടത് എന്റെ അടത്തെത്തിയാൽ ശിക്ഷ നിർബന്ധമാകും." (ദ,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 513, 513, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ نُعَيْمِ بْنِ هَزَّالٍ الْأَسْلَمِي: أَنَّ مَاعِزًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَقَرَّ عِنْدَهُ أَرْبَعَ مَرَّاتٍ، فَأَمَرَ بِرَجْمِهِ، وَقَالَ لِهَزَّالٍ: "لَوْ سَتَرْتَهُ بِثَوْبِكَ كَانَ خَيْرًا لَكَ". وَفِي رِوَايَةٍ: أَنْ هَزَّالًا أَمَرَ مَاعِزًا أَنْ يَأْتِيَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيُخْبِرَهُ. (د)', 'നുഐമുബ്നു ഹസാൽ(റ): മാഇസ്(റ) നബി(സ)യെ സമീപിച്ച് നാലു തവണ തന്റെ തെറ്റ് ഏറ്റുപറഞ്ഞു. അപ്പോൾ നബി(സ) മാഇസിനെ എറിഞ്ഞുകൊല്ലാൻ കൽപിച്ചു. എന്നിട്ട് ഹസ്സാൽ എന്നവരോട് പറഞ്ഞു: "അവനെ നിങ്ങളുടെ വസ്ത്രം കൊണ്ട് മറച്ചിരുന്നെങ്കിൽ അതായിരുന്നു നിങ്ങൾക്ക് ഉത്തമമായത്." മറ്റൊരു നിവേദനം: ഹസ്സാൽ എന്നവർ നബി(സ)യെ സമീപിച്ചു വിവരം നബി(സ)യെ അറിയിക്കാൻ മാഇസിനോടാവശ്യപ്പെട്ടു. (ദ)', 'نُعَيْمِ بْنِ هَزَّالٍ الْأَسْلَمِي', 'നുഐമുബ്നു ഹസാൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 513, 513, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=177), 1, 'وَفِي رِوَايَةٍ: أَنْ هَزَّالًا أَمَرَ مَاعِزًا أَنْ يَأْتِيَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيُخْبِرَهُ. (د)', 'മറ്റൊരു നിവേദനം: ഹസ്സാൽ എന്നവർ നബി(സ)യെ സമീപിച്ചു വിവരം നബി(സ)യെ അറിയിക്കാൻ മാഇസിനോടാവശ്യപ്പെട്ടു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "حَدٌّ يُعْمَلُ فِي الْأَرْضِ خَيْرٌ لِأَهْلِ الْأَرْضِ مِنْ أَنْ يُمْطَرُوا ثَلَاثِينَ صَبَاحاً". وَفِي رِوَايَةٍ: "إِقَامَةُ حَدٍّ بِأَرْضٍ خَيْرٌ لِأَهْلِهَا مِنْ مَطَرِ أَرْبَعِينَ لَيْلَةً". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഭൂമിയിൽ വെച്ച് നടപ്പാക്കപ്പെടുന്ന ശിക്ഷ മുപ്പത് പ്രഭാതങ്ങളിൽ മഴ പെയ്യുന്നതിനേക്കാൾ ഭൂലോകർക്ക് ഉത്തമമാണ്." മറ്റൊരു നിവേദനം: "ഒരു നാട്ടിൽ ശിക്ഷ നടപ്പാക്കൽ ആ നാട്ടുകാർക്ക് നാൽപത് രാത്രികളിലെ മഴയേക്കാൾ ഉത്തമമാണ്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 513, 513, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=178), 1, 'وَفِي رِوَايَةٍ: "إِقَامَةُ حَدٍّ بِأَرْضٍ خَيْرٌ لِأَهْلِهَا مِنْ مَطَرِ أَرْبَعِينَ لَيْلَةً". (ن)', 'മറ്റൊരു നിവേദനം: "ഒരു നാട്ടിൽ ശിക്ഷ നടപ്പാക്കൽ ആ നാട്ടുകാർക്ക് നാൽപത് രാത്രികളിലെ മഴയേക്കാൾ ഉത്തമമാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ، عَنْ سَعِيدِ بْنِ سَعْدِ بْنِ عُبَادَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ بَيْنَ أَبْيَاتِنَا رَجُلٌ مُخْدَجٌ ضَعِيفٌ، فَلَمْ يُرَعْ إِلَّا وَهُوَ عَلَى أَمَةٍ مِنْ إِمَاءِ الدَّارِ يَخْبُثُ بِهَا، فَرَفَعَ شَأْنَهُ سَعْدُ بْنُ عُبَادَةَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "اجْلِدُوهُ ضَرْبَ مِائَةِ سَوْطٍ". قَالُوا: يَا نَبِيَّ اللَّهِ، هُوَ أَضْعَفُ مِنْ ذَلِكَ، لَوْ ضَرَبْنَاهُ مِائَةَ سَوْطٍ مَاتَ. قَالَ: "فَخُذُوا لَهُ عِثْكَالًا فِيهِ مِائَةُ شِمْرَاخٍ، فَاضْرِبُوهُ ضَرْبَةً وَاحِدَةً". [ز: فِي إِسْنَادِهِ مُدَلِّسٌ عَنْعَنَهُ] (جه)', 'അബൂഉമാമതുബ്നു സഹ്ലുബ്നു ഹുനൈഫ്(റ), സഈദുബ്നു സഅ്ദുബ്നു ഉബാദ(റ): ഞങ്ങളുടെ വീടുകൾക്കിടയിൽ ബലഹീനനും വൈകല്യമുള്ളവനുമായ ഒരാളുണ്ടായിരുന്നു. വീട്ടിലെ അടിമകളിലെ ഒരു അടിമസ്ത്രീയെ വ്യഭിചരിക്കും വരെ അയാളിൽ പേടിക്കപ്പെടേണ്ട ഒന്നുമുണ്ടായിരുന്നില്ല. അയാളുടെ വിഷയം സഅ്ദുബ്നു ഉബാദ നബി(സ)യെ ഉണർത്തി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അയാളെ ചാട്ട കൊണ്ട് നൂറ് അടി അടിക്കുക." അവർ പറഞ്ഞു: റസൂലേ, അയാൾക്ക് അത് കൊള്ളാനുള്ള ആരോഗ്യമില്ല. നൂറ് അടി അടിച്ചാൽ അയാൾ മരിക്കും. നബി(സ) പറഞ്ഞു: "നൂറ് തണ്ടുകളുള്ള ഒരു ഈത്തപ്പനക്കൊമ്പെടുക്കുക. എന്നിട്ട് അതുകൊണ്ട് ഒരടി അടിക്കുക." (ജ)', 'أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ، عَنْ سَعِيدِ بْنِ سَعْدِ بْنِ عُبَادَةَ', 'അബൂഉമാമതുബ്നു സഹ്ലുബ്നു ഹുനൈഫ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ مُدَلِّسٌ عَنْعَنَهُ', null, 513, 514, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ وَائِلٍ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتُكْرِهَتِ امْرَأَةٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَدَرَأَ عَنْهَا الْحَدَّ، وَأَقَامَهُ عَلَى الَّذِي أَصَابَهَا، وَلَمْ يَذْكُرْ أَنَّهُ جَعَلَ لَهَا مَهْرًا. (ت,جه)', 'വാഇൽ(റ): നബി(സ)യുടെ കാലത്ത് ഒരു സ്ത്രീ വ്യഭിചാരത്തിന് നിർബന്ധിക്കപ്പെട്ടു. നബി(സ) അവളെ ശിക്ഷയിൽ നിന്നൊഴിവാക്കി. വ്യഭിചരിച്ചവന്റെ മേൽ ശിക്ഷ നടപ്പാക്കി. അവൾക്ക് മഹ്റ് കൊടുക്കാൻ നബി(സ) കൽപിച്ചു എന്ന് നിവേദകൻ പരാമർശിച്ചിട്ടില്ല. (തു,ജ)', 'وَائِلٍ', 'വാഇൽ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 514, 514, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُقَامُ الحُدُودُ فِي المَسَاجِدِ". (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "പള്ളികളിൽ വെച്ച് ശിക്ഷ നടപ്പിലാക്കപ്പെടരുത്." (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 514, 514, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ نَهَى عَنْ إِقَامَةِ الحَدِّ فِي المَسَاجِدِ. [ز: فِي إِسْنَادِهِ ضَعِيفٌ] (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): പള്ളികളിൽ വെച്ച് ശിക്ഷ നടപ്പിലാക്കൽ തിരുദൂതർ(സ) വിലക്കിയിരിക്കുന്നു. ഇതിന്റെ സനദിൽ ബലഹീനതയുണ്ട്. (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ ضَعِيفٌ', null, 514, 514, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ جُنْدُبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "حَدُّ السَّاحِرِ ضَرْبُهُ بِالسَّيْفِ". (ت)', 'ജുൻദുബ്(റ): നബി(സ) പറഞ്ഞു: "മാരണം ചെയ്യുന്നവനുള്ള ശിക്ഷ അവനെ വാൾ കൊണ്ട് വെട്ടലാണ്." (തു)', 'جُنْدُبٍ', 'ജുൻദുബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 514, 514, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ : أَنَّ سَعْدَ بْنَ عُبَادَةَ الْأَنْصَارِيَّ رَضِيَ اللهُ عَنْهُ قَالَ: يَا رَسُولَ اللَّهِ، الرَّجُلُ يَجِدُ مَعَ امْرَأَتِهِ رَجُلًا، أَيَقْتُلُهُ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَا". قَالَ سَعْدٌ: بَلَى، وَالَّذِي أَكْرَمَكَ بِالْحَقِّ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "اسْمَعُوا مَا يَقُولُ سَيِّدُكُمْ". (م,د,جه)', 'അബൂഹുറൈറ(റ): സഅ്ദുബ്നു ഉബാദ(റ) ചോദിച്ചു: ഒരാൾ തന്റെ ഭാര്യയുടെ കൂടെ മറ്റൊരുത്തനെ കണ്ടാൽ അയാൾക്ക് അവനെ വധിച്ചുകൂടേ? നബി(സ) പറഞ്ഞു: "ചെയ്യരുത്." സഅ്ദ് പറഞ്ഞു: ശരി, അങ്ങയെ സത്യം കൊണ്ട് അനുഗ്രഹിച്ചവൻ സത്യം. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ നേതാവ് പറയുന്നത് കേൾക്കുക." (മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 515, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ سَعْدَ بْنَ عُبَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَرَأَيْتَ لَوْ وَجَدْتُ مَعَ امْرَأَتِي رَجُلًا، أُمْهِلُهُ حَتَّى آتِيَ بِأَرْبَعَةِ شُهَدَاءَ؟ قَالَ: "نَعَمْ". (م,د)', 'അബൂഹുറൈറ(റ): സഅ്ദുബ്നു ഉബാദ(റ) തിരുമേനി(സ)യോട് ചോദിച്ചു: എന്റെ ഭാര്യയോടുകൂടെ മറ്റൊരുത്തനെ കണ്ടാൽ, നാല് സാക്ഷികളെ കൊണ്ടുവരുന്നതുവരെ പിന്തിക്കണോ? തിരുമേനി(സ) പറഞ്ഞു: "അതെ." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 515, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ سَلَمَةَ بْنِ الْمُحَبِّقِ قَالَ: قِيلَ لِأَبِي ثَابِتٍ سَعْدِ بْنِ عُبَادَةَ – رَضِيَ اللهُ عَنْهُ – حِينَ نَزَلَتْ آيَةُ الْحُدُودِ، وَكَانَ رَجُلًا غَيُورًا: أَرَأَيْتَ لَوْ أَنَّكَ وَجَدْتَ مَعَ امْرَأَتِكَ رَجُلًا، أَيَّ شَيْءٍ كُنْتَ تَصْنَعُ؟ قَالَ: كُنْتُ ضَارِبَهُمَا بِالسَّيْفِ، أَنْتَظِرُ حَتَّى أَجِيءَ بِأَرْبَعَةٍ؟ إِلَى مَا ذَاكَ قَدْ قَضَى حَاجَتَهُ وَذَهَبَ. أَوْ أَقُولُ: رَأَيْتُ كَذَا وَكَذَا، فَتَضْرِبُونِي الْحَدَّ، وَلَا تَقْبَلُوا لِي شَهَادَةً أَبَدًا. قَالَ: فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَقَالَ: "كَفَى بِالسَّيْفِ شَاهِدًا". ثُمَّ قَالَ: "لَا، إِنِّي أَخَافُ أَنْ يَتَتَابَعَ فِي ذَلِكَ السَّكْرَانُ وَالْغَيْرَانُ". (جه)', 'സലമതുബ്നുൽ മുഹബ്ബിഖ്(റ): ശിക്ഷയുടെ സൂക്തങ്ങൾ ഇറങ്ങിയപ്പോൾ ഒരാൾ സഅ്ദുബ്നു ഉബാദ(റ) വിനോട് - അദ്ദേഹം പെട്ടെന്ന് ദേഷ്യം പിടിക്കുന്നവരായിരുന്നു - ചോദിച്ചു: നിങ്ങളുടെ ഭാര്യയുടെ കൂടെ മറ്റൊരാളെ കണ്ടാൽ നിങ്ങളെന്ത് ചെയ്യും? സഅ്ദ്(റ) പറഞ്ഞു: രണ്ട് പേരെയും വാൾ കൊണ്ട് ഞാൻ വെട്ടും. നാല് പേരെ കൊണ്ടുവരുവോളം ഞാൻ കാത്തുനിൽക്കണോ? അങ്ങനെ അവൻ തന്റെ ആവശ്യവും കഴിഞ്ഞ് സ്ഥലം കാലിയാക്കും. അതല്ലെങ്കിൽ ഞാനിങ്ങനെയൊക്കെ കണ്ടു എന്നു പറയണോ? എന്നിട്ട് എന്നെ ഹദ്ദ് അടിക്കും, ഒരിക്കലും എന്റെ സാക്ഷിത്വം സ്വീകരിക്കാതെ. നിവേദകൻ പറയുന്നു: വിഷയം നബി(സ)യെ ധരിപ്പിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "സാക്ഷിയായിട്ട് വാൾ മതി." ശേഷം നബി(സ) പറഞ്ഞു: "അങ്ങനെ പറ്റില്ല, മദ്യപാനിയും മുൻകോപിയും ഇതിനെ ദുരുപയോഗം ചെയ്യുമെന്ന് ഞാൻ ഭയപ്പെടുന്നു." (ജ)', 'سَلَمَةَ بْنِ الْمُحَبِّقِ قَالَ', 'സലമതുബ്നുൽ മുഹബ്ബിഖ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 515, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ بِي خَالِي الْحَارِثُ بْنُ عَمْرٍو– رَضِيَ اللهُ عَنْهُ – وَقَدْ عَقَدَ لَهُ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ لِوَاءً، فَقُلْتُ لَهُ: أَيْنَ تُرِيدُ؟ فَقَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ إِلَى رَجُلٍ تَزَوَّجَ امْرَأَةَ أَبِيهِ مِنْ بَعْدِهِ، فَأَمَرَنِي أَنْ أَضْرِبَ عُنُقَهُ. (د,ت,ن,جه)', 'ബർറാഉബ്നു ആസിബ്(റ): എന്റെ അമ്മാവൻ ഹാരിസുബ്നു അംറ് എന്റെ അരികിലൂടെ നടന്നുപോയി. നബി(സ)യുടെ ഒരു പതാക അവരുടെ കൂടെയുണ്ടായിരുന്നു. ഞാൻ ചോദിച്ചു: നിങ്ങളെങ്ങോട്ടാണ്? ഹാരിസ്(റ) പറഞ്ഞു: തന്റെ പിതാവിനു ശേഷം പിതാവിന്റെ ഭാര്യയെ വിവാഹം ചെയ്തവന്റെ കഴുത്ത് വെട്ടാൻ കൽപിച്ചുകൊണ്ട് നബി(സ) എന്നെ അയച്ചിരിക്കുകയാണ്. (ദ,തു,ന,ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബർറാഉബ്നു ആസിബ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 515, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ قُرَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ إِلَى رَجُلٍ تَزَوَّجَ امْرَأَةَ أَبِيهِ: أَنْ أَضْرِبَ عُنُقَهُ وَأُصَفِّيَ مَالَهُ. (جه)', 'ഖുർറ(റ): സ്വന്തം പിതാവിന്റെ ഭാര്യയെ പിതാവിന്റെ ശേഷം വിവാഹം ചെയ്തവനെ കഴുത്ത് വെട്ടാനും അവന്റെ സ്വത്ത് ജപ്തി ചെയ്യാനും വേണ്ടി നബി(സ) എന്നെ അയച്ചു. (ജ)', 'قُرَّةَ', 'ഖുർറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 516, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنِ انْتَسَبَ إِلَى غَيْرِ أَبِيهِ، أَوْ تَوَلَّى غَيْرَ مَوَالِيهِ، فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "തന്റെ പിതാവല്ലാത്തവരുടെ മേൽ ആരെങ്കിലും തന്റെ പിതൃത്വം ആരോപിച്ചാൽ അല്ലെങ്കിൽ ഒരടിമ തന്റെ യജമാനനല്ലാവരിലേക്ക് തന്റെ യജമാനത്വം ആരോപിച്ചാൽ അവന്റെ മേൽ അല്ലാഹുവിന്റെയും മാലാഖമാരുടെയും സകല ജനങ്ങളുടെയും ശാപം ഉണ്ടായിരിക്കും." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 516, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ أَبِي عُثْمَانَ النَّهْدِيِّ قَالَ: سَمِعْتُ سَعْدًا وَأَبَا بَكْرَةَ، وَكُلٌّ وَاحِدٍ مِنْهُمَا يَقُولُ: سَمِعَتْ أُذُنَايَ وَوَعَى قَلْبِي مُحَمَّدًا صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنِ ادَّعَى إِلَى غَيْرِ أَبِيهِ – وَهُوَ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ – فَالْجَنَّةُ عَلَيْهِ حَرَامٌ". (ق,د,جه)', 'അബൂഉസ്മനിന്നഹ്ദി(റ): സഅ്ദ്(റ)വും അബൂബക്റ(റ)വും പറയുന്നത് ഞാൻ കേട്ടു: "മനഃപൂർവ്വം തന്റെ പിതാവല്ലാത്തവരിലേക്ക് തന്റെ പിതൃത്വം ആരെങ്കിലും ആരോപിച്ചാൽ സ്വർഗ്ഗം അവന് നിഷിദ്ധമാണ്" എന്ന് നബി(സ) പറയുന്നത് ഞാൻ രണ്ട് ചെവികൾ കൊണ്ട് കേൾക്കുകയും ഹൃദിസ്ഥമാക്കുകയും ചെയ്തിട്ടുണ്ട്. (ബു,മു,ദ,ജ)', 'أَبِي عُثْمَانَ النَّهْدِيِّ قَالَ', 'അബൂഉസ്മനിന്നഹ്ദി(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 516, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنِ ادَّعَى إِلَى غَيْرِ أَبِيهِ لَمْ يَرِحْ رَائِحَةَ الْجَنَّةِ، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ خَمْسِ مِائَةِ عَامٍ". (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "തന്റെ പിതാവല്ലാത്തവരിലേക്ക് തന്റെ പിതൃത്വം വല്ലവനും ആരോപിച്ചാൽ സ്വർഗ്ഗത്തിന്റെ വാസന അവന് അനുഭവിക്കാനാവില്ല. തീർച്ചയായും അഞ്ഞൂറ് വർഷത്തെ വഴിദൂരം വരെ സ്വർഗ്ഗവാസന എത്തും." (ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 516, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا". (م,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നമുക്കു നേരെ ആയുധം ഊരിയവൻ നമ്മിൽ പെട്ടവനല്ല." (ബു,മു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 516, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ شَهَرَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا". (جه)', 'അബൂമൂസൽ അശ്അരി(റ): റസൂൽ(സ) പറഞ്ഞു: "നമുക്കു നേരെ ആയുധം ഏന്തിയവൻ നമ്മിൽ പെട്ടവനല്ല." (ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنِ الْأَشْعَثِ بْنِ قَيْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فِي وَفْدِ كِنْدَةَ، وَلَا يَرَوْنِي إِلَّا أَفْضَلَهُمْ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَلَسْتُمْ مِنَّا؟ فَقَالَ: "نَحْنُ بَنُو النَّضْرِ بْنِ كِنَانَةَ، لَا نَقْفُو أُمَّنَا، وَلَا نَنْتَفِي مِنْ أَبِينَا". قَالَ: فَكَانَ الْأَشْعَثُ بْنُ قَيْسٍ يَقُولُ: لَا أُوتَى بِرَجُلٍ نَفَى رَجُلًا مِنْ قُرَيْشٍ، مِنَ النَّضْرِ بْنِ كِنَانَةَ، إِلَّا جَلَدْتُهُ الْحَدَّ. (جه)', 'അശ്അസുബ്നു ഖൈസ്(റ): ഖിൻദ ഗോത്രത്തിലെ സംഘത്തോടൊപ്പം ഞാൻ റസൂൽ(സ)യുടെയടുത്ത് ചെന്നു. ആ സംഘത്തിലെ ശ്രേഷ്ഠർ മാത്രമേ എന്നെ കണ്ടിട്ടുണ്ടായിരുന്നുള്ളൂ. ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, നിങ്ങളും ഞങ്ങളിൽ പെട്ടവരല്ലേ? റസൂൽ(സ) പറഞ്ഞു: "ഞങ്ങൾ ബനൂന്നള്റുബ്നു കിനാന ഗോത്രക്കാർ, ഞങ്ങളുടെ മാതാവിനെ പിന്തുടരുകയില്ല (മാതാവിലേക്ക് ചേർത്തി പറയുകയില്ല), പിതാവിൽ നിന്ന് പിതൃത്വം നിഷേധിക്കപ്പെടുകയുമില്ല (പിതാവിലേക്കാണ് ചേർത്തുക)." നിവേദകൻ പറയുന്നു: ശേഷം അശ്അസുബ്നു ഖൈസ്(റ) ഇപ്രകാരം പറയുമായിരുന്നു: നള്റുബ്നു കിനാനയിൽപ്പെട്ട ഖുറൈശിയായ ഒരാളെ നിഷേധിക്കുന്ന (ഗോത്രത്തിൽ പെട്ടവനല്ലെന്ന് പറയുന്ന) വ്യക്തിയെ എന്റെയടുക്കൽ കൊണ്ടുവന്നാൽ ഞാനവനെ ഹദ്ദ് അടിക്കുക തന്നെ ചെയ്യും. (ജ)', 'الْأَشْعَثِ بْنِ قَيْسٍ', 'അശ്അസുബ്നു ഖൈസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، عَنْ عُمَرَ، رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ وَجَدْتُمُوهُ غَلَّ فِي سَبِيلِ اللَّهِ فَاحْرِقُوا مَتَاعَهُ". (د,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വല്ലവനും വഞ്ചിച്ചാൽ അവന്റെ ചരക്കുകൾ നിങ്ങൾ കത്തിക്കുക." (ദ,തു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ، عَنْ عُمَرَ،', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ عِكْرِمَةَ: أَنَّ عَلِيًّا رَضِيَ اللهُ عَنْهُ أَحْرَقَ نَاسًا ارْتَدُّوا عَنِ الْإِسْلَامِ، فَبَلَغَ ذَلِكَ ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فَقَالَ: لَمْ أَكُنْ لِأُحْرِقَهُمْ بِالنَّارِ، إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُعَذِّبُوا بِعَذَابِ اللَّهِ". وَكُنْتُ قَاتِلَهُمْ بِقَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ بَدَّلَ دِينَهُ فَاقْتُلُوهُ". فَبَلَغَ ذَلِكَ عَلِيًّا رَضِيَ اللهُ عَنْهُ، فَقَالَ: وَيْحَ ابْنِ عَبَّاسٍ. (خ,د,ت,ن,جه)', 'ഇക്രിമ(റ): ഇസ്ലാമിൽ നിന്ന് പുറത്തുപോയ ഒരു കൂട്ടമാളുകളെ അലി(റ) ചുട്ടുകൊന്നു. ആ വിവരം ഇബ്നുഅബ്ബാസ്(റ)വിന്റെയടുത്തെത്തി. അദ്ദേഹം പറഞ്ഞു: ഞാനവരെ തീ കൊണ്ട് കരിക്കുമായിരുന്നില്ല. കാരണം റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "അല്ലാഹുവിന്റെ ശിക്ഷ കൊണ്ട് നിങ്ങൾ ശിക്ഷിക്കരുത്." എന്നാൽ റസൂൽ(സ)യുടെ വാക്കിനനുസൃതമായി ഞാൻ അവരെ വധിക്കുമായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "തന്റെ മതത്തെ മാറ്റിയവനെ നിങ്ങൾ വധിക്കുക." ആ വിവരം അലി(റ) അറിഞ്ഞു. അലി(റ) പറഞ്ഞു: ഇബ്നുഅബ്ബാസിന്റെ കഷ്ടം. (ബു,ദ,തു,ന,ജ)', 'عِكْرِمَةَ', 'ഇക്രിമ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 517, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ بَدَّلَ دِينَهُ فَاقْتُلُوهُ". (خ,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ ദീൻ വിട്ട് മറ്റൊന്നു സ്വീകരിച്ചാൽ അവനെ നിങ്ങൾ വധിച്ചുകളയുക." (ബു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 518, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَا يَحِلُّ دَمُ رَجُلٍ مُسْلِمٍ – يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ – إِلَّا بِإِحْدَى ثَلَاثٍ: الثَّيِّبُ الزَّانِي، وَالنَّفْسُ بِالنَّفْسِ، وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ. (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും ഞാൻ അല്ലാഹുവിന്റെ ദൂതനാണെന്നും സാക്ഷ്യം വഹിക്കുന്ന ഒരു മുസ്ലിമിന്റെയും രക്തം മൂന്നിലൊരു കാരണം കൊണ്ടല്ലാതെ ഒഴുക്കാൻ പാടില്ല: വിവാഹിതനായ വ്യഭിചാരി, ഒരാളെ കൊന്നവൻ, ഇസ്ലാം മതത്തെ വെടിഞ്ഞ് സംഘത്തിൽ നിന്ന് വിട്ടുനിന്നവൻ." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 518, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ – يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ – إِلَّا بِإِحْدَى ثَلَاثٍ: رَجُلٌ زَنَى بَعْدَ إِحْصَانٍ فَإِنَّهُ يُرْجَمُ، وَرَجُلٌ خَرَجَ مُحَارِبًا لِلَّهِ وَرَسُولِهِ فَإِنَّهُ يُقْتَلُ أَوْ يُصْلَبُ أَوْ يُنْفَى مِنَ الْأَرْضِ، أَوْ يَقْتُلُ نَفْسًا فَيُقْتَلُ بِهَا". (د,ن)', 'ആഇശ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും മുഹമ്മദ് അല്ലാഹുവിന്റെ ദൂതനാണെന്നും സാക്ഷ്യം വഹിക്കുന്നവന്റെ രക്തം മൂന്ന് കാരണങ്ങൾ കൊണ്ടല്ലാതെ ഒഴുക്കപ്പെടരുത്: വിവാഹിതനായ ശേഷം വ്യഭിചരിക്കുന്നവൻ; അവൻ എറിഞ്ഞ് കൊല്ലപ്പെടണം, അല്ലാഹുവിനും റസൂലിനുമെതിരെ യുദ്ധം ചെയ്യാൻ പുറപ്പെട്ടവൻ; അവൻ കൊല്ലപ്പെടുകയോ കുരിശിലേറ്റപ്പെടുകയോ ഭൂമിയിൽ നിന്ന് തുടച്ചുമാറ്റപ്പെടുകയോ വേണം, ഒരാളെ വധിക്കുന്നവൻ; അവൻ അതു കാരണം വധിക്കപ്പെടണം." (ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 518, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: أَقْبَلْتُ إِلَى النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ وَمَعِي رَجُلَانِ مِنَ الْأَشْعَرِيِّينَ، أَحَدُهُمَا عَنْ يَمِينِي وَالْآخَرُ عَنْ يَسَارِي، فَكِلَاهُمَا سَأَلَ الْعَمَلَ، وَالنَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ سَاكِتٌ، فَقَالَ: "مَا تَقُولُ يَا أَبَا مُوسَى. أَوْ: يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ". قُلْتُ: وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَطْلَعَانِي عَلَى مَا فِي أَنْفُسِهِمَا، وَمَا شَعَرْتُ أَنَّهُمَا يَطْلُبَانِ الْعَمَلَ. وَكَأَنِّي أَنْظُرُ إِلَى سِوَاكِهِ تَحْتَ شَفَتِهِ قَلَصَتْ، قَالَ: "لَنْ نَسْتَعْمِلَ – أَوْ: لَا نَسْتَعْمِلُ – عَلَى عَمَلِنَا مَنْ أَرَادَهُ، وَلَكِنِ اذْهَبْ أَنْتَ يَا أَبَا مُوسَى. أَوْ: يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ". فَبَعَثَهُ عَلَى الْيَمَنِ، ثُمَّ أَتْبَعَهُ مُعَاذَ بْنَ جَبَلٍ، قَالَ: فَلَمَّا قَدِمَ عَلَيْهِ مُعَاذٌ قَالَ: انْزِلْ. وَأَلْقَى لَهُ وِسَادَةً، وَإِذَا رَجُلٌ عِنْدَهُ مُوثَقٌ، قَالَ: مَا هَذَا؟ قَالَ: هَذَا كَانَ يَهُودِيًّا فَأَسْلَمَ، ثُمَّ رَاجَعَ دِينَهُ دِينَ السُّوءِ. قَالَ: لَا أَجْلِسُ حَتَّى يُقْتَلَ، قَضَاءُ اللَّهِ وَرَسُولِهِ. ثَلَاثَ مَرَّاتٍ، فَأَمَرَ بِهِ فَقُتِلَ، ثُمَّ تَذَاكَرَا قِيَامَ اللَّيْلِ، فَقَالَ أَحَدُهُمَا مُعَاذُ بْنُ جَبَلٍ: أَمَّا أَنَا فَأَنَامُ وَأَقُومُ، أَوْ: أَقُومُ وَأَنَامُ، وَأَرْجُو فِي نَوْمَتِي مَا أَرْجُو فِي قَوْمَتِي. (ق,د)', 'അബൂമൂസാ(റ): ഞാൻ നബി(സ)യുടെ അടുത്തേക്ക് ചെന്നു. എന്റെ കൂടെ അശ്അരിയ്യിൽ പെട്ട രണ്ട് പേരുമുണ്ടായിരുന്നു. ഒരാൾ ഇടത്തും ഒരാൾ വലത്തുമായിരുന്നു. അവർ രണ്ട് പേരും നബി(സ)യോട് അധികാരപദവികൾ ചോദിച്ചു. നബി(സ) ഒന്നും പറഞ്ഞില്ല. പിന്നീട് അവിടന്ന് പറഞ്ഞു: "അബൂമൂസാ, അല്ലെങ്കിൽ: അബ്ദുല്ലാഹിബ്നു ഖൈസ്, നിങ്ങൾ എന്ത് പറയുന്നു?" ഞാൻ പറഞ്ഞു: അങ്ങയെ സത്യവുമായി അയച്ചവനാണ! അവരുടെ മനസ്സിലുള്ളത് അവർ എന്നോട് പറഞ്ഞിരുന്നില്ല. അവർ അധികാരപദവികൾ തേടിയാണ് വരുന്നതെന്ന് എനിക്ക് അറിയുകയും ചെയ്യുമായിരുന്നില്ല. രണ്ട് ചുണ്ടുകൾക്കുമിടയിലായിരുന്ന നബി(സ)യുടെ മിസ്വാക്കിലേക്ക് ഞാനിപ്പോഴും നോക്കുന്നത് പോലെയുണ്ട്. അപ്പോൾ നബി(സ) ഇങ്ങനെ പറഞ്ഞു: "അധികാരം ആഗ്രഹിക്കുന്നവന്ന് നാം അധികാരം നൽകുകയില്ല, അല്ലെങ്കിൽ: അധികാരം നൽകാറില്ല. എങ്കിലും അബൂമൂസാ, അല്ലെങ്കിൽ: അബ്ദുല്ലാഹിബ്നു ഖൈസ്, നിങ്ങൾ പോവുക." അങ്ങനെ നബി(സ) അബൂമൂസാ(റ)വിനെ യമനിലേക്ക് ഗവർണ്ണറായി അയച്ചു. ശേഷം മുആദുബ്നു ജബൽ(റ)വിനെ അബൂമൂസാ(റ)വിന്റെ പിന്നിൽ അയച്ചു. അബൂമൂസാ(റ) തുടരുന്നു: മുആദ്(റ) യമനിലെത്തിയപ്പോൾ അബൂമൂസാ(റ) ഇരിക്കാൻ നിർദേശിച്ചു. ശേഷം പരവതാനി വിരിച്ചുകൊടുത്തു. അപ്പോൾ അബൂമൂസാ(റ)വിന്റെയടുക്കൽ കൈകാലുകൾ ബന്ധിക്കപ്പെട്ട ഒരാൾ ഉണ്ടായിരുന്നു. മുആദ്(റ) ചോദിച്ചു: ഇതാരാണ്? അദ്ദേഹം പറഞ്ഞു: ഇവൻ ജൂതനായിരുന്നു. അങ്ങനെ അവൻ മുസ്ലിമായി. ശേഷം അവൻ മോശമായ തന്റെ ആദ്യ മതം തന്നെ സ്വീകരിച്ചു. അപ്പോൾ മുആദ്(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെയും അവന്റെ റസൂലിന്റെയും വിധി പ്രകാരം അവൻ വധിക്കപ്പെടുന്നത് വരെ ഞാൻ ഇരിക്കുകയില്ല. ഇപ്രകാരം മൂന്ന് തവണ പറഞ്ഞു. അപ്പോൾ അബൂമൂസാ(റ) അയാളെ വധിക്കാനുത്തരവിട്ടു. പിന്നീട് രാത്രി നിസ്കാരത്തെക്കുറിച്ച് അവർ രണ്ട് പേരും സംസാരിച്ചു. അപ്പോൾ മുആദ്(റ) പറഞ്ഞു: ഞാൻ ഉറങ്ങും, പിന്നെ എഴുന്നേറ്റ് ആരാധനയിൽ മുഴുകും. അല്ലെങ്കിൽ ആദ്യം ആരാധനയിൽ മുഴുകും. പിന്നെ ഉറങ്ങും. ആരാധനയിൽ മുഴുകുമ്പോൾ ലഭിക്കുന്ന പ്രതിഫലങ്ങൾ എന്റെ നിദ്രയിലും ഞാൻ പ്രതീക്ഷിക്കുന്നു. (ബു,മു,ദ)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 518, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمَ عَلَيَّ مُعَاذٌ وَأَنَا بِالْيَمَنِ، وَرَجُلٌ كَانَ يَهُودِيًّا فَأَسْلَمَ فَارْتَدَّ عَنِ الْإِسْلَامِ، فَلَمَّا قَدِمَ مُعَاذٌ قَالَ: لَا أَنْزِلُ عَنْ دَابَّتِي حَتَّى يُقْتَلَ. فَقُتِلَ، قَالَ أَحَدُهُمَا: وَكَانَ قَدِ اسْتُتِيبَ قَبْلَ ذَلِكَ. وفي رواية: فَأُتِيَ أَبُو مُوسَى بِرَجُلٍ قَدِ ارْتَدَّ عَنِ الْإِسْلَامِ، فَدَعَاهُ عِشْرِينَ لَيْلَةً أَوْ قَرِيبًا مِنْهَا، فَجَاءَ مُعَاذٌ فَدَعَاهُ فَأَبَى، فَضَرَبَ عُنُقَهُ. وفي رواية: فَلَمْ يَنْزِلْ حَتَّى ضُرِبَ عُنُقُهُ، وَمَا اسْتَتَابَهُ. (د)', 'അബൂമൂസാ(റ): ഞാൻ യമനിലായിരിക്കെ മുആദ്(റ) എന്റെ അടുത്തുവന്നു. മുസ്ലിമാവുകയും ശേഷം ഇസ്ലാമിൽ നിന്ന് മടങ്ങുകയും ചെയ്ത ഒരു ജൂതൻ അവിടെയുണ്ടായിരുന്നു. മുആദ്(റ) വന്നപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അവൻ വധിക്കപ്പെടും വരെ ഞാൻ എന്റെ വാഹനത്തിൽ നിന്ന് ഇറങ്ങുകയില്ല. അങ്ങനെ ആ ജൂതനെ വധിച്ചു. അവരിലൊരാൾ പറഞ്ഞു: കൊല്ലപ്പെടും മുമ്പ് തൗബ ചെയ്ത് മടങ്ങാൻ അവനോട് ആവശ്യപ്പെട്ടിരുന്നു. മറ്റൊരു നിവേദനം: ഇസ്ലാമിൽ നിന്ന് മടങ്ങിയ ഒരാളെ അബൂമൂസാ(റ)വിന്റെ അടുത്തേക്ക് കൊണ്ടുവന്നു. ഇരുപതോ ഇരുപതോളമോ രാത്രികളിൽ അയാളോട് തൗബ ചെയ്ത് മടങ്ങാൻ അബൂമൂസാ(റ) ആവശ്യപ്പെട്ടു. പിന്നെ മുആദ്(റ) വന്നു. അദ്ദേഹവും അയാളോട് തൗബ ചെയ്ത് മടങ്ങാൻ ആവശ്യപ്പെട്ടു. പക്ഷേ, അയാളപ്പോഴും അതിനു സമ്മതിച്ചില്ല. അപ്പോൾ അദ്ദേഹം അയാളുടെ കഴുത്തറുത്തു. മറ്റൊരു നിവേദനം: അയാളുടെ കഴുത്ത് വെട്ടുന്നത് വരെ മുആദ്(റ) വാഹനത്തിൽ നിന്നിറങ്ങയില്ല. പക്ഷേ, അയാളോട് തൗബ ചെയ്യാനാവശ്യപ്പെട്ടില്ല. (ദ)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=201), 1, 'وَفِي رِوَايَةٍ: فَأُتِيَ أَبُو مُوسَى بِرَجُلٍ قَدِ ارْتَدَّ عَنِ الْإِسْلَامِ، فَدَعَاهُ عِشْرِينَ لَيْلَةً أَوْ قَرِيبًا مِنْهَا، فَجَاءَ مُعَاذٌ فَدَعَاهُ فَأَبَى، فَضَرَبَ عُنُقَهُ.', 'മറ്റൊരു നിവേദനം: ഇസ്ലാമിൽ നിന്ന് മടങ്ങിയ ഒരാളെ അബൂമൂസാ(റ)വിന്റെ അടുത്തേക്ക് കൊണ്ടുവന്നു. ഇരുപതോ ഇരുപതോളമോ രാത്രികളിൽ അയാളോട് തൗബ ചെയ്ത് മടങ്ങാൻ അബൂമൂസാ(റ) ആവശ്യപ്പെട്ടു. പിന്നെ മുആദ്(റ) വന്നു. അദ്ദേഹവും അയാളോട് തൗബ ചെയ്ത് മടങ്ങാൻ ആവശ്യപ്പെട്ടു. പക്ഷേ, അയാളപ്പോഴും അതിനു സമ്മതിച്ചില്ല. അപ്പോൾ അദ്ദേഹം അയാളുടെ കഴുത്തറുത്തു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=6 and h.hadith_no=201), 2, 'وَفِي رِوَايَةٍ: فَلَمْ يَنْزِلْ حَتَّى ضُرِبَ عُنُقُهُ، وَمَا اسْتَتَابَهُ. (د)', 'മറ്റൊരു നിവേദനം: അയാളുടെ കഴുത്ത് വെട്ടുന്നത് വരെ മുആദ്(റ) വാഹനത്തിൽ നിന്നിറങ്ങയില്ല. പക്ഷേ, അയാളോട് തൗബ ചെയ്യാനാവശ്യപ്പെട്ടില്ല. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ عَبْدُ اللَّهِ بْنُ سَعْدِ بْنِ أَبِي سَرْحٍ يَكْتُبُ لِرَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَأَزَلَّهُ الشَّيْطَانُ، فَلَحِقَ بِالْكُفَّارِ، فَأَمَرَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَنْ يُقْتَلَ يَوْمَ الْفَتْحِ، فَاسْتَجَارَ لَهُ عُثْمَانُ بْنُ عَفَّانَ، فَأَجَارَهُ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): അബ്ദുല്ലാഹിബ്നു സഅ്ദിബ്നി അബീസർഹ്(റ) നബി(സ)യുടെ എഴുത്തുകാരനായിരുന്നു. ശേഷം പിശാച് അയാളെ പിഴപ്പിച്ചു. അങ്ങനെ അയാൾ നിഷേധികളുടെ കൂടെ ചേർന്നു. മക്കാവിജയത്തിൽ അയാളെ വധിക്കാൻ തിരുദൂതർ(സ) ഉത്തരവിട്ടു. അപ്പോൾ അയാൾക്ക് വേണ്ടി ഉസ്മാൻ(റ) അഭയം ആവശ്യപ്പെട്ടു. തിരുദൂതർ(സ) അയാൾക്ക് അഭയം നൽകുകയും ചെയ്തു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 520, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا كَانَ يَوْمُ فَتْحِ مَكَّةَ اخْتَبَأَ عَبْدُ اللَّهِ بْنُ سَعْدِ بْنِ أَبِي سَرْحٍ عِنْدَ عُثْمَانَ بْنِ عَفَّانَ، فَجَاءَ بِهِ حَتَّى أَوْقَفَهُ عَلَى النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ، بَايِعْ عَبْدَ اللَّهِ، فَرَفَعَ رَأْسَهُ، فَنَظَرَ إِلَيْهِ، ثَلَاثًا، كُلُّ ذَلِكَ يَأْبَى، فَبَايَعَهُ بَعْدَ ثَلَاثٍ، ثُمَّ أَقْبَلَ عَلَى أَصْحَابِهِ فَقَالَ: "أَمَا كَانَ فِيكُمْ رَجُلٌ رَشِيدٌ، يَقُومُ إِلَى هَذَا حَيْثُ رَآنِي كَفَفْتُ يَدِي عَنْ بَيْعَتِهِ، فَيَقْتُلُهُ". فَقَالُوا: مَا نَدْرِي يَا رَسُولَ اللَّهِ مَا فِي نَفْسِكَ، أَلَّا أَوْمَأْتَ إِلَيْنَا بِعَيْنِكَ؟ قَالَ: "إِنَّهُ لَا يَنْبَغِي لِنَبِيٍّ أَنْ تَكُونَ لَهُ خَائِنَةُ الْأَعْيُنِ". (د)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): മക്കാവിജയദിനത്തിൽ അബ്ദുല്ലാഹിബ്നു സഅ്ദിബ്നി അബീസർഹ് ഉസ്മാൻ(റ)വിന്റെ അടുക്കൽ ഒളിവിൽ കഴിഞ്ഞു. അയാളെ കൊണ്ടുവന്ന് റസൂൽ(സ)യുടെ മുന്നിൽ നിർത്തി. അപ്പോൾ ഉസ്മാൻ(റ) പറഞ്ഞു: തിരുദൂതരേ, അബ്ദുല്ലക്ക് ഉടമ്പടി നൽകിയാലും! നബി(സ) മൂന്ന് തവണ ഉസ്മാൻ(റ)വിനെ തല ഉയർത്തി നോക്കി. എല്ലാം ഒരു വിസമ്മതത്തിന്റേതായിരുന്നു. മൂന്നാമത്തേതിന് ശേഷം നബി(സ) അയാൾക്ക് ഉടമ്പടി നൽകി. ശേഷം നബി(സ) തന്റെ അനുചരരുടെ നേരെ തിരിഞ്ഞ് ചോദിച്ചു: "ഇവന് ഉടമ്പടി നൽകാതെ എന്റെ കരം ഞാൻ പിടിച്ചുവെക്കുന്നത് കാണുമ്പോൾ ഇവനെ എണീറ്റുകൊല്ലാൻ തന്റേടമുള്ള ഒരാളും നിങ്ങളുടെ കൂട്ടത്തിലില്ലേ?" അവർ പറഞ്ഞു: റസൂലേ, അങ്ങയുടെ മനസ്സിലുള്ളത് ഞങ്ങൾക്കറിയില്ലായിരുന്നു. അങ്ങയുടെ കണ്ണ് കൊണ്ട് ഒരു സൂചന നൽകിയിരുന്നുവെങ്കിൽ! തിരുമേനി(സ) പറഞ്ഞു: "കട്ട് നോക്കൽ ഒരു പ്രവാചകനും പാടുള്ളതല്ല." (ദ)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 520, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللهِ الْبَجَلِي رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا أَبَقَ الْعَبْدُ إِلَى الشِّرْكِ فَقَدْ حَلَّ دَمُهُ". (م,د,ن)', 'ജരീറുബ്നു അബ്ദില്ല: തിരുദൂതർ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരു അടിമ ബഹുദൈവാരാധകരിലേക്ക് ഓടിപ്പോയാൽ അവന്റെ രക്തം (ചിന്തൽ) അനുവദനീയമാണ്." (മു,ദ,ന)', 'جَرِيرِ بْنِ عَبْدِ اللهِ الْبَجَلِي', 'ജരീറുബ്നു അബ്ദില്ല', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 520, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ عِكْرِمَةَ: أَنَّ عَلِيًّا رَضِيَ اللهُ عَنْهُ حَرَّقَ قَوْمًا ارْتَدُّوا عَنِ الْإِسْلَامِ، فَبَلَغَ ذَلِكَ ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فَقَالَ: لَوْ كُنْتُ أَنَا لَقَتَلْتُهُمْ، لِقَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ بَدَّلَ دِينَهُ فَاقْتُلُوهُ": وَلَمْ أَكُنْ لِأُحَرِّقَهُمْ، لِقَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَا تُعَذِّبُوا بِعَذَابِ اللَّهِ". فَبَلَغَ ذَلِكَ عَلِيًّا فَقَالَ: صَدَقَ ابْنُ عَبَّاسٍ (خ,د,ت,ن,جه)', 'ഇക്രിമ(റ): ഇസ്ലാമിൽ നിന്ന് മടങ്ങിയ ഒരു കൂട്ടമാളുകളെ അലി(റ) ചുട്ടുകൊന്നു. അത് ഇബ്നുഅബ്ബാസ്(റ) അറിഞ്ഞു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഞാനായിരുന്നെങ്കിൽ അവരെ വധിക്കുമായിരുന്നു. കാരണം നബി(സ) പറഞ്ഞിട്ടുണ്ട്: "ആരെങ്കിലും ദീനിൽ നിന്ന് മാറിയാൽ അവനെ നിങ്ങൾ വധിക്കുക." ഞാൻ അവരെ കരിക്കുമായിരുന്നില്ല. കാരണം നബി(സ) പറഞ്ഞിട്ടുണ്ട്: "അല്ലാഹുവിന്റെ ശിക്ഷ കൊണ്ട് നിങ്ങൾ ശിക്ഷിക്കരുത്." ഇത് അലി(റ) അറിഞ്ഞു. അപ്പോൾ അലി(റ) പറഞ്ഞു: ഇബ്നുഅബ്ബാസ്(റ) സത്യം പറഞ്ഞിരിക്കുന്നു. (ബു,ദ,തു,ന,ജ)', 'عِكْرِمَةَ', 'ഇക്രിമ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 520, 521, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ يَهُودِيَّةً كَانَتْ تَشْتُمُ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ وَتَقَعُ فِيهِ، فَخَنَقَهَا رَجُلٌ حَتَّى مَاتَتْ، فَأَبْطَلَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ دَمَهَا. (د)', 'അലി(റ): ഒരു ജൂതസ്ത്രീ നബി(സ)യെ ചീത്ത വിളിക്കുകയും ഇകഴ്ത്തുകയും ചെയ്യാറുണ്ടായിരുന്നു. അപ്പോൾ ഒരാൾ അവളെ കഴുത്ത് ഞെക്കിക്കൊന്നു. അവളുടെ രക്തത്തിന് പ്രതിക്രിയ ചെയ്യേണ്ടതില്ലെന്ന് നബി(സ) കൽപിച്ചു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 521, 521, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ أَبِي بَرْزَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ عِنْدَ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ ، فَتَغَيَّظَ عَلَى رَجُلٍ فَاشْتَدَّ عَلَيْهِ، فَقُلْتُ: تَأْذَنُ لِي يَا خَلِيفَةَ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَضْرِبُ عُنُقَهُ؟ قَالَ: فَأَذْهَبَتْ كَلِمَتِي غَضَبَهُ، فَقَامَ فَدَخَلَ فَأَرْسَلَ إِلَيَّ فَقَالَ: مَا الَّذِي قُلْتَ آنِفًا؟ قُلْتُ: ائْذَنْ لِي أَضْرِبُ عُنُقَهُ، قَالَ: أَكُنْتَ فَاعِلًا لَوْ أَمَرْتُكَ؟ قُلْتُ: نَعَمْ، قَالَ: لَا وَاللَّهِ، مَا كَانَتْ لِبَشَرٍ بَعْدَ مُحَمَّدٍ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَعْمَى كَانَتْ لَهُ أُمُّ وَلَدٍ تَشْتُمُ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ وَتَقَعُ فِيهِ، فَيَنْهَاهَا فَلَا تَنْتَهِي، وَيَزْجُرُهَا فَلَا تَنْزَجِرُ، قَالَ: فَلَمَّا كَانَتْ ذَاتَ لَيْلَةٍ جَعَلَتْ تَقَعُ فِي النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ وَتَشْتُمُهُ، فَأَخَذَ الْمِغْوَلَ فَوَضَعَهُ فِي بَطْنِهَا، وَاتَّكَأَ عَلَيْهَا فَقَتَلَهَا، فَوَقَعَ بَيْنَ رِجْلَيْهَا طِفْلٌ، فَلَطَّخَتْ مَا هُنَاكَ بِالدَّمِ، فَلَمَّا أَصْبَحَ ذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَجَمَعَ النَّاسَ فَقَالَ: "أَنْشُدُ اللَّهَ رَجُلًا فَعَلَ مَا فَعَلَ لِي عَلَيْهِ حَقٌّ إِلَّا قَامَ". فَقَامَ الْأَعْمَى يَتَخَطَّى النَّاسَ وَهُوَ يَتَزَلْزَلُ حَتَّى قَعَدَ بَيْنَ يَدَيِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَنَا صَاحِبُهَا، كَانَتْ تَشْتُمُكَ وَتَقَعُ فِيكَ فَأَنْهَاهَا فَلَا تَنْتَهِي، وَأَزْجُرُهَا فَلَا تَنْزَجِرُ، وَلِي مِنْهَا ابْنَانِ مِثْلُ اللُّؤْلُؤَتَيْنِ، وَكَانَتْ بِي رَفِيقَةً، فَلَمَّا كَانَ الْبَارِحَةَ جَعَلَتْ تَشْتُمُكَ وَتَقَعُ فِيكَ، فَأَخَذْتُ الْمِغْوَلَ فَوَضَعْتُهُ فِي بَطْنِهَا، وَاتَّكَأْتُ عَلَيْهَا حَتَّى قَتَلْتُهَا. فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "أَلَا، اشْهَدُوا أَنَّ دَمَهَا هَدَرٌ". (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു അന്ധന് ഒരു മകനുള്ള അടിമസ്ത്രീ ഉണ്ടായിരുന്നു. അവൾ നബി(സ)യെ ഇകഴ്ത്തുകയും ചീത്തവിളിക്കുകയും ചെയ്യുമായിരുന്നു. അന്ധൻ അവളെ വിലക്കിയെങ്കിലും അവൾ നിർത്തിയില്ല. അയാൾ ശകാരിച്ചിട്ടും അവൾ സ്വീകരിച്ചില്ല. അങ്ങനെ ഒരു രാത്രി അവൾ റസൂൽ(സ)യെ ചീത്തപറഞ്ഞും ഇകഴ്ത്തിയും കൊണ്ടിരുന്നു. അപ്പോൾ അയാൾ കഠാരയെടുത്ത് അവളുടെ വയറ്റിൽ വെച്ച് അതിന്മേൽ ചാഞ്ഞു. അങ്ങനെ അവളെ കൊന്നു. അപ്പോൾ അവളുടെ കാലുകൾക്കിടയിൽ ഒരു കുട്ടി പെട്ടു. അവിടെയുള്ള രക്തത്തിൽ അത് കുളിച്ചു. പിറ്റേന്ന് പ്രഭാതത്തിൽ വിഷയം നബി(സ)യെ അറിയിക്കപ്പെട്ടു. നബി(സ) ജനങ്ങളെ ഒരുമിച്ചുകൂട്ടി. എന്നിട്ട് പറഞ്ഞു: "ഈ പ്രവൃത്തി ചെയ്തവൻ എഴുന്നേറ്റ് നിൽക്കണമെന്ന് എനിക്ക് അവന്റെ മേലിലുള്ള ബാധ്യതയുടെ അടിസ്ഥാനത്തിൽ അല്ലാഹുവിന്റെ പേരിൽ അപേക്ഷിക്കുന്നു." അന്ധൻ എഴുന്നേറ്റ് നിന്നു. ജനങ്ങളുടെ പിരടികൾക്കിടയിലൂടെ നടന്നു. അയാൾ വിറയ്ക്കുന്നുണ്ടായിരുന്നു. അയാൾ നബി(സ)യുടെ മുന്നിലിരുന്നു. ശേഷം പറഞ്ഞു: റസൂലേ, ഞാനാണ് അത് ചെയ്തവൻ. അവൾ അങ്ങയെ ചീത്തവിളിക്കുകയും ഇകഴ്ത്തുകയും ചെയ്യുമായിരുന്നു. ഞാനവളെ വിലക്കിയെങ്കിലും അവൾ അത് നിർത്തിയില്ല. ഞാനവളെ ശകാരിച്ചു. തന്റെ സ്വഭാവം മാറ്റാൻ പക്ഷേ അവൾ തയ്യാറായില്ല. അവളിൽ നിന്ന് എനിക്ക് മുത്തുകൾ പോലുള്ള രണ്ട് മക്കളുണ്ട്. അവൾ എനിക്ക് പ്രിയപ്പെട്ടവളായിരുന്നു. ഇന്നലെ രാത്രിയായപ്പോൾ അവൾ അങ്ങയെ ചീത്തവിളിക്കാനും ഇകഴ്ത്താനും തുടങ്ങി. അപ്പോൾ ഞാൻ കഠാരയെടുത്ത് അവളുടെ വയറ്റിൽ കുത്തി അതന്മേൽ ചാഞ്ഞു അവളുടെ കഥ കഴിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അറിയുക! അവളുടെ രക്തം ഒഴുക്കപ്പെടേണ്ടതാണെന്നതിന് നിങ്ങൾ സാക്ഷികളാവുക." (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 521, 522, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
