മറ്റൊരു നിവേദനം: "എന്നാൽ ഒരു അവിവാഹിതൻ ഒരവിവാഹിതയുമായി അവിഹിത ബന്ധത്തിലേർപ്പെട്ടാൽ നൂറടിയും ഒരു വർഷത്തേക്കു നാടു കടത്തലുമാണ്." (മു,ദ,തു,ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 458, 458, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
