സുഹ്‌രി(റ) പറയുന്നു: ഈ സൂക്തം യഹൂദികളിൽ ആണ് അവതരിച്ചത്: ''സന്മാർഗ്ഗദർശനവും പ്രകാശവുമുള്ള തൗറാത്ത് നാം അവതരിപ്പിച്ചു. അല്ലാഹുവിന് വഴിപ്പെടുന്നവരായ പ്രവാചകന്മാർ അതു കൊണ്ടു വിധി കൽപിക്കുന്നു.'' (മാഇദ: 44) നബി(സ) അവരിൽപ്പെട്ടവരായിരുന്നു. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'المائدة:٤٤', null, 469, 470, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
