وَرَوَى مَسْعُودُ بْنُ الْأَسْوَدِ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ نَحْوَ هَذَا الْخَيرِ، قَالَ: سَرَقَتْ قَطِيفَةً مِنْ بَيْتِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ. (د,جه)', 'ആഇശ(റ): മഖ്സൂം ഗോത്രത്തിലെ ഒരു സ്ത്രീ (ജനങ്ങളിൽ നിന്ന്) സാധനങ്ങൾ വാങ്ങുകയും അത് തിരിച്ചുനൽകാതിരിക്കുകയും ചെയ്യുമായിരുന്നു. അപ്പോൾ നബി(സ) അവളുടെ കൈ മുറിക്കാൻ ആജ്ഞാപിച്ചു. ശേഷം നിവേദകൻ ലൈസ്(റ)വിൽ നിന്നും ഖുതൈബ(റ) ഉദ്ധരിച്ച ഹദീസ് പോലെത്തന്നെ വിവരിച്ചു. അതിൽ ഇതുകൂടിയുണ്ട്: അപ്രകാരം നബി(സ) അവളുടെ കൈ മുറിച്ചു. (ദ)
മസ്ഊദുബ്നുൽ അസ്വദ്(റ) നബി(സ)യിൽനിന്ന് ഇതുപോലുള്ള മറ്റൊരു ഹദീസ് റിപ്പോർട്ട് ചെയ്തിരിക്കുന്നു. അദ്ദേഹം പറഞ്ഞു: അവൾ റസൂൽ(സ)യുടെ വീട്ടിൽനിന്ന് ഒരു പട്ട് തുണി മോഷ്ടിച്ചു. (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 482, 482, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
