മറ്റൊരു നിവേദനം: "പശ്ചാത്താപം അതിന് ശേഷമാണ് (അവനിലേക്ക്) പ്രത്യക്ഷപ്പെടുത്തുന്നത്." മറ്റൊരു നിവേദനം: "അവനത് ചെയ്താൽ തന്റെ കഴുത്തിൽ നിന്നും ഇസ്ലാമിന്റെ കുടുക്കിനെ ഊരിയിരിക്കുന്നു. അവൻ പശ്ചാത്തപിക്കുന്നുവെങ്കിൽ അല്ലാഹു അവന്റെ പശ്ചാത്താപം സ്വീകരിക്കും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 501, 501, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
